// src/lib/validations/link.ts
import { z } from "zod";

export const CreateLinkSchema = z.object({
  profileId: z.string().min(1, "Profile ID is required"),
  label: z
    .string()
    .min(1, "Label is required")
    .max(80, "Label cannot exceed 80 characters"),
  url: z
    .string()
    .url("Please enter a valid URL (including https://)"),
  icon: z.string().optional().default("globe"),
});

export type CreateLinkInput = z.infer<typeof CreateLinkSchema>;

export interface ActionState<T = unknown> {
  success: boolean;
  message?: string;
  errors?: Record<string, string[] | undefined>;
  data?: T;
}
```

### Step 2 · Build the Link Mutation Server Actions
Create `src/app/actions/link-actions.ts`. Note the mandatory `'use server'` directive at the top of the file:

```typescript
// src/app/actions/link-actions.ts
"use server";

import { revalidatePath } from "next/cache";
import { prisma } from "@/lib/prisma";
import { CreateLinkSchema, ActionState } from "@/lib/validations/link";

/**
 * Creates a new link for a creator profile.
 */
export async function createLinkAction(
  _prevState: ActionState,
  formData: FormData
): Promise<ActionState> {
  const rawData = {
    profileId: formData.get("profileId"),
    label: formData.get("label"),
    url: formData.get("url"),
    icon: formData.get("icon") || "globe",
  };

  // 1. Server-side validation
  const result = CreateLinkSchema.safeParse(rawData);
  if (!result.success) {
    return {
      success: false,
      message: "Validation failed. Please correct the errors below.",
      errors: result.error.flatten().fieldErrors,
    };
  }

  try {
    // 2. Fetch current profile to get handle for cache purge
    const profile = await prisma.profile.findUnique({
      where: { id: result.data.profileId },
      select: { handle: true, _count: { select: { links: true } } },
    });

    if (!profile) {
      return { success: false, message: "Profile not found." };
    }

    // 3. Insert link with position set to current link count
    await prisma.link.create({
      data: {
        profileId: result.data.profileId,
        label: result.data.label,
        url: result.data.url,
        icon: result.data.icon,
        position: profile._count.links,
        isActive: true,
      },
    });

    // 4. Purge ISR cache for the creator's public profile and admin route
    revalidatePath(`/${profile.handle}`);
    revalidatePath(`/admin/${profile.handle}`);

    return {
      success: true,
      message: "Link added successfully!",
    };
  } catch (error) {
    console.error("Failed to create link:", error);
    return {
      success: false,
      message: "A database error occurred while creating the link. Please try again.",
    };
  }
}

/**
 * Deletes a link and cascades associated click events.
 */
export async function deleteLinkAction(
  linkId: string,
  handle: string
): Promise<{ success: boolean; message: string }> {
  try {
    await prisma.link.delete({
      where: { id: linkId },
    });

    revalidatePath(`/${handle}`);
    revalidatePath(`/admin/${handle}`);

    return { success: true, message: "Link deleted." };
  } catch (error) {\n    console.error("Failed to delete link:", error);
    return { success: false, message: "Could not delete link." };
  }
}

/**
 * Toggles a link's active visibility status.
 */
export async function toggleLinkAction(
  linkId: string,
  isActive: boolean,
  handle: string
): Promise<{ success: boolean }> {
  try {
    await prisma.link.update({
      where: { id: linkId },
      data: { isActive },
    });

    revalidatePath(`/${handle}`);
    revalidatePath(`/admin/${handle}`);

    return { success: true };
  } catch (error) {
    console.error("Failed to toggle link:", error);
    return { success: false };
  }
}
```

