### Step 6 · Type-Safe Tenant Guard & Scoped Query Engine
Create `src/lib/tenant.ts`. This module extracts tenant memberships, enforces permissions, and provides scoped query execution:

```typescript
// src/lib/tenant.ts
import { prisma } from "@/lib/prisma";
import { notFound, redirect } from "next/navigation";
import { Role, Plan } from "@prisma/client";

export interface TenantContext {
  org: {
    id: string;
    slug: string;
    name: string;
    plan: Plan;
    stripeCustomerId: string | null;
    stripeSubscriptionId: string | null;
  };
  role: Role;
  userId: string;
}

/**
 * Resolves an organization by slug and verifies that the given user is an active member.
 * Throws 404 if org does not exist; throws error or redirects if unauthorized.
 */
export async function requireOrgMember(orgSlug: string, userId: string): Promise<TenantContext> {
  const org = await prisma.org.findUnique({
    where: { slug: orgSlug },
    include: {
      members: {
        where: { userId },
        select: { role: true },
      },
    },
  });

  if (!org) {
    notFound();
  }

  const membership = org.members[0];
  if (!membership) {
    throw new Error("FORBIDDEN_TENANT_ACCESS");
  }

  return {
    org: {
      id: org.id,
      slug: org.slug,
      name: org.name,
      plan: org.plan,
      stripeCustomerId: org.stripeCustomerId,
      stripeSubscriptionId: org.stripeSubscriptionId,
    },
    role: membership.role,
    userId,
  };
}

/**
 * Creates an isolated Prisma query scope bound strictly to one organization ID.
 */
export function withTenantScope(orgId: string) {
  return {
    projects: {
      findMany: () => prisma.project.findMany({ where: { orgId }, orderBy: { createdAt: "desc" } }),
      count: () => prisma.project.count({ where: { orgId } }),
      create: (data: { name: string; description?: string }) =>
        prisma.project.create({ data: { ...data, orgId } }),
    },
    members: {
      findMany: () =>
        prisma.membership.findMany({
          where: { orgId },
          include: { user: { select: { id: true, name: true, email: true, image: true } } },
        }),
      count: () => prisma.membership.count({ where: { orgId } }),
    },
  };
}
```

