// src/actions/org.ts
"use server";

import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { Role, Plan } from "@prisma/client";

export async function createOrgAction(formData: FormData) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("UNAUTHORIZED");

  const name = formData.get("name") as string;
  const slug = (formData.get("slug") as string).toLowerCase().trim().replace(/[^a-z0-9-]/g, "");

  if (!name || name.length < 2) throw new Error("Invalid organization name");
  if (!slug || slug.length < 3) throw new Error("Slug must be at least 3 characters");

  // Check slug uniqueness
  const existing = await prisma.org.findUnique({ where: { slug } });
  if (existing) throw new Error("Slug already taken. Please pick another.");

  // Create Org and assign user as OWNER atomically
  await prisma.org.create({
    data: {
      name,
      slug,
      plan: Plan.FREE,
      members: {
        create: {
          userId: session.user.id,
          role: Role.OWNER,
        },
      },
    },
  });

  redirect(`/${slug}`);
}
```

