### Step 3 · Stripe Checkout Server Action
Create `src/actions/checkout.ts`. This Server Action validates user permissions (`OWNER` or `ADMIN`), ensures customer ID consistency, and generates the Checkout Session:

```typescript
// src/actions/checkout.ts
"use server";

import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { stripe } from "@/lib/stripe";
import { Role } from "@prisma/client";
import { redirect } from "next/navigation";

export async function createCheckoutSession(orgSlug: string, priceId: string) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("UNAUTHORIZED");

  // 1. Verify organization and user's role
  const org = await prisma.org.findUnique({
    where: { slug: orgSlug },
    include: {
      members: {
        where: { userId: session.user.id },
        select: { role: true },
      },
    },
  });

  if (!org) throw new Error("Organization not found");
  const role = org.members[0]?.role;
  if (role !== Role.OWNER && role !== Role.ADMIN) {
    throw new Error("Only organization Owners and Admins can manage billing subscriptions.");
  }

  // 2. Resolve or create Stripe Customer
  let customerId = org.stripeCustomerId;
  if (!customerId) {
    const customer = await stripe.customers.create({
      name: org.name,
      email: session.user.email || undefined,
      metadata: {
        orgId: org.id,
        orgSlug: org.slug,
      },
    });
    customerId = customer.id;
    await prisma.org.update({
      where: { id: org.id },
      data: { stripeCustomerId: customerId },
    });
  }

  const appUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";

  // 3. Create Checkout Session
  const checkoutSession = await stripe.checkout.sessions.create({
    customer: customerId,
    mode: "subscription",
    payment_method_types: ["card"],
    line_items: [{ price: priceId, quantity: 1 }],
    client_reference_id: org.id,
    subscription_data: {
      metadata: {
        orgId: org.id,
        orgSlug: org.slug,
        initiatedBy: session.user.id,
      },
    },
    success_url: `${appUrl}/${orgSlug}/billing/return?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${appUrl}/${orgSlug}/billing`,
  });

  if (!checkoutSession.url) {
    throw new Error("Failed to initialize Stripe checkout URL");
  }

  redirect(checkoutSession.url);
}
```

