# Phase 4 — Cryptographically Verified, Idempotent Stripe Webhook Pipeline

## 🎯 What You Will Accomplish

Construct a rock-solid, production-grade HTTP POST route handler at `/api/stripe` that extracts raw payload buffers, verifies Stripe HMAC-SHA256 signatures (`stripe-signature`), enforces database idempotency via the `ProcessedEvent` table to prevent duplicate execution during network retries, and synchronizes subscription states (`customer.subscription.created`, `customer.subscription.updated`, `customer.subscription.deleted`, `invoice.payment_failed`) directly into PostgreSQL.

---

## 💡 Core Concepts & Architecture Decisions

### 1. Raw Body Requirement for HMAC-SHA256 Verification
Stripe computes the webhook signature by hashing the exact, unparsed byte sequence of the HTTP request payload using your `STRIPE_WEBHOOK_SECRET`.
- If your Next.js route handler parses the body with `await req.json()` before signature verification, JSON whitespace differences and object key order variations will corrupt the hash, throwing `Webhook signature verification failed`.
- Always extract the unparsed payload using `const rawBody = await req.text()`.

### 2. Distributed Idempotency via ACID Unique Constraints
Stripe guarantees **at-least-once delivery**. If your server takes more than 3 seconds to reply or network fluctuations cause connection drops, Stripe will retry sending the same webhook event up to 72 hours later.
- **The Race Hazard:** Processing duplicate `customer.subscription.created` events could trigger duplicate email alerts, duplicate invoices, or corrupted seat counters.
- **The ACID Fix:** Persist `event.id` into the `ProcessedEvent` table with a unique primary key before executing state changes. If `prisma.processedEvent.create` fails with a unique constraint violation (`P2002`), immediately return HTTP 200 OK and abort.

### 3. Subscription Lifecycle State Machine
Map Stripe subscription statuses directly to application plan tiers:

```
               ┌───────────────┐
               │    FREE       │ ◄──────────┐
               └───────┬───────┘            │
                       │ Checkout           │ Deleted / Canceled
                       ▼                    │
               ┌───────────────┐            │
               │ PRO / TEAM    │────────────┘
               └───────┬───────┘
                       │ Payment Failed
                       ▼
               ┌───────────────┐
               │   PAST_DUE    │ (Grace Period Warning)
               └───────────────┘
```

---

## 🛠 Step-by-Step Implementation

### Step 1 · Webhook Subscription Synchronization Module
Create `src/lib/stripe-webhook-handlers.ts`. This module contains the business logic for updating organization subscriptions:

```typescript
// src/lib/stripe-webhook-handlers.ts
import { prisma } from "@/lib/prisma";
import { Plan } from "@prisma/client";
import Stripe from "stripe";

/**
 * Resolves the application Plan enum from a Stripe Price ID
 */
export function resolvePlanFromPriceId(priceId?: string): Plan {
  if (!priceId) return Plan.FREE;
  if (priceId === process.env.STRIPE_TEAM_MONTHLY_PRICE_ID || priceId === process.env.STRIPE_TEAM_YEARLY_PRICE_ID) {
    return Plan.TEAM;
  }
  if (priceId === process.env.STRIPE_PRO_MONTHLY_PRICE_ID || priceId === process.env.STRIPE_PRO_YEARLY_PRICE_ID) {
    return Plan.PRO;
  }
  return Plan.PRO; // Default paid fallback
}

/**
 * Synchronizes subscription status into PostgreSQL Org table
 */
export async function syncSubscriptionToOrg(subscription: Stripe.Subscription) {
  const orgId = subscription.metadata?.orgId;
  const customerId = subscription.customer as string;

  // Find org either by metadata orgId or by stripeCustomerId
  const org =
    (orgId ? await prisma.org.findUnique({ where: { id: orgId } }) : null) ||
    (await prisma.org.findUnique({ where: { stripeCustomerId: customerId } }));

  if (!org) {
    console.warn(`[Stripe Webhook] No matching organization found for customer ${customerId}`);
    return;
  }

  const isActive = subscription.status === "active" || subscription.status === "trialing";
  const priceId = subscription.items.data[0]?.price?.id;
  const targetPlan = isActive ? resolvePlanFromPriceId(priceId) : Plan.FREE;

  const periodEnd = (subscription as any).current_period_end
    ? new Date((subscription as any).current_period_end * 1000)
    : null;

  await prisma.org.update({
    where: { id: org.id },
    data: {
      plan: targetPlan,
      stripeSubscriptionId: subscription.id,
      stripeCustomerId: customerId,
      stripePriceId: priceId,
      stripeCurrentPeriodEnd: periodEnd,
    },
  });

  console.log(`[Stripe Webhook] Org ${org.slug} synchronized to plan: ${targetPlan}`);
}

/**
 * Handles subscription cancellation or deletion
 */
export async function handleSubscriptionDeleted(subscription: Stripe.Subscription) {
  const customerId = subscription.customer as string;
  const org = await prisma.org.findUnique({ where: { stripeCustomerId: customerId } });
  if (!org) return;

  await prisma.org.update({
    where: { id: org.id },
    data: {
      plan: Plan.FREE,
      stripeSubscriptionId: null,
      stripePriceId: null,
      stripeCurrentPeriodEnd: null,
    },
  });

  console.log(`[Stripe Webhook] Org ${org.slug} downgraded to FREE after subscription cancellation.`);
}
```

### Step 2 · Build the Webhook Route Handler
Create `src/app/api/stripe/route.ts`. Ensure `export const dynamic = 'force-dynamic'` is set to avoid Next.js caching:

```typescript
// src/app/api/stripe/route.ts
import { NextRequest, NextResponse } from "next/server";
import { stripe } from "@/lib/stripe";
import { prisma } from "@/lib/prisma";
import {
  syncSubscriptionToOrg,
  handleSubscriptionDeleted,
} from "@/lib/stripe-webhook-handlers";
import Stripe from "stripe";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  const rawBody = await req.text();
  const signature = req.headers.get("stripe-signature");

  if (!signature || !process.env.STRIPE_WEBHOOK_SECRET) {
    return new NextResponse("Missing stripe-signature or webhook secret", { status: 400 });
  }

  let event: Stripe.Event;

  // 1. Cryptographically verify webhook signature against raw byte payload
  try {
    event = stripe.webhooks.constructEvent(
      rawBody,
      signature,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err: any) {
    console.error(`[Webhook Error] Bad Signature: ${err.message}`);
    return new NextResponse(`Webhook Error: ${err.message}`, { status: 400 });
  }

  // 2. Distributed Idempotency: Prevent duplicate execution
  try {
    await prisma.processedEvent.create({
      data: {
        id: event.id,
        eventType: event.type,
      },
    });
  } catch (dbError: any) {
    // Prisma code P2002 indicates unique constraint violation (already processed)
    if (dbError.code === "P2002") {
      console.log(`[Webhook Idempotency] Skipping duplicate event ${event.id}`);
      return new NextResponse("Event already processed", { status: 200 });
    }
    throw dbError;
  }

  // 3. Dispatch and handle verified events
  try {
    switch (event.type) {
      case "checkout.session.completed": {
        const session = event.data.object as Stripe.Checkout.Session;
        if (session.subscription) {
          const sub = await stripe.subscriptions.retrieve(session.subscription as string);
          await syncSubscriptionToOrg(sub);
        }
        break;
      }

      case "customer.subscription.created":
      case "customer.subscription.updated": {
        const sub = event.data.object as Stripe.Subscription;
        await syncSubscriptionToOrg(sub);
        break;
      }

      case "customer.subscription.deleted": {
        const sub = event.data.object as Stripe.Subscription;
        await handleSubscriptionDeleted(sub);
        break;
      }

      case "invoice.payment_failed": {
        const invoice = event.data.object as Stripe.Invoice;
        console.warn(`[Webhook Invoice Failed] Payment failed for customer ${invoice.customer}`);
        // In production: trigger transactional email notification
        break;
      }

      default:
        console.log(`[Stripe Webhook] Unhandled event type: ${event.type}`);
    }

    return new NextResponse("Webhook handled successfully", { status: 200 });
  } catch (handlerError: any) {
    console.error(`[Webhook Handler Error] Event ${event.id} failed:`, handlerError);
    return new NextResponse("Internal webhook processing error", { status: 500 });
  }
}
```

