### Step 2 · Build Entitlement Evaluator & Guard Helper
Create `src/lib/entitlements.ts`. This module queries current resource consumption and enforces hard bounds:

```typescript
// src/lib/entitlements.ts
import { prisma } from "@/lib/prisma";
import { PLAN_LIMITS, PlanEntitlements } from "@/config/plans";
import { Plan } from "@prisma/client";

export interface OrgUsageSummary {
  plan: Plan;
  limits: PlanEntitlements;
  usage: {
    projects: number;
    seats: number;
  };
  isOverQuota: {
    projects: boolean;
    seats: boolean;
  };
}

/**
 * Queries organization usage and compares against plan limits
 */
export async function getOrgUsage(orgId: string): Promise<OrgUsageSummary> {
  const org = await prisma.org.findUniqueOrThrow({
    where: { id: orgId },
    select: { plan: true },
  });

  const [projectCount, seatCount] = await Promise.all([
    prisma.project.count({ where: { orgId } }),
    prisma.membership.count({ where: { orgId } }),
  ]);

  const limits = PLAN_LIMITS[org.plan];

  return {
    plan: org.plan,
    limits,
    usage: {
      projects: projectCount,
      seats: seatCount,
    },
    isOverQuota: {
      projects: projectCount >= limits.maxProjects,
      seats: seatCount >= limits.maxSeats,
    },
  };
}

/**
 * Server Assertion: Throws error if organization has exhausted project quota
 */
export async function assertCanCreateProject(orgId: string) {
  const { limits, usage } = await getOrgUsage(orgId);
  if (usage.projects >= limits.maxProjects) {
    throw new Error(
      `PROJECT_LIMIT_EXCEEDED: Your ${limits.maxProjects} project limit has been reached on this plan.`
    );
  }
}

/**
 * Server Assertion: Throws error if organization has exhausted seat quota
 */
export async function assertCanInviteMember(orgId: string) {
  const { limits, usage } = await getOrgUsage(orgId);
  if (usage.seats >= limits.maxSeats) {
    throw new Error(
      `SEAT_LIMIT_EXCEEDED: Your plan allows a maximum of ${limits.maxSeats} seat(s).`
    );
  }
}
```

### Step 3 · Gated Project Creation Server Action
Create `src/actions/projects.ts`. This action validates permissions and asserts project limits inside an atomic flow:

```typescript
// src/actions/projects.ts
"use server";

import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { assertCanCreateProject } from "@/lib/entitlements";
import { revalidatePath } from "next/cache";

export async function createProjectAction(orgSlug: string, formData: FormData) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("UNAUTHORIZED");

  const name = formData.get("name") as string;
  const description = formData.get("description") as string;

  if (!name || name.trim().length === 0) {
    throw new Error("Project name is required");
  }

  // 1. Resolve organization and verify membership
  const org = await prisma.org.findUnique({
    where: { slug: orgSlug },
    include: {
      members: {
        where: { userId: session.user.id },
      },
    },
  });

  if (!org || org.members.length === 0) {
    throw new Error("FORBIDDEN: You are not a member of this workspace.");
  }

  // 2. Enforce atomic plan entitlement limit
  await assertCanCreateProject(org.id);

  // 3. Create project in PostgreSQL
  await prisma.project.create({
    data: {
      orgId: org.id,
      name: name.trim(),
      description: description?.trim() || null,
    },
  });

  revalidatePath(`/${orgSlug}/projects`);
  revalidatePath(`/${orgSlug}`);
}
```

