// src/components/UsageMeter.tsx
interface UsageMeterProps {
  title: string;
  current: number;
  limit: number;
  unit: string;
}

export function UsageMeter({ title, current, limit, unit }: UsageMeterProps) {
  const isUnlimited = !isFinite(limit);
  const percentage = isUnlimited ? 0 : Math.min(Math.round((current / limit) * 100), 100);
  const isFull = !isUnlimited && current >= limit;

  return (
    <div className="space-y-2 rounded-xl border border-stone-800 bg-[#12100d] p-4">
      <div className="flex items-center justify-between text-xs">
        <span className="font-medium text-stone-300">{title}</span>
        <span className="font-mono text-stone-400">
          {current} / {isUnlimited ? "∞" : limit} {unit}
        </span>
      </div>

      <div className="h-2 w-full rounded-full bg-stone-900 overflow-hidden">
        <div
          className={`h-full transition-all duration-500 rounded-full ${
            isFull ? "bg-red-500" : percentage > 75 ? "bg-amber-500" : "bg-emerald-500"
          }`}
          style={{ width: `${isUnlimited ? 15 : percentage}%` }}
        />
      </div>

      {isFull && (
        <p className="text-[11px] text-red-400 font-medium">
          Quota limit reached. Upgrade your subscription to add more.
        </p>
      )}
