### Step 1 · Customer Portal Server Action
Create `src/actions/portal.ts`. This action validates that the requester is an `OWNER` or `ADMIN`, retrieves `org.stripeCustomerId`, and generates a secure portal session:

```typescript
// src/actions/portal.ts
"use server";

import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { stripe } from "@/lib/stripe";
import { Role } from "@prisma/client";
import { redirect } from "next/navigation";

export async function openCustomerPortal(orgSlug: string) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("UNAUTHORIZED");

  // Verify org and membership role
  const org = await prisma.org.findUnique({
    where: { slug: orgSlug },
    include: {
      members: {
        where: { userId: session.user.id },
        select: { role: true },
      },
    },
  });

  if (!org) throw new Error("Organization not found");
  const role = org.members[0]?.role;
  if (role !== Role.OWNER && role !== Role.ADMIN) {
    throw new Error("Only organization Owners and Admins can access billing portal.");
  }

  if (!org.stripeCustomerId) {
    throw new Error("No Stripe customer record found for this organization.");
  }

  const appUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";

  // Generate temporary Customer Portal session
  const portalSession = await stripe.billingPortal.sessions.create({
    customer: org.stripeCustomerId,
    return_url: `${appUrl}/${orgSlug}/billing`,
  });

  redirect(portalSession.url);
}
```

