### Step 3 · Viewport Affine Coordinate Matrix Math
Create `src/lib/matrix.ts` to convert between Screen and World coordinates cleanly:

```typescript
// src/lib/matrix.ts
import { Point, ViewportTransform } from "@/types/canvas";

/**
 * Converts browser screen coordinates into infinite world whiteboard coordinates
 */
export function screenToWorld(screenPoint: Point, viewport: ViewportTransform): Point {
  return {
    x: (screenPoint.x - viewport.panX) / viewport.zoom,
    y: (screenPoint.y - viewport.panY) / viewport.zoom,
  };
}

/**
 * Converts world coordinates into browser screen pixel coordinates
 */
export function worldToScreen(worldPoint: Point, viewport: ViewportTransform): Point {
  return {
    x: worldPoint.x * viewport.zoom + viewport.panX,
    y: worldPoint.y * viewport.zoom + viewport.panY,
  };
}

/**
 * Clamps zoom levels to safe numerical boundaries (10% to 500%)
 */
export function clampZoom(zoom: number): number {
  return Math.min(Math.max(zoom, 0.1), 5.0);
}
```

### Step 4 · Hi-DPI Canvas Resizing Hook
Create `src/hooks/useCanvasResize.ts`. This hook tracks window size and adjusts canvas physical backing pixels dynamically:

```typescript
// src/hooks/useCanvasResize.ts
import { useEffect, useState, RefObject } from "react";

export function useCanvasResize(canvasRef: RefObject<HTMLCanvasElement | null>) {
  const [size, setSize] = useState({ width: 0, height: 0, dpr: 1 });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const handleResize = () => {
      const parent = canvas.parentElement;
      if (!parent) return;

      const dpr = window.devicePixelRatio || 1;
      const width = parent.clientWidth;
      const height = parent.clientHeight;

      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      setSize({ width, height, dpr });
    };

    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [canvasRef]);

  return size;
}
```

### Step 5 · Pure Vector Rendering Engine
Create `src/lib/renderer.ts`. This module executes pure immediate-mode drawing commands on the 2D context:

```typescript
// src/lib/renderer.ts
import { CanvasShape, ViewportTransform } from "@/types/canvas";

export function renderScene(
  ctx: CanvasRenderingContext2D,
  shapes: CanvasShape[],
  viewport: ViewportTransform,
  dpr: number
) {
  const { width, height } = ctx.canvas;

  // 1. Reset transform and clear backing buffer
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, width, height);

  // 2. Set Hi-DPI scaling followed by viewport pan/zoom transform
  ctx.setTransform(
    dpr * viewport.zoom,
    0,
    0,
    dpr * viewport.zoom,
    dpr * viewport.panX,
    dpr * viewport.panY
  );

  // 3. Draw subtle infinite grid
  drawInfiniteGrid(ctx, viewport, width / dpr, height / dpr);

  // 4. Render shapes sorted by z-index
  const sortedShapes = [...shapes].sort((a, b) => a.zIndex - b.zIndex);

  for (const shape of sortedShapes) {
    ctx.save();
    ctx.globalAlpha = shape.opacity;
    ctx.fillStyle = shape.fill;
    ctx.strokeStyle = shape.stroke;
    ctx.lineWidth = shape.strokeWidth;

    switch (shape.type) {
      case "rect": {
        ctx.beginPath();
        if (shape.borderRadius && shape.borderRadius > 0) {
          ctx.roundRect(shape.x, shape.y, shape.w, shape.h, shape.borderRadius);
        } else {
          ctx.rect(shape.x, shape.y, shape.w, shape.h);
        }
        if (shape.fill !== "transparent") ctx.fill();
        if (shape.strokeWidth > 0) ctx.stroke();
        break;
      }

      case "ellipse": {
        ctx.beginPath();
        const rx = Math.abs(shape.w) / 2;
        const ry = Math.abs(shape.h) / 2;
        const cx = shape.x + rx;
        const cy = shape.y + ry;
        ctx.ellipse(cx, cy, Math.max(rx, 1), Math.max(ry, 1), 0, 0, Math.PI * 2);
        if (shape.fill !== "transparent") ctx.fill();
        if (shape.strokeWidth > 0) ctx.stroke();
        break;
      }

      case "line": {
        ctx.beginPath();
        ctx.moveTo(shape.x, shape.y);
        ctx.lineTo(shape.x2, shape.y2);
        ctx.stroke();
        break;
      }
    }

    ctx.restore();
  }
}

function drawInfiniteGrid(
  ctx: CanvasRenderingContext2D,
  viewport: ViewportTransform,
  viewWidth: number,
  viewHeight: number
) {
  const gridSize = 40;
  const startX = Math.floor(-viewport.panX / viewport.zoom / gridSize) * gridSize;
  const startY = Math.floor(-viewport.panY / viewport.zoom / gridSize) * gridSize;
  const endX = startX + viewWidth / viewport.zoom + gridSize;
  const endY = startY + viewHeight / viewport.zoom + gridSize;

  ctx.save();
  ctx.strokeStyle = "#1c1a17";
  ctx.lineWidth = 1 / viewport.zoom;
  ctx.beginPath();

  for (let x = startX; x <= endX; x += gridSize) {
    ctx.moveTo(x, startY);
    ctx.lineTo(x, endY);
  }
  for (let y = startY; y <= endY; y += gridSize) {
    ctx.moveTo(startX, y);
    ctx.lineTo(endX, y);
  }
  ctx.stroke();
  ctx.restore();
}
```

### Step 6 · Dirty-Flag Render Loop Controller
Create `src/lib/render-loop.ts`. This ensures we only invoke `requestAnimationFrame` when the canvas state actually mutates:

```typescript
// src/lib/render-loop.ts
export class RenderLoopController {
  private isDirty = true;
  private animFrameId: number | null = null;
  private renderCallback: () => void;

  constructor(renderCallback: () => void) {
    this.renderCallback = renderCallback;
  }

  public markDirty() {
    this.isDirty = true;
    if (this.animFrameId === null) {
      this.animFrameId = requestAnimationFrame(this.tick);
    }
  }

  private tick = () => {
    this.animFrameId = null;
    if (this.isDirty) {
      this.isDirty = false;
      this.renderCallback();
    }
  };

  public destroy() {
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
  }
}
```

