      w: 160,
      h: 160,
      fill: "#17140f",
      stroke: "#d97706",
      strokeWidth: 2,
      opacity: 0.9,
      zIndex: 2,
    },
  ]);

  const [viewport, setViewport] = useState<ViewportTransform>({
    panX: 50,
    panY: 50,
    zoom: 1.0,
  });

  const isPanningRef = useRef(false);
  const lastPanPoint = useRef({ x: 0, y: 0 });
  const renderLoopRef = useRef<RenderLoopController | null>(null);
  const { width, height, dpr } = useCanvasResize(canvasRef);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    renderScene(ctx, shapes, viewport, dpr);
  }, [shapes, viewport, dpr]);

  useEffect(() => {
    renderLoopRef.current = new RenderLoopController(draw);
    renderLoopRef.current.markDirty();
    return () => renderLoopRef.current?.destroy();
  }, [draw]);

  // Handle mouse wheel zoom & trackpad pinch
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const cursorX = e.clientX - rect.left;
    const cursorY = e.clientY - rect.top;

    const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
    const newZoom = clampZoom(viewport.zoom * zoomFactor);

    // Zoom centered around cursor position
    const newPanX = cursorX - (cursorX - viewport.panX) * (newZoom / viewport.zoom);
    const newPanY = cursorY - (cursorY - viewport.panY) * (newZoom / viewport.zoom);

    setViewport({ panX: newPanX, panY: newPanY, zoom: newZoom });
  };

  // Handle middle-click or spacebar drag panning
  const handlePointerDown = (e: React.PointerEvent) => {
    if (e.button === 1 || e.buttons === 4 || e.spaceKey) {
      isPanningRef.current = true;
      lastPanPoint.current = { x: e.clientX, y: e.clientY };
      e.currentTarget.setPointerCapture(e.pointerId);
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isPanningRef.current) return;
    const dx = e.clientX - lastPanPoint.current.x;
    const dy = e.clientY - lastPanPoint.current.y;
    lastPanPoint.current = { x: e.clientX, y: e.clientY };

    setViewport((prev) => ({
      ...prev,
      panX: prev.panX + dx,
      panY: prev.panY + dy,
    }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isPanningRef.current) {
      isPanningRef.current = false;
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
  };

  return (
    <div className="relative h-screen w-screen overflow-hidden bg-[#0d0c0a] select-none">
      <canvas
        ref={canvasRef}
        onWheel={handleWheel}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        className="absolute inset-0 cursor-crosshair touch-none"
      />

      {/* HUD Info Bar */}
      <div className="absolute bottom-4 left-4 z-10 flex items-center gap-3 rounded-xl border border-stone-800 bg-[#12100d]/90 px-3.5 py-1.5 backdrop-blur font-mono text-[11px] text-stone-400 shadow-xl">
        <span>Zoom: {Math.round(viewport.zoom * 100)}%</span>
        <span className="text-stone-700">|</span>
        <span>Pan: {Math.round(viewport.panX)}, {Math.round(viewport.panY)}</span>
        <span className="text-stone-700">|</span>
        <span>Shapes: {shapes.length}</span>
      </div>
    </div>
  );
}
