### Step 4 · Hook for Dragging, Resizing & Hit Interactions
Create `src/hooks/usePointerInteractions.ts`:

```typescript
// src/hooks/usePointerInteractions.ts
import { useState, useRef, useCallback } from "react";
import { CanvasShape, ViewportTransform, Point } from "@/types/canvas";
import { screenToWorld } from "@/lib/matrix";
import { findTopShapeAtPoint } from "@/lib/hit-test";
import { getShapeHandles, hitTestHandle, HandleType } from "@/lib/transform-handles";
import { PointerState } from "@/lib/pointer-machine";

interface UsePointerProps {
  shapes: CanvasShape[];
  viewport: ViewportTransform;
  onUpdateShape: (shape: CanvasShape) => void;
  onSetViewport: (updater: (prev: ViewportTransform) => ViewportTransform) => void;
}

export function usePointerInteractions({
  shapes,
  viewport,
  onUpdateShape,
  onSetViewport,
}: UsePointerProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [state, setState] = useState<PointerState>({ type: "IDLE" });

  const selectedShape = shapes.find((s) => s.id === selectedId) || null;
  const handles = selectedShape ? getShapeHandles(selectedShape, viewport) : [];

  const handlePointerDown = (e: React.PointerEvent, canvasRect: DOMRect) => {
    const screenPoint = { x: e.clientX - canvasRect.left, y: e.clientY - canvasRect.top };
    const worldPoint = screenToWorld(screenPoint, viewport);

    // 1. Spacebar or middle click initiates Pan
    if (e.button === 1 || e.spaceKey) {
      setState({ type: "PANNING", lastPoint: { x: e.clientX, y: e.clientY } });
      e.currentTarget.setPointerCapture(e.pointerId);
      return;
    }

    // 2. Test resize handles on already selected shape
    if (selectedShape) {
      const hitHandle = hitTestHandle(screenPoint, handles);
      if (hitHandle) {
        setState({
          type: "RESIZING",
          shapeId: selectedShape.id,
          handle: hitHandle,
          startPoint: worldPoint,
          initialShape: { ...selectedShape },
        });
        e.currentTarget.setPointerCapture(e.pointerId);
        return;
      }
    }

    // 3. Test shape raycasting
    const hitShape = findTopShapeAtPoint(worldPoint, shapes);
    if (hitShape) {
      setSelectedId(hitShape.id);
      setState({
        type: "DRAGGING",
        shapeId: hitShape.id,
        startPoint: worldPoint,
        initialShape: { ...hitShape },
      });
      e.currentTarget.setPointerCapture(e.pointerId);
    } else {
      // Clicked blank canvas: clear selection or start marquee
      setSelectedId(null);
      setState({ type: "IDLE" });
    }
  };

  const handlePointerMove = (e: React.PointerEvent, canvasRect: DOMRect) => {
    const screenPoint = { x: e.clientX - canvasRect.left, y: e.clientY - canvasRect.top };
    const worldPoint = screenToWorld(screenPoint, viewport);

    if (state.type === "PANNING") {
      const dx = e.clientX - state.lastPoint.x;
      const dy = e.clientY - state.lastPoint.y;
      onSetViewport((prev) => ({ ...prev, panX: prev.panX + dx, panY: prev.panY + dy }));
      setState({ type: "PANNING", lastPoint: { x: e.clientX, y: e.clientY } });
    } else if (state.type === "DRAGGING") {
      const dx = worldPoint.x - state.startPoint.x;
      const dy = worldPoint.y - state.startPoint.y;
      onUpdateShape({
        ...state.initialShape,
        x: state.initialShape.x + dx,
        y: state.initialShape.y + dy,
      });
    } else if (state.type === "RESIZING") {
      const dx = worldPoint.x - state.startPoint.x;
      const dy = worldPoint.y - state.startPoint.y;
      const s = { ...state.initialShape };

      if (state.handle.includes("e")) s.w = Math.max(20, state.initialShape.w + dx);
      if (state.handle.includes("s")) s.h = Math.max(20, state.initialShape.h + dy);
      if (state.handle.includes("w")) {
        const newW = Math.max(20, state.initialShape.w - dx);
        s.x = state.initialShape.x + (state.initialShape.w - newW);
        s.w = newW;
      }
      if (state.handle.includes("n")) {
        const newH = Math.max(20, state.initialShape.h - dy);
        s.y = state.initialShape.y + (state.initialShape.h - newH);
        s.h = newH;
      }
      onUpdateShape(s);
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (state.type !== "IDLE") {
      setState({ type: "IDLE" });
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
  };

  return {
    selectedId,
    selectedShape,
    handles,
    state,
    handlePointerDown,
    handlePointerMove,
    handlePointerUp,
  };
}
```

