```typescript
// src/lib/render-selection.ts
import { CanvasShape, ViewportTransform } from "@/types/canvas";
import { getShapeHandles } from "@/lib/transform-handles";

export function renderSelectionOverlay(
  ctx: CanvasRenderingContext2D,
  selectedShape: CanvasShape,
  viewport: ViewportTransform,
  dpr: number
) {
  const handles = getShapeHandles(selectedShape, viewport);
  const { x, y, w, h } = selectedShape;

  ctx.save();
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  // Draw selection outline box
  const topLeft = { x: x * viewport.zoom + viewport.panX, y: y * viewport.zoom + viewport.panY };
  const boxW = w * viewport.zoom;
  const boxH = h * viewport.zoom;

  ctx.strokeStyle = "#f59e0b";
  ctx.lineWidth = 1.5;
  ctx.setLineDash([4, 4]);
  ctx.strokeRect(topLeft.x, topLeft.y, boxW, boxH);
  ctx.setLineDash([]);

  // Draw 8 transform handles
  for (const handle of handles) {
    ctx.fillStyle = "#ffffff";
    ctx.strokeStyle = "#d97706";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.rect(handle.screenX - 4, handle.screenY - 4, 8, 8);
    ctx.fill();
    ctx.stroke();
  }

  ctx.restore();
}
