### Step 2 · CRDT Serialization & Shape Converters
Create `src/lib/crdt/shapes.ts`. This module serializes between plain TypeScript `CanvasShape` objects and reactive `Y.Map` models:

```typescript
// src/lib/crdt/shapes.ts
import * as Y from "yjs";
import { CanvasShape } from "@/types/canvas";
import { ydoc, yshapes, LOCAL_ORIGIN } from "@/lib/crdt/doc";

/**
 * Converts a plain CanvasShape object into a nested Y.Map and inserts it into the document
 */
export function setYjsShape(shape: CanvasShape) {
  ydoc.transact(() => {
    let shapeMap = yshapes.get(shape.id);
    if (!shapeMap) {
      shapeMap = new Y.Map();
      yshapes.set(shape.id, shapeMap);
    }

    Object.entries(shape).forEach(([key, value]) => {
      if (shapeMap!.get(key) !== value) {
        shapeMap!.set(key, value);
      }
    });
  }, LOCAL_ORIGIN);
}

/**
 * Deletes a shape from the CRDT document
 */
export function deleteYjsShape(shapeId: string) {
  ydoc.transact(() => {
    yshapes.delete(shapeId);
  }, LOCAL_ORIGIN);
}

/**
 * Converts the entire Y.Map shapes collection into an array of CanvasShape objects
 */
export function getYjsShapesArray(): CanvasShape[] {
  const shapes: CanvasShape[] = [];
  yshapes.forEach((shapeMap, id) => {
    const obj = shapeMap.toJSON() as CanvasShape;
    shapes.push({ ...obj, id });
  });
  return shapes.sort((a, b) => a.zIndex - b.zIndex);
}
```

### Step 3 · Connect Canvas Engine to Yjs Document Observer
Create `src/hooks/useYjsCanvas.ts`. This hook listens for deep changes in the Yjs document and triggers canvas redraws:

```typescript
// src/hooks/useYjsCanvas.ts
import { useEffect, useState, useCallback } from "react";
import { CanvasShape } from "@/types/canvas";
import { ydoc, yshapes } from "@/lib/crdt/doc";
import { getYjsShapesArray, setYjsShape, deleteYjsShape } from "@/lib/crdt/shapes";

export function useYjsCanvas() {
  const [shapes, setShapes] = useState<CanvasShape[]>(() => getYjsShapesArray());

  const refreshShapes = useCallback(() => {
    setShapes(getYjsShapesArray());
  }, []);

  useEffect(() => {
    // Observe deep mutations across all shapes in the map
    const observer = () => {
      refreshShapes();
    };

    yshapes.observeDeep(observer);
    return () => {
      yshapes.unobserveDeep(observer);
    };
  }, [refreshShapes]);

  const updateShape = useCallback((shape: CanvasShape) => {
    setYjsShape(shape);
  }, []);

  const deleteShape = useCallback((shapeId: string) => {
    deleteYjsShape(shapeId);
  }, []);

  return {
    shapes,
    updateShape,
    deleteShape,
  };
}
```

