### Step 2 · Room Multiplexer & Connection Pool
Create `server/src/rooms.ts`. This module isolates documents by room ID and tracks client sockets:

```typescript
// server/src/rooms.ts
import * as Y from "yjs";
import { WebSocket } from "ws";

export interface Room {
  name: string;
  doc: Y.Doc;
  clients: Set<WebSocket>;
  lastActivity: number;
}

export class RoomManager {
  private rooms = new Map<string, Room>();

  public getOrCreateRoom(roomName: string): Room {
    let room = this.rooms.get(roomName);
    if (!room) {
      const doc = new Y.Doc();
      room = {
        name: roomName,
        doc,
        clients: new Set(),
        lastActivity: Date.now(),
      };
      this.rooms.set(roomName, room);
      console.log(`[RoomManager] Room created: ${roomName}`);
    }
    return room;
  }

  public removeClient(roomName: string, client: WebSocket) {
    const room = this.rooms.get(roomName);
    if (!room) return;
    room.clients.delete(client);

    // Cleanup empty room after 5 minutes of inactivity
    if (room.clients.size === 0) {
      setTimeout(() => {
        if (room && room.clients.size === 0) {
          room.doc.destroy();
          this.rooms.delete(roomName);
          console.log(`[RoomManager] Garbage collected empty room: ${roomName}`);
        }
      }, 5 * 60 * 1000);
    }
  }
}
```

### Step 3 · Binary Sync Protocol Dispatcher
Create `server/src/sync-protocol.ts` to decode and handle Yjs sync messages:

```typescript
// server/src/sync-protocol.ts
import * as syncProtocol from "y-protocols/sync";
import * as encoding from "lib0/encoding";
import * as decoding from "lib0/decoding";
import { WebSocket } from "ws";
import { Room } from "./rooms.js";

const MESSAGE_SYNC = 0;

export function handleSyncMessage(
  ws: WebSocket,
  room: Room,
  message: Uint8Array
) {
  const decoder = decoding.createDecoder(message);
  const messageType = decoding.readVarUint(decoder);

  if (messageType === MESSAGE_SYNC) {
    const encoder = encoding.createEncoder();
    encoding.writeVarUint(encoder, MESSAGE_SYNC);

    // Read sync step and process against room Y.Doc
    syncProtocol.readSyncMessage(decoder, encoder, room.doc, ws);

    // If a reply payload was generated, send back to requester
    if (encoding.length(encoder) > 1) {
      ws.send(encoding.toUint8Array(encoder));
    }
  }
}

export function setupDocListener(room: Room) {
  // When the server document updates, broadcast the delta to all other clients in the room
  room.doc.on("update", (update: Uint8Array, origin: any) => {
    const encoder = encoding.createEncoder();
    encoding.writeVarUint(encoder, MESSAGE_SYNC);
    syncProtocol.writeUpdate(encoder, update);
    const message = encoding.toUint8Array(encoder);

    room.clients.forEach((client) => {
      if (client !== origin && client.readyState === WebSocket.OPEN) {
        client.send(message);
      }
    });
  });
}
```

### Step 4 · WebSocket Server Entrypoint & Heartbeat
Create `server/src/server.ts`:

```typescript
// server/src/server.ts
import { WebSocketServer, WebSocket } from "ws";
import { createServer } from "http";
import { RoomManager } from "./rooms.js";
import { handleSyncMessage, setupDocListener } from "./sync-protocol.js";
import * as syncProtocol from "y-protocols/sync";
import * as encoding from "lib0/encoding";

const PORT = process.env.PORT || 1234;
const server = createServer();
const wss = new WebSocketServer({ server });
const roomManager = new RoomManager();

wss.on("connection", (ws: WebSocket, req) => {
  // Extract room name from URL path: /rooms/my-canvas-room
  const url = new URL(req.url || "", `http://${req.headers.host}`);
  const roomName = url.pathname.replace(/^\/rooms\//, "") || "default-room";

  const room = roomManager.getOrCreateRoom(roomName);
  room.clients.add(ws);

  if (room.clients.size === 1) {
    setupDocListener(room);
  }

  // Step 1: Send Sync Step 1 to new client (Server's State Vector)
  const encoder = encoding.createEncoder();
  encoding.writeVarUint(encoder, 0); // MESSAGE_SYNC
  syncProtocol.writeSyncStep1(encoder, room.doc);
  ws.send(encoding.toUint8Array(encoder));

  ws.on("message", (data: Buffer) => {
    const uint8 = new Uint8Array(data);
    handleSyncMessage(ws, room, uint8);
  });

  ws.on("close", () => {
    roomManager.removeClient(roomName, ws);
  });
});

server.listen(PORT, () => {
  console.log(`[WebSocket Server] Running on ws://localhost:${PORT}`);
});
```

