### Step 5 · Custom Next.js WebSocket Provider Client
In the Next.js application, create `src/lib/crdt/websocket-provider.ts`:

```typescript
// src/lib/crdt/websocket-provider.ts
import { ydoc } from "@/lib/crdt/doc";
import * as syncProtocol from "y-protocols/sync";
import * as encoding from "lib0/encoding";
import * as decoding from "lib0/decoding";

export class CanvasWebSocketProvider {
  private ws: WebSocket | null = null;
  private roomName: string;
  private url: string;

  constructor(url: string, roomName: string) {
    this.url = url;
    this.roomName = roomName;
    this.connect();
  }

  private connect() {
    this.ws = new WebSocket(`${this.url}/rooms/${this.roomName}`);
    this.ws.binaryType = "arraybuffer";

    this.ws.onopen = () => {
      console.log(`[Yjs WS] Connected to room ${this.roomName}`);
      // Send local State Vector to Server (Sync Step 1)
      const encoder = encoding.createEncoder();
      encoding.writeVarUint(encoder, 0);
      syncProtocol.writeSyncStep1(encoder, ydoc);
      this.ws?.send(encoding.toUint8Array(encoder));
    };

    this.ws.onmessage = (event) => {
      const uint8 = new Uint8Array(event.data as ArrayBuffer);
      const decoder = decoding.createDecoder(uint8);
      const messageType = decoding.readVarUint(decoder);

      if (messageType === 0) {
        const encoder = encoding.createEncoder();
        encoding.writeVarUint(encoder, 0);
        syncProtocol.readSyncMessage(decoder, encoder, ydoc, this);
        if (encoding.length(encoder) > 1) {
          this.ws?.send(encoding.toUint8Array(encoder));
        }
      }
    };

    // Forward local document changes to WebSocket server
    ydoc.on("update", (update, origin) => {
      if (origin !== this && this.ws?.readyState === WebSocket.OPEN) {
        const encoder = encoding.createEncoder();
        encoding.writeVarUint(encoder, 0);
        syncProtocol.writeUpdate(encoder, update);
        this.ws.send(encoding.toUint8Array(encoder));
      }
    });

    this.ws.onclose = () => {
      console.warn("[Yjs WS] Disconnected. Reconnecting in 2s...");
      setTimeout(() => this.connect(), 2000);
    };
  }

  public disconnect() {
    this.ws?.close();
  }
}
```

