```typescript
// src/hooks/useAwarenessBroadcast.ts
import { useEffect, useRef } from "react";
import { awareness, CollaboratorState } from "@/lib/crdt/awareness";
import { Point, ViewportTransform } from "@/types/canvas";
import { screenToWorld } from "@/lib/matrix";

export function useAwarenessBroadcast(
  user: { id: string; name: string; color: string },
  viewport: ViewportTransform,
  selectedShapeId: string | null
) {
  const lastBroadcastTime = useRef(0);

  useEffect(() => {
    // Initialize local presence state
    awareness.setLocalStateField("user", user);
    awareness.setLocalStateField("selectedShapeId", selectedShapeId);
  }, [user, selectedShapeId]);

  const broadcastCursor = (screenPoint: Point | null) => {
    const now = performance.now();
    // Throttle to 30 updates per second (33ms interval)
    if (now - lastBroadcastTime.current < 33) return;
    lastBroadcastTime.current = now;

    const worldPoint = screenPoint ? screenToWorld(screenPoint, viewport) : null;

    awareness.setLocalState({
      user,
      cursor: worldPoint,
      selectedShapeId,
      lastUpdated: Date.now(),
    } as CollaboratorState);
  };

  return { broadcastCursor };
}
```

### Step 4 · GPU-Accelerated Remote Cursors Overlay
Create `src/components/RemoteCursors.tsx`. This component renders cursor pointers with smooth CSS transitions:

```tsx
// src/components/RemoteCursors.tsx
"use client";

import { useEffect, useState } from "react";
import { awareness, CollaboratorState } from "@/lib/crdt/awareness";
import { ydoc } from "@/lib/crdt/doc";
import { ViewportTransform } from "@/types/canvas";
import { worldToScreen } from "@/lib/matrix";
import { Navigation } from "lucide-react";

interface RemoteCursorsProps {
  viewport: ViewportTransform;
}

export function RemoteCursors({ viewport }: RemoteCursorsProps) {
  const [peers, setPeers] = useState<{ clientId: number; state: CollaboratorState }[]>([]);

  useEffect(() => {
    const updatePeers = () => {
      const states = awareness.getStates();
      const peerList: { clientId: number; state: CollaboratorState }[] = [];

      states.forEach((state, clientId) => {
        if (clientId !== ydoc.clientID && state.user && state.cursor) {
          peerList.push({ clientId, state: state as CollaboratorState });
        }
      });

      setPeers(peerList);
    };

    awareness.on("change", updatePeers);
    return () => awareness.off("change", updatePeers);
  }, []);

  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden z-30">
      {peers.map(({ clientId, state }) => {
        if (!state.cursor) return null;
        const screenPoint = worldToScreen(state.cursor, viewport);

        return (
          <div
            key={clientId}
            className="absolute top-0 left-0 transition-transform duration-75 ease-out will-change-transform"
            style={{
              transform: `translate3d(${screenPoint.x}px, ${screenPoint.y}px, 0)`,
            }}
          >
            {/* Cursor Pointer Icon */}
            <Navigation
              className="h-4 w-4 -rotate-90 fill-current filter drop-shadow-md"
              style={{ color: state.user.color }}
            />

            {/* Collaborator Name Tag */}
            <div
              className="ml-4 -mt-1 rounded-md px-2 py-0.5 font-sans text-[11px] font-semibold text-stone-950 shadow-md whitespace-nowrap"
              style={{ backgroundColor: state.user.color }}
            >
              {state.user.name}
            </div>
          </div>
        );
      })}
    </div>
  );
}
```

### Step 5 · Render Multi-User Colored Selection Boxes
Modify `src/lib/renderer.ts` to draw colored selection frames around shapes selected by remote peers:

```typescript
// In src/lib/renderer.ts
import { awareness, CollaboratorState } from "@/lib/crdt/awareness";
import { ydoc } from "@/lib/crdt/doc";

export function renderRemoteSelections(
  ctx: CanvasRenderingContext2D,
  shapes: CanvasShape[],
  viewport: ViewportTransform,
  dpr: number
) {
  const states = awareness.getStates();

  states.forEach((state, clientId) => {
    if (clientId === ydoc.clientID) return;
    const collab = state as CollaboratorState;
    if (!collab.selectedShapeId) return;

    const target = shapes.find((s) => s.id === collab.selectedShapeId);
    if (!target) return;

    // Draw remote selection outline
    ctx.save();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const screen = worldToScreen({ x: target.x, y: target.y }, viewport);

    ctx.strokeStyle = collab.user.color;
    ctx.lineWidth = 2;
    ctx.strokeRect(screen.x, screen.y, target.w * viewport.zoom, target.h * viewport.zoom);

    // Label tag on top
    ctx.fillStyle = collab.user.color;
    ctx.font = "10px sans-serif";
    ctx.fillText(collab.user.name, screen.x, Math.max(screen.y - 4, 12));
    ctx.restore();
  });
}
```

