### Step 7 · Aggregated Board Hierarchy Query
Add a full-board relational query to `BoardsRepository` that fetches the board, all columns, and all cards in a single query using PostgreSQL `json_agg`:

```typescript
// Add to src/repositories/boards.repo.ts
export interface FullBoardData extends BoardEntity {
  columns: Array<ColumnEntity & { cards: CardEntity[] }>;
}

public static async getFullBoard(boardId: number): Promise<FullBoardData | null> {
  const query = `
    SELECT 
      b.*,
      COALESCE(
        json_agg(
          json_build_object(
            'id', c.id,
            'board_id', c.board_id,
            'title', c.title,
            'rank', c.rank,
            'cards', COALESCE(
              (SELECT json_agg(cd.* ORDER BY cd.rank ASC) 
               FROM cards cd WHERE cd.column_id = c.id),
              '[]'::json
            )
          ) ORDER BY c.rank ASC
        ) FILTER (WHERE c.id IS NOT NULL),
        '[]'::json
      ) as columns
    FROM boards b
    LEFT JOIN columns c ON c.board_id = b.id
    WHERE b.id = $1
    GROUP BY b.id;
  `;
  const { rows } = await pool.query<FullBoardData>(query, [boardId]);
  return rows[0] || null;
}
```

