    queryKey: kanbanKeys.board(boardId),
    queryFn: () => apiClient<Board>(`/boards/${boardId}`),
    staleTime: 1000 * 60, // Data fresh for 1 minute
  });
}

export function useCreateCard(boardId: number) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data: { columnId: number; title: string; description?: string; rank: string }) =>
      apiClient<Card>("/cards", {
        method: "POST",
        body: JSON.stringify(data),
      }),
    onSuccess: () => {
      // Invalidate board query to refetch updated card list
      queryClient.invalidateQueries({ queryKey: kanbanKeys.board(boardId) });
    },
  });
}
