// src/utils/fractional.ts
import { generateKeyBetween } from "fractional-indexing";

/**
 * Calculates a lexicographical midpoint rank string between two neighbor cards.
 * If inserting at the very top, prevRank is null.
 * If inserting at the very bottom, nextRank is null.
 */
export function computeRankBetween(prevRank: string | null, nextRank: string | null): string {
  return generateKeyBetween(prevRank, nextRank);
}
```

### Step 3 · Optimistic Card Reorder Mutation Hook
Create `web/src/hooks/useMoveCard.ts`:

```typescript
// src/hooks/useMoveCard.ts
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiClient } from "@/api/client";
import { Board, kanbanKeys } from "./useBoard";

interface MoveCardPayload {
  cardId: number;
  sourceColumnId: number;
  targetColumnId: number;
  newRank: string;
  boardId: number;
}

export function useMoveCard() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ cardId, targetColumnId, newRank }: MoveCardPayload) =>
      apiClient(`/cards/${cardId}/move`, {
        method: "PATCH",
        body: JSON.stringify({ targetColumnId, newRank }),
      }),

    // 1. Optimistic Update: Modify local cache immediately
    onMutate: async (newMove) => {
      const queryKey = kanbanKeys.board(newMove.boardId);
      await queryClient.cancelQueries({ queryKey });

      // Snapshot current board state
      const previousBoard = queryClient.getQueryData<Board>(queryKey);

      if (previousBoard) {
        // Deep copy board and reposition card optimistically
        const updatedColumns = previousBoard.columns.map((col) => {
          // Remove card from source column
          if (col.id === newMove.sourceColumnId) {
            return {
              ...col,
              cards: col.cards.filter((c) => c.id !== newMove.cardId),
            };
          }
          // Insert card into target column
          if (col.id === newMove.targetColumnId) {
            const movedCard = previousBoard.columns
              .flatMap((c) => c.cards)
              .find((c) => c.id === newMove.cardId);

            if (!movedCard) return col;
            const updatedCard = { ...movedCard, column_id: newMove.targetColumnId, rank: newMove.newRank };
            const newCards = [...col.cards, updatedCard].sort((a, b) => a.rank.localeCompare(b.rank));
            return { ...col, cards: newCards };
          }
          return col;
        });

        queryClient.setQueryData<Board>(queryKey, { ...previousBoard, columns: updatedColumns });
      }

      return { previousBoard, queryKey };
    },

    // 2. Rollback to snapshot on network failure
    onError: (_err, _variables, context) => {
      if (context?.previousBoard) {
        queryClient.setQueryData(context.queryKey, context.previousBoard);
        alert("Network error: Card movement rolled back.");
      }
    },

    // 3. Reconcile with ground truth
    onSettled: (_data, _error, variables) => {
      queryClient.invalidateQueries({ queryKey: kanbanKeys.board(variables.boardId) });
    },
  });
}
```

