### Step 6 · DragDropContext Handler & Midpoint Calculation
Update `web/src/components/KanbanBoard.tsx` with `onDragEnd` reordering math:

```tsx
// In src/components/KanbanBoard.tsx
import { DragDropContext, DropResult } from "@hello-pangea/dnd";
import { useMoveCard } from "@/hooks/useMoveCard";
import { computeRankBetween } from "@/utils/fractional";

export function KanbanBoard({ boardId }: { boardId: number }) {
  const { data: board } = useBoard(boardId);
  const moveCard = useMoveCard();

  const handleDragEnd = (result: DropResult) => {
    const { destination, source, draggableId } = result;
    if (!destination || !board) return;

    // If dropped in the exact same spot, do nothing
    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const cardId = Number(draggableId);
    const sourceColId = Number(source.droppableId);
    const targetColId = Number(destination.droppableId);

    const targetColumn = board.columns.find((c) => c.id === targetColId);
    if (!targetColumn) return;

    // Get cards in target column (excluding the moving card if within same column)
    const targetCards = targetColumn.cards.filter((c) => c.id !== cardId);

    // Compute neighbors in destination index
    const prevCard = targetCards[destination.index - 1];
    const nextCard = targetCards[destination.index];

    const prevRank = prevCard?.rank ?? null;
    const nextRank = nextCard?.rank ?? null;

    const newRank = computeRankBetween(prevRank, nextRank);

    moveCard.mutate({
      cardId,
      sourceColumnId: sourceColId,
      targetColumnId: targetColId,
      newRank,
      boardId,
    });
  };

  return (
    <DragDropContext onDragEnd={handleDragEnd}>
      <div className="flex gap-6 overflow-x-auto pb-6">
        {board?.columns.map((column) => (
          <KanbanColumn key={column.id} column={column} onAddCard={...} />
        ))}
      </div>
    </DragDropContext>
  );
}
```

