### Step 3 · Discriminated Union Protocol Envelopes

Define the strict wire contract in `src/protocol/envelope.ts`. Using a discriminated union on the `type` field allows TypeScript and Zod to statically enforce payload shapes.

Create `src/protocol/envelope.ts`:

```typescript
import { z } from 'zod';

// Client to Server Actions
export const JoinRoomSchema = z.object({
  type: z.literal('ROOM_JOIN'),
  roomId: z.string().min(1).max(64),
});

export const LeaveRoomSchema = z.object({
  type: z.literal('ROOM_LEAVE'),
  roomId: z.string().min(1).max(64),
});

export const SendMessageSchema = z.object({
  type: z.literal('CHAT_MESSAGE_SEND'),
  roomId: z.string().min(1).max(64),
  content: z.string().min(1).max(4000),
  clientMsgId: z.string().uuid(), // Idempotency key from client
});

export const TypingStatusSchema = z.object({
  type: z.literal('TYPING_STATUS'),
  roomId: z.string().min(1).max(64),
  isTyping: z.boolean(),
});

export const InboundEnvelopeSchema = z.discriminatedUnion('type', [
  JoinRoomSchema,
  LeaveRoomSchema,
  SendMessageSchema,
  TypingStatusSchema,
]);

export type InboundEnvelope = z.infer<typeof InboundEnvelopeSchema>;

// Server to Client Events
export interface ServerEnvelope<T = unknown> {
  type: 'ACK' | 'CHAT_MESSAGE_BROADCAST' | 'PRESENCE_SYNC' | 'TYPING_UPDATE' | 'ERROR';
  payload: T;
  timestamp: number;
  correlationId?: string;
}

export function makeServerEnvelope<T>(type: ServerEnvelope<T>['type'], payload: T, correlationId?: string): string {
  return JSON.stringify({
    type,
    payload,
    timestamp: Date.now(),
    correlationId,
  });
}
