### Step 4 · Extended Socket Interface & Connection Registry

Create `src/server/connection-registry.ts` to manage active sockets, their metadata, and room memberships without memory leaks.

```typescript
import { WebSocket } from 'ws';

export interface TrackedSocket extends WebSocket {
  id: string;
  userId: string;
  isAlive: boolean;
  joinedRooms: Set<string>;
}

export class ConnectionRegistry {
  private sockets = new Map<string, TrackedSocket>();
  private roomMembers = new Map<string, Set<string>>(); // roomId -> Set<socketId>

  public register(socket: TrackedSocket): void {
    this.sockets.set(socket.id, socket);
  }

  public unregister(socketId: string): void {
    const socket = this.sockets.get(socketId);
    if (!socket) return;

    for (const roomId of socket.joinedRooms) {
      this.leaveRoom(socketId, roomId);
    }
    this.sockets.delete(socketId);
  }

  public joinRoom(socketId: string, roomId: string): void {
    const socket = this.sockets.get(socketId);
    if (!socket) return;

    socket.joinedRooms.add(roomId);
    if (!this.roomMembers.has(roomId)) {
      this.roomMembers.set(roomId, new Set());
    }
    this.roomMembers.get(roomId)!.add(socketId);
  }

  public leaveRoom(socketId: string, roomId: string): void {
    const socket = this.sockets.get(socketId);
    if (socket) {
      socket.joinedRooms.delete(roomId);
    }
    const members = this.roomMembers.get(roomId);
    if (members) {
      members.delete(socketId);
      if (members.size === 0) {
        this.roomMembers.delete(roomId);
      }
    }
  }

  public getRoomSockets(roomId: string): TrackedSocket[] {
    const memberIds = this.roomMembers.get(roomId);
    if (!memberIds) return [];
    const result: TrackedSocket[] = [];
    for (const id of memberIds) {
      const s = this.sockets.get(id);
      if (s && s.readyState === WebSocket.OPEN) {
        result.push(s);
      }
    }
    return result;
  }

  public get(socketId: string): TrackedSocket | undefined {
    return this.sockets.get(socketId);
  }

  public getAll(): TrackedSocket[] {
    return Array.from(this.sockets.values());
  }
}

export const registry = new ConnectionRegistry();
```

