### Step 5 · Heartbeat Daemon & Zombie Reaper

Create `src/server/heartbeat.ts` to detect and disconnect un-ponged sockets.

```typescript
import { ConnectionRegistry, TrackedSocket } from './connection-registry.js';
import { env } from '../config/env.js';

export function setupHeartbeat(registry: ConnectionRegistry): NodeJS.Timeout {
  return setInterval(() => {
    const sockets = registry.getAll();
    for (const socket of sockets) {
      if (!socket.isAlive) {
        console.warn(`[Heartbeat] Terminating inactive socket: ${socket.id} (user: ${socket.userId})`);
        socket.terminate();
        registry.unregister(socket.id);
        continue;
      }
      // Reset alive flag before pinging; the pong callback will set it back to true
      socket.isAlive = false;
      socket.ping();
    }
  }, env.HEARTBEAT_INTERVAL_MS);
}
```

