### Step 6 · Message Dispatcher & Inbound Frame Validator

Create `src/server/message-dispatcher.ts` to parse, validate, and safely route incoming WebSocket messages.

```typescript
import { RawData } from 'ws';
import { InboundEnvelopeSchema, makeServerEnvelope } from '../protocol/envelope.js';
import { TrackedSocket, registry } from './connection-registry.js';

export function handleInboundMessage(socket: TrackedSocket, rawData: RawData): void {
  let rawString: string;
  try {
    rawString = rawData.toString();
  } catch (err) {
    socket.send(makeServerEnvelope('ERROR', { code: 'INVALID_UTF8', message: 'Payload must be UTF-8 string' }));
    return;
  }

  let jsonPayload: unknown;
  try {
    jsonPayload = JSON.parse(rawString);
  } catch (err) {
    socket.send(makeServerEnvelope('ERROR', { code: 'MALFORMED_JSON', message: 'Unable to parse JSON frame' }));
    return;
  }

  const parseResult = InboundEnvelopeSchema.safeParse(jsonPayload);
  if (!parseResult.success) {
    socket.send(makeServerEnvelope('ERROR', {
      code: 'VALIDATION_FAILED',
      message: 'Frame structure rejected',
      details: parseResult.error.flatten(),
    }));
    return;
  }

  const message = parseResult.data;
  switch (message.type) {
    case 'ROOM_JOIN': {
      registry.joinRoom(socket.id, message.roomId);
      socket.send(makeServerEnvelope('ACK', { action: 'ROOM_JOINED', roomId: message.roomId }));
      break;
    }
    case 'ROOM_LEAVE': {
      registry.leaveRoom(socket.id, message.roomId);
      socket.send(makeServerEnvelope('ACK', { action: 'ROOM_LEFT', roomId: message.roomId }));
      break;
    }
    case 'CHAT_MESSAGE_SEND': {
      // Broadcast locally to room members
      const recipients = registry.getRoomSockets(message.roomId);
      const broadcastPayload = makeServerEnvelope('CHAT_MESSAGE_BROADCAST', {
        roomId: message.roomId,
        senderId: socket.userId,
        content: message.content,
        clientMsgId: message.clientMsgId,
        serverMsgId: crypto.randomUUID(),
      });

      for (const peer of recipients) {
        peer.send(broadcastPayload);
      }
      break;
    }
    case 'TYPING_STATUS': {
      const peers = registry.getRoomSockets(message.roomId).filter((s) => s.id !== socket.id);
      const typingPayload = makeServerEnvelope('TYPING_UPDATE', {
        roomId: message.roomId,
        userId: socket.userId,
        isTyping: message.isTyping,
      });
      for (const peer of peers) {
        peer.send(typingPayload);
      }
      break;
    }
  }
}
```

