### Step 7 · Master WebSocket Server Factory

Create `src/server/ws-server.ts` to bind the WebSocket server to an HTTP listener with connection events and resource tracking.

```typescript
import { createServer, Server as HttpServer } from 'http';
import { WebSocketServer, WebSocket } from 'ws';
import { v4 as uuidv4 } from 'uuid';
import { env } from '../config/env.js';
import { TrackedSocket, registry } from './connection-registry.js';
import { setupHeartbeat } from './heartbeat.js';
import { handleInboundMessage } from './message-dispatcher.js';

export function createChatServer(): { httpServer: HttpServer; wss: WebSocketServer } {
  const httpServer = createServer((req, res) => {
    if (req.url === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ status: 'healthy', timestamp: Date.now() }));
      return;
    }
    res.writeHead(404);
    res.end();
  });

  const wss = new WebSocketServer({
    server: httpServer,
    maxPayload: env.MAX_PAYLOAD_BYTES,
    clientTracking: false, // We use our own custom ConnectionRegistry
  });

  setupHeartbeat(registry);

  wss.on('connection', (rawSocket: WebSocket, req) => {
    const socket = rawSocket as TrackedSocket;
    socket.id = uuidv4();
    socket.userId = (req.headers['x-user-id'] as string) || `guest-${socket.id.slice(0, 6)}`;
    socket.isAlive = true;
    socket.joinedRooms = new Set();

    registry.register(socket);

    socket.on('pong', () => {
      socket.isAlive = true;
    });

    socket.on('message', (data) => {
      handleInboundMessage(socket, data);
    });

    socket.on('close', (code, reason) => {
      registry.unregister(socket.id);
    });

    socket.on('error', (err) => {
      console.error(`[Socket Error] ${socket.id}:`, err);
      registry.unregister(socket.id);
    });
  });

  return { httpServer, wss };
}
```

