### Step 2 · JWT Verification Service with Strict Claim Types

Create `src/auth/jwt-verifier.ts` to verify signatures, check expiration timestamps, and decode payload claims.

```typescript
import jwt from 'jsonwebtoken';
import { env } from '../config/env.js';

export interface AuthClaims {
  sub: string;       // User ID
  email: string;
  role: 'user' | 'admin';
  sessionId: string;
}

export class AuthError extends Error {
  constructor(public code: string, message: string) {
    super(message);
    this.name = 'AuthError';
  }
}

export function verifyToken(token: string): AuthClaims {
  try {
    const decoded = jwt.verify(token, env.JWT_SECRET, {
      algorithms: ['HS256'],
    }) as AuthClaims;
    return decoded;
  } catch (err: any) {
    if (err.name === 'TokenExpiredError') {
      throw new AuthError('TOKEN_EXPIRED', 'JWT token has expired');
    }
    throw new AuthError('INVALID_TOKEN', 'JWT signature verification failed');
  }
}

export function signDevToken(claims: Partial<AuthClaims>): string {
  return jwt.sign(
    {
      sub: claims.sub || 'user-1',
      email: claims.email || 'dev@buildscape.io',
      role: claims.role || 'user',
      sessionId: claims.sessionId || crypto.randomUUID(),
    },
    env.JWT_SECRET,
    { expiresIn: '2h' }
  );
}
```

