### Step 3 · Multi-Strategy Token Extractor

Create `src/auth/token-extractor.ts` to extract credentials from either the query string or the `Sec-WebSocket-Protocol` header.

```typescript
import { IncomingMessage } from 'http';

export function extractToken(req: IncomingMessage): { token: string | null; subprotocol?: string } {
  // 1. Check Sec-WebSocket-Protocol (Preferred for browsers)
  const protocols = req.headers['sec-websocket-protocol'];
  if (protocols) {
    const parts = protocols.split(',').map((p) => p.trim());
    // Look for format: ['buildscape-auth', '<JWT>']
    const authIndex = parts.indexOf('buildscape-auth');
    if (authIndex !== -1 && parts[authIndex + 1]) {
      return { token: parts[authIndex + 1], subprotocol: 'buildscape-auth' };
    }
  }

  // 2. Fallback to URL search parameters (?token=...)
  if (req.url) {
    try {
      const host = req.headers.host || 'localhost';
      const url = new URL(req.url, `http://${host}`);
      const token = url.searchParams.get('token');
      if (token) return { token };
    } catch (e) {
      return { token: null };
    }
  }

  return { token: null };
}
```

