### Step 5 · Sliding Token-Bucket Rate Limiter

Create `src/security/rate-limiter.ts` to throttle connection rates per IP and message throughput per active socket.

```typescript
export class TokenBucketRateLimiter {
  private buckets = new Map<string, { tokens: number; lastRefill: number }>();

  constructor(
    private capacity: number,
    private refillRatePerSec: number
  ) {}

  public tryConsume(key: string, tokensRequested = 1): boolean {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill tokens based on elapsed time
      const elapsedSec = (now - bucket.lastRefill) / 1000;
      bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsedSec * this.refillRatePerSec);
      bucket.lastRefill = now;
    }

    if (bucket.tokens >= tokensRequested) {
      bucket.tokens -= tokensRequested;
      return true;
    }
    return false;
  }

  public prune(maxIdleMs = 60000): void {
    const now = Date.now();
    for (const [key, val] of this.buckets.entries()) {
      if (now - val.lastRefill > maxIdleMs) {
        this.buckets.delete(key);
      }
    }
  }
}

export const ipConnectionLimiter = new TokenBucketRateLimiter(20, 2); // Burst 20, 2 per sec
export const messageLimiter = new TokenBucketRateLimiter(15, 10);     // Burst 15, 10 per sec
```

