### Step 7 · Integrated HTTP Upgrade Interceptor

Update `src/server/ws-server.ts` to take full control of the HTTP `upgrade` event via `noServer: true`.

```typescript
import { createServer, Server as HttpServer, IncomingMessage } from 'http';
import { WebSocketServer, WebSocket } from 'ws';
import { Socket } from 'net';
import { v4 as uuidv4 } from 'uuid';
import { env } from '../config/env.js';
import { registry, AuthenticatedSocket } from './connection-registry.js';
import { extractToken } from '../auth/token-extractor.js';
import { verifyToken } from '../auth/jwt-verifier.js';
import { validateOrigin } from '../security/origin-guard.js';
import { ipConnectionLimiter, messageLimiter } from '../security/rate-limiter.js';
import { setupHeartbeat } from './heartbeat.js';
import { handleInboundMessage } from './message-dispatcher.js';
import { makeServerEnvelope } from '../protocol/envelope.js';

export function createSecureChatServer(): { httpServer: HttpServer; wss: WebSocketServer } {
  const httpServer = createServer((req, res) => {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'active', secure: true }));
  });

  const wss = new WebSocketServer({ noServer: true, maxPayload: env.MAX_PAYLOAD_BYTES });
  setupHeartbeat(registry);

  httpServer.on('upgrade', (req: IncomingMessage, socket: Socket, head: Buffer) => {
    const clientIp = req.socket.remoteAddress || 'unknown';

    // 1. IP Rate Limiting
    if (!ipConnectionLimiter.tryConsume(clientIp)) {
      socket.write('HTTP/1.1 429 Too Many Requests\r\nRetry-After: 5\r\n\r\n');
      socket.destroy();
      return;
    }

    // 2. Validate Origin
    if (!validateOrigin(req)) {
      socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
      socket.destroy();
      return;
    }

    // 3. Extract & Validate JWT
    const { token, subprotocol } = extractToken(req);
    if (!token) {
      socket.write('HTTP/1.1 401 Unauthorized\r\nContent-Type: text/plain\r\n\r\nMissing authentication token');
      socket.destroy();
      return;
    }

    let claims;
    try {
      claims = verifyToken(token);
    } catch (err: any) {
      socket.write(`HTTP/1.1 401 Unauthorized\r\nContent-Type: text/plain\r\n\r\n${err.message}`);
      socket.destroy();
      return;
    }

    // 4. Complete Upgrade Handshake
    wss.handleUpgrade(req, socket, head, (ws) => {
      const authSocket = ws as AuthenticatedSocket;
      authSocket.id = uuidv4();
      authSocket.userId = claims.sub;
      authSocket.claims = claims;
      authSocket.isAlive = true;
      authSocket.joinedRooms = new Set();

      registry.register(authSocket);
      wss.emit('connection', authSocket, req);
    });
  });

  wss.on('connection', (socket: AuthenticatedSocket) => {
    socket.on('pong', () => {
      socket.isAlive = true;
    });

    socket.on('message', (data) => {
      // Per-socket message throughput rate-limiting
      if (!messageLimiter.tryConsume(socket.id)) {
        socket.send(makeServerEnvelope('ERROR', {
          code: 'RATE_LIMIT_EXCEEDED',
          message: 'Message rate limit exceeded (max 10 msgs/sec)',
        }));
        return;
      }
      handleInboundMessage(socket, data);
    });

    socket.on('close', () => registry.unregister(socket.id));
    socket.on('error', () => registry.unregister(socket.id));
  });

  return { httpServer, wss };
}
```

