### Step 5 · Dynamic Subscription Manager with Local Reference Counting

Create `src/rooms/distributed-room-manager.ts`. To conserve Redis memory, an instance subscribes to `chat:room:<id>` only when the **first** local client joins that room, and unsubscribes when the **last** local client leaves.

```typescript
import { redisSub, redisPub } from '../redis/redis-client.js';
import { getRoomChannel, RedisRoomMessage, REDIS_ROOM_PREFIX } from '../pubsub/pubsub-types.js';
import { registry } from '../server/connection-registry.js';
import { makeServerEnvelope } from '../protocol/envelope.js';
import { env } from '../config/env.js';

export class DistributedRoomManager {
  private activeSubscriptions = new Set<string>();

  constructor() {
    this.initSubscriberListener();
  }

  private initSubscriberListener(): void {
    redisSub.on('message', (channel: string, rawPayload: string) => {
      if (!channel.startsWith(REDIS_ROOM_PREFIX)) return;
      const roomId = channel.slice(REDIS_ROOM_PREFIX.length);

      let payload: RedisRoomMessage;
      try {
        payload = JSON.parse(rawPayload);
      } catch (err) {
        console.error('[PubSub] Failed to parse Redis message:', err);
        return;
      }

      // Demultiplex to local sockets joined to this room
      const localSockets = registry.getRoomSockets(roomId);
      const broadcastFrame = makeServerEnvelope('CHAT_MESSAGE_BROADCAST', {
        roomId: payload.roomId,
        senderId: payload.senderId,
        content: payload.content,
        clientMsgId: payload.clientMsgId,
        serverMsgId: payload.serverMsgId,
      });

      for (const socket of localSockets) {
        // Suppress echo to the originating sender socket
        if (payload.originInstanceId === env.INSTANCE_ID && payload.originSocketId === socket.id) {
          continue;
        }
        socket.send(broadcastFrame);
      }
    });
  }

  public async joinRoom(socketId: string, roomId: string): Promise<void> {
    registry.joinRoom(socketId, roomId);

    // If this is our instance's first local subscriber to this room, subscribe on Redis
    if (!this.activeSubscriptions.has(roomId)) {
      this.activeSubscriptions.add(roomId);
      const channel = getRoomChannel(roomId);
      await redisSub.subscribe(channel);
      console.log(`[Redis Sub] Subscribed to channel ${channel}`);
    }
  }

  public async leaveRoom(socketId: string, roomId: string): Promise<void> {
    registry.leaveRoom(socketId, roomId);

    // If no local sockets remain in this room, unsubscribe from Redis
    const remainingLocal = registry.getRoomSockets(roomId);
    if (remainingLocal.length === 0 && this.activeSubscriptions.has(roomId)) {
      this.activeSubscriptions.delete(roomId);
      const channel = getRoomChannel(roomId);
      await redisSub.unsubscribe(channel);
      console.log(`[Redis Sub] Unsubscribed from channel ${channel}`);
    }
  }

  public async publishToRoom(message: Omit<RedisRoomMessage, 'originInstanceId'>): Promise<void> {
    const fullPayload: RedisRoomMessage = {
      ...message,
      originInstanceId: env.INSTANCE_ID,
    };
    const channel = getRoomChannel(message.roomId);
    await redisPub.publish(channel, JSON.stringify(fullPayload));
  }
}

export const roomManager = new DistributedRoomManager();
```

