### Step 3 · Message Repository with Keyset Queries

Create `src/repositories/message-repository.ts`:

```typescript
import { pool } from '../db/pool.js';

export interface PersistedMessage {
  id: string;
  roomId: string;
  senderId: string;
  content: string;
  clientMsgId: string;
  createdAt: string;
}

export interface KeysetPaginationResult {
  messages: PersistedMessage[];
  nextCursor: string | null;
  hasMore: boolean;
}

export class MessageRepository {
  public async saveMessage(
    roomId: string,
    senderId: string,
    content: string,
    clientMsgId: string
  ): Promise<PersistedMessage> {
    const query = `
      INSERT INTO messages (room_id, sender_id, content, client_msg_id)
      VALUES ($1, $2, $3, $4)
      ON CONFLICT (client_msg_id) DO UPDATE SET content = EXCLUDED.content
      RETURNING id::text, room_id AS "roomId", sender_id AS "senderId", 
                content, client_msg_id AS "clientMsgId", created_at AS "createdAt";
    `;
    const res = await pool.query(query, [roomId, senderId, content, clientMsgId]);
    return res.rows[0];
  }

  public async getHistory(
    roomId: string,
    cursorId?: string,
    limit = 50
  ): Promise<KeysetPaginationResult> {
    const safeLimit = Math.min(Math.max(limit, 1), 100);

    let query: string;
    let params: any[];

    if (cursorId) {
      query = `
        SELECT id::text, room_id AS "roomId", sender_id AS "senderId", 
               content, client_msg_id AS "clientMsgId", created_at AS "createdAt"
        FROM messages
        WHERE room_id = $1 AND id < $2
        ORDER BY id DESC
        LIMIT $3;
      `;
      params = [roomId, cursorId, safeLimit + 1];
    } else {
      query = `
        SELECT id::text, room_id AS "roomId", sender_id AS "senderId", 
               content, client_msg_id AS "clientMsgId", created_at AS "createdAt"
        FROM messages
        WHERE room_id = $1
        ORDER BY id DESC
        LIMIT $2;
      `;
      params = [roomId, safeLimit + 1];
    }

    const res = await pool.query(query, params);
    const hasMore = res.rows.length > safeLimit;
    const rows = hasMore ? res.rows.slice(0, safeLimit) : res.rows;
    const nextCursor = rows.length > 0 ? rows[rows.length - 1].id : null;

    return {
      messages: rows,
      nextCursor: hasMore ? nextCursor : null,
      hasMore,
    };
  }
}

export const messageRepo = new MessageRepository();
```

