### Step 6 · REST Keyset Pagination API Endpoint

Create `src/http/history-controller.ts` providing an HTTP GET route for initial history load and upward infinite scrolling.

```typescript
import { IncomingMessage, ServerResponse } from 'http';
import { messageRepo } from '../repositories/message-repository.js';
import { verifyToken } from '../auth/jwt-verifier.js';

export async function handleHistoryRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url!, `http://${req.headers.host}`);
  const roomId = url.searchParams.get('roomId');
  const cursor = url.searchParams.get('cursor') || undefined;
  const limit = Number(url.searchParams.get('limit')) || 50;

  // Auth validation
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Missing Bearer token' }));
    return;
  }

  try {
    verifyToken(authHeader.split(' ')[1]);
  } catch (err: any) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.message }));
    return;
  }

  if (!roomId) {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'roomId query parameter is required' }));
    return;
  }

  try {
    const history = await messageRepo.getHistory(roomId, cursor, limit);
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(history));
  } catch (err) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Database query failed' }));
  }
}
```

