```typescript
import { ChatMessage } from '../types/chat.js';

export type ChatAction =
  | { type: 'SET_HISTORY'; messages: ChatMessage[] }
  | { type: 'PREPEND_HISTORY'; messages: ChatMessage[] }
  | { type: 'ADD_OPTIMISTIC'; message: ChatMessage }
  | { type: 'RECONCILE_ACK'; clientMsgId: string; serverMsgId: string }
  | { type: 'RECEIVE_BROADCAST'; message: ChatMessage }
  | { type: 'MARK_FAILED'; clientMsgId: string };

export function chatReducer(state: ChatMessage[], action: ChatAction): ChatMessage[] {
  switch (action.type) {
    case 'SET_HISTORY':
      return action.messages;

    case 'PREPEND_HISTORY': {
      // Keyset pagination prepend: filter out duplicates
      const existingIds = new Set(state.map((m) => m.clientMsgId));
      const uniqueIncoming = action.messages.filter((m) => !existingIds.has(m.clientMsgId));
      return [...uniqueIncoming, ...state];
    }

    case 'ADD_OPTIMISTIC':
      return [...state, action.message];

    case 'RECONCILE_ACK':
      return state.map((m) => {
        if (m.clientMsgId === action.clientMsgId) {
          return { ...m, id: action.serverMsgId, status: 'SENT' };
        }
        return m;
      });

    case 'RECEIVE_BROADCAST': {
      // Check if message is already present (e.g. self echo)
      const exists = state.some((m) => m.clientMsgId === action.message.clientMsgId);
      if (exists) {
        return state.map((m) =>
          m.clientMsgId === action.message.clientMsgId ? { ...m, status: 'SENT' } : m
        );
      }
      return [...state, action.message];
    }

    case 'MARK_FAILED':
      return state.map((m) =>
        m.clientMsgId === action.clientMsgId ? { ...m, status: 'FAILED' } : m
      );

    default:
      return state;
  }
}
```

