### Step 5 · The Complete `useChat` Lifecycle Hook

Create `frontend/hooks/useChat.ts`:

```typescript
import { useEffect, useReducer, useRef, useState, useCallback } from 'react';
import { ChatMessage, UseChatOptions } from '../types/chat.js';
import { chatReducer } from '../reducers/chatReducer.js';
import { BackoffManager } from '../utils/backoff.js';
import { OutboundQueue } from '../utils/message-queue.js';

export function useChat({ roomId, token, wsUrl, apiBaseUrl }: UseChatOptions) {
  const [messages, dispatch] = useReducer(chatReducer, []);
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'DISCONNECTED'>('CONNECTING');
  const [isTypingUsers, setIsTypingUsers] = useState<string[]>([]);

  const wsRef = useRef<WebSocket | null>(null);
  const backoffRef = useRef(new BackoffManager());
  const queueRef = useRef(new OutboundQueue());
  const isMountedRef = useRef(true);

  // Initial History Fetch via Keyset API
  const fetchInitialHistory = useCallback(async () => {
    try {
      const res = await fetch(`${apiBaseUrl}/api/messages?roomId=${roomId}&limit=50`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Failed to load history');
      const data = await res.json();
      const formatted: ChatMessage[] = data.messages.reverse().map((m: any) => ({
        id: m.id,
        clientMsgId: m.clientMsgId,
        roomId: m.roomId,
        senderId: m.senderId,
        content: m.content,
        status: 'SENT',
        createdAt: new Date(m.createdAt).getTime(),
      }));
      dispatch({ type: 'SET_HISTORY', messages: formatted });
    } catch (err) {
      console.error('[History Load Error]', err);
    }
  }, [roomId, token, apiBaseUrl]);

  useEffect(() => {
    isMountedRef.current = true;
    fetchInitialHistory();

    let reconnectTimer: NodeJS.Timeout;

    const connect = () => {
      if (!isMountedRef.current) return;
      setConnectionStatus('CONNECTING');

      // Pass token via subprotocol for browser security
      const socket = new WebSocket(wsUrl, ['buildscape-auth', token]);
      wsRef.current = socket;

      socket.onopen = () => {
        if (!isMountedRef.current) return;
        setConnectionStatus('CONNECTED');
        backoffRef.current.reset();

        // Join current room
        socket.send(JSON.stringify({ type: 'ROOM_JOIN', roomId }));

        // Drain offline queue
        const queued = queueRef.current.drain();
        for (const item of queued) {
          socket.send(JSON.stringify({
            type: 'CHAT_MESSAGE_SEND',
            roomId: item.roomId,
            content: item.content,
            clientMsgId: item.clientMsgId,
          }));
        }
      };

      socket.onmessage = (event) => {
        try {
          const frame = JSON.parse(event.data);
          if (frame.type === 'ACK' && frame.payload.action === 'MESSAGE_PERSISTED') {
            dispatch({
              type: 'RECONCILE_ACK',
              clientMsgId: frame.payload.clientMsgId,
              serverMsgId: frame.payload.serverMsgId,
            });
          } else if (frame.type === 'CHAT_MESSAGE_BROADCAST') {
            dispatch({
              type: 'RECEIVE_BROADCAST',
              message: {
                id: frame.payload.serverMsgId,
                clientMsgId: frame.payload.clientMsgId,
                roomId: frame.payload.roomId,
                senderId: frame.payload.senderId,
                content: frame.payload.content,
                status: 'SENT',
                createdAt: frame.timestamp,
              },
            });
          } else if (frame.type === 'TYPING_UPDATE') {
            const { userId, isTyping } = frame.payload;
            setIsTypingUsers((prev) =>
              isTyping ? Array.from(new Set([...prev, userId])) : prev.filter((u) => u !== userId)
            );
          }
        } catch (e) {
          console.error('[Client Message Parse Error]', e);
        }
      };

      socket.onclose = () => {
        if (!isMountedRef.current) return;
        setConnectionStatus('DISCONNECTED');
        const delay = backoffRef.current.getNextDelay();
        console.log(`[WebSocket] Disconnected. Reconnecting in ${delay}ms...`);
        reconnectTimer = setTimeout(connect, delay);
      };

      socket.onerror = (err) => {
        console.error('[WebSocket Error]', err);
        socket.close();
      };
    };

    connect();

    return () => {
      isMountedRef.current = false;
      clearTimeout(reconnectTimer);
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, [roomId, token, wsUrl, fetchInitialHistory]);

  // Optimistic Send Action
  const sendMessage = useCallback((content: string) => {
    const clientMsgId = crypto.randomUUID();
    const optimisticMsg: ChatMessage = {
      id: clientMsgId,
      clientMsgId,
      roomId,
      senderId: 'me',
      content,
      status: 'PENDING',
      createdAt: Date.now(),
    };

    dispatch({ type: 'ADD_OPTIMISTIC', message: optimisticMsg });

    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({
        type: 'CHAT_MESSAGE_SEND',
        roomId,
        content,
        clientMsgId,
      }));
    } else {
      // Enqueue message to send immediately once reconnected
      queueRef.current.enqueue({ roomId, content, clientMsgId });
    }
  }, [roomId]);

  return { messages, sendMessage, connectionStatus, isTypingUsers };
}
```

