import { redisPub } from '../redis/redis-client.js';
import { getRoomChannel } from '../pubsub/pubsub-types.js';

export class TypingEngine {
  private static TYPING_TTL_SEC = 3;

  public async setTyping(roomId: string, userId: string, isTyping: boolean): Promise<void> {
    const key = `typing:${roomId}:${userId}`;
    const channel = getRoomChannel(roomId);

    if (isTyping) {
      await redisPub.set(key, '1', 'EX', TypingEngine.TYPING_TTL_SEC);
    } else {
      await redisPub.del(key);
    }

    // Broadcast typing update over Redis Pub/Sub
    const payload = JSON.stringify({
      type: 'TYPING_UPDATE',
      payload: { roomId, userId, isTyping },
      timestamp: Date.now(),
    });
    await redisPub.publish(channel, payload);
  }
}

export const typingEngine = new TypingEngine();
