import { redisPub } from '../redis/redis-client.js';

export function startPresenceWorker(sweepIntervalMs = 15000): NodeJS.Timeout {
  return setInterval(async () => {
    try {
      const keys = await redisPub.keys('presence:set:*');
      for (const setKey of keys) {
        const roomId = setKey.replace('presence:set:', '');
        const members = await redisPub.smembers(setKey);
        for (const member of members) {
          const isAlive = await redisPub.exists(`presence:${roomId}:${member}`);
          if (!isAlive) {
            await redisPub.srem(setKey, member);
            await presenceManager.broadcastPresenceDelta(roomId, member, false);
            console.log(`[Presence Sweep] Cleaned up expired presence for user ${member} in room ${roomId}`);
          }
        }
      }
    } catch (err) {
      console.error('[Presence Worker Error]', err);
    }
  }, sweepIntervalMs);
}
```

