### Step 5 · Order Finite State Machine Implementation

Create `src/domain/order-fsm.ts` to strictly govern state transitions.

```typescript
import { OrderStatus } from '@prisma/client';

export class InvalidStateTransitionError extends Error {
  constructor(public currentStatus: OrderStatus, public targetStatus: OrderStatus) {
    super(`Illegal order status transition from '${currentStatus}' to '${targetStatus}'`);
    this.name = 'InvalidStateTransitionError';
  }
}

const LEGAL_TRANSITIONS: Record<OrderStatus, readonly OrderStatus[]> = {
  PENDING: ['PAID', 'CANCELLED'],
  PAID: ['FULFILLED', 'REFUNDED'],
  FULFILLED: ['REFUNDED'],
  CANCELLED: [], // Terminal state
  REFUNDED: [],  // Terminal state
};

export class OrderStateMachine {
  public static canTransition(current: OrderStatus, target: OrderStatus): boolean {
    const allowed = LEGAL_TRANSITIONS[current];
    return allowed.includes(target);
  }

  public static assertCanTransition(current: OrderStatus, target: OrderStatus): void {
    if (!this.canTransition(current, target)) {
      throw new InvalidStateTransitionError(current, target);
    }
  }
}
```

