### Step 3 · Atomic Inventory Reservation Service

Create `src/services/inventory-service.ts` to execute atomic conditional updates inside a Prisma transaction.

```typescript
import { Prisma } from '@prisma/client';

export class InsufficientStockError extends Error {
  constructor(public sku: string, public requestedQty: number) {
    super(`Insufficient stock available for SKU '${sku}' (requested: ${requestedQty})`);
    this.name = 'InsufficientStockError';
  }
}

export class InventoryService {
  /**
   * Atomically reserve stock for a single variant.
   * Fails if available stock (stock - reserved) is less than qty.
   */
  public static async reserveVariantStock(
    tx: Prisma.TransactionClient,
    sku: string,
    qty: number
  ): Promise<void> {
    // Conditional atomic update serialized by PostgreSQL row-level write lock
    const rowsUpdated = await tx.$executeRaw`
      UPDATE "Variant"
      SET "reserved" = "reserved" + ${qty},
          "updatedAt" = NOW()
      WHERE "sku" = ${sku}
        AND ("stock" - "reserved") >= ${qty};
    `;

    if (rowsUpdated === 0) {
      throw new InsufficientStockError(sku, qty);
    }
  }

  /**
   * Release previously reserved stock (e.g., payment cancelled or cart timed out).
   */
  public static async releaseVariantStock(
    tx: Prisma.TransactionClient,
    sku: string,
    qty: number
  ): Promise<void> {
    await tx.$executeRaw`
      UPDATE "Variant"
      SET "reserved" = GREATEST(0, "reserved" - ${qty}),
          "updatedAt" = NOW()
      WHERE "sku" = ${sku};
    `;
  }

  /**
   * Finalize reservation after successful payment: deduct physical stock.
   */
  public static async commitVariantStock(
    tx: Prisma.TransactionClient,
    sku: string,
    qty: number
  ): Promise<void> {
    await tx.$executeRaw`
      UPDATE "Variant"
      SET "stock" = GREATEST(0, "stock" - ${qty}),
          "reserved" = GREATEST(0, "reserved" - ${qty}),
          "updatedAt" = NOW()
      WHERE "sku" = ${sku};
    `;
  }
}
```

