### Step 4 · Deadlock-Safe Multi-Item Reservation Coordinator

Create `src/services/reservation-coordinator.ts` that enforces deterministic SKU ordering before acquiring locks.

```typescript
import { prisma } from '../db/prisma.js';
import { InventoryService } from './inventory-service.js';

export interface ItemReservationRequest {
  sku: string;
  quantity: number;
}

export class ReservationCoordinator {
  public static async reserveItems(items: ItemReservationRequest[]): Promise<void> {
    // 1. Sort deterministically by SKU to eliminate deadlocks
    const sortedItems = [...items].sort((a, b) => a.sku.localeCompare(b.sku));

    // 2. Execute all reservations inside an interactive Prisma transaction
    await prisma.$transaction(async (tx) => {
      for (const item of sortedItems) {
        await InventoryService.reserveVariantStock(tx, item.sku, item.quantity);
      }
    }, {
      isolationLevel: 'ReadCommitted',
      timeout: 5000, // 5-second lock timeout
    });
  }

  public static async releaseItems(items: ItemReservationRequest[]): Promise<void> {
    await prisma.$transaction(async (tx) => {
      for (const item of items) {
        await InventoryService.releaseVariantStock(tx, item.sku, item.quantity);
      }
    });
  }
}
```

