import { Redis } from 'ioredis';
import { ItemReservationRequest } from './reservation-coordinator.js';

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

export class ReservationTTLService {
  private static TTL_SECONDS = 900; // 15-minute checkout reservation hold

  public static async trackHold(orderId: string, items: ItemReservationRequest[]): Promise<void> {
    const key = `reservation:hold:${orderId}`;
    await redis.set(key, JSON.stringify(items), 'EX', this.TTL_SECONDS);
  }

  public static async clearHold(orderId: string): Promise<void> {
    await redis.del(`reservation:hold:${orderId}`);
  }
}
