```typescript
import { prisma } from '../db/prisma.js';
import { InventoryService } from '../services/inventory-service.js';
import { OrderStatus } from '@prisma/client';

export async function releaseExpiredReservations(expiryWindowMinutes = 15): Promise<number> {
  const cutoff = new Date(Date.now() - expiryWindowMinutes * 60 * 1000);

  // Find PENDING orders that exceeded checkout window
  const expiredOrders = await prisma.order.findMany({
    where: {
      status: OrderStatus.PENDING,
      createdAt: { lt: cutoff },
    },
    include: { lines: true },
  });

  let releasedCount = 0;

  for (const order of expiredOrders) {
    await prisma.$transaction(async (tx) => {
      for (const line of order.lines) {
        await InventoryService.releaseVariantStock(tx, line.variantSku, line.quantity);
      }
      await tx.order.update({
        where: { id: order.id },
        data: { status: OrderStatus.CANCELLED },
      });
    });
    releasedCount++;
  }

  return releasedCount;
}
```

