import { Request, Response, NextFunction } from 'express';
import { prisma } from '../db/prisma.js';

export async function requireIdempotencyKey(req: Request, res: Response, next: NextFunction): Promise<void> {
  const key = req.header('Idempotency-Key');
  if (!key) {
    res.status(400).json({
      error: 'IDEMPOTENCY_KEY_REQUIRED',
      message: 'Checkout requests must provide a unique Idempotency-Key header',
    });
    return;
  }

  // Check if an order with this idempotency key already exists
  const existingOrder = await prisma.order.findUnique({
    where: { idempotencyKey: key },
    include: { lines: true },
  });

  if (existingOrder) {
    console.log(`[Idempotency] Replay detected for key: ${key}. Returning cached order.`);
    res.status(200).json({
      replayed: true,
      order: existingOrder,
    });
    return;
  }

  next();
}
```

