### Step 4 · Transactional Checkout Service

Create `src/services/checkout-service.ts` to atomically reserve stock, create the pending order, and provision the Stripe PaymentIntent.

```typescript
import { prisma } from '../db/prisma.js';
import { stripe } from '../config/stripe.js';
import { InventoryService } from './inventory-service.js';
import { ReservationTTLService } from './reservation-ttl.js';
import { OrderStatus } from '@prisma/client';

export interface CheckoutInputItem {
  sku: string;
  quantity: number;
}

export class CheckoutService {
  public static async createCheckoutSession(
    idempotencyKey: string,
    items: CheckoutInputItem[],
    userId?: string
  ) {
    // Sort items by SKU to prevent lock deadlocks
    const sortedItems = [...items].sort((a, b) => a.sku.localeCompare(b.sku));

    // 1. Fetch variant prices and validate existence
    const skus = sortedItems.map((i) => i.sku);
    const variants = await prisma.variant.findMany({
      where: { sku: { in: skus } },
      include: { product: true },
    });

    if (variants.length !== skus.length) {
      throw new Error('One or more requested SKUs do not exist');
    }

    const variantMap = new Map(variants.map((v) => [v.sku, v]));
    let totalCents = 0;
    const lineItemsData = sortedItems.map((item) => {
      const variant = variantMap.get(item.sku)!;
      totalCents += variant.priceCents * item.quantity;
      return {
        variantSku: variant.sku,
        titleSnapshot: `${variant.product.title} - ${variant.title}`,
        unitPriceCents: variant.priceCents,
        quantity: item.quantity,
      };
    });

    // 2. Atomic reservation and Order creation in one transaction
    const order = await prisma.$transaction(async (tx) => {
      for (const item of sortedItems) {
        await InventoryService.reserveVariantStock(tx, item.sku, item.quantity);
      }

      return tx.order.create({
        data: {
          userId,
          idempotencyKey,
          status: OrderStatus.PENDING,
          totalCents,
          lines: {
            create: lineItemsData,
          },
        },
        include: { lines: true },
      });
    });

    // 3. Create Stripe PaymentIntent with Stripe's idempotency key
    const paymentIntent = await stripe.paymentIntents.create(
      {
        amount: totalCents,
        currency: 'usd',
        metadata: {
          orderId: order.id,
          idempotencyKey,
        },
      },
      {
        idempotencyKey: `stripe-pi-${idempotencyKey}`,
      }
    );

    // 4. Bind Stripe Intent ID to order and set Redis TTL hold
    await prisma.order.update({
      where: { id: order.id },
      data: { stripeIntentId: paymentIntent.id },
    });
    await ReservationTTLService.trackHold(order.id, sortedItems);

    return {
      orderId: order.id,
      clientSecret: paymentIntent.client_secret,
      totalCents,
    };
  }
}
```

