### Step 6 · Stripe Webhook Interceptor with Raw Body Preservation

Create `src/controllers/webhook-controller.ts`. Stripe requires raw unparsed byte buffers to verify cryptographic signatures.

```typescript
import { Request, Response } from 'express';
import { stripe } from '../config/stripe.js';
import { handlePaymentIntentSucceeded } from '../services/payment-event-handler.js';
import Stripe from 'stripe';

export async function handleStripeWebhook(req: Request, res: Response): Promise<void> {
  const sig = req.headers['stripe-signature'];
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!sig || !webhookSecret) {
    res.status(400).send('Webhook secret or signature missing');
    return;
  }

  let event: Stripe.Event;
  try {
    // Verify HMAC-SHA256 signature using raw Buffer
    event = stripe.webhooks.constructEvent(req.body, sig, webhookSecret);
  } catch (err: any) {
    console.error(`[Webhook Verification Error]: ${err.message}`);
    res.status(400).send(`Webhook Error: ${err.message}`);
    return;
  }

  // Handle verified events
  switch (event.type) {
    case 'payment_intent.succeeded': {
      const paymentIntent = event.data.object as Stripe.PaymentIntent;
      await handlePaymentIntentSucceeded(paymentIntent);
      break;
    }
    default:
      console.log(`[Stripe Webhook] Unhandled event type: ${event.type}`);
  }

  res.status(200).json({ received: true });
}
```

