### Step 7 · Payment Event Handler

Create `src/services/payment-event-handler.ts` to transition the order from `PENDING` to `PAID`:

```typescript
import Stripe from 'stripe';
import { prisma } from '../db/prisma.js';
import { OrderStateMachine } from '../domain/order-fsm.js';
import { OrderStatus } from '@prisma/client';
import { ReservationTTLService } from './reservation-ttl.js';

export async function handlePaymentIntentSucceeded(paymentIntent: Stripe.PaymentIntent): Promise<void> {
  const orderId = paymentIntent.metadata.orderId;
  if (!orderId) {
    console.warn('[Webhook] PaymentIntent missing orderId in metadata');
    return;
  }

  const order = await prisma.order.findUnique({ where: { id: orderId } });
  if (!order) {
    console.error(`[Webhook] Order ${orderId} not found`);
    return;
  }

  // Idempotency: if already marked PAID or FULFILLED, ignore repeat webhooks
  if (order.status === OrderStatus.PAID || order.status === OrderStatus.FULFILLED) {
    console.log(`[Webhook] Order ${orderId} already processed (status: ${order.status})`);
    return;
  }

  OrderStateMachine.assertCanTransition(order.status, OrderStatus.PAID);

  await prisma.order.update({
    where: { id: orderId },
    data: { status: OrderStatus.PAID },
  });

  // Clear temporary hold from Redis
  await ReservationTTLService.clearHold(orderId);
  console.log(`✓ Order ${orderId} transitioned to PAID via Stripe Webhook.`);
}
```

