```typescript
import { Worker, Job } from 'bullmq';
import { FULFILLMENT_QUEUE_NAME, FulfillmentJobData } from '../queues/fulfillment-queue.js';
import { redisConnectionOptions } from '../queues/redis-connection.js';
import { prisma } from '../db/prisma.js';
import { OrderStatus } from '@prisma/client';
import { OrderStateMachine } from '../domain/order-fsm.js';
import { InventoryService } from '../services/inventory-service.js';
import { generateInvoicePdf } from '../services/invoice-generator.js';

export function createFulfillmentWorker(): Worker<FulfillmentJobData> {
  return new Worker<FulfillmentJobData>(
    FULFILLMENT_QUEUE_NAME,
    async (job: Job<FulfillmentJobData>) => {
      const { orderId } = job.data;
      console.log(`[Worker] Starting fulfillment for order: ${orderId} (Attempt: ${job.attemptsMade + 1})`);

      // 1. Fetch order and lines
      const order = await prisma.order.findUnique({
        where: { id: orderId },
        include: { lines: true },
      });

      if (!order) {
        throw new Error(`Order ${orderId} does not exist`);
      }

      // 2. Idempotency Check: if order is not in PAID state, skip execution
      if (order.status !== OrderStatus.PAID) {
        console.log(`[Worker] Order ${orderId} is currently '${order.status}'. Skipping fulfillment.`);
        return;
      }

      // 3. Commit inventory (deduct physical stock) and transition order to FULFILLED
      OrderStateMachine.assertCanTransition(order.status, OrderStatus.FULFILLED);

      await prisma.$transaction(async (tx) => {
        for (const line of order.lines) {
          await InventoryService.commitVariantStock(tx, line.variantSku, line.quantity);
        }

        await tx.order.update({
          where: { id: orderId },
          data: { status: OrderStatus.FULFILLED },
        });
      });

      // 4. Generate PDF invoice
      const pdfPath = await generateInvoicePdf({
        orderId: order.id,
        totalCents: order.totalCents,
        items: order.lines.map((l) => ({
          title: l.titleSnapshot,
          qty: l.quantity,
          unitPriceCents: l.unitPriceCents,
        })),
      });

      console.log(`✓ [Worker] Order ${orderId} fulfilled successfully! Invoice: ${pdfPath}`);
    },
    {
      connection: redisConnectionOptions,
      concurrency: 5, // Process up to 5 jobs simultaneously
    }
  );
}
```

