import { fulfillmentQueue } from './fulfillment-queue.js';

export async function getDeadLetterJobs() {
  const failedJobs = await fulfillmentQueue.getFailed(0, 100);
  return failedJobs.map((j) => ({
    id: j.id,
    orderId: j.data.orderId,
    failedReason: j.failedReason,
    attempts: j.attemptsMade,
    timestamp: j.timestamp,
  }));
}

export async function retryFailedJob(jobId: string): Promise<boolean> {
  const job = await fulfillmentQueue.getJob(jobId);
  if (job) {
    await job.retry();
    return true;
  }
  return false;
}
