### Step 4 · Admin Catalog & Stock Adjustment Controller

Create `src/controllers/admin-controller.ts`:

```typescript
import { Router, Request, Response } from 'express';
import { authenticateJWT, requirePermission } from '../middleware/auth-guard.js';
import { prisma } from '../db/prisma.js';
import { z } from 'zod';

export const adminRouter = Router();
adminRouter.use(authenticateJWT);

const AdjustStockSchema = z.object({
  delta: z.number().int(),
  reason: z.string().min(3),
});

// Adjust physical warehouse stock with audit trail
adminRouter.patch(
  '/variants/:sku/stock',
  requirePermission('ADJUST_INVENTORY'),
  async (req: Request, res: Response) => {
    const { sku } = req.params;
    const parseResult = AdjustStockSchema.safeParse(req.body);
    if (!parseResult.success) {
      res.status(400).json({ error: 'VALIDATION_FAILED', details: parseResult.error.flatten() });
      return;
    }

    const { delta, reason } = parseResult.data;

    const result = await prisma.$transaction(async (tx) => {
      const variant = await tx.variant.findUniqueOrThrow({ where: { sku } });
      const previousStock = variant.stock;
      const newStock = previousStock + delta;

      if (newStock < variant.reserved) {
        throw new Error(`Cannot reduce stock below current reserved count (${variant.reserved})`);
      }

      const updated = await tx.variant.update({
        where: { sku },
        data: { stock: newStock },
      });

      await tx.auditLog.create({
        data: {
          userId: req.user!.userId,
          action: 'STOCK_ADJUSTMENT',
          entity: 'Variant',
          entityId: variant.id,
          details: { sku, previousStock, newStock, delta, reason },
        },
      });

      return updated;
    });

    res.status(200).json({ variant: result });
  }
);
```

