### Step 5 · React Admin Auth Provider & Claims Hook

Create `frontend/context/AdminAuthContext.tsx`:

```tsx
import React, { createContext, useContext, useState, ReactNode } from 'react';

export type Role = 'CUSTOMER' | 'SUPPORT' | 'INVENTORY_MANAGER' | 'ADMIN';

export interface AuthState {
  token: string | null;
  email: string | null;
  role: Role | null;
}

interface AuthContextType extends AuthState {
  login: (token: string) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const token = localStorage.getItem('admin_token');
    if (token) {
      try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        return { token, email: payload.email, role: payload.role };
      } catch (e) {
        return { token: null, email: null, role: null };
      }
    }
    return { token: null, email: null, role: null };
  });

  const login = (token: string) => {
    const payload = JSON.parse(atob(token.split('.')[1]));
    localStorage.setItem('admin_token', token);
    setAuth({ token, email: payload.email, role: payload.role });
  };

  const logout = () => {
    localStorage.removeItem('admin_token');
    setAuth({ token: null, email: null, role: null });
  };

  return (
    <AuthContext.Provider value={{ ...auth, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAdminAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAdminAuth must be used within an AuthProvider');
  return ctx;
};
```

