import React, { ReactNode } from 'react';
import { useAdminAuth, Role } from '../context/AdminAuthContext.js';

interface CanProps {
  allowedRoles: Role[];
  children: ReactNode;
  fallback?: ReactNode;
}

export const Can: React.FC<CanProps> = ({ allowedRoles, children, fallback = null }) => {
  const { role } = useAdminAuth();
  if (!role || !allowedRoles.includes(role)) {
    return <>{fallback}</>;
  }
  return <>{children}</>;
};
