### Step 4 · Prometheus Scrape & Correlation Middleware

Create `src/middleware/observability-middleware.ts`:

```typescript
import { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { httpRequestDuration } from '../monitoring/metrics.js';
import { asyncLocalStorage } from '../monitoring/logger.js';

export function observabilityMiddleware(req: Request, res: Response, next: NextFunction): void {
  const correlationId = (req.header('x-correlation-id') as string) || uuidv4();
  res.setHeader('x-correlation-id', correlationId);

  const store = new Map<string, string>();
  store.set('correlationId', correlationId);

  const start = process.hrtime();

  res.on('finish', () => {
    const diff = process.hrtime(start);
    const durationSec = diff[0] + diff[1] / 1e9;
    const route = req.route?.path || req.path;
    httpRequestDuration
      .labels(req.method, route, String(res.statusCode))
      .observe(durationSec);
  });

  asyncLocalStorage.run(store, () => next());
}
```

