package io.buildscape.taskmanager.task.service;

import io.buildscape.taskmanager.category.entity.Category;
import io.buildscape.taskmanager.category.repository.CategoryRepository;
import io.buildscape.taskmanager.common.exception.ResourceNotFoundException;
import io.buildscape.taskmanager.common.exception.UnauthorizedResourceAccessException;
import io.buildscape.taskmanager.task.dto.CreateTaskRequest;
import io.buildscape.taskmanager.task.dto.TaskResponse;
import io.buildscape.taskmanager.task.dto.UpdateTaskStatusRequest;
import io.buildscape.taskmanager.task.entity.Task;
import io.buildscape.taskmanager.task.entity.TaskStatus;
import io.buildscape.taskmanager.task.repository.TaskRepository;
import io.buildscape.taskmanager.user.entity.AppUser;
import io.buildscape.taskmanager.user.repository.AppUserRepository;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TaskServiceImpl implements TaskService {

    private final TaskRepository taskRepository;
    private final AppUserRepository userRepository;
    private final CategoryRepository categoryRepository;

    public TaskServiceImpl(TaskRepository taskRepository,
                           AppUserRepository userRepository,
                           CategoryRepository categoryRepository) {
        this.taskRepository = taskRepository;
        this.userRepository = userRepository;
        this.categoryRepository = categoryRepository;
    }

    @Override
    @Transactional
    public TaskResponse createTask(String userEmail, CreateTaskRequest request) {
        AppUser user = userRepository.findByEmail(userEmail)
                .orElseThrow(() -> new ResourceNotFoundException("User", "email", userEmail));

        Category category = null;
        if (request.categoryId() != null) {
            category = categoryRepository.findById(request.categoryId())
                    .orElseThrow(() -> new ResourceNotFoundException("Category", "id", request.categoryId()));
            if (!category.getOwner().getId().equals(user.getId())) {
                throw new UnauthorizedResourceAccessException("Cannot assign a category owned by another user");
            }
        }

        Task task = new Task(
                request.title(),
                request.description(),
                request.priority(),
                request.dueDate(),
                user,
                category
        );

        Task saved = taskRepository.save(task);
        return TaskResponse.fromEntity(saved);
    }

    @Override
    @Transactional(readOnly = true)
    public Page<TaskResponse> getTasks(String userEmail, TaskStatus status, Pageable pageable) {
        AppUser user = userRepository.findByEmail(userEmail)
                .orElseThrow(() -> new ResourceNotFoundException("User", "email", userEmail));

        Page<Task> page = (status == null)
                ? taskRepository.findByOwnerId(user.getId(), pageable)
                : taskRepository.findByOwnerIdAndStatus(user.getId(), status, pageable);

        return page.map(TaskResponse::fromEntity);
    }

    @Override
    @Transactional(readOnly = true)
    public TaskResponse getTaskById(String userEmail, Long taskId) {
        AppUser user = userRepository.findByEmail(userEmail)
                .orElseThrow(() -> new ResourceNotFoundException("User", "email", userEmail));

        Task task = taskRepository.findById(taskId)
                .orElseThrow(() -> new ResourceNotFoundException("Task", "id", taskId));

        if (!task.getOwner().getId().equals(user.getId())) {
            throw new UnauthorizedResourceAccessException("You are not authorized to view this task");
        }

        return TaskResponse.fromEntity(task);
    }

    @Override
    @Transactional
    public TaskResponse updateTaskStatus(String userEmail, Long taskId, UpdateTaskStatusRequest request) {
        AppUser user = userRepository.findByEmail(userEmail)
                .orElseThrow(() -> new ResourceNotFoundException("User", "email", userEmail));

        Task task = taskRepository.findById(taskId)
                .orElseThrow(() -> new ResourceNotFoundException("Task", "id", taskId));

        if (!task.getOwner().getId().equals(user.getId())) {
            throw new UnauthorizedResourceAccessException("You are not authorized to update this task");
        }

        task.setStatus(request.status());
        return TaskResponse.fromEntity(task);
    }

    @Override
    @Transactional
    public void deleteTask(String userEmail, Long taskId) {
        AppUser user = userRepository.findByEmail(userEmail)
                .orElseThrow(() -> new ResourceNotFoundException("User", "email", userEmail));

        Task task = taskRepository.findById(taskId)
                .orElseThrow(() -> new ResourceNotFoundException("Task", "id", taskId));

        if (!task.getOwner().getId().equals(user.getId())) {
            throw new UnauthorizedResourceAccessException("You are not authorized to delete this task");
        }

        taskRepository.delete(task);
    }
}
