```java
package io.buildscape.taskmanager.auth.controller;

import io.buildscape.taskmanager.auth.dto.AuthDtos.*;
import io.buildscape.taskmanager.common.dto.ApiResponse;
import io.buildscape.taskmanager.security.JwtTokenProvider;
import io.buildscape.taskmanager.user.entity.AppUser;
import io.buildscape.taskmanager.user.repository.AppUserRepository;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/auth")
public class AuthController {

    private final AppUserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final AuthenticationManager authenticationManager;
    private final JwtTokenProvider tokenProvider;

    public AuthController(AppUserRepository userRepository,
                          PasswordEncoder passwordEncoder,
                          AuthenticationManager authenticationManager,
                          JwtTokenProvider tokenProvider) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
        this.authenticationManager = authenticationManager;
        this.tokenProvider = tokenProvider;
    }

    @PostMapping("/register")
    public ResponseEntity<ApiResponse<AuthResponse>> register(@Valid @RequestBody RegisterRequest req) {
        if (userRepository.existsByEmail(req.email())) {
            return ResponseEntity.status(HttpStatus.CONFLICT)
                    .body(ApiResponse.error("Email is already registered"));
        }

        AppUser user = new AppUser(req.email(), passwordEncoder.encode(req.password()), req.fullName(), "ROLE_USER");
        userRepository.save(user);

        String token = tokenProvider.generateToken(user.getEmail(), user.getRole());
        return ResponseEntity.status(HttpStatus.CREATED)
                .body(ApiResponse.ok(new AuthResponse(token, "Bearer", user.getEmail(), user.getFullName()), "Registration successful"));
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<AuthResponse>> login(@Valid @RequestBody LoginRequest req) {
        authenticationManager.authenticate(new UsernamePasswordAuthenticationToken(req.email(), req.password()));
        AppUser user = userRepository.findByEmail(req.email()).orElseThrow();
        String token = tokenProvider.generateToken(user.getEmail(), user.getRole());
        return ResponseEntity.ok(ApiResponse.ok(new AuthResponse(token, "Bearer", user.getEmail(), user.getFullName())));
    }
}
```

