### Step 5 · TanStack Query Hooks with Optimistic Status Updates

Create `src/hooks/useTasks.ts`:

```typescript
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { taskApi, TaskStatus, CreateTaskDto, Task } from '../api/taskApi.js';

export function useTasks(statusFilter?: TaskStatus) {
  const queryClient = useQueryClient();

  const tasksQuery = useQuery({
    queryKey: ['tasks', statusFilter],
    queryFn: () => taskApi.getTasks(statusFilter),
  });

  const updateStatusMutation = useMutation({
    mutationFn: ({ id, status }: { id: number; status: TaskStatus }) =>
      taskApi.updateStatus(id, status),
    onMutate: async ({ id, status }) => {
      await queryClient.cancelQueries({ queryKey: ['tasks'] });
      const previousTasks = queryClient.getQueryData<Task[]>(['tasks', statusFilter]);

      // Optimistically update the cache
      queryClient.setQueryData<Task[]>(['tasks', statusFilter], (old = []) =>
        old.map((t) => (t.id === id ? { ...t, status } : t))
      );

      return { previousTasks };
    },
    onError: (err, variables, context) => {
      if (context?.previousTasks) {
        queryClient.setQueryData(['tasks', statusFilter], context.previousTasks);
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
    },
  });

  const createTaskMutation = useMutation({
    mutationFn: (dto: CreateTaskDto) => taskApi.createTask(dto),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] });
    },
  });

  return {
    tasks: tasksQuery.data || [],
    isLoading: tasksQuery.isLoading,
    updateStatus: updateStatusMutation.mutate,
    createTask: createTaskMutation.mutate,
  };
}
```

