### Step 4 · Write Flyway Migration: Deferred Zero-Sum Trigger & Immutability
Create `src/main/resources/db/migration/V2__enforce_zero_sum_trigger.sql`:

```sql
-- 1. Function to enforce double-entry zero-sum invariant on commit
CREATE OR REPLACE FUNCTION verify_ledger_tx_zero_sum()
RETURNS TRIGGER AS $$
DECLARE
    tx_balance BIGINT;
BEGIN
    -- Sum all entry amounts associated with this transaction
    SELECT COALESCE(SUM(amount), 0)
    INTO tx_balance
    FROM entry
    WHERE tx_id = NEW.tx_id;

    -- Invariant: Sum of debits and credits MUST strictly equal zero
    IF tx_balance <> 0 THEN
        RAISE EXCEPTION 'Double-entry zero-sum invariant violated for tx_id %: net sum is % minor units (must equal 0)',
            NEW.tx_id, tx_balance
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 2. Attach constraint trigger: executed after entire transaction batch inserts
CREATE CONSTRAINT TRIGGER trg_verify_entry_zero_sum
AFTER INSERT ON entry
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION verify_ledger_tx_zero_sum();

-- 3. Prevent tampering: entries are strictly append-only
CREATE OR REPLACE FUNCTION forbid_entry_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'Ledger entries are strictly immutable. UPDATE and DELETE operations are forbidden.'
        USING ERRCODE = 'data_exception';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_prevent_entry_update
BEFORE UPDATE OR DELETE ON entry
FOR EACH ROW
EXECUTE FUNCTION forbid_entry_mutation();
```

