    private Long balanceCache;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    protected Account() {}

    public Account(UUID id, String accountNumber, String holderName, String currency, Long initialBalance) {
        this.id = id;
        this.accountNumber = accountNumber;
        this.holderName = holderName;
        this.currency = currency.toUpperCase();
        this.balanceCache = initialBalance;
        this.createdAt = Instant.now();
        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public String getAccountNumber() { return accountNumber; }
    public String getHolderName() { return holderName; }
    public String getCurrency() { return currency; }
    public Long getBalanceCache() { return balanceCache; }
    public Instant getCreatedAt() { return createdAt; }

    public void debit(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("Debit amount must be positive");
        if (this.balanceCache < amount) throw new IllegalStateException("Insufficient funds in account: " + this.id);
        this.balanceCache -= amount;
        this.updatedAt = Instant.now();
    }

    public void credit(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("Credit amount must be positive");
        this.balanceCache += amount;
        this.updatedAt = Instant.now();
    }
}
