                ledgerTxRepository.save(new LedgerTx(txId, "idem-" + txId, "Unbalanced theft"));
                entryRepository.save(new Entry(txId, acc1, 5000L)); // Missing opposing credit!
                return null;
            });
        }).isInstanceOf(DataIntegrityViolationException.class)
          .hasMessageContaining("Double-entry zero-sum invariant violated");
    }
