    Long computeCalculatedBalance(@Param("accountId") UUID accountId);

    // CRITICAL: Pessimistic write lock with explicit ascending order by primary key ID
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT a FROM Account a WHERE a.id IN :ids ORDER BY a.id ASC")
    List<Account> lockAccountsForUpdate(@Param("ids") List<UUID> ids);
}
