### Step 4 · Implement Core Transfer Service with Lock Ordering & Invariant Checks
Create `src/main/java/io/buildscape/banking/service/TransferService.java`:

```java
package io.buildscape.banking.service;

import io.buildscape.banking.domain.Account;
import io.buildscape.banking.domain.Entry;
import io.buildscape.banking.domain.LedgerTx;
import io.buildscape.banking.dto.TransferRequest;
import io.buildscape.banking.dto.TransferResponse;
import io.buildscape.banking.exception.AccountNotFoundException;
import io.buildscape.banking.exception.CurrencyMismatchException;
import io.buildscape.banking.exception.InsufficientFundsException;
import io.buildscape.banking.repository.AccountRepository;
import io.buildscape.banking.repository.EntryRepository;
import io.buildscape.banking.repository.LedgerTxRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.*;
import java.util.stream.Stream;

@Service
public class TransferService {

    private static final Logger log = LoggerFactory.getLogger(TransferService.class);

    private final AccountRepository accountRepository;
    private final LedgerTxRepository ledgerTxRepository;
    private final EntryRepository entryRepository;

    public TransferService(AccountRepository accountRepository,
                           LedgerTxRepository ledgerTxRepository,
                           EntryRepository entryRepository) {
        this.accountRepository = accountRepository;
        this.ledgerTxRepository = ledgerTxRepository;
        this.entryRepository = entryRepository;
    }

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public TransferResponse executeTransfer(String idempotencyKey, TransferRequest request) {
        if (request.fromAccountId().equals(request.toAccountId())) {
            throw new IllegalArgumentException("Self-transfers are not permitted");
        }

        // 1. Idempotency Check: Return existing record if already processed
        Optional<LedgerTx> existingTx = ledgerTxRepository.findByIdemKey(idempotencyKey);
        if (existingTx.isPresent()) {
            LedgerTx tx = existingTx.get();
            log.info("Idempotent replay detected for key {}", idempotencyKey);
            return new TransferResponse(
                    tx.getId(),
                    tx.getIdemKey(),
                    request.fromAccountId(),
                    request.toAccountId(),
                    request.amount(),
                    "COMPLETED_IDEMPOTENT_REPLAY",
                    tx.getCreatedAt(),
                    true
            );
        }

        // 2. Deterministic Lock Ordering: Sort UUIDs to prevent cyclic deadlocks (40P01)
        List<UUID> sortedAccountIds = Stream.of(request.fromAccountId(), request.toAccountId())
                .sorted()
                .toList();

        List<Account> lockedAccounts = accountRepository.lockAccountsForUpdate(sortedAccountIds);
        if (lockedAccounts.size() < 2) {
            throw new AccountNotFoundException(request.fromAccountId());
        }

        Map<UUID, Account> accountMap = new HashMap<>();
        for (Account a : lockedAccounts) {
            accountMap.put(a.getId(), a);
        }

        Account source = accountMap.get(request.fromAccountId());
        Account destination = accountMap.get(request.toAccountId());

        if (source == null) throw new AccountNotFoundException(request.fromAccountId());
        if (destination == null) throw new AccountNotFoundException(request.toAccountId());

        // 3. Currency Match Check
        if (!source.getCurrency().equalsIgnoreCase(destination.getCurrency())) {
            throw new CurrencyMismatchException(source.getCurrency(), destination.getCurrency());
        }

        // 4. Balance Solvency Check
        if (source.getBalanceCache() < request.amount()) {
            throw new InsufficientFundsException(source.getId(), source.getBalanceCache(), request.amount());
        }

        // 5. Create Transaction Record
        UUID txId = UUID.randomUUID();
        LedgerTx tx = new LedgerTx(txId, idempotencyKey, request.description());
        ledgerTxRepository.save(tx);

        // 6. Double-Entry Postings: debit source (-amount), credit destination (+amount)
        Entry debitEntry = new Entry(txId, source.getId(), -request.amount());
        Entry creditEntry = new Entry(txId, destination.getId(), request.amount());
        entryRepository.save(debitEntry);
        entryRepository.save(creditEntry);

        // 7. Update Cached Balances atomically
        source.debit(request.amount());
        destination.credit(request.amount());
        accountRepository.save(source);
        accountRepository.save(destination);

        log.info("Transfer {} successfully processed. Debited {} from {}, credited {}",
                txId, request.amount(), source.getId(), destination.getId());

        return new TransferResponse(
                tx.getId(),
                tx.getIdemKey(),
                source.getId(),
                destination.getId(),
                request.amount(),
                "COMPLETED",
                Instant.now(),
                false
        );
    }
}
```

