```java
package io.buildscape.banking;

import io.buildscape.banking.domain.Account;
import io.buildscape.banking.dto.TransferRequest;
import io.buildscape.banking.repository.AccountRepository;
import io.buildscape.banking.service.TransferService;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import java.util.UUID;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class TransferDeadlockTest {

    @Autowired
    private AccountRepository accountRepository;
    @Autowired
    private TransferService transferService;

    @Test
    @DisplayName("100 simultaneous opposing transfers (A->B and B->A) never trigger deadlocks")
    void concurrentOpposingTransfersNeverDeadlock() throws Exception {
        UUID accA = UUID.randomUUID();
        UUID accB = UUID.randomUUID();

        // Seed both accounts with $1,000,000 cents ($10,000.00)
        accountRepository.save(new Account(accA, "ACC-DEADLOCK-A", "User A", "USD", 1_000_000L));
        accountRepository.save(new Account(accB, "ACC-DEADLOCK-B", "User B", "USD", 1_000_000L));

        int totalTransfers = 100;
        int threadPoolSize = 16;
        ExecutorService executor = Executors.newFixedThreadPool(threadPoolSize);
        CountDownLatch readyLatch = new CountDownLatch(totalTransfers);
        CountDownLatch startLatch = new CountDownLatch(1);
        AtomicInteger successCount = new AtomicInteger(0);
        AtomicInteger errorCount = new AtomicInteger(0);

        for (int i = 0; i < totalTransfers; i++) {
            final int index = i;
            final boolean aToB = (index % 2 == 0);
            executor.submit(() -> {
                readyLatch.countDown();
                try {
                    startLatch.await(); // Synchronize burst start
                    UUID from = aToB ? accA : accB;
                    UUID to = aToB ? accB : accA;
                    String key = "stress-idem-" + index;

                    transferService.executeTransfer(key, new TransferRequest(from, to, 100L, "Concurrent transfer"));
                    successCount.incrementAndGet();
                } catch (Exception e) {
                    errorCount.incrementAndGet();
                }
            });
        }

        readyLatch.await(5, TimeUnit.SECONDS);
        startLatch.countDown(); // Release all threads concurrently
        executor.shutdown();
        boolean completed = executor.awaitTermination(30, TimeUnit.SECONDS);

        assertThat(completed).isTrue();
        assertThat(errorCount.get()).isEqualTo(0);
        assertThat(successCount.get()).isEqualTo(totalTransfers);

        // Invariant: Total combined balance must remain unchanged
        Account refreshedA = accountRepository.findById(accA).orElseThrow();
        Account refreshedB = accountRepository.findById(accB).orElseThrow();
        assertThat(refreshedA.getBalanceCache() + refreshedB.getBalanceCache()).isEqualTo(2_000_000L);
    }
}
```

