    void idempotentReplayPreservesExactBalance() {
        UUID accSrc = UUID.randomUUID();
        UUID accDst = UUID.randomUUID();
        String idemKey = "idem-replay-" + UUID.randomUUID();

        accountRepository.save(new Account(accSrc, "SRC-IDEM-01", "Source", "USD", 50_000L));
        accountRepository.save(new Account(accDst, "DST-IDEM-01", "Destination", "USD", 10_000L));

        TransferRequest req = new TransferRequest(accSrc, accDst, 5_000L, "First payment attempt");

