        TransferResponse resp1 = transferService.executeTransfer(idemKey, req);
        assertThat(resp1.isReplay()).isFalse();
        assertThat(resp1.amount()).isEqualTo(5_000L);

        // Replay 10 identical calls
        for (int i = 0; i < 10; i++) {
            TransferResponse replayResp = transferService.executeTransfer(idemKey, req);
            assertThat(replayResp.isReplay()).isTrue();
            assertThat(replayResp.transactionId()).isEqualTo(resp1.transactionId());
