        Account finalSrc = accountRepository.findById(accSrc).orElseThrow();
        Account finalDst = accountRepository.findById(accDst).orElseThrow();
        assertThat(finalSrc.getBalanceCache()).isEqualTo(45_000L);
        assertThat(finalDst.getBalanceCache()).isEqualTo(15_000L);
    }
