import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

@Component
public class OutboxRelayScheduler {

    private static final Logger log = LoggerFactory.getLogger(OutboxRelayScheduler.class);

    private final OutboxRepository outboxRepository;
    private final KafkaTemplate<String, String> kafkaTemplate;

    @Value("${ledger.kafka.transfer-topic}")
    private String transferTopic;

    @Value("${ledger.kafka.relay-batch-size:50}")
    private int batchSize;

    public OutboxRelayScheduler(OutboxRepository outboxRepository, KafkaTemplate<String, String> kafkaTemplate) {
        this.outboxRepository = outboxRepository;
        this.kafkaTemplate = kafkaTemplate;
    }

    @Scheduled(fixedDelayString = "${ledger.relay.poll-interval-ms:250}")
    @Transactional
    public void processOutboxBatch() {
        List<OutboxEvent> pendingEvents = outboxRepository.fetchUnpublishedBatchForUpdate(batchSize);
        if (pendingEvents.isEmpty()) {
            return;
        }

        log.debug("Polled {} unpublished outbox events for publishing", pendingEvents.size());

        for (OutboxEvent event : pendingEvents) {
            try {
                // Publish synchronously with 3s timeout to verify Kafka broker acknowledgment
                kafkaTemplate.send(transferTopic, event.getAggregateId(), event.getPayload())
                        .get(3, TimeUnit.SECONDS);

                event.markPublished();
                log.debug("Successfully published event {} to Kafka topic {}", event.getId(), transferTopic);
            } catch (Exception ex) {
                log.error("Failed to publish outbox event {} to Kafka. Will retry next cycle: {}",
                        event.getId(), ex.getMessage());
                // Stop processing batch to preserve strictly ordered aggregate delivery
                break;
            }
        }

        outboxRepository.saveAll(pendingEvents);
    }
}
```

