    private UUID accountId;

    @Column(name = "period_month", nullable = false, length = 7)
    private String periodMonth;

    @Column(name = "total_debits", nullable = false)
    private Long totalDebits = 0L;

    @Column(name = "total_credits", nullable = false)
    private Long totalCredits = 0L;

    @Column(name = "closing_balance", nullable = false)
    private Long closingBalance = 0L;

    @Column(name = "transaction_count", nullable = false)
    private Integer transactionCount = 0;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    protected AccountStatement() {}

    public AccountStatement(UUID id, UUID accountId, String periodMonth, Long initialBalance) {
        this.id = id;
        this.accountId = accountId;
        this.periodMonth = periodMonth;
        this.closingBalance = initialBalance;
        this.totalDebits = 0L;
        this.totalCredits = 0L;
        this.transactionCount = 0;
        this.updatedAt = Instant.now();
    }

    public void applyDebit(long amount) {
        this.totalDebits += amount;
        this.closingBalance -= amount;
        this.transactionCount++;
        this.updatedAt = Instant.now();
    }

    public void applyCredit(long amount) {
        this.totalCredits += amount;
        this.closingBalance += amount;
        this.transactionCount++;
        this.updatedAt = Instant.now();
    }

    public UUID getId() { return id; }
    public UUID getAccountId() { return accountId; }
    public String getPeriodMonth() { return periodMonth; }
    public Long getTotalDebits() { return totalDebits; }
    public Long getTotalCredits() { return totalCredits; }
    public Long getClosingBalance() { return closingBalance; }
    public Integer getTransactionCount() { return transactionCount; }
}
