package io.buildscape.banking.service;

import io.buildscape.banking.domain.Account;
import io.buildscape.banking.domain.AccountStatement;
import io.buildscape.banking.event.TransferCompletedEvent;
import io.buildscape.banking.repository.AccountRepository;
import io.buildscape.banking.repository.AccountStatementRepository;
import io.buildscape.banking.repository.ProcessedEventRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.UUID;

@Service
public class StatementProjector {

    private static final Logger log = LoggerFactory.getLogger(StatementProjector.class);
    private static final String CONSUMER_GROUP = "account-statement-projector";
    private static final DateTimeFormatter PERIOD_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM").withZone(ZoneOffset.UTC);

    private final ProcessedEventRepository processedEventRepository;
    private final AccountStatementRepository statementRepository;
    private final AccountRepository accountRepository;

    public StatementProjector(ProcessedEventRepository processedEventRepository,
                              AccountStatementRepository statementRepository,
                              AccountRepository accountRepository) {
        this.processedEventRepository = processedEventRepository;
        this.statementRepository = statementRepository;
        this.accountRepository = accountRepository;
    }

    @Transactional
    public boolean projectTransfer(TransferCompletedEvent event) {
        // 1. Atomic Deduplication Guard
        int inserted = processedEventRepository.insertIfAbsent(event.eventId(), CONSUMER_GROUP);
        if (inserted == 0) {
            log.warn("Duplicate event detected and ignored: {}", event.eventId());
            return false; // Already processed by this consumer group
        }

        String period = PERIOD_FORMATTER.format(event.timestamp());

        // 2. Project Source Account (Debit)
        Account source = accountRepository.findById(event.fromAccountId()).orElse(null);
        if (source != null) {
            AccountStatement srcStmt = statementRepository.findByAccountIdAndPeriodMonth(source.getId(), period)
                    .orElseGet(() -> statementRepository.save(new AccountStatement(
                            UUID.randomUUID(), source.getId(), period, source.getBalanceCache() + event.amount()
                    )));
            srcStmt.applyDebit(event.amount());
            statementRepository.save(srcStmt);
        }

        // 3. Project Destination Account (Credit)
        Account destination = accountRepository.findById(event.toAccountId()).orElse(null);
        if (destination != null) {
            AccountStatement dstStmt = statementRepository.findByAccountIdAndPeriodMonth(destination.getId(), period)
                    .orElseGet(() -> statementRepository.save(new AccountStatement(
                            UUID.randomUUID(), destination.getId(), period, destination.getBalanceCache() - event.amount()
                    )));
            dstStmt.applyCredit(event.amount());
            statementRepository.save(dstStmt);
        }

        log.info("Successfully projected transfer {} onto statements for period {}", event.transactionId(), period);
        return true;
    }
}
```

