package io.buildscape.banking.consumer;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.buildscape.banking.event.TransferCompletedEvent;
import io.buildscape.banking.service.StatementProjector;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.stereotype.Component;

@Component
public class LedgerEventListener {

    private static final Logger log = LoggerFactory.getLogger(LedgerEventListener.class);

    private final StatementProjector statementProjector;
    private final ObjectMapper objectMapper;

    public LedgerEventListener(StatementProjector statementProjector, ObjectMapper objectMapper) {
        this.statementProjector = statementProjector;
        this.objectMapper = objectMapper;
    }

    @KafkaListener(
        topics = "${ledger.kafka.transfer-topic:banking.ledger.transfers}",
        groupId = "account-statement-projector",
        containerFactory = "kafkaListenerContainerFactory"
    )
    public void onTransferEvent(ConsumerRecord<String, String> record, Acknowledgment ack) {
        try {
            TransferCompletedEvent event = objectMapper.readValue(record.value(), TransferCompletedEvent.class);
            log.debug("Received Kafka record: key={}, eventId={}", record.key(), event.eventId());

            // Apply idempotent projection in database
            statementProjector.projectTransfer(event);

            // CRITICAL: Acknowledge offset to broker ONLY after DB commit
            ack.acknowledge();
        } catch (Exception ex) {
            log.error("Error consuming transfer event from partition {}: {}", record.partition(), ex.getMessage());
            throw new RuntimeException("Triggering retry/DLT", ex);
        }
    }
}
