import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class PointInTimeService {

    private final EntityManager entityManager;
    private final AccountRepository accountRepository;

    public PointInTimeService(EntityManager entityManager, AccountRepository accountRepository) {
        this.entityManager = entityManager;
        this.accountRepository = accountRepository;
    }

    @Transactional(readOnly = true)
    public Long reconstructHistoricalBalance(UUID accountId, Instant asOfTimestamp) {
        Account account = accountRepository.findById(accountId)
                .orElseThrow(() -> new AccountNotFoundException(accountId));

        // Sum all entries created on or before the given historical timestamp
        Number sum = (Number) entityManager.createNativeQuery("""
                SELECT COALESCE(SUM(amount), 0)
                FROM entry
                WHERE account_id = :accountId
                  AND created_at <= :timestamp
                """)
                .setParameter("accountId", accountId)
                .setParameter("timestamp", asOfTimestamp)
                .getSingleResult();

        return sum.longValue();
    }
}
