package io.buildscape.banking.service;

import io.buildscape.banking.domain.ReconciliationDiscrepancy;
import io.buildscape.banking.domain.ReconciliationRun;
import io.buildscape.banking.repository.AccountRepository;
import io.buildscape.banking.repository.AccountRepository.AccountDiscrepancyProjection;
import io.buildscape.banking.repository.ReconciliationDiscrepancyRepository;
import io.buildscape.banking.repository.ReconciliationRunRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Service
public class ReconciliationEngine {

    private static final Logger log = LoggerFactory.getLogger(ReconciliationEngine.class);

    private final AccountRepository accountRepository;
    private final ReconciliationRunRepository runRepository;
    private final ReconciliationDiscrepancyRepository discrepancyRepository;

    public ReconciliationEngine(AccountRepository accountRepository,
                                ReconciliationRunRepository runRepository,
                                ReconciliationDiscrepancyRepository discrepancyRepository) {
        this.accountRepository = accountRepository;
        this.runRepository = runRepository;
        this.discrepancyRepository = discrepancyRepository;
    }

    // Run nightly at 02:00:00 UTC
    @Scheduled(cron = "${ledger.reconciliation.cron:0 0 2 * * ?}")
    @Transactional
    public ReconciliationRun executeReconciliation() {
        UUID runId = UUID.randomUUID();
        ReconciliationRun run = new ReconciliationRun(runId);
        runRepository.save(run);

        log.info("🔍 Commencing ledger reconciliation audit run: {}", runId);

        try {
            long totalAccounts = accountRepository.count();
            List<AccountDiscrepancyProjection> discrepancies = accountRepository.findAccountsWithDrift();

            List<ReconciliationDiscrepancy> discrepancyEntities = new ArrayList<>();
            for (AccountDiscrepancyProjection disc : discrepancies) {
                log.error("🚨 BALANCE DRIFT DETECTED! Account: {}, Cached: {}, Calculated: {}, Drift: {} minor units",
                        disc.getAccountId(), disc.getCachedBalance(), disc.getCalculatedSum(), disc.getDriftAmount());

                discrepancyEntities.add(new ReconciliationDiscrepancy(
                        runId,
                        disc.getAccountId(),
                        disc.getCachedBalance(),
                        disc.getCalculatedSum(),
                        disc.getDriftAmount()
                ));
            }

            if (!discrepancyEntities.isEmpty()) {
                discrepancyRepository.saveAll(discrepancyEntities);
            }

            run.complete((int) totalAccounts, discrepancyEntities.size());
            runRepository.save(run);

            log.info("✓ Reconciliation run {} finished. Checked {} accounts, detected {} discrepancies.",
                    runId, totalAccounts, discrepancyEntities.size());
            return run;
        } catch (Exception ex) {
            log.error("Reconciliation run {} encountered fatal error: {}", runId, ex.getMessage(), ex);
            run.fail();
            runRepository.save(run);
            throw new RuntimeException(ex);
        }
    }
}
```

