Create `src/utils/financial.ts`:

```typescript
// Minor units (cents) to formatted currency string
export function formatMinorUnits(amount: number, currency: string = "USD"): string {
  const absoluteAmount = Math.abs(amount) / 100;
  const formatted = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(absoluteAmount);

  return amount < 0 ? `-${formatted}` : formatted;
}

// Generate standard UUIDv4 for Idempotency-Key headers
export function generateIdempotencyKey(): string {
  return "idem-" + crypto.randomUUID();
}
```

