### Step 4 · Build Transfer Modal Component with Idempotency Key Binding
Create `src/components/TransferModal.tsx`:

```tsx
import React, { useState, useEffect } from "react";
import { ledgerApi, AccountDTO } from "../api/ledgerClient";
import { generateIdempotencyKey, formatMinorUnits } from "../utils/financial";
import { Send, AlertCircle, CheckCircle2, X } from "lucide-react";

interface TransferModalProps {
  accounts: AccountDTO[];
  onClose: () => void;
  onSuccess: () => void;
}

export const TransferModal: React.FC<TransferModalProps> = ({ accounts, onClose, onSuccess }) => {
  const [fromId, setFromId] = useState(accounts[0]?.id || "");
  const [toId, setToId] = useState(accounts[1]?.id || "");
  const [dollarAmount, setDollarAmount] = useState("");
  const [description, setDescription] = useState("");
  const [idempotencyKey, setIdempotencyKey] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Generate a new idempotency key when modal opens
  useEffect(() => {
    setIdempotencyKey(generateIdempotencyKey());
  }, []);

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    const parsedCents = Math.round(parseFloat(dollarAmount) * 100);
    if (isNaN(parsedCents) || parsedCents <= 0) {
      setError("Please enter a valid transfer amount greater than $0.00");
      setLoading(false);
      return;
    }

    try {
      await ledgerApi.post(
        "/transfers",
        {
          fromAccountId: fromId,
          toAccountId: toId,
          amount: parsedCents,
          description: description || "Funds transfer",
        },
        {
          headers: { "Idempotency-Key": idempotencyKey },
        }
      );
      onSuccess();
      onClose();
    } catch (err: any) {
      const detail = err.response?.data?.detail || err.message || "Transfer failed";
      setError(detail);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm">
      <div className="w-full max-w-md rounded-2xl border border-stone-800 bg-[#12100d] p-6 shadow-2xl text-[#f0ede8]">
        <div className="flex items-center justify-between pb-4 border-b border-stone-800">
          <h2 className="font-serif text-lg font-bold text-white flex items-center gap-2">
            <Send className="h-4 w-4 text-amber-500" /> Initiate Ledger Transfer
          </h2>
          <button onClick={onClose} className="text-stone-400 hover:text-white transition">
            <X className="h-5 w-5" />
          </button>
        </div>

        {error && (
          <div className="mt-4 flex items-center gap-2 rounded-lg bg-red-950/50 border border-red-800/60 p-3 text-xs text-red-200">
            <AlertCircle className="h-4 w-4 shrink-0 text-red-400" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleTransfer} className="mt-4 space-y-4">
          <div>
            <label className="block text-xs font-mono text-stone-400 mb-1">Source Account</label>
            <select
              value={fromId}
              onChange={(e) => setFromId(e.target.value)}
              className="w-full rounded-lg border border-stone-800 bg-[#1a1713] px-3 py-2 text-xs font-mono text-white outline-none focus:border-amber-600"
            >
              {accounts.map((acc) => (
                <option key={acc.id} value={acc.id}>
                  {acc.holderName} ({acc.accountNumber}) — Avail: {formatMinorUnits(acc.balanceCache, acc.currency)}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-mono text-stone-400 mb-1">Destination Account</label>
            <select
              value={toId}
              onChange={(e) => setToId(e.target.value)}
              className="w-full rounded-lg border border-stone-800 bg-[#1a1713] px-3 py-2 text-xs font-mono text-white outline-none focus:border-amber-600"
            >
              {accounts.filter((a) => a.id !== fromId).map((acc) => (
                <option key={acc.id} value={acc.id}>
                  {acc.holderName} ({acc.accountNumber})
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-mono text-stone-400 mb-1">Amount ($ USD)</label>
            <input
              type="number"
              step="0.01"
              placeholder="50.00"
              value={dollarAmount}
              onChange={(e) => setDollarAmount(e.target.value)}
              className="w-full rounded-lg border border-stone-800 bg-[#1a1713] px-3 py-2 text-xs font-mono text-white outline-none focus:border-amber-600"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-mono text-stone-400 mb-1">Description / Reference</label>
            <input
              type="text"
              placeholder="e.g. Invoice payment #401"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full rounded-lg border border-stone-800 bg-[#1a1713] px-3 py-2 text-xs text-white outline-none focus:border-amber-600"
              required
            />
          </div>

          <div className="pt-2 border-t border-stone-800/80 flex items-center justify-between text-[11px] font-mono text-stone-500">
            <span>Idempotency-Key:</span>
            <span className="truncate max-w-[200px] text-stone-400">{idempotencyKey}</span>
          </div>

          <div className="pt-2 flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg border border-stone-800 px-4 py-2 text-xs font-medium text-stone-400 hover:text-white hover:bg-stone-900 transition"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading || fromId === toId}
              className="rounded-lg bg-amber-600 px-4 py-2 text-xs font-bold text-white hover:bg-amber-500 transition disabled:opacity-50"
            >
              {loading ? "Executing Transfer..." : "Transfer Funds"}
