### Step 6 · Multi-Threaded Property-Based Conservation Test
Create `src/test/java/io/buildscape/banking/LedgerPropertyConservationTest.java`:

```java
package io.buildscape.banking;

import io.buildscape.banking.domain.Account;
import io.buildscape.banking.dto.TransferRequest;
import io.buildscape.banking.repository.AccountRepository;
import io.buildscape.banking.service.TransferService;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.UUID;
import java.util.concurrent.*;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class LedgerPropertyConservationTest {

    @Autowired
    private AccountRepository accountRepository;
    @Autowired
    private TransferService transferService;

    @Test
    @DisplayName("Universal Invariant: Total system balance is 100% conserved across 500 randomized concurrent transfers")
    void totalSystemBalanceIsConservedUnderChaoticConcurrency() throws Exception {
        int accountCount = 8;
        long initialDepositPerAccount = 250_000L; // $2,500.00 each
        long expectedTotalSystemMoney = accountCount * initialDepositPerAccount; // $20,000.00 total

        List<UUID> accountIds = new ArrayList<>();
        for (int i = 0; i < accountCount; i++) {
            UUID id = UUID.randomUUID();
            accountRepository.save(new Account(id, "PROP-ACC-" + i, "Trader " + i, "USD", initialDepositPerAccount));
            accountIds.add(id);
        }

        int totalTransfers = 500;
        ExecutorService executor = Executors.newFixedThreadPool(16);
        CountDownLatch latch = new CountDownLatch(totalTransfers);
        Random random = new Random(1337); // Deterministic seed

        for (int i = 0; i < totalTransfers; i++) {
            final int index = i;
            executor.submit(() -> {
                try {
                    int fromIdx = random.nextInt(accountCount);
                    int toIdx = (fromIdx + 1 + random.nextInt(accountCount - 1)) % accountCount;
                    UUID from = accountIds.get(fromIdx);
                    UUID to = accountIds.get(toIdx);
                    long amount = 1 + random.nextInt(5_000); // 1 to $50.00
                    String key = "prop-idem-" + index;

                    transferService.executeTransfer(key, new TransferRequest(from, to, amount, "Random transfer " + index));
                } catch (Exception ignored) {
                    // InsufficientFundsExceptions are expected and valid business rejections
                } finally {
                    latch.countDown();
                }
            });
        }

        latch.await(30, TimeUnit.SECONDS);
        executor.shutdown();

        // INVARIANT VERIFICATION: Sum all account balances in PostgreSQL
        long actualTotalMoney = accountRepository.findAll().stream()
                .filter(a -> accountIds.contains(a.getId()))
                .mapToLong(Account::getBalanceCache)
                .sum();

        assertThat(actualTotalMoney)
                .withFailMessage("System money leaked or minted! Expected %d cents, found %d cents",
                        expectedTotalSystemMoney, actualTotalMoney)
                .isEqualTo(expectedTotalSystemMoney);
    }
}
```

### Step 7 · Create Production Multi-Stage Dockerfile
Create `Dockerfile`:

```dockerfile
# Stage 1: Build JAR
FROM eclipse-temurin:21-jdk-alpine AS builder
WORKDIR /build
COPY .mvn/ .mvn/
COPY mvnw pom.xml ./
RUN chmod +x ./mvnw && ./mvnw dependency:go-offline -B
COPY src ./src
RUN ./mvnw clean package -DskipTests

# Stage 2: Hardened Runtime JRE
FROM eclipse-temurin:21-jre-alpine
WORKDIR /app
RUN addgroup -g 10001 -S bankinggroup && \
    adduser -u 10001 -S bankinguser -G bankinggroup
COPY --from=builder /build/target/*.jar app.jar
RUN chown -R bankinguser:bankinggroup /app
USER bankinguser
EXPOSE 8080
ENTRYPOINT ["java", "-XX:+UseContainerSupport", "-XX:MaxRAMPercentage=75.0", "-jar", "app.jar"]
```

