### Step 2 · Implement Strongly-Typed Configuration Domain Model
Create `internal/config/config.go` defining the options that control crawler execution:

```go
package config

import (
	"errors"
	"fmt"
	"net/url"
	"time"
)

// Config holds all validated runtime parameters for the crawler engine.
type Config struct {
	// SeedURL is the starting target URL.
	SeedURL *url.URL

	// Concurrency defines the maximum number of concurrent worker goroutines.
	Concurrency int

	// MaxPages is the upper bound on total unique pages to crawl before stopping.
	MaxPages int

	// MaxDepth limits how many links deep the crawler will traverse from the seed.
	MaxDepth int

	// RateLimit specifies the maximum HTTP requests allowed per second.
	RateLimit float64

	// RequestTimeout is the hard timeout applied to each individual HTTP request.
	RequestTimeout time.Duration

	// OutputFile is the target file path where results will be written.
	OutputFile string

	// OutputFormat determines serialization: "json" (array) or "jsonl" (line-delimited).
	OutputFormat string

	// RestrictDomain ensures the crawler only visits URLs with the exact same host as SeedURL.
	RestrictDomain bool

	// UserAgent is the identifier sent in the HTTP request headers.
	UserAgent string
}

// Validate checks all configuration constraints and returns descriptive errors.
func (c *Config) Validate() error {
	if c.SeedURL == nil || c.SeedURL.String() == "" {
		return errors.New("seed URL is required (use -url=https://example.com)")
	}

	if c.SeedURL.Scheme != "http" && c.SeedURL.Scheme != "https" {
		return fmt.Errorf("invalid URL scheme %q: only http and https are supported", c.SeedURL.Scheme)
	}

	if c.SeedURL.Host == "" {
		return fmt.Errorf("invalid URL %q: host must not be empty", c.SeedURL.String())
	}

	if c.Concurrency < 1 {
		return fmt.Errorf("concurrency must be at least 1, got %d", c.Concurrency)
	}
	if c.Concurrency > 128 {
		return fmt.Errorf("concurrency exceeds safety limit of 128, got %d", c.Concurrency)
	}

	if c.MaxPages < 1 {
		return fmt.Errorf("max-pages must be at least 1, got %d", c.MaxPages)
	}

	if c.MaxDepth < 0 {
		return fmt.Errorf("max-depth cannot be negative, got %d", c.MaxDepth)
	}

	if c.RateLimit <= 0 {
		return fmt.Errorf("rate-limit must be greater than 0 requests/sec, got %.2f", c.RateLimit)
	}

	if c.RequestTimeout < 500*time.Millisecond {
		return fmt.Errorf("request timeout must be at least 500ms, got %v", c.RequestTimeout)
	}

	if c.OutputFormat != "json" && c.OutputFormat != "jsonl" {
		return fmt.Errorf("unsupported output format %q: must be 'json' or 'jsonl'", c.OutputFormat)
	}

	return nil
}
```

### Step 3 · Implement Robust CLI Flag Parser
Create `internal/config/flags.go` using standard Go `flag.FlagSet` for isolated testability:

```go
package config

import (
	"flag"
	"fmt"
	"io"
	"net/url"
	"time"
)

// ParseFlags parses command-line arguments into a validated Config struct.
// It accepts an argument slice and output writer to allow unit test verification.
func ParseFlags(args []string, output io.Writer) (*Config, error) {
	fs := flag.NewFlagSet("gocrawl", flag.ContinueOnError)
	fs.SetOutput(output)

	var (
		rawURL         = fs.String("url", "", "Target seed URL to begin crawling (required)")
		concurrency    = fs.Int("c", 8, "Number of concurrent crawler workers")
		maxPages       = fs.Int("max-pages", 100, "Maximum number of unique pages to crawl")
		maxDepth       = fs.Int("depth", 3, "Maximum link traversal depth (0 = seed page only)")
		rateLimit      = fs.Float64("rate", 10.0, "Maximum requests per second (politeness limit)")
		timeoutSeconds = fs.Int("timeout", 10, "HTTP request timeout in seconds")
		outputFile     = fs.String("output", "", "Destination file path for crawl results (default stdout)")
		outputFormat   = fs.String("format", "jsonl", "Output format: 'jsonl' or 'json'")
		restrictDomain = fs.Bool("same-domain", true, "Restrict crawling strictly to the seed host domain")
		userAgent      = fs.String("user-agent", "GoCrawl/1.0 (+https://github.com/buildscape/gocrawl)", "User-Agent header string")
	)

	fs.Usage = func() {
		fmt.Fprintln(output, "GoCrawl - High-Performance Concurrent Web Crawler CLI")
		fmt.Fprintln(output, "\nUsage: gocrawl -url=<target-url> [flags]")
		fmt.Fprintln(output, "\nFlags:")
		fs.PrintDefaults()
	}

	if err := fs.Parse(args); err != nil {
		return nil, err
	}

	if *rawURL == "" {
		fs.Usage()
		return nil, fmt.Errorf("missing required flag: -url")
	}

	parsedURL, err := url.Parse(*rawURL)
	if err != nil {
		return nil, fmt.Errorf("failed to parse seed URL %q: %w", *rawURL, err)
	}

	cfg := &Config{
		SeedURL:        parsedURL,
		Concurrency:    *concurrency,
		MaxPages:       *maxPages,
		MaxDepth:       *maxDepth,
		RateLimit:      *rateLimit,
		RequestTimeout: time.Duration(*timeoutSeconds) * time.Second,
		OutputFile:     *outputFile,
		OutputFormat:   *outputFormat,
		RestrictDomain: *restrictDomain,
		UserAgent:      *userAgent,
	}

	if err := cfg.Validate(); err != nil {
		return nil, fmt.Errorf("configuration error: %w", err)
	}

	return cfg, nil
}
```

### Step 4 · Implement ANSI Colored Terminal Logger
Create `internal/logger/logger.go` to deliver clear terminal status output:

```go
package logger

import (
	"fmt"
	"io"
	"os"
	"sync"
	"time"
)

type Level int

const (
	LevelDebug Level = iota
	LevelInfo
	LevelWarn
	LevelError
)

const (
	colorReset  = "\033[0m"
	colorCyan   = "\033[36m"
	colorGreen  = "\033[32m"
	colorYellow = "\033[33m"
	colorRed    = "\033[31m"
)

type Logger struct {
	mu     sync.Mutex
	w      io.Writer
	colors bool
}

func New(w io.Writer, colors bool) *Logger {
	return &Logger{w: w, colors: colors}
}

var Default = New(os.Stderr, true)

func (l *Logger) log(prefix, color, format string, args ...any) {
	l.mu.Lock()
	defer l.mu.Unlock()

	timestamp := time.Now().Format("15:04:05")
	msg := fmt.Sprintf(format, args...)

	if l.colors {
		fmt.Fprintf(l.w, "%s%s %s%s %s\n", color, timestamp, prefix, colorReset, msg)
	} else {
		fmt.Fprintf(l.w, "%s %s %s\n", timestamp, prefix, msg)
	}
}

func (l *Logger) Info(format string, args ...any) {
	l.log("[INFO]", colorGreen, format, args...)
}

func (l *Logger) Warn(format string, args ...any) {
	l.log("[WARN]", colorYellow, format, args...)
}

func (l *Logger) Error(format string, args ...any) {
	l.log("[ERR] ", colorRed, format, args...)
}
```

