// Engine coordinates the concurrent crawling pipeline.
type Engine struct {
	cfg *config.Config
	log *logger.Logger
}

// New creates an Engine instance from validated configuration.
func New(cfg *config.Config, log *logger.Logger) *Engine {
	return &Engine{
		cfg: cfg,
		log: log,
	}
}

// Run starts the crawler and blocks until all pages are crawled or ctx is cancelled.
func (e *Engine) Run(ctx context.Context) error {
	e.log.Info("Starting GoCrawl on target: %s", e.cfg.SeedURL.String())
	e.log.Info("Configuration: concurrency=%d, max-pages=%d, max-depth=%d, rate=%.1f req/s",
		e.cfg.Concurrency, e.cfg.MaxPages, e.cfg.MaxDepth, e.cfg.RateLimit)

	// Skeleton placeholder: in Phase 4 & 5, worker pool processes jobs here
	select {
	case <-ctx.Done():
		e.log.Warn("Crawler interrupted by context cancellation: %v", ctx.Err())
		return ctx.Err()
	case <-time.After(100 * time.Millisecond):
		e.log.Info("Phase 1 initialization check completed successfully.")
		return nil
	}
}
