### Step 6 · Author Root CLI Entrypoint with OS Signal Interception
Create `cmd/gocrawl/main.go` linking the CLI flags, logger, signal context, and engine:

```go
package main

import (
	"context"
	"errors"
	"os"
	"os/signal"
	"syscall"

	"github.com/buildscape/gocrawl/internal/config"
	"github.com/buildscape/gocrawl/internal/crawler"
	"github.com/buildscape/gocrawl/internal/logger"
)

func main() {
	log := logger.Default

	// 1. Parse and validate CLI flags from os.Args[1:]
	cfg, err := config.ParseFlags(os.Args[1:], os.Stderr)
	if err != nil {
		// If user passed -h or --help, ParseFlags returns flag.ErrHelp; exit cleanly
		if errors.Is(err, config.ErrHelp) {
			os.Exit(0)
		}
		log.Error("Initialization failed: %v", err)
		os.Exit(1)
	}

	// 2. Intercept POSIX interruption signals (SIGINT, SIGTERM) into a cancellable Context
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// 3. Instantiate and execute the crawler engine
	engine := crawler.New(cfg, log)
	if err := engine.Run(ctx); err != nil {
		if errors.Is(err, context.Canceled) {
			log.Warn("Crawler halted gracefully by user request.")
			os.Exit(0)
		}
		log.Error("Crawler execution error: %v", err)
		os.Exit(1)
	}

	log.Info("Crawler completed successfully.")
}
```

Add `var ErrHelp = flag.ErrHelp` in `internal/config/flags.go` to support help exit.

