### Step 2 · Configure High-Performance Connection-Pooled Transport
Create `internal/fetcher/client.go` configuring optimized connection reuse and timeouts:

```go
package fetcher

import (
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/buildscape/gocrawl/internal/config"
)

// NewHTTPClient creates an http.Client tuned specifically for concurrent crawling.
func NewHTTPClient(cfg *config.Config) *http.Client {
	transport := &http.Transport{
		Proxy: http.ProxyFromEnvironment,
		DialContext: (&net.Dialer{
			Timeout:   10 * time.Second,
			KeepAlive: 30 * time.Second,
		}).DialContext,
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          100,
		MaxIdleConnsPerHost:   cfg.Concurrency * 2,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
		ResponseHeaderTimeout: cfg.RequestTimeout,
	}

	return &http.Client{
		Transport: transport,
		Timeout:   cfg.RequestTimeout,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Maximum 10 redirects to avoid cycles
			if len(via) >= 10 {
				return http.ErrUseLastResponse
			}
			// If restricted to same domain, do not follow redirects to external hosts
			if cfg.RestrictDomain && req.URL.Host != cfg.SeedURL.Host {
				return http.ErrUseLastResponse
			}
			return nil
		},
	}
}
