### Step 3 · Implement Memory-Safe HTTP Fetcher with `io.LimitReader`
Create `internal/fetcher/fetcher.go` executing context-bound requests with body limits:

```go
package fetcher

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/buildscape/gocrawl/internal/config"
)

const (
	// MaxResponseBodyBytes sets the ceiling for page contents (2MB)
	MaxResponseBodyBytes = 2 * 1024 * 1024
)

type HTTPFetcher struct {
	client *http.Client
	cfg    *config.Config
}

func New(cfg *config.Config) *HTTPFetcher {
	return &HTTPFetcher{
		client: NewHTTPClient(cfg),
		cfg:    cfg,
	}
}

func (f *HTTPFetcher) Fetch(ctx context.Context, target *url.URL) (*PageResponse, error) {
	start := time.Now()

	// 1. Construct request with parent context
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("failed to build request for %s: %w", target, err)
	}

	// 2. Set polite and standard request headers
	req.Header.Set("User-Agent", f.cfg.UserAgent)
	req.Header.Set("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8")
	req.Header.Set("Accept-Language", "en-US,en;q=0.5")
	req.Header.Set("Accept-Encoding", "gzip, deflate")

	// 3. Dispatch HTTP request
	resp, err := f.client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("network request failed for %s: %w", target, err)
	}
	defer resp.Body.Close()

	duration := time.Since(start)
	contentType := resp.Header.Get("Content-Type")

	// 4. Validate that response is HTML or text before reading
	if !strings.HasPrefix(contentType, "text/") &&
		!strings.Contains(contentType, "application/xhtml+xml") &&
		!strings.Contains(contentType, "application/xml") {
		// Drain up to 1KB to enable connection reuse, then return non-HTML response
		_, _ = io.CopyN(io.Discard, resp.Body, 1024)
		return &PageResponse{
			URL:         target,
			StatusCode:  resp.StatusCode,
			Header:      resp.Header,
			ContentType: contentType,
			Body:        nil,
			Duration:    duration,
		}, nil
	}

	// 5. Read body bounded by MaxResponseBodyBytes
	limitedReader := io.LimitReader(resp.Body, MaxResponseBodyBytes)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return nil, fmt.Errorf("error reading response body from %s: %w", target, err)
	}

	return &PageResponse{
		URL:          target,
		StatusCode:   resp.StatusCode,
		Header:       resp.Header,
		ContentType:  contentType,
		Body:         body,
		Duration:     duration,
		RedirectedTo: resp.Request.URL,
	}, nil
}
```

### Step 4 · Implement Exponential Backoff Retry Decorator
Create `internal/fetcher/retry.go` to handle transient server errors (500, 502, 503, 504):

```go
package fetcher

import (
	"context"
	"fmt"
	"net/url"
	"time"
)

type RetryingFetcher struct {
	base       Fetcher
	maxRetries int
	baseDelay  time.Duration
}

func NewRetryingFetcher(base Fetcher, maxRetries int, baseDelay time.Duration) *RetryingFetcher {
	return &RetryingFetcher{
		base:       base,
		maxRetries: maxRetries,
		baseDelay:  baseDelay,
	}
}

func (r *RetryingFetcher) Fetch(ctx context.Context, target *url.URL) (*PageResponse, error) {
	var lastErr error
	delay := r.baseDelay

	for attempt := 0; attempt <= r.maxRetries; attempt++ {
		if attempt > 0 {
			select {
			case <-ctx.Done():
				return nil, ctx.Err()
			case <-time.After(delay):
				delay *= 2 // Exponential backoff: 500ms, 1000ms, 2000ms
			}
		}

		resp, err := r.base.Fetch(ctx, target)
		if err == nil {
			// Only retry on transient 5xx server errors
			if resp.StatusCode < 500 {
				return resp, nil
			}
			lastErr = fmt.Errorf("server error HTTP %d", resp.StatusCode)
		} else {
			lastErr = err
		}
	}

	return nil, fmt.Errorf("fetch failed after %d retries: %w", r.maxRetries, lastErr)
}
```

