### Step 2 · Implement Canonical URL Normalizer
Create `internal/parser/normalizer.go` to handle RFC 3986 URL standardization, query parameter pruning, and path cleaning:

```go
package parser

import (
	"net/url"
	"path"
	"sort"
	"strings"
)

// TrackingQueryParams lists ubiquitous query parameters that do not alter page content.
var TrackingQueryParams = map[string]bool{
	"utm_source":   true,
	"utm_medium":   true,
	"utm_campaign": true,
	"utm_term":     true,
	"utm_content":  true,
	"fbclid":       true,
	"gclid":        true,
	"msclkid":      true,
	"ref":          true,
	"source":       true,
}

// NormalizeURL resolves a raw link against a base page URL and applies canonical normalization rules.
func NormalizeURL(baseURL *url.URL, rawHref string) (*url.URL, error) {
	trimmed := strings.TrimSpace(rawHref)
	if trimmed == "" {
		return nil, url.InvalidHostError("empty URL")
	}

	// 1. Parse raw string into URL object
	parsed, err := url.Parse(trimmed)
	if err != nil {
		return nil, err
	}

	// 2. Resolve relative URLs (e.g. "../about", "/docs", "page.html") against base
	resolved := baseURL.ResolveReference(parsed)

	// 3. Force lowercase scheme and host (paths remain case-sensitive per RFC 3986)
	resolved.Scheme = strings.ToLower(resolved.Scheme)
	resolved.Host = strings.ToLower(resolved.Host)

	// Remove standard default ports
	if (resolved.Scheme == "http" && resolved.Port() == "80") ||
		(resolved.Scheme == "https" && resolved.Port() == "443") {
		resolved.Host = resolved.Hostname()
	}

	// 4. Strip client-side fragment identifier (#section)
	resolved.Fragment = ""

	// 5. Clean path dot-segments (/a/b/../c -> /a/c)
	if resolved.Path != "" {
		cleanPath := path.Clean(resolved.Path)
		// Preserve trailing slash if original had it and wasn't root
		if strings.HasSuffix(resolved.Path, "/") && cleanPath != "/" {
			cleanPath += "/"
		}
		// Strip redundant directory index files
		if strings.HasSuffix(cleanPath, "/index.html") || strings.HasSuffix(cleanPath, "/index.htm") {
			cleanPath = strings.TrimSuffix(cleanPath, "index.html")
			cleanPath = strings.TrimSuffix(cleanPath, "index.htm")
		}
		resolved.Path = cleanPath
	} else {
		resolved.Path = "/"
	}

	// 6. Scrub tracking query parameters and sort remaining alphabetically
	if resolved.RawQuery != "" {
		queryParams := resolved.Query()
		for key := range queryParams {
			if TrackingQueryParams[strings.ToLower(key)] {
				queryParams.Del(key)
			}
		}

		if len(queryParams) == 0 {
			resolved.RawQuery = ""
		} else {
			// Encode sorts keys predictably
			resolved.RawQuery = queryParams.Encode()
		}
	}

	return resolved, nil
}
```

### Step 3 · Implement Domain Boundary and File Filter
