package parser

import (
	"net/url"
	"path/filepath"
	"strings"
)

// NonCrawlableExtensions identifies file formats that do not contain HTML hyperlinks.
var NonCrawlableExtensions = map[string]bool{
	// Images
	".jpg": true, ".jpeg": true, ".png": true, ".gif": true, ".svg": true, ".webp": true, ".ico": true,
	// Documents
	".pdf": true, ".doc": true, ".docx": true, ".xls": true, ".xlsx": true, ".ppt": true, ".pptx": true,
	// Archives
	".zip": true, ".tar": true, ".gz": true, ".rar": true, ".7z": true, ".bz2": true,
	// Media
	".mp3": true, ".mp4": true, ".wav": true, ".avi": true, ".mov": true, ".mkv": true,
	// Styles and Scripts
	".css": true, ".js": true, ".map": true,
}

// FilterOptions configures filtering behavior.
type FilterOptions struct {
	AllowedHost   string
	RestrictHost  bool
}

// ShouldCrawl evaluates whether a resolved URL is acceptable for crawling.
func ShouldCrawl(target *url.URL, opts FilterOptions) bool {
	if target == nil {
		return false
	}

	// 1. Only allow HTTP and HTTPS schemes
	if target.Scheme != "http" && target.Scheme != "https" {
		return false
	}

	// 2. Reject empty hosts
	if target.Host == "" {
		return false
	}

	// 3. Enforce same-domain boundary if configured
	if opts.RestrictHost && opts.AllowedHost != "" {
		if !strings.EqualFold(target.Host, opts.AllowedHost) {
			return false
		}
	}

	// 4. Reject binary asset extensions
	ext := strings.ToLower(filepath.Ext(target.Path))
	if NonCrawlableExtensions[ext] {
		return false
	}

	return true
}
