### Step 4 · Implement High-Performance Streaming HTML Tokenizer
Create `internal/parser/tokenizer.go` using `golang.org/x/net/html` to extract `<a>` tags and text:

```go
package parser

import (
	"bytes"
	"io"
	"net/url"
	"strings"

	"golang.org/x/net/html"
)

// ExtractLinks streams through an HTML document byte slice, extracting all valid hyperlinks.
func ExtractLinks(baseURL *url.URL, body []byte, filterOpts FilterOptions) ([]DiscoveredLink, error) {
	tokenizer := html.NewTokenizer(bytes.NewReader(body))
	var links []DiscoveredLink

	for {
		tokenType := tokenizer.Next()

		switch tokenType {
		case html.ErrorToken:
			err := tokenizer.Err()
			if err == io.EOF {
				return links, nil
			}
			return links, err

		case html.StartTagToken, html.SelfClosingTagToken:
			token := tokenizer.Token()
			if token.Data != "a" {
				continue
			}

			var rawHref string
			for _, attr := range token.Attr {
				if attr.Key == "href" {
					rawHref = attr.Val
					break
				}
			}

			if rawHref == "" || strings.HasPrefix(rawHref, "#") {
				continue
			}

			// Extract visible anchor text inside <a> tag if StartTagToken
			var anchorText string
			if tokenType == html.StartTagToken {
				anchorText = extractAnchorText(tokenizer)
			}

			// Canonicalize URL
			normalized, err := NormalizeURL(baseURL, rawHref)
			if err != nil {
				continue
			}

			// Filter by domain and file extension
			if !ShouldCrawl(normalized, filterOpts) {
				continue
			}

			links = append(links, DiscoveredLink{
				Raw:        rawHref,
				Resolved:   normalized,
				AnchorText: strings.TrimSpace(anchorText),
			})
		}
	}
}

// extractAnchorText collects immediate inner text until the closing </a> tag.
func extractAnchorText(z *html.Tokenizer) string {
	var sb strings.Builder
	for {
		tt := z.Next()
		switch tt {
		case html.ErrorToken:
			return sb.String()
		case html.TextToken:
			sb.WriteString(string(z.Text()))
		case html.EndTagToken:
			t := z.Token()
			if t.Data == "a" {
				return sb.String()
			}
		}
	}
}
```

### Step 5 · Implement HTML Metadata Extractor
Create `internal/parser/metadata.go` to scan for `<title>`, `<meta name="description">`, and `<link rel="canonical">` tags:

```go
package parser

import (
	"bytes"
	"io"
	"strings"

	"golang.org/x/net/html"
)

// ExtractMetadata scans the HTML document for title, description, and canonical link.
func ExtractMetadata(body []byte) PageMetadata {
	var meta PageMetadata
	z := html.NewTokenizer(bytes.NewReader(body))

	for {
		tt := z.Next()
		switch tt {
		case html.ErrorToken:
			if z.Err() == io.EOF {
				return meta
			}
			return meta

		case html.StartTagToken:
			t := z.Token()
			if t.Data == "title" {
				if z.Next() == html.TextToken {
					meta.Title = strings.TrimSpace(string(z.Text()))
				}
			}

		case html.SelfClosingTagToken:
			t := z.Token()
			if t.Data == "meta" {
				var name, content string
				for _, attr := range t.Attr {
					if strings.EqualFold(attr.Key, "name") || strings.EqualFold(attr.Key, "property") {
						name = strings.ToLower(attr.Val)
					} else if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if name == "description" || name == "og:description" {
					if meta.Description == "" {
						meta.Description = strings.TrimSpace(content)
					}
				}
			} else if t.Data == "link" {
				var isCanonical bool
				var href string
				for _, attr := range t.Attr {
					if attr.Key == "rel" && strings.EqualFold(attr.Val, "canonical") {
						isCanonical = true
					} else if attr.Key == "href" {
						href = attr.Val
					}
				}
				if isCanonical && href != "" {
					meta.Canonical = strings.TrimSpace(href)
				}
			}
		}
	}
}
```

