### Step 2 · Implement Thread-Safe `VisitedSet` with `sync.RWMutex`
Create `internal/state/visited.go` implementing atomic test-and-set semantics:

```go
package state

import "sync"

// VisitedSet is a thread-safe deduplication set for URL strings.
type VisitedSet struct {
	mu sync.RWMutex
	m  map[string]struct{}
}

// NewVisitedSet initializes an empty VisitedSet with pre-allocated capacity.
func NewVisitedSet(initialCapacity int) *VisitedSet {
	if initialCapacity <= 0 {
		initialCapacity = 1024
	}
	return &VisitedSet{
		m: make(map[string]struct{}, initialCapacity),
	}
}

// CheckAndAdd atomically checks if a URL is present. If absent, it records it and returns true.
// If the URL was already present, it returns false.
func (v *VisitedSet) CheckAndAdd(rawURL string) bool {
	v.mu.Lock()
	defer v.mu.Unlock()

	if _, exists := v.m[rawURL]; exists {
		return false
	}

	v.m[rawURL] = struct{}{}
	return true
}

// Contains returns true if the URL has already been recorded.
func (v *VisitedSet) Contains(rawURL string) bool {
	v.mu.RLock()
	defer v.mu.RUnlock()
	_, exists := v.m[rawURL]
	return exists
}

// Count returns the total number of unique recorded URLs.
func (v *VisitedSet) Count() int {
	v.mu.RLock()
	defer v.mu.RUnlock()
	return len(v.m)
}

// All returns a snapshot slice of all recorded URLs.
func (v *VisitedSet) All() []string {
	v.mu.RLock()
	defer v.mu.RUnlock()

	out := make([]string, 0, len(v.m))
	for u := range v.m {
		out = append(out, u)
	}
	return out
}
```

### Step 3 · Implement Lock-Free Crawler Metrics Collector
Create `internal/state/metrics.go` using `sync/atomic` for single-nanosecond overhead:

```go
package state

import (
	"sync/atomic"
	"time"
)

// Metrics tracks real-time crawler performance using lock-free hardware atomics.
type Metrics struct {
	startTime     time.Time
	pagesCrawled  atomic.Uint64
	bytesRead     atomic.Uint64
	linksFound    atomic.Uint64
	errorsCount   atomic.Uint64
	activeWorkers atomic.Int64
}

// NewMetrics initializes a fresh metrics collector.
func NewMetrics() *Metrics {
	return &Metrics{
		startTime: time.Now(),
	}
}

// IncPages increments successfully crawled pages count by 1.
func (m *Metrics) IncPages() {
	m.pagesCrawled.Add(1)
}

// AddBytes adds the number of downloaded bytes to the total.
func (m *Metrics) AddBytes(n int) {
	if n > 0 {
		m.bytesRead.Add(uint64(n))
	}
}

// AddLinks adds newly discovered links to the running total.
func (m *Metrics) AddLinks(n int) {
	if n > 0 {
		m.linksFound.Add(uint64(n))
	}
}

// IncErrors increments the failure counter by 1.
func (m *Metrics) IncErrors() {
	m.errorsCount.Add(1)
}

// IncWorkers registers an active worker goroutine.
func (m *Metrics) IncWorkers() {
	m.activeWorkers.Add(1)
}

// DecWorkers registers a worker completing or pausing.
func (m *Metrics) DecWorkers() {
	m.activeWorkers.Add(-1)
}

// Snapshot produces an immutable point-in-time performance summary.
func (m *Metrics) Snapshot() MetricsSnapshot {
	elapsed := time.Since(m.startTime)
	pages := m.pagesCrawled.Load()

	var pagesPerSec float64
	if elapsed.Seconds() > 0 {
		pagesPerSec = float64(pages) / elapsed.Seconds()
	}

	return MetricsSnapshot{
		PagesCrawled:   pages,
		BytesRead:      m.bytesRead.Load(),
		LinksFound:     m.linksFound.Load(),
		ErrorsCount:    m.errorsCount.Load(),
		ActiveWorkers:  m.activeWorkers.Load(),
		ElapsedTime:    elapsed,
		PagesPerSecond: pagesPerSec,
	}
}
```

