package ratelimit

import (
	"context"
	"time"

	"golang.org/x/time/rate"
)

// RateLimiter controls the dispatch frequency of crawler HTTP requests.
type RateLimiter struct {
	limiter *rate.Limiter
}

// NewLimiter creates a RateLimiter enforcing requestsPerSec with allowable burst capacity.
func NewLimiter(requestsPerSec float64, burst int) *RateLimiter {
	if requestsPerSec <= 0 {
		requestsPerSec = 10.0
	}
	if burst < 1 {
		burst = 1
	}
	limit := rate.Limit(requestsPerSec)
	return &RateLimiter{
		limiter: rate.NewLimiter(limit, burst),
	}
}

// Wait blocks cooperatively until a token is available or context is cancelled.
func (r *RateLimiter) Wait(ctx context.Context) error {
	return r.limiter.Wait(ctx)
}

// SetRate dynamically reconfigures the rate limit without restarting the engine.
func (r *RateLimiter) SetRate(requestsPerSec float64) {
	r.limiter.SetLimit(rate.Limit(requestsPerSec))
}
