### Step 5 · Implement Robots.txt Politeness Parser
Create `internal/ratelimit/robots.go` parsing site crawling restrictions:

```go
package ratelimit

import (
	"bufio"
	"context"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
)

// RobotsGuard evaluates whether a URL path is permissible under robots.txt.
type RobotsGuard struct {
	mu             sync.RWMutex
	disallowed     []string
	userAgent      string
	crawlDelaySecs int
}

// NewRobotsGuard creates an empty robots guard for a given user agent.
func NewRobotsGuard(userAgent string) *RobotsGuard {
	return &RobotsGuard{
		disallowed: make([]string, 0),
		userAgent:  strings.ToLower(userAgent),
	}
}

// LoadFromHost attempts to fetch and parse /robots.txt from the target host.
func (g *RobotsGuard) LoadFromHost(ctx context.Context, client *http.Client, hostURL *url.URL) error {
	robotsURL := fmt.Sprintf("%s://%s/robots.txt", hostURL.Scheme, hostURL.Host)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, robotsURL, nil)
	if err != nil {
		return err
	}
	req.Header.Set("User-Agent", g.userAgent)

	resp, err := client.Do(req)
	if err != nil {
		// If robots.txt cannot be reached, standard convention allows crawling
		return nil
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil
	}

	g.mu.Lock()
	defer g.mu.Unlock()

	scanner := bufio.NewScanner(resp.Body)
	currentUserAgentApplies := false

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}

		parts := strings.SplitN(line, ":", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(parts[0]))
		val := strings.TrimSpace(parts[1])

		if key == "user-agent" {
			lowerVal := strings.ToLower(val)
			currentUserAgentApplies = lowerVal == "*" || strings.Contains(g.userAgent, lowerVal)
		} else if currentUserAgentApplies && key == "disallow" && val != "" {
			g.disallowed = append(g.disallowed, val)
		}
	}

	return scanner.Err()
}

// IsAllowed checks if a path is permitted.
func (g *RobotsGuard) IsAllowed(targetPath string) bool {
	g.mu.RLock()
	defer g.mu.RUnlock()

	if targetPath == "" {
		targetPath = "/"
	}

	for _, prefix := range g.disallowed {
		if strings.HasPrefix(targetPath, prefix) {
			return false
		}
	}
	return true
}
```

