)

// Controller manages shared runtime state, deduplication, and politeness limits.
type Controller struct {
	Visited *VisitedSet
	Metrics *Metrics
	Limiter *ratelimit.RateLimiter
	Robots  *ratelimit.RobotsGuard
	cfg     *config.Config
}

// NewController constructs a Controller according to user configuration.
func NewController(cfg *config.Config) *Controller {
	return &Controller{
		Visited: NewVisitedSet(cfg.MaxPages * 2),
		Metrics: NewMetrics(),
		Limiter: ratelimit.NewLimiter(cfg.RateLimit, int(cfg.RateLimit/2)+1),
		Robots:  ratelimit.NewRobotsGuard(cfg.UserAgent),
		cfg:     cfg,
	}
}

// AcquirePermit verifies robots compliance and respects the token-bucket rate limit.
func (c *Controller) AcquirePermit(ctx context.Context, target *url.URL) error {
	if !c.Robots.IsAllowed(target.Path) {
		return ErrRobotsDisallowed
	}
	return c.Limiter.Wait(ctx)
}

// ErrRobotsDisallowed is returned when a URL path is blocked by robots.txt.
var ErrRobotsDisallowed = &RobotsError{Msg: "path disallowed by robots.txt"}

type RobotsError struct{ Msg string }
func (e *RobotsError) Error() string { return e.Msg }
