func TestVisitedSet_ConcurrentStressRace(t *testing.T) {
	set := state.NewVisitedSet(1000)
	const goroutines = 500
	const urlsPerGoroutine = 50

	var wg sync.WaitGroup
	wg.Add(goroutines)

	var duplicateDetections atomic.Int64

	for g := 0; g < goroutines; g++ {
		go func(workerID int) {
			defer wg.Done()
			for i := 0; i < urlsPerGoroutine; i++ {
				// Create overlapping URLs among workers to force race collisions
				u := fmt.Sprintf("https://example.com/item/%d", i%20)
				if !set.CheckAndAdd(u) {
					duplicateDetections.Add(1)
				}
				_ = set.Contains(u)
			}
		}(g)
	}

	wg.Wait()

	// Exactly 20 distinct URLs were inserted
	if set.Count() != 20 {
		t.Errorf("expected exactly 20 distinct URLs, got %d", set.Count())
	}

	totalAttempts := goroutines * urlsPerGoroutine
	expectedDuplicates := totalAttempts - 20
	if duplicateDetections.Load() != int64(expectedDuplicates) {
		t.Errorf("expected %d duplicates caught, got %d", expectedDuplicates, duplicateDetections.Load())
	}
}

func TestMetrics_AtomicAccuracy(t *testing.T) {
	m := state.NewMetrics()
	const workers = 100
	const iterations = 1000

	var wg sync.WaitGroup
	wg.Add(workers)

	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for j := 0; j < iterations; j++ {
				m.IncPages()
				m.AddBytes(10)
				m.AddLinks(2)
				m.IncErrors()
			}
		}()
	}

	wg.Wait()
	snap := m.Snapshot()

	expectedPages := uint64(workers * iterations)
	if snap.PagesCrawled != expectedPages {
		t.Errorf("expected %d pages, got %d", expectedPages, snap.PagesCrawled)
	}
	if snap.BytesRead != expectedPages*10 {
		t.Errorf("bytes mismatch: got %d", snap.BytesRead)
	}
	if snap.LinksFound != expectedPages*2 {
		t.Errorf("links mismatch: got %d", snap.LinksFound)
	}
	if snap.ErrorsCount != expectedPages {
		t.Errorf("errors mismatch: got %d", snap.ErrorsCount)
	}
}
