)

// CrawlJob represents a single URL to be fetched and processed by a worker.
type CrawlJob struct {
	URL   *url.URL
	Depth int
}

// CrawlResult represents the output emitted by a worker upon completing a job.
type CrawlResult struct {
	Job         CrawlJob
	StatusCode  int
	Duration    time.Duration
	BytesRead   int
	Links       []parser.DiscoveredLink
	Metadata    parser.PageMetadata
