### Step 2 · Implement In-Memory Dynamic Frontier Queue
Create `internal/crawler/frontier.go` to provide safe, unbounded FIFO queueing:

```go
package crawler

// FrontierQueue is an in-memory FIFO queue for CrawlJob items.
type FrontierQueue struct {
	items []CrawlJob
}

// NewFrontierQueue creates an empty frontier queue.
func NewFrontierQueue(initialCapacity int) *FrontierQueue {
	return &FrontierQueue{
		items: make([]CrawlJob, 0, initialCapacity),
	}
}

// Push appends a job to the tail of the queue.
func (q *FrontierQueue) Push(job CrawlJob) {
	q.items = append(q.items, job)
}

// Pop removes and returns the job at the head of the queue.
func (q *FrontierQueue) Pop() (CrawlJob, bool) {
	if len(q.items) == 0 {
		return CrawlJob{}, false
	}
	item := q.items[0]
	// Avoid memory leak by zeroing head before slice re-slicing
	q.items[0] = CrawlJob{}
	q.items = q.items[1:]
	return item, true
}

// Len returns current queue length.
func (q *FrontierQueue) Len() int {
	return len(q.items)
}
```

### Step 3 · Implement Worker Goroutine Loop
Create `internal/crawler/worker.go` implementing worker execution and channel streaming:

```go
package crawler

import (
	"context"
	"sync"
	"time"

	"github.com/buildscape/gocrawl/internal/fetcher"
	"github.com/buildscape/gocrawl/internal/parser"
	"github.com/buildscape/gocrawl/internal/state"
)

// StartWorker launches a worker goroutine reading jobs and emitting results.
func StartWorker(
	ctx context.Context,
	workerID int,
	jobs <-chan CrawlJob,
	results chan<- CrawlResult,
	f fetcher.Fetcher,
	p *parser.Parser,
	ctrl *state.Controller,
	wg *sync.WaitGroup,
) {
	wg.Add(1)
	go func() {
		defer wg.Done()

		for {
			select {
			case <-ctx.Done():
				return
			case job, ok := <-jobs:
				if !ok {
					return
				}

				ctrl.Metrics.IncWorkers()
				start := time.Now()

				// 1. Acquire rate limit and robots permit
				if err := ctrl.AcquirePermit(ctx, job.URL); err != nil {
					ctrl.Metrics.IncErrors()
					ctrl.Metrics.DecWorkers()
					select {
					case <-ctx.Done():
						return
					case results <- CrawlResult{Job: job, Error: err, Duration: time.Since(start)}:
					}
					continue
				}

				// 2. Fetch page over HTTP
				resp, err := f.Fetch(ctx, job.URL)
				if err != nil {
					ctrl.Metrics.IncErrors()
					ctrl.Metrics.DecWorkers()
					select {
					case <-ctx.Done():
						return
					case results <- CrawlResult{Job: job, Error: err, Duration: time.Since(start)}:
					}
					continue
				}

				ctrl.Metrics.IncPages()
				ctrl.Metrics.AddBytes(len(resp.Body))

				// 3. Parse HTML and extract links
				parseRes, err := p.Parse(job.URL, resp.Body)
				var links []parser.DiscoveredLink
				var meta parser.PageMetadata
				if err == nil && parseRes != nil {
					links = parseRes.Links
					meta = parseRes.Metadata
					ctrl.Metrics.AddLinks(len(links))
				}

				ctrl.Metrics.DecWorkers()

				// 4. Emit result
				select {
				case <-ctx.Done():
					return
				case results <- CrawlResult{
					Job:        job,
					StatusCode: resp.StatusCode,
					Duration:   time.Since(start),
					BytesRead:  len(resp.Body),
					Links:      links,
					Metadata:   meta,
					Error:      err,
				}:
				}
			}
		}
	}()
}
```

### Step 4 · Implement Dynamic Coordinator Engine
Create `internal/crawler/coordinator.go` managing the event loop and work dispatching:

```go
package crawler

import (
	"context"
	"sync"

	"github.com/buildscape/gocrawl/internal/config"
	"github.com/buildscape/gocrawl/internal/fetcher"
	"github.com/buildscape/gocrawl/internal/logger"
	"github.com/buildscape/gocrawl/internal/parser"
	"github.com/buildscape/gocrawl/internal/state"
)

// Coordinator orchestrates workers, frontier scheduling, and result collection.
type Coordinator struct {
	cfg     *config.Config
	log     *logger.Logger
	ctrl    *state.Controller
	fetcher fetcher.Fetcher
	parser  *parser.Parser
}

// NewCoordinator creates a Coordinator.
func NewCoordinator(
	cfg *config.Config,
	log *logger.Logger,
	ctrl *state.Controller,
	f fetcher.Fetcher,
	p *parser.Parser,
) *Coordinator {
	return &Coordinator{
		cfg:     cfg,
		log:     log,
		ctrl:    ctrl,
		fetcher: f,
		parser:  p,
	}
}

// Execute runs the crawl pipeline until max pages reached, queue empty, or context cancelled.
func (c *Coordinator) Execute(ctx context.Context, onResult func(CrawlResult)) error {
	jobs := make(chan CrawlJob, c.cfg.Concurrency)
	results := make(chan CrawlResult, c.cfg.Concurrency*2)

	var workerWg sync.WaitGroup
	for i := 0; i < c.cfg.Concurrency; i++ {
		StartWorker(ctx, i+1, jobs, results, c.fetcher, c.parser, c.ctrl, &workerWg)
	}

	frontier := NewFrontierQueue(1024)

	// Seed the initial target
	if c.ctrl.Visited.CheckAndAdd(c.cfg.SeedURL.String()) {
		frontier.Push(CrawlJob{URL: c.cfg.SeedURL, Depth: 0})
	}

	inFlight := 0
	totalCrawled := 0

	defer func() {
		close(jobs)
		workerWg.Wait()
	}()

	for {
		// Dynamic select: if frontier has items, attempt to send to jobs
		var sendCh chan<- CrawlJob
		var nextJob CrawlJob

		if frontier.Len() > 0 && totalCrawled+inFlight < c.cfg.MaxPages {
			nextJob, _ = frontier.Pop()
			sendCh = jobs
		}

		// Termination check
		if frontier.Len() == 0 && inFlight == 0 {
			c.log.Info("All discovered links processed. Crawl complete.")
			return nil
		}
		if totalCrawled >= c.cfg.MaxPages {
			c.log.Info("Reached target page limit (%d). Halting crawl.", c.cfg.MaxPages)
			return nil
		}

		select {
		case <-ctx.Done():
			c.log.Warn("Crawl cancelled by context: %v", ctx.Err())
			return ctx.Err()

		case sendCh <- nextJob:
			inFlight++

		case res := <-results:
			inFlight--
			if res.Error == nil {
				totalCrawled++
			}

			if onResult != nil {
				onResult(res)
			}

			// If depth limit permits, enqueue unvisited child links
			if res.Job.Depth < c.cfg.MaxDepth {
				for _, link := range res.Links {
					linkStr := link.Resolved.String()
					if c.ctrl.Visited.CheckAndAdd(linkStr) {
						frontier.Push(CrawlJob{
							URL:   link.Resolved,
							Depth: res.Job.Depth + 1,
						})
					}
				}
			}
		}
	}
}
```

