// StartProgressReporter periodically writes crawl telemetry to the console.
func StartProgressReporter(ctx context.Context, w io.Writer, ctrl *state.Controller, interval time.Duration) {
	go func() {
		ticker := time.NewTicker(interval)
		defer ticker.Stop()

		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				snap := ctrl.Metrics.Snapshot()
				fmt.Fprintf(w, "\r[PROGRESS] Crawled: %d pages | Speed: %.1f req/s | Discovered: %d | Errors: %d | Elapsed: %s   ",
					snap.PagesCrawled,
					snap.PagesPerSecond,
					snap.LinksFound,
					snap.ErrorsCount,
					snap.ElapsedTime.Round(time.Second),
				)
			}
		}
	}()
}
