Update `internal/crawler/engine.go` connecting all modules together:

```go
package crawler

import (
	"context"
	"os"
	"time"

	"github.com/buildscape/gocrawl/internal/config"
	"github.com/buildscape/gocrawl/internal/fetcher"
	"github.com/buildscape/gocrawl/internal/logger"
	"github.com/buildscape/gocrawl/internal/parser"
	"github.com/buildscape/gocrawl/internal/state"
)

type Engine struct {
	cfg         *config.Config
	log         *logger.Logger
	ctrl        *state.Controller
	fetcher     fetcher.Fetcher
	parser      *parser.Parser
	coordinator *Coordinator
}

func New(cfg *config.Config, log *logger.Logger) *Engine {
	baseFetcher := fetcher.New(cfg)
	retryingFetcher := fetcher.NewRetryingFetcher(baseFetcher, 2, 500*time.Millisecond)
	htmlParser := parser.New(cfg)
	controller := state.NewController(cfg)
	coord := NewCoordinator(cfg, log, controller, retryingFetcher, htmlParser)

	return &Engine{
		cfg:         cfg,
		log:         log,
		ctrl:        controller,
		fetcher:     retryingFetcher,
		parser:      htmlParser,
		coordinator: coord,
	}
}

func (e *Engine) Run(ctx context.Context) error {
	e.log.Info("Starting GoCrawl on target: %s", e.cfg.SeedURL.String())
	e.log.Info("Parameters: concurrency=%d, max-pages=%d, max-depth=%d, rate=%.1f req/s",
		e.cfg.Concurrency, e.cfg.MaxPages, e.cfg.MaxDepth, e.cfg.RateLimit)

	StartProgressReporter(ctx, os.Stderr, e.ctrl, 1*time.Second)

	err := e.coordinator.Execute(ctx, func(res CrawlResult) {
		if res.Error != nil {
			e.log.Warn("Failed [%s]: %v", res.Job.URL.Path, res.Error)
		} else {
			e.log.Info("[%d] %s (%s, %d bytes, %d links)",
				res.StatusCode, res.Job.URL.Path, res.Duration.Round(time.Millisecond), res.BytesRead, len(res.Links))
		}
	})

	finalSnap := e.ctrl.Metrics.Snapshot()
	e.log.Info("=== Crawl Summary ===")
	e.log.Info("Total Pages Crawled: %d", finalSnap.PagesCrawled)
	e.log.Info("Total Bytes Received: %d", finalSnap.BytesRead)
	e.log.Info("Total Links Found:   %d", finalSnap.LinksFound)
	e.log.Info("Total Errors:        %d", finalSnap.ErrorsCount)
	e.log.Info("Total Duration:      %s", finalSnap.ElapsedTime.Round(time.Millisecond))

	return err
}
