### Step 1 · Define Exporter Interfaces and Serialization Data Transfer Objects
Create `internal/storage/types.go` declaring the export record schema and writer contracts:

```go
package storage

import (
	"io"
	"time"

	"github.com/buildscape/gocrawl/internal/crawler"
)

// PageRecord represents the serialized JSON structure written to disk for each page.
type PageRecord struct {
	URL         string            `json:"url"`
	StatusCode  int               `json:"status_code"`
	Title       string            `json:"title"`
	Description string            `json:"description,omitempty"`
	Canonical   string            `json:"canonical,omitempty"`
	LinksCount  int               `json:"links_count"`
	Links       []string          `json:"links"`
	DurationMs  int64             `json:"duration_ms"`
	BytesRead   int               `json:"bytes_read"`
	Timestamp   time.Time         `json:"timestamp"`
	Error       string            `json:"error,omitempty"`
}

// Exporter defines the contract for streaming page records to storage.
type Exporter interface {
	// WriteRecord serializes and outputs a single CrawlResult.
	WriteRecord(res crawler.CrawlResult) error
	// Close flushes any buffered data and finalizes the output stream.
	Close() error
}

// NewPageRecord maps an internal CrawlResult into a PageRecord.
func NewPageRecord(res crawler.CrawlResult) PageRecord {
	links := make([]string, 0, len(res.Links))
	for _, l := range res.Links {
		links = append(links, l.Resolved.String())
	}

	errStr := ""
	if res.Error != nil {
		errStr = res.Error.Error()
	}

	return PageRecord{
		URL:         res.Job.URL.String(),
		StatusCode:  res.StatusCode,
		Title:       res.Metadata.Title,
		Description: res.Metadata.Description,
		Canonical:   res.Metadata.Canonical,
		LinksCount:  len(links),
		Links:       links,
		DurationMs:  res.Duration.Milliseconds(),
		BytesRead:   res.BytesRead,
		Timestamp:   time.Now().UTC(),
		Error:       errStr,
	}
}
```

### Step 2 · Implement Buffered Streaming JSON Lines (JSONL) Exporter
Create `internal/storage/jsonl.go` with thread-safe buffered output:

```go
package storage

import (
	"bufio"
	"encoding/json"
	"io"
	"sync"

	"github.com/buildscape/gocrawl/internal/crawler"
)

// JSONLExporter writes page records as newline-delimited JSON objects.
type JSONLExporter struct {
	mu     sync.Mutex
	writer *bufio.Writer
	closer io.Closer
}

// NewJSONLExporter creates a buffered JSON Lines exporter.
func NewJSONLExporter(w io.Writer) *JSONLExporter {
	var closer io.Closer
	if c, ok := w.(io.Closer); ok {
		closer = c
	}

	return &JSONLExporter{
		writer: bufio.NewWriterSize(w, 64*1024), // 64KB write buffer
		closer: closer,
	}
}

// WriteRecord formats a PageRecord as a single-line JSON object followed by newline.
func (e *JSONLExporter) WriteRecord(res crawler.CrawlResult) error {
	record := NewPageRecord(res)
	data, err := json.Marshal(record)
	if err != nil {
		return err
	}

	e.mu.Lock()
	defer e.mu.Unlock()

	if _, err := e.writer.Write(data); err != nil {
		return err
	}
	return e.writer.WriteByte('\n')
}

// Close flushes buffered bytes and closes underlying writer.
func (e *JSONLExporter) Close() error {
	e.mu.Lock()
	defer e.mu.Unlock()

	if err := e.writer.Flush(); err != nil {
		return err
	}
	if e.closer != nil {
		return e.closer.Close()
	}
	return nil
}
```

### Step 3 · Implement Streaming Formatted JSON Array Exporter
Create `internal/storage/json.go` emitting a standard JSON array with streaming envelope management:

```go
package storage

import (
	"bufio"
	"encoding/json"
	"io"
	"sync"

	"github.com/buildscape/gocrawl/internal/crawler"
)

// JSONArrayExporter writes records into a formatted JSON array without loading all into memory.
type JSONArrayExporter struct {
	mu        sync.Mutex
	writer    *bufio.Writer
	closer    io.Closer
	firstItem bool
}

// NewJSONArrayExporter creates an exporter and writes the opening array bracket '['.
func NewJSONArrayExporter(w io.Writer) (*JSONArrayExporter, error) {
	var closer io.Closer
	if c, ok := w.(io.Closer); ok {
		closer = c
	}

	bw := bufio.NewWriterSize(w, 64*1024)
	if _, err := bw.WriteString("[\n"); err != nil {
		return nil, err
	}

	return &JSONArrayExporter{
		writer:    bw,
		closer:    closer,
		firstItem: true,
	}, nil
}

// WriteRecord writes a JSON object preceded by a comma if not the first record.
func (e *JSONArrayExporter) WriteRecord(res crawler.CrawlResult) error {
	record := NewPageRecord(res)
	data, err := json.MarshalIndent(record, "  ", "  ")
	if err != nil {
		return err
	}

	e.mu.Lock()
	defer e.mu.Unlock()

	if !e.firstItem {
		if _, err := e.writer.WriteString(",\n"); err != nil {
			return err
		}
	} else {
		e.firstItem = false
	}

	if _, err := e.writer.WriteString("  "); err != nil {
		return err
	}
	if _, err := e.writer.Write(data); err != nil {
		return err
	}
	return nil
}

// Close writes the closing array bracket ']' and flushes buffer.
func (e *JSONArrayExporter) Close() error {
	e.mu.Lock()
	defer e.mu.Unlock()

	if _, err := e.writer.WriteString("\n]\n"); err != nil {
		return err
	}
	if err := e.writer.Flush(); err != nil {
		return err
	}
	if e.closer != nil {
		return e.closer.Close()
	}
	return nil
}
```

### Step 4 · Implement Storage Factory and Profiling Hook
Create `internal/storage/factory.go` and `internal/crawler/pprof.go`:

```go
package storage

import (
	"fmt"
	"io"
	"os"
)

// CreateExporter instantiates the requested exporter targeting a file or stdout.
func CreateExporter(filePath, format string) (Exporter, error) {
	var writer io.Writer = os.Stdout
	if filePath != "" {
		f, err := os.Create(filePath)
		if err != nil {
			return nil, fmt.Errorf("failed to create output file %q: %w", filePath, err)
		}
		writer = f
	}

	switch format {
	case "jsonl":
		return NewJSONLExporter(writer), nil
	case "json":
		return NewJSONArrayExporter(writer)
	default:
		return nil, fmt.Errorf("unsupported output format: %s", format)
	}
}
