package main

import (
	"context"
	"errors"
	"os"
	"os/signal"
	"syscall"

	"github.com/buildscape/gocrawl/internal/config"
	"github.com/buildscape/gocrawl/internal/crawler"
	"github.com/buildscape/gocrawl/internal/logger"
	"github.com/buildscape/gocrawl/internal/storage"
)

func main() {
	log := logger.Default

	cfg, err := config.ParseFlags(os.Args[1:], os.Stderr)
	if err != nil {
		if errors.Is(err, config.ErrHelp) {
			os.Exit(0)
		}
		log.Error("Configuration error: %v", err)
		os.Exit(1)
	}

	// Optional pprof profiling server
	if os.Getenv("GOCRAWL_PPROF") != "" {
		crawler.StartPprofServer(os.Getenv("GOCRAWL_PPROF"), log)
	}

	// Initialize Storage Exporter
	exporter, err := storage.CreateExporter(cfg.OutputFile, cfg.OutputFormat)
	if err != nil {
		log.Error("Storage initialization error: %v", err)
		os.Exit(1)
	}
	defer func() {
		if err := exporter.Close(); err != nil {
			log.Warn("Failed to cleanly flush exporter: %v", err)
		}
	}()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	engine := crawler.New(cfg, log)

	// Run crawler engine and stream each result into exporter
	err = engine.RunWithExporter(ctx, exporter)
	if err != nil && !errors.Is(err, context.Canceled) {
		log.Error("Crawler execution terminated with error: %v", err)
		os.Exit(1)
	}

	log.Info("Crawler completed successfully.")
}
```

