PLATFORMS=(
  "linux/amd64"
  "linux/arm64"
  "darwin/amd64"
  "darwin/arm64"
  "windows/amd64"
)

echo "=== Building GoCrawl Release Binaries (Version ${VERSION}) ==="

for PLATFORM in "${PLATFORMS[@]}"; do
  GOOS=${PLATFORM%/*}
  GOARCH=${PLATFORM#*/}

  OUTPUT_NAME="${APP_NAME}-${VERSION}-${GOOS}-${GOARCH}"
  if [ "${GOOS}" = "windows" ]; then
