### Step 2 · Author the Protocol Buffers Specification (`proto/raft.proto`)
Create `proto/raft.proto` defining the consensus service and message types:

```protobuf
syntax = "proto3";

package raft;

option go_package = "github.com/buildscape/raftkv/proto/raftpb";

// Raft defines the consensus RPC interface between cluster peer nodes.
service RaftService {
  // RequestVote is invoked by candidates to gather votes during elections.
  rpc RequestVote(RequestVoteArgs) returns (RequestVoteReply);

  // AppendEntries replicates log entries and serves as cluster heartbeat.
  rpc AppendEntries(AppendEntriesArgs) returns (AppendEntriesReply);
}

// LogEntry represents an individual state machine command recorded in the log.
message LogEntry {
  uint64 index = 1;     // Position in log (1-based)
  uint64 term = 2;      // Term when entry was received by leader
  bytes data = 3;       // Encoded command payload for state machine
}

// RequestVoteArgs contains candidate election parameters.
message RequestVoteArgs {
  uint64 term = 1;              // Candidate's current term
  string candidate_id = 2;      // Candidate requesting vote
  uint64 last_log_index = 3;    // Index of candidate's last log entry
  uint64 last_log_term = 4;     // Term of candidate's last log entry
}

// RequestVoteReply contains voter response.
message RequestVoteReply {
  uint64 term = 1;              // CurrentTerm, for candidate to update itself
  bool vote_granted = 2;        // True means candidate received vote
}

// AppendEntriesArgs contains log entries or heartbeat metadata.
message AppendEntriesArgs {
  uint64 term = 1;              // Leader's current term
  string leader_id = 2;         // So follower can redirect clients
  uint64 prev_log_index = 3;    // Index of log entry immediately preceding new ones
  uint64 prev_log_term = 4;     // Term of prev_log_index entry
  repeated LogEntry entries = 5;// Log entries to store (empty for heartbeat)
  uint64 leader_commit = 6;     // Leader's commitIndex
}

// AppendEntriesReply contains replication result.
message AppendEntriesReply {
  uint64 term = 1;              // CurrentTerm, for leader to update itself
  bool success = 2;             // True if follower contained entry matching prev_log_index and prev_log_term
  uint64 match_index = 3;       // Follower's last log index if successful
  uint64 conflict_index = 4;    // Hint: First index of conflicting term (for fast recovery)
  uint64 conflict_term = 5;     // Hint: Conflicting term on follower
}
```

