package storage

import (
	"errors"

	"github.com/buildscape/raftkv/proto/raftpb"
)

var (
	ErrNotFound = errors.New("storage: key or log entry not found")
	ErrCorrupted = errors.New("storage: persistence file corrupted")
)

// PersistentState captures the non-volatile Raft variables required across reboots.
type PersistentState struct {
	CurrentTerm uint64              `json:"current_term"`
	VotedFor    string              `json:"voted_for"`
	Entries     []*raftpb.LogEntry  `json:"entries"`
}

// Storage defines the interface for durable Raft state persistence.
type Storage interface {
	// SaveState persists currentTerm, votedFor, and the complete log atomically with fsync.
	SaveState(state *PersistentState) error
	// LoadState retrieves the persisted state from disk on node bootstrap.
	LoadState() (*PersistentState, error)
	// AppendEntries appends new log entries durably.
	AppendEntries(entries []*raftpb.LogEntry) error
	// TruncateLog discards all log entries starting from index onwards.
	TruncateLog(fromIndex uint64) error
	// Close cleanly releases file locks and flushes buffers.
	Close() error
}
