### Step 5 · Implement Atomic Disk Storage Engine with `os.File.Sync`
Create `internal/storage/disk.go` implementing atomic write-then-rename and durable WAL persistence:

```go
package storage

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// DiskStorage persists Raft state to disk using atomic tempfile writes and fsync.
type DiskStorage struct {
	mu       sync.RWMutex
	dir      string
	state    *PersistentState
	metaFile string
}

// NewDiskStorage initializes or re-opens disk persistence in target directory.
func NewDiskStorage(dir string) (*DiskStorage, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("failed to create storage dir: %w", err)
	}

	ds := &DiskStorage{
		dir:      dir,
		metaFile: filepath.Join(dir, "raft_state.json"),
		state: &PersistentState{
			CurrentTerm: 0,
			VotedFor:    "",
			Entries:     make([]*raftpb.LogEntry, 0),
		},
	}

	// Load existing state if available
	if _, err := os.Stat(ds.metaFile); err == nil {
		loaded, err := ds.LoadState()
		if err != nil {
			return nil, err
		}
		ds.state = loaded
	}

	return ds, nil
}

// SaveState atomically writes state to a tempfile, calls Sync(), and renames to target.
func (ds *DiskStorage) SaveState(state *PersistentState) error {
	ds.mu.Lock()
	defer ds.mu.Unlock()

	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal state error: %w", err)
	}

	tmpFile := fmt.Sprintf("%s.tmp.%d", ds.metaFile, os.Getpid())
	f, err := os.OpenFile(tmpFile, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
	if err != nil {
		return fmt.Errorf("open temp state file: %w", err)
	}

	if _, err := f.Write(data); err != nil {
		_ = f.Close()
		_ = os.Remove(tmpFile)
		return fmt.Errorf("write temp state: %w", err)
	}

	// CRITICAL: Flush kernel write buffers to physical disk before proceeding
	if err := f.Sync(); err != nil {
		_ = f.Close()
		_ = os.Remove(tmpFile)
		return fmt.Errorf("sync state file: %w", err)
	}

	if err := f.Close(); err != nil {
		return fmt.Errorf("close temp file: %w", err)
	}

	// Atomic replacement guarantees either old state or new state is visible, never half-written
	if err := os.Rename(tmpFile, ds.metaFile); err != nil {
		return fmt.Errorf("atomic rename state file: %w", err)
	}

	ds.state = state
	return nil
}

// LoadState reads and unmarshals the durable state from disk.
func (ds *DiskStorage) LoadState() (*PersistentState, error) {
	ds.mu.RLock()
	defer ds.mu.RUnlock()

	data, err := os.ReadFile(ds.metaFile)
	if err != nil {
		if os.IsNotExist(err) {
			return &PersistentState{Entries: make([]*raftpb.LogEntry, 0)}, nil
		}
		return nil, fmt.Errorf("read state file: %w", err)
	}

	var state PersistentState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("unmarshal state file: %w", err)
	}

	return &state, nil
}

// AppendEntries appends log entries and persists state to disk.
func (ds *DiskStorage) AppendEntries(entries []*raftpb.LogEntry) error {
	ds.mu.Lock()
	ds.state.Entries = append(ds.state.Entries, entries...)
	ds.mu.Unlock()

	return ds.SaveState(ds.state)
}

// TruncateLog removes entries starting from index.
func (ds *DiskStorage) TruncateLog(fromIndex uint64) error {
	ds.mu.Lock()
	newEntries := make([]*raftpb.LogEntry, 0)
	for _, e := range ds.state.Entries {
		if e.Index < fromIndex {
			newEntries = append(newEntries, e)
		}
	}
	ds.state.Entries = newEntries
	ds.mu.Unlock()

	return ds.SaveState(ds.state)
}

// Close closes any open descriptors.
func (ds *DiskStorage) Close() error {
	return nil
}
```

### Step 6 · Construct Peer Connection Pool & gRPC Client Transports
Create `internal/raft/peer.go` to handle thread-safe peer connection multiplexing:

```go
package raft

import (
	"context"
	"fmt"
	"sync"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// Peer represents a remote node in the Raft consensus group.
type Peer struct {
	ID       string
	Addr     string
	mu       sync.Mutex
	conn     *grpc.ClientConn
	client   raftpb.RaftServiceClient
}

// NewPeer initializes peer metadata without connecting immediately.
func NewPeer(id, addr string) *Peer {
	return &Peer{
		ID:   id,
		Addr: addr,
	}
}

// Connect establishes or returns existing gRPC connection.
func (p *Peer) Connect() (raftpb.RaftServiceClient, error) {
	p.mu.Lock()
	defer p.mu.Unlock()

	if p.client != nil {
		return p.client, nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	conn, err := grpc.DialContext(
		ctx,
		p.Addr,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithBlock(),
	)
	if err != nil {
		return nil, fmt.Errorf("failed dialing peer %s at %s: %w", p.ID, p.Addr, err)
	}

	p.conn = conn
	p.client = raftpb.NewRaftServiceClient(conn)
	return p.client, nil
}

// Close terminates the peer gRPC connection.
func (p *Peer) Close() error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.conn != nil {
		err := p.conn.Close()
		p.conn = nil
		p.client = nil
		return err
	}
	return nil
}
```

### Step 7 · Build Raft Node Skeleton & Register gRPC Server
Create `internal/raft/node.go` bootstrapping the node and exposing gRPC service handlers:

```go
package raft

import (
	"context"
	"fmt"
	"log"
	"net"
	"sync"

	"google.golang.org/grpc"

	"github.com/buildscape/raftkv/internal/storage"
	"github.com/buildscape/raftkv/proto/raftpb"
)

// Node represents a single participant in the Raft consensus cluster.
type Node struct {
	raftpb.UnimplementedRaftServiceServer

	mu       sync.RWMutex
	id       string
	addr     string
	peers    map[string]*Peer
	storage  storage.Storage

	// Persistent state on all servers
	currentTerm uint64
	votedFor    string
	logEntries  []*raftpb.LogEntry

	// Volatile state on all servers
	commitIndex uint64
	lastApplied uint64

	grpcServer *grpc.Server
}

// Config holds bootstrap configuration parameters.
type Config {
	ID      string
	Addr    string
	Peers   map[string]string // ID -> Addr
	DataDir string
}

// NewNode initializes a Raft node with storage and peer mapping.
func NewNode(cfg Config) (*Node, error) {
	ds, err := storage.NewDiskStorage(cfg.DataDir)
	if err != nil {
		return nil, fmt.Errorf("init disk storage: %w", err)
	}

	state, err := ds.LoadState()
	if err != nil {
		return nil, fmt.Errorf("load persisted state: %w", err)
	}

	peers := make(map[string]*Peer)
	for pid, paddr := range cfg.Peers {
		if pid != cfg.ID {
			peers[pid] = NewPeer(pid, paddr)
		}
	}

	node := &Node{
		id:          cfg.ID,
		addr:        cfg.Addr,
		peers:       peers,
		storage:     ds,
		currentTerm: state.CurrentTerm,
		votedFor:    state.VotedFor,
		logEntries:  state.Entries,
	}

	return node, nil
}

// Start binds gRPC listener and begins accepting consensus RPCs.
func (n *Node) Start() error {
	lis, err := net.Listen("tcp", n.addr)
	if err != nil {
		return fmt.Errorf("listen error on %s: %w", n.addr, err)
	}

	n.grpcServer = grpc.NewServer()
	raftpb.RegisterRaftServiceServer(n.grpcServer, n)

	go func() {
		log.Printf("🛡️ [RAFT NODE %s] Listening for consensus RPCs on %s", n.id, n.addr)
		if err := n.grpcServer.Serve(lis); err != nil {
			log.Printf("gRPC server error: %v", err)
		}
	}()

	return nil
}

// Stop gracefully shuts down gRPC server and closes peer connections.
func (n *Node) Stop() {
	if n.grpcServer != nil {
		n.grpcServer.GracefulStop()
	}
	for _, peer := range n.peers {
		_ = peer.Close()
	}
	_ = n.storage.Close()
	log.Printf("🛑 [RAFT NODE %s] Stopped cleanly.", n.id)
}

// RequestVote handler stub (implemented in Phase 3).
func (n *Node) RequestVote(ctx context.Context, args *raftpb.RequestVoteArgs) (*raftpb.RequestVoteReply, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	return &raftpb.RequestVoteReply{
		Term:        n.currentTerm,
		VoteGranted: false,
	}, nil
}

// AppendEntries handler stub (implemented in Phase 4).
func (n *Node) AppendEntries(ctx context.Context, args *raftpb.AppendEntriesArgs) (*raftpb.AppendEntriesReply, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	return &raftpb.AppendEntriesReply{
		Term:    n.currentTerm,
		Success: true,
	}, nil
}
```

