### Step 2 · Implement High-Performance Binary Serialization for Log Commands
Create `internal/state/codec.go` using compact binary encoding:

```go
package state

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
)

// EncodeCommand serializes a Command into a compact binary byte slice.
func EncodeCommand(c Command) ([]byte, error) {
	buf := new(bytes.Buffer)

	// Op length and string
	opBytes := []byte(c.Op)
	if err := binary.Write(buf, binary.BigEndian, uint16(len(opBytes))); err != nil {
		return nil, err
	}
	buf.Write(opBytes)

	// Key length and bytes
	keyBytes := []byte(c.Key)
	if err := binary.Write(buf, binary.BigEndian, uint32(len(keyBytes))); err != nil {
		return nil, err
	}
	buf.Write(keyBytes)

	// Value length and bytes
	valBytes := []byte(c.Value)
	if err := binary.Write(buf, binary.BigEndian, uint32(len(valBytes))); err != nil {
		return nil, err
	}
	buf.Write(valBytes)

	// ClientID length and bytes
	clientBytes := []byte(c.ClientID)
	if err := binary.Write(buf, binary.BigEndian, uint16(len(clientBytes))); err != nil {
		return nil, err
	}
	buf.Write(clientBytes)

	// Sequence number (uint64)
	if err := binary.Write(buf, binary.BigEndian, c.Seq); err != nil {
		return nil, err
	}

	return buf.Bytes(), nil
}

// DecodeCommand deserializes a binary byte slice back into a Command.
func DecodeCommand(data []byte) (Command, error) {
	r := bytes.NewReader(data)
	var c Command

	// Read Op
	var opLen uint16
	if err := binary.Read(r, binary.BigEndian, &opLen); err != nil {
		return c, fmt.Errorf("decode opLen: %w", err)
	}
	opBuf := make([]byte, opLen)
	if _, err := io.ReadFull(r, opBuf); err != nil {
		return c, fmt.Errorf("decode op: %w", err)
	}
	c.Op = OpType(opBuf)

	// Read Key
	var keyLen uint32
	if err := binary.Read(r, binary.BigEndian, &keyLen); err != nil {
		return c, fmt.Errorf("decode keyLen: %w", err)
	}
	keyBuf := make([]byte, keyLen)
	if _, err := io.ReadFull(r, keyBuf); err != nil {
		return c, fmt.Errorf("decode key: %w", err)
	}
	c.Key = string(keyBuf)

	// Read Value
	var valLen uint32
	if err := binary.Read(r, binary.BigEndian, &valLen); err != nil {
		return c, fmt.Errorf("decode valLen: %w", err)
	}
	valBuf := make([]byte, valLen)
	if _, err := io.ReadFull(r, valBuf); err != nil {
		return c, fmt.Errorf("decode val: %w", err)
	}
	c.Value = string(valBuf)

	// Read ClientID
	var clientLen uint16
	if err := binary.Read(r, binary.BigEndian, &clientLen); err != nil {
		return c, fmt.Errorf("decode clientLen: %w", err)
	}
	clientBuf := make([]byte, clientLen)
	if _, err := io.ReadFull(r, clientBuf); err != nil {
		return c, fmt.Errorf("decode clientID: %w", err)
	}
	c.ClientID = string(clientBuf)

	// Read Seq
	if err := binary.Read(r, binary.BigEndian, &c.Seq); err != nil {
		return c, fmt.Errorf("decode seq: %w", err)
	}

	return c, nil
}
```

### Step 3 · Implement In-Memory Key-Value Store with `sync.RWMutex`
Create `internal/state/kv.go` providing thread-safe point read, write, and delete primitives:

```go
package state

import (
	"sync"
)

// KVStore represents the deterministic in-memory storage engine.
type KVStore struct {
	mu   sync.RWMutex
	data map[string]string
}

// NewKVStore creates an empty KVStore.
func NewKVStore() *KVStore {
	return &KVStore{
		data: make(map[string]string),
	}
}

// Get retrieves a key value using read-lock.
func (kv *KVStore) Get(key string) (string, bool) {
	kv.mu.RLock()
	defer kv.mu.RUnlock()
	val, exists := kv.data[key]
	return val, exists
}

// Set inserts or updates a key value using write-lock.
func (kv *KVStore) Set(key, value string) {
	kv.mu.Lock()
	defer kv.mu.Unlock()
	kv.data[key] = value
}

// Delete removes a key from the store.
func (kv *KVStore) Delete(key string) bool {
	kv.mu.Lock()
	defer kv.mu.Unlock()
	_, exists := kv.data[key]
	if exists {
		delete(kv.data, key)
	}
	return exists
}

// CloneSnapshot exports an isolated deep-copy of all key-value entries.
func (kv *KVStore) CloneSnapshot() map[string]string {
	kv.mu.RLock()
	defer kv.mu.RUnlock()
	cp := make(map[string]string, len(kv.data))
	for k, v := range kv.data {
		cp[k] = v
	}
	return cp
}

// RestoreFromSnapshot completely replaces state with snapshot map.
func (kv *KVStore) RestoreFromSnapshot(snap map[string]string) {
	kv.mu.Lock()
	defer kv.mu.Unlock()
	kv.data = make(map[string]string, len(snap))
	for k, v := range snap {
		kv.data[k] = v
	}
}
```

### Step 4 · Implement Per-Client Deduplication Table & Idempotency Manager
Create `internal/state/dedup.go` tracking client request sequence numbers and caching responses:

```go
package state

import "sync"

// ClientSession caches the latest sequence number and result for a specific client.
type ClientSession struct {
	LastSeq uint64
	Result  CommandResult
}

// DedupTable prevents duplicate execution of retried client proposals.
type DedupTable struct {
	mu       sync.RWMutex
	sessions map[string]*ClientSession
}

// NewDedupTable creates a new deduplication table.
func NewDedupTable() *DedupTable {
	return &DedupTable{
		sessions: make(map[string]*ClientSession),
	}
}

// IsDuplicate returns true and cached result if cmd.Seq has already been executed.
func (dt *DedupTable) IsDuplicate(clientID string, seq uint64) (bool, CommandResult) {
	dt.mu.RLock()
	defer dt.mu.RUnlock()

	session, exists := dt.sessions[clientID]
	if exists && seq <= session.LastSeq {
		return true, session.Result
	}
	return false, CommandResult{}
}

// Record updates the client's latest executed sequence number and cached result.
func (dt *DedupTable) Record(clientID string, seq uint64, res CommandResult) {
	dt.mu.Lock()
	defer dt.mu.Unlock()

	session, exists := dt.sessions[clientID]
	if !exists {
		dt.sessions[clientID] = &ClientSession{
			LastSeq: seq,
			Result:  res,
		}
		return
	}

	if seq > session.LastSeq {
		session.LastSeq = seq
		session.Result = res
	}
}

// CloneSessions produces a snapshot of all client sessions for state machine compaction.
func (dt *DedupTable) CloneSessions() map[string]ClientSession {
	dt.mu.RLock()
	defer dt.mu.RUnlock()
	cp := make(map[string]ClientSession, len(dt.sessions))
	for k, v := range dt.sessions {
		cp[k] = *v
	}
	return cp
}

// RestoreSessions overwrites deduplication sessions from a restored snapshot.
func (dt *DedupTable) RestoreSessions(sessions map[string]ClientSession) {
	dt.mu.Lock()
	defer dt.mu.Unlock()
	dt.sessions = make(map[string]*ClientSession, len(sessions))
	for k, v := range sessions {
		val := v
		dt.sessions[k] = &val
	}
}
```

### Step 5 · Implement State Machine Command Applier
Create `internal/state/apply.go` connecting the KV store and deduplication table:

```go
package state

// StateMachine coordinates deterministic command execution with idempotence.
type StateMachine struct {
	kv    *KVStore
	dedup *DedupTable
}

// NewStateMachine creates an integrated StateMachine.
func NewStateMachine() *StateMachine {
	return &StateMachine{
		kv:    NewKVStore(),
		dedup: NewDedupTable(),
	}
}

// Apply executes a committed Command deterministically, returning CommandResult.
func (sm *StateMachine) Apply(cmd Command) CommandResult {
	// 1. Evaluate Deduplication for mutating operations
	if cmd.Op == OpSet || cmd.Op == OpDel {
		if isDup, cachedResult := sm.dedup.IsDuplicate(cmd.ClientID, cmd.Seq); isDup {
			return cachedResult
		}
	}

	var res CommandResult

	// 2. Execute Deterministic Mutation
	switch cmd.Op {
	case OpSet:
		sm.kv.Set(cmd.Key, cmd.Value)
		res = CommandResult{Value: cmd.Value, Success: true}
	case OpDel:
		existed := sm.kv.Delete(cmd.Key)
		res = CommandResult{Success: existed}
	case OpGet:
		val, found := sm.kv.Get(cmd.Key)
		res = CommandResult{Value: val, Success: found}
	default:
		res = CommandResult{Success: false, Error: "unknown operation"}
	}

	// 3. Record in deduplication table
	if cmd.Op == OpSet || cmd.Op == OpDel {
		sm.dedup.Record(cmd.ClientID, cmd.Seq, res)
	}

	return res
}

// GetDirect retrieves a value without going through log (for linearizable reads).
func (sm *StateMachine) GetDirect(key string) (string, bool) {
	return sm.kv.Get(key)
}
```

### Step 6 · Construct Decoupled `applyCh` Channel Pipeline in Raft Core
Create `internal/raft/apply_pipe.go` defining the asynchronous apply message and dispatch loop:

```go
package raft

import (
	"log"
	"sync"

	"github.com/buildscape/raftkv/internal/state"
)

// ApplyMsg is sent over applyCh when an entry is committed by consensus.
type ApplyMsg struct {
	CommandValid bool
	Command      []byte
	CommandIndex uint64
	CommandTerm  uint64

	// Snapshot fields
	SnapshotValid bool
	Snapshot      []byte
	SnapshotTerm  uint64
	SnapshotIndex uint64
}

// ApplierRunner coordinates the consumer loop reading from applyCh.
type ApplierRunner struct {
	mu       sync.Mutex
	applyCh  <-chan ApplyMsg
	sm       *state.StateMachine
	waiters  map[uint64]chan state.CommandResult
	stopCh   chan struct{}
}

// NewApplierRunner creates an applier worker decoupled from Raft core.
func NewApplierRunner(applyCh <-chan ApplyMsg, sm *state.StateMachine) *ApplierRunner {
	return &ApplierRunner{
		applyCh: applyCh,
		sm:      sm,
		waiters: make(map[uint64]chan state.CommandResult),
		stopCh:  make(chan struct{}),
	}
}

// Start executes the continuous background applier worker.
func (ar *ApplierRunner) Start() {
	go func() {
		for {
			select {
			case <-ar.stopCh:
				return
			case msg, ok := <-ar.applyCh:
				if !ok {
					return
				}
				if msg.CommandValid {
					ar.processEntry(msg)
				}
			}
		}
	}()
}

func (ar *ApplierRunner) processEntry(msg ApplyMsg) {
	cmd, err := state.DecodeCommand(msg.Command)
	if err != nil {
		log.Printf("❌ Applier failed decoding entry at index %d: %v", msg.CommandIndex, err)
		return
	}

	result := ar.sm.Apply(cmd)

	ar.mu.Lock()
	ch, exists := ar.waiters[msg.CommandIndex]
	if exists {
		delete(ar.waiters, msg.CommandIndex)
		select {
		case ch <- result:
		default:
		}
	}
	ar.mu.Unlock()
}

// RegisterWaiter binds a client response channel to a specific committed index.
func (ar *ApplierRunner) RegisterWaiter(index uint64) chan state.CommandResult {
	ar.mu.Lock()
	defer ar.mu.Unlock()
	ch := make(chan state.CommandResult, 1)
	ar.waiters[index] = ch
	return ch
}

// Stop halts the applier worker.
func (ar *ApplierRunner) Stop() {
	close(ar.stopCh)
}
```

### Step 7 · Author State Machine Snapshot Binary Serialization & Restoration Hooks
Create `internal/state/snapshot.go` supporting complete memory compaction:

```go
package state

import (
	"bytes"
	"encoding/gob"
	"fmt"
)

// SnapshotData encapsulates full database state and client deduplication sessions.
type SnapshotData struct {
	KVData   map[string]string
	Sessions map[string]ClientSession
}

// CreateSnapshot serializes state machine state into gob binary bytes.
func (sm *StateMachine) CreateSnapshot() ([]byte, error) {
	snap := SnapshotData{
		KVData:   sm.kv.CloneSnapshot(),
		Sessions: sm.dedup.CloneSessions(),
	}

	var buf bytes.Buffer
	if err := gob.NewEncoder(&buf).Encode(snap); err != nil {
		return nil, fmt.Errorf("encode snapshot: %w", err)
	}
	return buf.Bytes(), nil
}

// RestoreSnapshot restores state machine state from binary snapshot bytes.
func (sm *StateMachine) RestoreSnapshot(raw []byte) error {
	var snap SnapshotData
	r := bytes.NewReader(raw)
	if err := gob.NewDecoder(r).Decode(&snap); err != nil {
		return fmt.Errorf("decode snapshot: %w", err)
	}

	sm.kv.RestoreFromSnapshot(snap.KVData)
	sm.dedup.RestoreSessions(snap.Sessions)
	return nil
}
```

