## 🛠 Step-by-Step Implementation

### Step 1 · Define Raft State Enums & Role Transition Helpers
Create `internal/raft/state.go` defining node states and atomic role transitions:

```go
package raft

import "fmt"

// NodeRole represents the consensus role of a Raft node.
type NodeRole int

const (
	RoleFollower NodeRole = iota
	RoleCandidate
	RoleLeader
)

func (r NodeRole) String() string {
	switch r {
	case RoleFollower:
		return "Follower"
	case RoleCandidate:
		return "Candidate"
	case RoleLeader:
		return "Leader"
	default:
		return "Unknown"
	}
}

// lastLogInfo returns the index and term of the last entry in the log.
// Must be called with n.mu held.
func (n *Node) lastLogInfo() (uint64, uint64) {
	if len(n.logEntries) == 0 {
		return 0, 0
	}
	last := n.logEntries[len(n.logEntries)-1]
	return last.Index, last.Term
}

// becomeFollower transitions node to Follower role and resets election timer.
func (n *Node) becomeFollower(term uint64, leaderID string) {
	n.role = RoleFollower
	n.currentTerm = term
	n.votedFor = ""
	n.leaderID = leaderID
	n.persistState()
	n.resetElectionTimer()
}

// becomeCandidate increments term, votes for self, and initiates campaign.
func (n *Node) becomeCandidate() {
	n.role = RoleCandidate
	n.currentTerm++
	n.votedFor = n.id
	n.leaderID = ""
	n.persistState()
	n.resetElectionTimer()
}

// becomeLeader initializes volatile leader state and begins heartbeats.
func (n *Node) becomeLeader() {
	if n.role != RoleCandidate {
		return
	}
	n.role = RoleLeader
	n.leaderID = n.id

	lastIdx, _ := n.lastLogInfo()
	for peerID := range n.peers {
		n.nextIndex[peerID] = lastIdx + 1
		n.matchIndex[peerID] = 0
	}

	// Stop election timer on leader
	n.stopElectionTimer()
	// Immediately broadcast initial heartbeat
	go n.broadcastHeartbeats()
}
```

### Step 2 · Implement Randomized Timer Engine with Safe Reset
Create `internal/raft/timer.go` implementing randomized election intervals:

```go
package raft

import (
	"crypto/rand"
	"math/big"
	"time"
)

const (
	MinElectionTimeout = 150 * time.Millisecond
	MaxElectionTimeout = 300 * time.Millisecond
	HeartbeatInterval  = 50 * time.Millisecond
)

// randomElectionTimeout returns a duration between 150ms and 300ms.
func randomElectionTimeout() time.Duration {
	diff := MaxElectionTimeout - MinElectionTimeout
	n, _ := rand.Int(rand.Reader, big.NewInt(int64(diff)))
	return MinElectionTimeout + time.Duration(n.Int64())
}

// resetElectionTimer restarts the election timer with a new randomized duration.
func (n *Node) resetElectionTimer() {
	if n.electionTimer == nil {
		n.electionTimer = time.NewTimer(randomElectionTimeout())
		return
	}

	if !n.electionTimer.Stop() {
		select {
		case <-n.electionTimer.C:
		default:
		}
	}
	n.electionTimer.Reset(randomElectionTimeout())
}

// stopElectionTimer disables the election timer (used when node becomes leader).
func (n *Node) stopElectionTimer() {
	if n.electionTimer != nil {
		if !n.electionTimer.Stop() {
			select {
			case <-n.electionTimer.C:
			default:
			}
		}
	}
}
