package raft

// isLogUpToDate evaluates if candidate's log is at least as up-to-date as receiver's log.
// Invariant: (CandidateLastTerm > ReceiverLastTerm) ||
//            (CandidateLastTerm == ReceiverLastTerm && CandidateLastIndex >= ReceiverLastIndex)
func (n *Node) isLogUpToDate(candLastIndex, candLastTerm uint64) bool {
	myLastIndex, myLastTerm := n.lastLogInfo()

	if candLastTerm != myLastTerm {
		return candLastTerm > myLastTerm
	}
	return candLastIndex >= myLastIndex
}
