### Step 4 · Implement Inbound `RequestVote` RPC Handler on Voters
Create `internal/raft/vote_handler.go` enforcing Raft Section 5.2 and 5.4 rules:

```go
package raft

import (
	"context"
	"log"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// RequestVote handles vote solicitations from candidates.
func (n *Node) RequestVote(ctx context.Context, args *raftpb.RequestVoteArgs) (*raftpb.RequestVoteReply, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	reply := &raftpb.RequestVoteReply{
		Term:        n.currentTerm,
		VoteGranted: false,
	}

	// Rule 1: Reject candidate with stale term
	if args.Term < n.currentTerm {
		return reply, nil
	}

	// Rule 2: If candidate has higher term, step down to Follower immediately
	if args.Term > n.currentTerm {
		n.becomeFollower(args.Term, "")
		reply.Term = n.currentTerm
	}

	// Rule 3: Check if we haven't voted, or already voted for this same candidate
	canVote := n.votedFor == "" || n.votedFor == args.CandidateId

	// Rule 4: Candidate's log must be at least as up-to-date as voter's log
	logOk := n.isLogUpToDate(args.LastLogIndex, args.LastLogTerm)

	if canVote && logOk {
		n.votedFor = args.CandidateId
		n.persistState()
		n.resetElectionTimer() // Granting vote resets election timer
		reply.VoteGranted = true
		log.Printf("🗳️ [NODE %s] Granted vote to %s in Term %d", n.id, args.CandidateId, n.currentTerm)
	}

	return reply, nil
}
