### Step 5 · Implement Candidate Election Campaign Loop with Parallel gRPC Dispatch
Create `internal/raft/election.go` executing parallel voting rounds and tallying quorums:

```go
package raft

import (
	"context"
	"log"
	"sync"
	"time"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// startElection runs an election round, gathering votes in parallel.
func (n *Node) startElection() {
	n.mu.Lock()
	n.becomeCandidate()
	term := n.currentTerm
	candID := n.id
	lastIdx, lastTerm := n.lastLogInfo()
	peersCount := len(n.peers)
	n.mu.Unlock()

	log.Printf("📣 [NODE %s] Starting election for Term %d", candID, term)

	var voteMu sync.Mutex
	votesReceived := 1 // Vote for self
	wonElection := false

	for peerID, peer := range n.peers {
		go func(pid string, p *Peer) {
			client, err := p.Connect()
			if err != nil {
				return
			}

			ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
			defer cancel()

			req := &raftpb.RequestVoteArgs{
				Term:         term,
				CandidateId:  candID,
				LastLogIndex: lastIdx,
				LastLogTerm:  lastTerm,
			}

			reply, err := client.RequestVote(ctx, req)
			if err != nil {
				return
			}

			n.mu.Lock()
			defer n.mu.Unlock()

			// If response term is higher, revert to follower immediately
			if reply.Term > n.currentTerm {
				n.becomeFollower(reply.Term, "")
				return
			}

			// Ignore stale replies if state or term changed during RPC
			if n.role != RoleCandidate || n.currentTerm != term {
				return
			}

			if reply.VoteGranted {
				voteMu.Lock()
				votesReceived++
				// Majority Quorum: votes > (totalNodes / 2)
				if !wonElection && votesReceived > (peersCount+1)/2 {
					wonElection = true
					voteMu.Unlock()
					log.Printf("👑 [NODE %s] Won election for Term %d with %d votes!", candID, term, votesReceived)
					n.becomeLeader()
					return
				}
				voteMu.Unlock()
			}
		}(peerID, peer)
	}
}
