### Step 6 · Implement Leader Heartbeat Dispatcher & Periodic `AppendEntries`
Create `internal/raft/heartbeat.go` keeping followers loyal:

```go
package raft

import (
	"context"
	"time"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// broadcastHeartbeats sends empty AppendEntries RPCs to all followers every 50ms.
func (n *Node) broadcastHeartbeats() {
	ticker := time.NewTicker(HeartbeatInterval)
	defer ticker.Stop()

	for {
		n.mu.Lock()
		if n.role != RoleLeader {
			n.mu.Unlock()
			return
		}
		term := n.currentTerm
		leaderID := n.id
		leaderCommit := n.commitIndex
		n.mu.Unlock()

		for _, peer := range n.peers {
			go func(p *Peer) {
				client, err := p.Connect()
				if err != nil {
					return
				}

				n.mu.Lock()
				prevLogIdx := n.nextIndex[p.ID] - 1
				prevLogTerm := uint64(0)
				if prevLogIdx > 0 && prevLogIdx <= uint64(len(n.logEntries)) {
					prevLogTerm = n.logEntries[prevLogIdx-1].Term
				}
				n.mu.Unlock()

				ctx, cancel := context.WithTimeout(context.Background(), 40*time.Millisecond)
				defer cancel()

				req := &raftpb.AppendEntriesArgs{
					Term:         term,
					LeaderId:     leaderID,
					PrevLogIndex: prevLogIdx,
					PrevLogTerm:  prevLogTerm,
					Entries:      nil, // Empty entries == Heartbeat
					LeaderCommit: leaderCommit,
				}

				reply, err := client.AppendEntries(ctx, req)
				if err != nil {
					return
				}

				n.mu.Lock()
				defer n.mu.Unlock()
				if reply.Term > n.currentTerm {
					n.becomeFollower(reply.Term, "")
				}
			}(peer)
		}

		<-ticker.C
	}
}
