### Step 1 · Design In-Memory Thread-Safe Log Buffer & Query Helpers
Create `internal/raft/log.go` managing entries, bounds checks, and index queries:

```go
package raft

import (
	"errors"

	"github.com/buildscape/raftkv/proto/raftpb"
)

var ErrIndexOutOfBounds = errors.New("raft log: index out of bounds")

// getEntry returns log entry at 1-based index.
func (n *Node) getEntry(index uint64) (*raftpb.LogEntry, error) {
	if index == 0 || index > uint64(len(n.logEntries)) {
		return nil, ErrIndexOutOfBounds
	}
	return n.logEntries[index-1], nil
}

// getTermForIndex returns the term for a given 1-based log index.
func (n *Node) getTermForIndex(index uint64) uint64 {
	if index == 0 {
		return 0
	}
	e, err := n.getEntry(index)
	if err != nil {
		return 0
	}
	return e.Term
}

// appendEntryLocal creates and appends an entry to local log.
func (n *Node) appendEntryLocal(data []byte) uint64 {
	lastIdx, _ := n.lastLogInfo()
	newIdx := lastIdx + 1

	entry := &raftpb.LogEntry{
		Index: newIdx,
		Term:  n.currentTerm,
		Data:  data,
	}
	n.logEntries = append(n.logEntries, entry)
	n.persistState()
	return newIdx
}
```

### Step 2 · Implement Follower `AppendEntries` Inbound RPC Handler
Create `internal/raft/append_handler.go` verifying terms and checking `prevLogIndex`:

```go
package raft

import (
	"context"
	"log"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// AppendEntries handles heartbeats and log replication from the leader.
func (n *Node) AppendEntries(ctx context.Context, args *raftpb.AppendEntriesArgs) (*raftpb.AppendEntriesReply, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	reply := &raftpb.AppendEntriesReply{
		Term:    n.currentTerm,
		Success: false,
	}

	// Rule 1: Reply false if term < currentTerm
	if args.Term < n.currentTerm {
		return reply, nil
	}

	// If term >= currentTerm, recognize leader and reset election timer
	if args.Term > n.currentTerm || n.role != RoleFollower {
		n.becomeFollower(args.Term, args.LeaderId)
		reply.Term = n.currentTerm
	} else {
		n.leaderID = args.LeaderId
		n.resetElectionTimer()
	}

	lastLogIdx, _ := n.lastLogInfo()

	// Rule 2: Reply false if log doesn't contain entry at prevLogIndex matching prevLogTerm
	if args.PrevLogIndex > lastLogIdx {
		reply.ConflictIndex = lastLogIdx + 1
		reply.ConflictTerm = 0
		return reply, nil
	}

	if args.PrevLogIndex > 0 {
		prevTerm := n.getTermForIndex(args.PrevLogIndex)
		if prevTerm != args.PrevLogTerm {
			reply.ConflictTerm = prevTerm
			// Find first index with this conflicting term for fast rollback
			for i := uint64(1); i <= args.PrevLogIndex; i++ {
				if n.getTermForIndex(i) == prevTerm {
					reply.ConflictIndex = i
					break
				}
			}
			return reply, nil
		}
	}

	// Rule 3 & 4: Append any new entries not already in the log, overwriting conflicting suffix
	for i, entry := range args.Entries {
		idx := entry.Index
		if idx <= lastLogIdx {
			existingTerm := n.getTermForIndex(idx)
			if existingTerm != entry.Term {
				// Conflict detected: truncate log from idx onwards
				log.Printf("⚠️ [NODE %s] Truncating divergent suffix from index %d", n.id, idx)
				n.logEntries = n.logEntries[:idx-1]
				n.logEntries = append(n.logEntries, args.Entries[i:]...)
				break
			}
		} else {
			// Beyond our last log index: append all remaining entries
			n.logEntries = append(n.logEntries, args.Entries[i:]...)
			break
		}
	}

	n.persistState()
	lastLogIdx, _ = n.lastLogInfo()
	reply.Success = true
	reply.MatchIndex = lastLogIdx

	// Rule 5: If leaderCommit > commitIndex, set commitIndex = min(leaderCommit, index of last new entry)
	if args.LeaderCommit > n.commitIndex {
		newCommit := args.LeaderCommit
		if lastLogIdx < newCommit {
			newCommit = lastLogIdx
		}
		n.commitIndex = newCommit
		n.applyCond.Broadcast() // Signal applier goroutine to execute committed entries
	}

	return reply, nil
}
```

### Step 3 · Implement Leader Replication Dispatcher
Create `internal/raft/replicate.go` coordinating concurrent peer replication:

```go
package raft

import (
	"context"
	"sync"
	"time"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// broadcastAppendEntries replicates unacknowledged log entries to followers.
func (n *Node) broadcastAppendEntries() {
	n.mu.Lock()
	if n.role != RoleLeader {
		n.mu.Unlock()
		return
	}
	term := n.currentTerm
	leaderID := n.id
	commitIdx := n.commitIndex
	n.mu.Unlock()

	var wg sync.WaitGroup
	for _, peer := range n.peers {
		wg.Add(1)
		go func(p *Peer) {
			defer wg.Done()
			n.replicateToPeer(p, term, leaderID, commitIdx)
		}(peer)
	}
	wg.Wait()

	// Check if commitIndex can be advanced after responses
	n.mu.Lock()
	if n.role == RoleLeader {
		n.checkAndUpdateCommitIndex()
	}
	n.mu.Unlock()
}

func (n *Node) replicateToPeer(p *Peer, term uint64, leaderID string, leaderCommit uint64) {
	client, err := p.Connect()
	if err != nil {
		return
	}

	n.mu.Lock()
	prevLogIdx := n.nextIndex[p.ID] - 1
	prevLogTerm := n.getTermForIndex(prevLogIdx)

	var entries []*raftpb.LogEntry
	if uint64(len(n.logEntries)) >= n.nextIndex[p.ID] {
		entries = n.logEntries[n.nextIndex[p.ID]-1:]
	}
	n.mu.Unlock()

	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	req := &raftpb.AppendEntriesArgs{
		Term:         term,
		LeaderId:     leaderID,
		PrevLogIndex: prevLogIdx,
		PrevLogTerm:  prevLogTerm,
		Entries:      entries,
		LeaderCommit: leaderCommit,
	}

	reply, err := client.AppendEntries(ctx, req)
	if err != nil {
		return
	}

	n.mu.Lock()
	defer n.mu.Unlock()

	if reply.Term > n.currentTerm {
		n.becomeFollower(reply.Term, "")
		return
	}

	if n.role != RoleLeader || n.currentTerm != term {
		return
	}

	if reply.Success {
		n.nextIndex[p.ID] = reply.MatchIndex + 1
		n.matchIndex[p.ID] = reply.MatchIndex
	} else {
		// Fast conflict rollback
		if reply.ConflictTerm > 0 {
			// Leader looks for conflictTerm in its own log
			found := false
			for i := prevLogIdx; i > 0; i-- {
				if n.getTermForIndex(i) == reply.ConflictTerm {
					n.nextIndex[p.ID] = i + 1
					found = true
					break
				}
			}
			if !found {
				n.nextIndex[p.ID] = reply.ConflictIndex
			}
		} else if reply.ConflictIndex > 0 {
			n.nextIndex[p.ID] = reply.ConflictIndex
		} else if n.nextIndex[p.ID] > 1 {
			n.nextIndex[p.ID]--
		}
	}
}
```

### Step 4 · Implement Quorum Commit Calculation (Figure 8 Enforced)
Create `internal/raft/commit.go` ensuring only current-term entries trigger direct commit:

```go
package raft

import (
	"log"
	"sort"
)

// checkAndUpdateCommitIndex evaluates matchIndex and advances commitIndex if quorum is achieved.
// Must be called with n.mu held.
func (n *Node) checkAndUpdateCommitIndex() {
	totalNodes := len(n.peers) + 1
	matches := make([]uint64, 0, totalNodes)

	lastIdx, _ := n.lastLogInfo()
	matches = append(matches, lastIdx) // Leader has its own last log index
	for _, m := range n.matchIndex {
		matches = append(matches, m)
	}

	sort.Slice(matches, func(i, j int) bool { return matches[i] < matches[j] })

	// Median index is replicated on majority of nodes
	medianMatchIndex := matches[totalNodes/2]

	// Raft Figure 8 Rule:
	// Leader commits entry only if medianMatchIndex > commitIndex AND entry.Term == currentTerm
	if medianMatchIndex > n.commitIndex {
		entryTerm := n.getTermForIndex(medianMatchIndex)
		if entryTerm == n.currentTerm {
			log.Printf("📈 [LEADER %s] Advancing commitIndex from %d to %d (Term %d)",
				n.id, n.commitIndex, medianMatchIndex, n.currentTerm)
			n.commitIndex = medianMatchIndex
			n.applyCond.Broadcast() // Wake applier loop
		}
	}
}
```

### Step 5 · Build Dedicated Asynchronous Applier Coordinator with `sync.Cond`
Create `internal/raft/applier.go` executing committed entries in sequential order:

```go
package raft

import (
	"sync"
)

// startApplyLoop starts the long-running background goroutine that applies committed entries.
func (n *Node) startApplyLoop() {
	n.applyCond = sync.NewCond(&n.mu)

	go func() {
		for {
			n.mu.Lock()
			for n.commitIndex <= n.lastApplied && !n.isKilled() {
				n.applyCond.Wait()
			}
			if n.isKilled() {
				n.mu.Unlock()
				return
			}

			// Fetch entries between lastApplied+1 and commitIndex
			entriesToApply := make([]*ApplyMsg, 0, n.commitIndex-n.lastApplied)
			for idx := n.lastApplied + 1; idx <= n.commitIndex; idx++ {
				e, err := n.getEntry(idx)
				if err != nil {
					break
				}
				entriesToApply = append(entriesToApply, &ApplyMsg{
					CommandValid: true,
					Command:      e.Data,
					CommandIndex: e.Index,
					CommandTerm:  e.Term,
				})
			}
			n.lastApplied = n.commitIndex
			n.mu.Unlock()

			// Dispatch to applyCh without holding n.mu to prevent deadlocks
			for _, msg := range entriesToApply {
				n.applyCh <- *msg
			}
		}
	}()
}

func (n *Node) isKilled() bool {
	return n.killed.Load()
}
```

