package raft

import (
	"errors"
)

var ErrNotLeader = errors.New("raft: this node is not the leader")

// Propose appends a client command to the Raft log and triggers replication.
// Returns assigned (index, term, isLeader).
func (n *Node) Propose(command []byte) (uint64, uint64, bool) {
	n.mu.Lock()
	defer n.mu.Unlock()

	if n.role != RoleLeader {
		return 0, 0, false
	}

	index := n.appendEntryLocal(command)
	term := n.currentTerm

	// Trigger replication across peers
	go n.broadcastAppendEntries()

	return index, term, true
}
