### Step 3 · Implement Client Waiter Channel Registry for Async Proposals
Create `internal/raft/waiter.go` allowing gRPC handlers to wait for log commits:

```go
package raft

import (
	"sync"
)

// ApplyResult represents the outcome of executing a command on the FSM.
type ApplyResult struct {
	Value string
	Err   error
}

// WaiterRegistry manages channels waiting for specific log indices to commit and apply.
type WaiterRegistry struct {
	mu      sync.Mutex
	waiters map[uint64]chan ApplyResult
}

func NewWaiterRegistry() *WaiterRegistry {
	return &WaiterRegistry{
		waiters: make(map[uint64]chan ApplyResult),
	}
}

// Register creates and stores a notification channel for a target log index.
func (w *WaiterRegistry) Register(index uint64) chan ApplyResult {
	w.mu.Lock()
	defer w.mu.Unlock()

	ch := make(chan ApplyResult, 1)
	w.waiters[index] = ch
	return ch
}

// Trigger sends the execution result to the waiting channel and cleans it up.
func (w *WaiterRegistry) Trigger(index uint64, res ApplyResult) {
	w.mu.Lock()
	defer w.mu.Unlock()

	if ch, ok := w.waiters[index]; ok {
		ch <- res
		delete(w.waiters, index)
	}
}

// CancelAll notifies all registered waiters with an error (e.g. on term step-down).
func (w *WaiterRegistry) CancelAll(err error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	for idx, ch := range w.waiters {
		ch <- ApplyResult{Err: err}
		delete(w.waiters, idx)
	}
}
```

### Step 4 · Implement Leader Mutation Dispatcher (`Submit`) with Context Timeouts
Create `internal/raft/submit.go` coordinating proposal, replication, and waiter completion:

```go
package raft

import (
	"context"
	"errors"
	"time"
)

var (
	ErrProposalTimeout = errors.New("raft: proposal execution timed out waiting for quorum")
	ErrLeaderStepDown  = errors.New("raft: node stepped down as leader before proposal committed")
)

// Submit accepts a client mutation, appends it to the log, replicates it, and blocks until applied.
func (n *Node) Submit(ctx context.Context, cmdData []byte) (string, error) {
	n.mu.Lock()
	if n.role != RoleLeader {
		leaderHint := n.leaderID
		n.mu.Unlock()
		return "", &NotLeaderError{LeaderID: leaderHint}
	}

	term := n.currentTerm
	index := n.appendEntryLocal(cmdData)
	waitCh := n.waiters.Register(index)
	n.mu.Unlock()

	// Trigger concurrent replication to followers
	go n.broadcastAppendEntries()

	select {
	case <-ctx.Done():
		n.waiters.Trigger(index, ApplyResult{Err: ctx.Err()})
		return "", ctx.Err()

	case <-time.After(2 * time.Second):
		n.waiters.Trigger(index, ApplyResult{Err: ErrProposalTimeout})
		return "", ErrProposalTimeout

	case res := <-waitCh:
		if res.Err != nil {
			return "", res.Err
		}
		// Double check we did not lose leadership in the meantime
		n.mu.Lock()
		currentTerm := n.currentTerm
		n.mu.Unlock()
		if currentTerm != term {
			return "", ErrLeaderStepDown
		}
		return res.Value, nil
	}
}

type NotLeaderError struct {
	LeaderID string
}

func (e *NotLeaderError) Error() string {
	return "node is not the cluster leader; current leader hint: " + e.LeaderID
}
```

