### Step 6 · Implement ReadIndex Protocol for Zero-Write Linearizable Reads
Create `internal/raft/read_index.go` eliminating stale reads through heartbeat confirmation:

```go
package raft

import (
	"context"
	"sync"
	"time"

	"github.com/buildscape/raftkv/proto/kvpb"
	"github.com/buildscape/raftkv/proto/raftpb"
)

// ReadIndex executes the Raft ReadIndex protocol to serve a linearizable read without log writes.
func (n *Node) ReadIndex(ctx context.Context, key string) (string, error) {
	n.mu.Lock()
	if n.role != RoleLeader {
		leaderHint := n.leaderID
		n.mu.Unlock()
		return "", &NotLeaderError{LeaderID: leaderHint}
	}

	readIndex := n.commitIndex
	term := n.currentTerm
	leaderID := n.id
	n.mu.Unlock()

	// Quorum Heartbeat Check: Verify leader still holds majority consensus
	peersCount := len(n.peers)
	var ackMu sync.Mutex
	ackCount := 1 // Count self
	quorumReached := make(chan bool, 1)

	for _, peer := range n.peers {
		go func(p *Peer) {
			client, err := p.Connect()
			if err != nil {
				return
			}
			hbCtx, cancel := context.WithTimeout(ctx, 40*time.Millisecond)
			defer cancel()

			req := &raftpb.AppendEntriesArgs{
				Term:     term,
				LeaderId: leaderID,
				Entries:  nil,
			}
			reply, err := client.AppendEntries(hbCtx, req)
			if err == nil && reply.Term == term {
				ackMu.Lock()
				ackCount++
				if ackCount > (peersCount+1)/2 {
					select {
					case quorumReached <- true:
					default:
					}
				}
				ackMu.Unlock()
			}
		}(peer)
	}

	select {
	case <-ctx.Done():
		return "", ctx.Err()
	case <-time.After(150 * time.Millisecond):
		return "", ErrProposalTimeout
	case <-quorumReached:
		// Quorum confirmed leadership in this term!
	}

	// Wait until local state machine lastApplied >= readIndex
	n.mu.Lock()
	for n.lastApplied < readIndex && !n.isKilled() {
		n.applyCond.Wait()
	}
	n.mu.Unlock()

	// Safely query state machine memory directly
	val, found := n.fsm.Get(key)
	if !found {
		return "", ErrKeyNotFound
	}
	return val, nil
}

var ErrKeyNotFound = errors.New("raftkv: key not found")
```

