		return cl, nil
	}
	conn, err := grpc.Dial(addr, grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		return nil, err
	}
	cl := kvpb.NewKeyValueServiceClient(conn)
	c.conns[addr] = cl
	return cl, nil
}

func (c *Client) Set(ctx context.Context, key, val string) error {
	c.mu.Lock()
	c.seq++
	seq := c.seq
	currLeader := c.leaderAddr
	c.mu.Unlock()

	for retries := 0; retries < 5; retries++ {
		client, err := c.getClient(currLeader)
		if err != nil {
			currLeader = c.nextSeed(currLeader)
			continue
		}

		reply, err := client.Set(ctx, &kvpb.SetRequest{
			Key:         key,
			Value:       val,
			ClientId:    c.clientID,
			SequenceNum: seq,
		})
		if err == nil && reply.Status == kvpb.StatusCode_OK {
			return nil
		}

		if reply != nil && reply.Status == kvpb.StatusCode_NOT_LEADER && reply.LeaderHint != "" {
			c.mu.Lock()
			c.leaderAddr = reply.LeaderHint
			currLeader = reply.LeaderHint
			c.mu.Unlock()
		} else {
			currLeader = c.nextSeed(currLeader)
		}
		time.Sleep(50 * time.Millisecond)
	}
	return fmt.Errorf("failed to execute Set after max retries")
}

func (c *Client) Get(ctx context.Context, key string) (string, error) {
	c.mu.Lock()
	c.seq++
	seq := c.seq
	currLeader := c.leaderAddr
	c.mu.Unlock()

	for retries := 0; retries < 5; retries++ {
		client, err := c.getClient(currLeader)
		if err != nil {
			currLeader = c.nextSeed(currLeader)
			continue
		}

		reply, err := client.Get(ctx, &kvpb.GetRequest{
			Key:         key,
			ClientId:    c.clientID,
			SequenceNum: seq,
		})
		if err == nil && reply.Status == kvpb.StatusCode_OK {
			return reply.Value, nil
		}

		if reply != nil && reply.Status == kvpb.StatusCode_NOT_LEADER && reply.LeaderHint != "" {
			c.mu.Lock()
			c.leaderAddr = reply.LeaderHint
			currLeader = reply.LeaderHint
			c.mu.Unlock()
		} else {
			currLeader = c.nextSeed(currLeader)
		}
		time.Sleep(50 * time.Millisecond)
	}
	return "", fmt.Errorf("failed to execute Get after max retries")
}

func (c *Client) nextSeed(curr string) string {
	for i, s := range c.seeds {
		if s == curr {
			return c.seeds[(i+1)%len(c.seeds)]
		}
	}
	return c.seeds[0]
}
```

