### Step 2 · Implement Virtual Log Index Mapping with Base Offset Translation
Create `internal/raft/snapshot_log.go` managing logical-to-physical index translation:

```go
package raft

import (
	"errors"

	"github.com/buildscape/raftkv/proto/raftpb"
)

var ErrCompacted = errors.New("raft: requested entry has been compacted into snapshot")

// logicalToPhysical converts a 1-based Raft log index to physical slice offset.
// Must be called with n.mu held.
func (n *Node) logicalToPhysical(index uint64) (int, error) {
	if index <= n.lastIncludedIndex {
		return -1, ErrCompacted
	}
	offset := int(index - n.lastIncludedIndex - 1)
	if offset >= len(n.logEntries) {
		return -1, ErrIndexOutOfBounds
	}
	return offset, nil
}

// getEntryVirtual retrieves an entry taking compaction offset into account.
func (n *Node) getEntryVirtual(index uint64) (*raftpb.LogEntry, error) {
	offset, err := n.logicalToPhysical(index)
	if err != nil {
		return nil, err
	}
	return n.logEntries[offset], nil
}

// getTermVirtual returns the term for a given logical index.
func (n *Node) getTermVirtual(index uint64) uint64 {
	if index == 0 {
		return 0
	}
	if index == n.lastIncludedIndex {
		return n.lastIncludedTerm
	}
	offset, err := n.logicalToPhysical(index)
	if err != nil {
		return 0
	}
	return n.logEntries[offset].Term
}

// lastVirtualLogInfo returns the index and term of the absolute last entry in the node's log.
func (n *Node) lastVirtualLogInfo() (uint64, uint64) {
	if len(n.logEntries) == 0 {
		return n.lastIncludedIndex, n.lastIncludedTerm
	}
	last := n.logEntries[len(n.logEntries)-1]
	return last.Index, last.Term
}
```

### Step 3 · Implement Periodic Snapshot Engine Discarding Compacted Entries
Create `internal/raft/snapshot_engine.go` writing snapshot files and truncating logs:

```go
package raft

import (
	"log"
	"os"
	"path/filepath"
)

// Snapshot creates a compacted state snapshot up to appliedIndex and truncates memory log.
func (n *Node) Snapshot(appliedIndex uint64, snapshotData []byte) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	if appliedIndex <= n.lastIncludedIndex {
		return nil // Snapshot already up to date
	}

	// Obtain term of the snapshot index
	snapTerm := n.getTermVirtual(appliedIndex)

	// Truncate the in-memory log: keep only entries beyond appliedIndex
	physicalOffset, err := n.logicalToPhysical(appliedIndex)
	if err == nil {
		rem := make([]*raftpb.LogEntry, len(n.logEntries)-(physicalOffset+1))
		copy(rem, n.logEntries[physicalOffset+1:])
		n.logEntries = rem
	} else {
		n.logEntries = nil
	}

	n.lastIncludedIndex = appliedIndex
	n.lastIncludedTerm = snapTerm

	// Persist snapshot to disk
	snapPath := filepath.Join(n.dataDir, "snapshot.bin")
	if err := os.WriteFile(snapPath, snapshotData, 0644); err != nil {
		log.Fatalf("💥 [NODE %s] Failed to write snapshot file: %v", n.id, err)
	}

	// Persist Raft metadata
	n.persistState()
	log.Printf("📸 [NODE %s] Compacted log up to Index %d (Term %d). Retained entries in memory: %d",
		n.id, appliedIndex, snapTerm, len(n.logEntries))
	return nil
}
```

### Step 4 · Implement `InstallSnapshot` RPC Handler and State Machine Restoration
Create `internal/raft/snapshot_handler.go` allowing lagging nodes to restore from leader:

```go
package raft

import (
	"context"
	"log"
	"os"
	"path/filepath"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// InstallSnapshot handles inbound snapshot chunks from the leader.
func (n *Node) InstallSnapshot(ctx context.Context, args *raftpb.InstallSnapshotArgs) (*raftpb.InstallSnapshotReply, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	reply := &raftpb.InstallSnapshotReply{Term: n.currentTerm}

	// Rule 1: Reply immediately if term < currentTerm
	if args.Term < n.currentTerm {
		return reply, nil
	}

	if args.Term > n.currentTerm {
		n.becomeFollower(args.Term, args.LeaderId)
		reply.Term = n.currentTerm
	} else {
		n.leaderID = args.LeaderId
		n.resetElectionTimer()
	}

	// If we already have a newer snapshot or log, ignore
	if args.LastIncludedIndex <= n.lastIncludedIndex {
		return reply, nil
	}

	// Save snapshot data to disk
	snapPath := filepath.Join(n.dataDir, "snapshot.bin")
	_ = os.WriteFile(snapPath, args.Data, 0644)

	// Truncate memory log: if an existing entry has same index and term, keep subsequent entries
	physicalOffset, err := n.logicalToPhysical(args.LastIncludedIndex)
	if err == nil && n.logEntries[physicalOffset].Term == args.LastIncludedTerm {
		rem := make([]*raftpb.LogEntry, len(n.logEntries)-(physicalOffset+1))
		copy(rem, n.logEntries[physicalOffset+1:])
		n.logEntries = rem
	} else {
		n.logEntries = nil
	}

	n.lastIncludedIndex = args.LastIncludedIndex
	n.lastIncludedTerm = args.LastIncludedTerm

	if args.LastIncludedIndex > n.commitIndex {
		n.commitIndex = args.LastIncludedIndex
	}
	if args.LastIncludedIndex > n.lastApplied {
		n.lastApplied = args.LastIncludedIndex
	}

	n.persistState()

	// Notify FSM to reset its state from snapshot
	go func(data []byte, idx, term uint64) {
		n.applyCh <- ApplyMsg{
			SnapshotValid: true,
			Snapshot:      data,
			SnapshotIndex: idx,
			SnapshotTerm:  term,
		}
	}(args.Data, args.LastIncludedIndex, args.LastIncludedTerm)

	log.Printf("📥 [NODE %s] Installed Snapshot from Leader up to Index %d (Term %d)",
		n.id, args.LastIncludedIndex, args.LastIncludedTerm)

	return reply, nil
}
```

### Step 5 · Implement Leader Snapshot Streaming to Lagging Followers
Create `internal/raft/snapshot_stream.go` dispatching snapshots when entries are truncated:

```go
package raft

import (
	"context"
	"log"
	"os"
	"path/filepath"
	"time"

	"github.com/buildscape/raftkv/proto/raftpb"
)

// sendSnapshotToPeer streams snapshot to a lagging follower.
func (n *Node) sendSnapshotToPeer(p *Peer) {
	client, err := p.Connect()
	if err != nil {
		return
	}

	n.mu.Lock()
	term := n.currentTerm
	leaderID := n.id
	lastIdx := n.lastIncludedIndex
	lastTerm := n.lastIncludedTerm
	n.mu.Unlock()

	snapPath := filepath.Join(n.dataDir, "snapshot.bin")
	data, err := os.ReadFile(snapPath)
	if err != nil {
		log.Printf("⚠️ [LEADER %s] Cannot stream snapshot to %s: file read error: %v", n.id, p.ID, err)
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	req := &raftpb.InstallSnapshotArgs{
		Term:              term,
		LeaderId:          leaderID,
		LastIncludedIndex: lastIdx,
		LastIncludedTerm:  lastTerm,
		Offset:            0,
		Data:              data,
		Done:              true,
	}

	reply, err := client.InstallSnapshot(ctx, req)
	if err != nil {
		return
	}

	n.mu.Lock()
	defer n.mu.Unlock()

	if reply.Term > n.currentTerm {
		n.becomeFollower(reply.Term, "")
		return
	}

	if n.role == RoleLeader && n.currentTerm == term {
		n.nextIndex[p.ID] = lastIdx + 1
		n.matchIndex[p.ID] = lastIdx
		log.Printf("🚀 [LEADER %s] Lagging follower %s successfully caught up to snapshot index %d", n.id, p.ID, lastIdx)
	}
}
