### Step 6 · Construct In-Memory Programmable Chaos Network Framework
Create `internal/chaos/network.go` simulating real-world network failure conditions:

```go
package chaos

import (
	"sync"
	"time"
)

// Network simulates network partitions, dropped messages, and latency delays.
type Network struct {
	mu         sync.RWMutex
	disabled   map[string]bool           // Disabled endpoints
	partitions map[string]map[string]bool // Source -> Target blocklist
	delay      time.Duration
}

func NewNetwork() *Network {
	return &Network{
		disabled:   make(map[string]bool),
		partitions: make(map[string]map[string]bool),
	}
}

// Partition isolates two sets of nodes from each other.
func (net *Network) Partition(groupA, groupB []string) {
	net.mu.Lock()
	defer net.mu.Unlock()

	for _, a := range groupA {
		if net.partitions[a] == nil { net.partitions[a] = make(map[string]bool) }
		for _, b := range groupB {
			net.partitions[a][b] = true
		}
	}
	for _, b := range groupB {
		if net.partitions[b] == nil { net.partitions[b] = make(map[string]bool) }
		for _, a := range groupA {
			net.partitions[b][a] = true
		}
	}
}

// Heal restores all network partitions and re-enables all nodes.
func (net *Network) Heal() {
	net.mu.Lock()
	defer net.mu.Unlock()
	net.disabled = make(map[string]bool)
	net.partitions = make(map[string]map[string]bool)
}

// IsBlocked checks if traffic from src to dst should be dropped.
func (net *Network) IsBlocked(src, dst string) bool {
	net.mu.RLock()
	defer net.mu.RUnlock()
	if net.disabled[src] || net.disabled[dst] {
		return true
	}
	if blockedTargets, ok := net.partitions[src]; ok {
		return blockedTargets[dst]
	}
	return false
}
```

