	// 6. Verify that all nodes converged on state and minority learned 'key_maj'
	val, err := client.Get(ctx, "key_maj")
	if err != nil || val != "majority_data" {
		t.Fatalf("convergence failed after heal: got %s, err: %v", val, err)
	}
}
