use pcap::{Active, Capture, Device};
use crate::error::SnifferError;

const DEFAULT_SNAPLEN: i32 = 65535;      // 64KB full packet capture
const DEFAULT_TIMEOUT_MS: i32 = 100;     // 100ms read timeout
const BUFFER_SIZE_BYTES: i32 = 4 * 1024 * 1024; // 4MB kernel ring buffer

pub struct CaptureConfig {
    pub device_name: String,
    pub promiscuous: bool,
    pub snaplen: i32,
    pub timeout_ms: i32,
    pub buffer_size: i32,
}

impl Default for CaptureConfig {
    fn default() -> Self {
        Self {
            device_name: String::new(),
            promiscuous: true,
            snaplen: DEFAULT_SNAPLEN,
            timeout_ms: DEFAULT_TIMEOUT_MS,
            buffer_size: BUFFER_SIZE_BYTES,
        }
    }
}

/// Opens a configured, live promiscuous packet capture session.
pub fn open_capture(device: Device, config: &CaptureConfig) -> Result<Capture<Active>, SnifferError> {
    let cap = Capture::from_device(device)?
        .promisc(config.promiscuous)
        .snaplen(config.snaplen)
        .timeout(config.timeout_ms)
        .buffer_size(config.buffer_size)
        .open()?;

    Ok(cap)
}
