### Step 5 · Implement Raw Packet Ingestion Loop
Create `src/capture/worker.rs` streaming packets from the kernel ring buffer:

```rust
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use pcap::{Active, Capture};
use crate::error::SnifferError;

/// Raw packet metadata and payload slice.
#[derive(Debug, Clone)]
pub struct RawPacket {
    pub timestamp_secs: i64,
    pub timestamp_micros: i64,
    pub caplen: u32,
    pub original_len: u32,
    pub data: Vec<u8>,
}

/// Runs the raw capture loop until the running flag is cleared.
pub fn run_capture_loop<F>(
    mut cap: Capture<Active>,
    running: Arc<AtomicBool>,
    mut on_packet: F,
) -> Result<u64, SnifferError>
where
    F: FnMut(RawPacket),
{
    let mut packet_count = 0u64;

    while running.load(Ordering::Relaxed) {
        match cap.next_packet() {
            Ok(packet) => {
                packet_count += 1;
                let raw = RawPacket {
                    timestamp_secs: packet.header.ts.tv_sec,
                    timestamp_micros: packet.header.ts.tv_usec,
                    caplen: packet.header.caplen,
                    original_len: packet.header.len,
                    data: packet.data.to_vec(),
                };
                on_packet(raw);
            }
            Err(pcap::Error::TimeoutExpired) => {
                // Normal timeout yield: continue to check running flag
                continue;
            }
            Err(err) => {
                return Err(SnifferError::Pcap(err));
            }
        }
    }

    Ok(packet_count)
}
```

