mod capture;
mod error;

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use clap::Parser;
use capture::{default_device, find_device_by_name, list_devices, open_capture, print_device_summary, run_capture_loop, CaptureConfig};

#[derive(Parser, Debug)]
#[command(name = "sniff", version = "0.1.0", about = "Raw Packet Sniffer & Flow Analyzer in Rust")]
struct Cli {
    /// Network interface to sniff on (e.g. eth0, lo, wlan0)
    #[arg(short, long)]
    interface: Option<String>,

    /// List available network interfaces and exit
    #[arg(short, long)]
    list: bool,

    /// Disable promiscuous mode
    #[arg(long, default_value_t = false)]
    no_promisc: bool,
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    if cli.list {
        let devices = list_devices()?;
        print_device_summary(&devices);
        return Ok(());
    }

    let device = match cli.interface {
        Some(name) => find_device_by_name(&name)?,
        None => default_device()?,
    };

    println!("🚀 Starting raw packet capture on interface '{}'", device.name);

    let config = CaptureConfig {
        device_name: device.name.clone(),
        promiscuous: !cli.no_promisc,
        ..Default::default()
    };

    let cap = open_capture(device, &config)?;

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();
    ctrlc::set_handler(move || {
        println!("\n🛑 Received termination signal, stopping capture...");
        r.store(false, Ordering::SeqCst);
    }).expect("Error setting Ctrl-C handler");

    let total = run_capture_loop(cap, running, |pkt| {
        println!("📦 [PACKET] ts={}.{:06} caplen={} original={} bytes",
            pkt.timestamp_secs, pkt.timestamp_micros, pkt.caplen, pkt.original_len);
    })?;

    println!("🏁 Capture finished. Total packets processed: {}", total);
    Ok(())
}
