use crate::protocol::constants::ether_type;
use crate::protocol::mac::MacAddress;

/// A zero-copy borrowed view over an Ethernet II frame.
#[derive(Debug, Clone, Copy)]
pub struct EthernetFrame<'a> {
    raw: &'a [u8],
}

impl<'a> EthernetFrame<'a> {
    pub const HEADER_LEN: usize = 14;

    /// Parses an Ethernet frame from a raw byte slice.
    /// Returns None if slice is shorter than 14 bytes.
    pub fn parse(bytes: &'a [u8]) -> Option<Self> {
        if bytes.len() < Self::HEADER_LEN {
            return None;
        }
        Some(Self { raw: bytes })
    }

    pub fn destination(&self) -> MacAddress {
        let mut mac = [0u8; 6];
        mac.copy_from_slice(&self.raw[0..6]);
        MacAddress(mac)
    }

    pub fn source(&self) -> MacAddress {
        let mut mac = [0u8; 6];
        mac.copy_from_slice(&self.raw[6..12]);
        MacAddress(mac)
    }

    pub fn ether_type(&self) -> u16 {
        u16::from_be_bytes([self.raw[12], self.raw[13]])
    }

    /// Returns the payload following the Ethernet header.
    pub fn payload(&self) -> &'a [u8] {
        &self.raw[Self::HEADER_LEN..]
    }
}
