```rust
use std::net::Ipv4Addr;

/// A zero-copy borrowed view over an IPv4 packet.
#[derive(Debug, Clone, Copy)]
pub struct Ipv4Packet<'a> {
    raw: &'a [u8],
}

impl<'a> Ipv4Packet<'a> {
    pub const MIN_HEADER_LEN: usize = 20;

    /// Parses an IPv4 packet, validating version, minimum length, and IHL.
    pub fn parse(bytes: &'a [u8]) -> Option<Self> {
        if bytes.len() < Self::MIN_HEADER_LEN {
            return None;
        }
        // Check Version == 4
        let version = bytes[0] >> 4;
        if version != 4 {
            return None;
        }
        // Check IHL >= 5 (20 bytes)
        let ihl = (bytes[0] & 0x0F) as usize;
        let header_len = ihl * 4;
        if header_len < Self::MIN_HEADER_LEN || bytes.len() < header_len {
            return None;
        }

        Some(Self { raw: bytes })
    }

    pub fn version(&self) -> u8 {
        self.raw[0] >> 4
    }

    pub fn header_length(&self) -> usize {
        ((self.raw[0] & 0x0F) as usize) * 4
    }

    pub fn dscp_ecn(&self) -> u8 {
        self.raw[1]
    }

    pub fn total_length(&self) -> u16 {
        u16::from_be_bytes([self.raw[2], self.raw[3]])
    }

    pub fn identification(&self) -> u16 {
        u16::from_be_bytes([self.raw[4], self.raw[5]])
    }

    pub fn ttl(&self) -> u8 {
        self.raw[8]
    }

    pub fn protocol(&self) -> u8 {
        self.raw[9]
    }

    pub fn checksum(&self) -> u16 {
        u16::from_be_bytes([self.raw[10], self.raw[11]])
    }

    pub fn source(&self) -> Ipv4Addr {
        Ipv4Addr::new(self.raw[12], self.raw[13], self.raw[14], self.raw[15])
    }

    pub fn destination(&self) -> Ipv4Addr {
        Ipv4Addr::new(self.raw[16], self.raw[17], self.raw[18], self.raw[19])
    }

    /// Returns the L4 transport payload slice following the IPv4 header.
    pub fn payload(&self) -> &'a [u8] {
        let h_len = self.header_length();
        let t_len = self.total_length() as usize;

        // Guard against truncated capture slices or invalid total_length
        let end = if t_len >= h_len && t_len <= self.raw.len() {
            t_len
        } else {
            self.raw.len()
        };
        &self.raw[h_len..end]
    }
}
```

### Step 6 · Implement RFC 1071 IPv4 Header Checksum Validator
Create `src/protocol/checksum.rs` verifying IPv4 checksum correctness:

```rust
/// Verifies the RFC 1071 one's complement checksum of an IPv4 header slice.
pub fn verify_ipv4_checksum(header_bytes: &[u8]) -> bool {
    if header_bytes.len() < 20 || header_bytes.len() % 2 != 0 {
        return false;
    }

    let mut sum: u32 = 0;
    for i in (0..header_bytes.len()).step_by(2) {
        let word = u16::from_be_bytes([header_bytes[i], header_bytes[i + 1]]) as u32;
        sum += word;
    }

    // Fold 32-bit sum into 16 bits
    while (sum >> 16) != 0 {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }

    // In one's complement addition, a valid header sum is 0xFFFF
    sum as u16 == 0xFFFF
}
```

