/// Decodes an Ethernet packet, unwrapping optional 802.1Q VLANs and parsing IPv4.
pub fn decode_packet(data: &[u8]) -> Option<(EthernetFrame, Option<Ipv4Packet>)> {
    let eth = EthernetFrame::parse(data)?;
    let mut ether_type = eth.ether_type();
    let mut payload = eth.payload();

    if ether_type == ether_type::VLAN_8021Q {
        let vlan = VlanHeader::parse(payload)?;
        ether_type = vlan.inner_ether_type();
        payload = vlan.payload();
    }

    let ipv4 = if ether_type == ether_type::IPV4 {
        Ipv4Packet::parse(payload)
    } else {
        None
    };

    Some((eth, ipv4))
}
