```rust
use bitflags::bitflags;

bitflags! {
    /// Standard TCP Header Control Flags (RFC 793 / RFC 3168)
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
    pub struct TcpFlags: u8 {
        const FIN = 0x01; // Connection termination
        const SYN = 0x02; // Synchronize sequence numbers
        const RST = 0x04; // Reset connection
        const PSH = 0x08; // Push buffer to application
        const ACK = 0x10; // Acknowledgment valid
        const URG = 0x20; // Urgent pointer valid
        const ECE = 0x40; // ECN-Echo
        const CWR = 0x80; // Congestion Window Reduced
    }
}

impl std::fmt::Display for TcpFlags {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut flags = Vec::new();
        if self.contains(TcpFlags::SYN) { flags.push("SYN"); }
        if self.contains(TcpFlags::ACK) { flags.push("ACK"); }
        if self.contains(TcpFlags::FIN) { flags.push("FIN"); }
        if self.contains(TcpFlags::RST) { flags.push("RST"); }
        if self.contains(TcpFlags::PSH) { flags.push("PSH"); }
        if self.contains(TcpFlags::URG) { flags.push("URG"); }
        if self.contains(TcpFlags::ECE) { flags.push("ECE"); }
        if self.contains(TcpFlags::CWR) { flags.push("CWR"); }
        write!(f, "[{}]", flags.join("|"))
    }
}
