```rust
use crate::protocol::tcp_flags::TcpFlags;

/// A zero-copy borrowed view over a TCP segment.
#[derive(Debug, Clone, Copy)]
pub struct TcpSegment<'a> {
    raw: &'a [u8],
}

impl<'a> TcpSegment<'a> {
    pub const MIN_HEADER_LEN: usize = 20;

    /// Parses a TCP segment from raw bytes, validating minimum length and data offset.
    pub fn parse(bytes: &'a [u8]) -> Option<Self> {
        if bytes.len() < Self::MIN_HEADER_LEN {
            return None;
        }

        let data_offset = ((bytes[12] >> 4) as usize) * 4;
        if data_offset < Self::MIN_HEADER_LEN || bytes.len() < data_offset {
            return None;
        }

        Some(Self { raw: bytes })
    }

    pub fn source_port(&self) -> u16 {
        u16::from_be_bytes([self.raw[0], self.raw[1]])
    }

    pub fn destination_port(&self) -> u16 {
        u16::from_be_bytes([self.raw[2], self.raw[3]])
    }

    pub fn sequence_number(&self) -> u32 {
        u32::from_be_bytes([self.raw[4], self.raw[5], self.raw[6], self.raw[7]])
    }

    pub fn acknowledgment_number(&self) -> u32 {
        u32::from_be_bytes([self.raw[8], self.raw[9], self.raw[10], self.raw[11]])
    }

    pub fn header_length(&self) -> usize {
        ((self.raw[12] >> 4) as usize) * 4
    }

    pub fn flags(&self) -> TcpFlags {
        TcpFlags::from_bits_truncate(self.raw[13])
    }

    pub fn window_size(&self) -> u16 {
        u16::from_be_bytes([self.raw[14], self.raw[15]])
    }

    pub fn checksum(&self) -> u16 {
        u16::from_be_bytes([self.raw[16], self.raw[17]])
    }

    pub fn urgent_pointer(&self) -> u16 {
        u16::from_be_bytes([self.raw[18], self.raw[19]])
    }

    /// Returns the application payload following the TCP header options.
    pub fn payload(&self) -> &'a [u8] {
        let h_len = self.header_length();
        &self.raw[h_len..]
    }
}
```

### Step 4 · Implement Zero-Copy UDP Datagram Parser
