```rust
/// A zero-copy borrowed view over a UDP datagram.
#[derive(Debug, Clone, Copy)]
pub struct UdpDatagram<'a> {
    raw: &'a [u8],
}

impl<'a> UdpDatagram<'a> {
    pub const HEADER_LEN: usize = 8;

    /// Parses a UDP datagram from raw bytes.
    pub fn parse(bytes: &'a [u8]) -> Option<Self> {
        if bytes.len() < Self::HEADER_LEN {
            return None;
        }
        let length = u16::from_be_bytes([bytes[4], bytes[5]]) as usize;
        if length < Self::HEADER_LEN || bytes.len() < length {
            return None;
        }
        Some(Self { raw: bytes })
    }

    pub fn source_port(&self) -> u16 {
        u16::from_be_bytes([self.raw[0], self.raw[1]])
    }

    pub fn destination_port(&self) -> u16 {
        u16::from_be_bytes([self.raw[2], self.raw[3]])
    }

    pub fn length(&self) -> u16 {
        u16::from_be_bytes([self.raw[4], self.raw[5]])
    }

    pub fn checksum(&self) -> u16 {
        u16::from_be_bytes([self.raw[6], self.raw[7]])
    }

    /// Returns the application payload.
    pub fn payload(&self) -> &'a [u8] {
        let total_len = self.length() as usize;
        let end = total_len.min(self.raw.len());
        &self.raw[Self::HEADER_LEN..end]
    }
}
