/// A zero-copy view over an ICMP control message (RFC 792).
#[derive(Debug, Clone, Copy)]
pub struct IcmpMessage<'a> {
    raw: &'a [u8],
}

impl<'a> IcmpMessage<'a> {
    pub const MIN_HEADER_LEN: usize = 4;

    pub fn parse(bytes: &'a [u8]) -> Option<Self> {
        if bytes.len() < Self::MIN_HEADER_LEN {
            return None;
        }
        Some(Self { raw: bytes })
    }

    pub fn message_type(&self) -> u8 {
        self.raw[0]
    }

    pub fn code(&self) -> u8 {
        self.raw[1]
    }

    pub fn checksum(&self) -> u16 {
        u16::from_be_bytes([self.raw[2], self.raw[3]])
    }

    pub fn payload(&self) -> &'a [u8] {
        &self.raw[Self::MIN_HEADER_LEN..]
    }

    pub fn type_description(&self) -> &'static str {
        match (self.message_type(), self.code()) {
            (0, _) => "Echo Reply (Ping)",
            (3, 0) => "Destination Net Unreachable",
            (3, 1) => "Destination Host Unreachable",
            (3, 3) => "Destination Port Unreachable",
            (8, _) => "Echo Request (Ping)",
            (11, _) => "Time Exceeded (TTL expired)",
            _ => "Other ICMP Message",
        }
    }
}
