use crate::protocol::icmp::IcmpMessage;
use crate::protocol::tcp::TcpSegment;
use crate::protocol::udp::UdpDatagram;

/// Represents a decoded Layer 4 transport protocol packet.
#[derive(Debug, Clone, Copy)]
pub enum TransportPacket<'a> {
    Tcp(TcpSegment<'a>),
    Udp(UdpDatagram<'a>),
    Icmp(IcmpMessage<'a>),
    Unknown(u8, &'a [u8]), // (protocol_number, raw_bytes)
}

impl<'a> TransportPacket<'a> {
    /// Parses transport packet based on the IPv4 protocol byte.
    pub fn parse(protocol: u8, bytes: &'a [u8]) -> Self {
        match protocol {
            6 => TcpSegment::parse(bytes).map(TransportPacket::Tcp).unwrap_or(TransportPacket::Unknown(protocol, bytes)),
            17 => UdpDatagram::parse(bytes).map(TransportPacket::Udp).unwrap_or(TransportPacket::Unknown(protocol, bytes)),
            1 => IcmpMessage::parse(bytes).map(TransportPacket::Icmp).unwrap_or(TransportPacket::Unknown(protocol, bytes)),
            other => TransportPacket::Unknown(other, bytes),
        }
    }
}
```

