pub use ipv4::Ipv4Packet;
pub use mac::MacAddress;
pub use tcp::TcpSegment;
pub use tcp_flags::TcpFlags;
pub use transport::TransportPacket;
pub use udp::UdpDatagram;
pub use vlan::VlanHeader;

/// Decodes an Ethernet packet into L2, L3, and L4 transport components.
pub fn decode_full_packet(data: &[u8]) -> Option<(EthernetFrame, Option<Ipv4Packet>, Option<TransportPacket>)> {
    let eth = EthernetFrame::parse(data)?;
    let mut ether_type = eth.ether_type();
    let mut payload = eth.payload();

    if ether_type == ether_type::VLAN_8021Q {
        let vlan = VlanHeader::parse(payload)?;
        ether_type = vlan.inner_ether_type();
        payload = vlan.payload();
    }

    if ether_type != ether_type::IPV4 {
        return Some((eth, None, None));
    }

    let ipv4 = Ipv4Packet::parse(payload)?;
    let transport = TransportPacket::parse(ipv4.protocol(), ipv4.payload());

    Some((eth, Some(ipv4), Some(transport)))
}
