```rust
use std::net::IpAddr;
use std::time::Instant;

/// Endpoint representation: (IP Address, Port)
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Endpoint {
    pub ip: IpAddr,
    pub port: u16,
}

/// Directional flow traffic metrics.
#[derive(Debug, Clone, Default)]
pub struct FlowMetrics {
    pub packets: u64,
    pub bytes: u64,
}

/// TCP Connection State Machine representation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum TcpState {
    #[default]
    Unknown,
    SynSent,
    SynReceived,
    Established,
    FinWait,
    Closed,
    Reset,
}

/// Aggregated bidirectional flow record.
#[derive(Debug, Clone)]
pub struct FlowRecord {
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub forward_metrics: FlowMetrics,
    pub reverse_metrics: FlowMetrics,
    pub tcp_state: TcpState,
}

impl FlowRecord {
    pub fn new(now: Instant, bytes: u64, is_forward: bool, tcp_state: TcpState) -> Self {
        let mut forward = FlowMetrics::default();
        let mut reverse = FlowMetrics::default();
        if is_forward {
            forward.packets = 1;
            forward.bytes = bytes;
        } else {
            reverse.packets = 1;
            reverse.bytes = bytes;
        }

        Self {
            first_seen: now,
            last_seen: now,
            forward_metrics: forward,
            reverse_metrics: reverse,
            tcp_state,
        }
    }

    pub fn total_packets(&self) -> u64 {
        self.forward_metrics.packets + self.reverse_metrics.packets
    }

    pub fn total_bytes(&self) -> u64 {
        self.forward_metrics.bytes + self.reverse_metrics.bytes
    }

    pub fn duration_secs(&self) -> f64 {
        self.last_seen.duration_since(self.first_seen).as_secs_f64()
    }
}
```

### Step 2 · Implement Canonical 5-Tuple Normalization
Create `src/flow/key.rs` implementing symmetric flow hashing:

```rust
use std::fmt;
use std::net::IpAddr;
use crate::flow::types::Endpoint;

/// A normalized, bidirectional flow key.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct FlowKey {
    pub endpoint_a: Endpoint,
    pub endpoint_b: Endpoint,
    pub protocol: u8,
}

impl FlowKey {
    /// Creates a normalized flow key from arbitrary source/destination endpoints.
    /// Returns (FlowKey, is_forward_direction).
pub fn from_packet(
        src_ip: IpAddr,
        src_port: u16,
        dst_ip: IpAddr,
        dst_port: u16,
        protocol: u8,
    ) -> (Self, bool) {
        let ep_src = Endpoint { ip: src_ip, port: src_port };
        let ep_dst = Endpoint { ip: dst_ip, port: dst_port };

        if ep_src <= ep_dst {
            (Self { endpoint_a: ep_src, endpoint_b: ep_dst, protocol }, true)
        } else {
            (Self { endpoint_a: ep_dst, endpoint_b: ep_src, protocol }, false)
        }
    }
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let proto_str = match self.protocol {
            6 => "TCP",
            17 => "UDP",
            1 => "ICMP",
            p => return write!(f, "Proto({}) {}:{} <-> {}:{}", p, self.endpoint_a.ip, self.endpoint_a.port, self.endpoint_b.ip, self.endpoint_b.port),
        };
        write!(f, "[{}] {}:{} <-> {}:{}", proto_str, self.endpoint_a.ip, self.endpoint_a.port, self.endpoint_b.ip, self.endpoint_b.port)
    }
}
