### Step 3 · Implement TCP Connection State Machine
Create `src/flow/state.rs` tracking TCP handshake and teardown flags:

```rust
use crate::flow::types::TcpState;
use crate::protocol::TcpFlags;

/// Updates the TCP state machine given newly observed flags on a flow.
pub fn update_tcp_state(current: TcpState, flags: TcpFlags, is_forward: bool) -> TcpState {
    if flags.contains(TcpFlags::RST) {
        return TcpState::Reset;
    }

    match current {
        TcpState::Unknown => {
            if flags.contains(TcpFlags::SYN) && !flags.contains(TcpFlags::ACK) {
                TcpState::SynSent
            } else if flags.contains(TcpFlags::SYN) && flags.contains(TcpFlags::ACK) {
                TcpState::SynReceived
            } else {
                TcpState::Established
            }
        }
        TcpState::SynSent => {
            if !is_forward && flags.contains(TcpFlags::SYN) && flags.contains(TcpFlags::ACK) {
                TcpState::SynReceived
            } else {
                current
            }
        }
        TcpState::SynReceived => {
            if is_forward && flags.contains(TcpFlags::ACK) {
                TcpState::Established
            } else {
                current
            }
        }
        TcpState::Established => {
            if flags.contains(TcpFlags::FIN) {
                TcpState::FinWait
            } else {
                current
            }
        }
        TcpState::FinWait => {
            if flags.contains(TcpFlags::ACK) || flags.contains(TcpFlags::FIN) {
                TcpState::Closed
            } else {
                current
            }
        }
        TcpState::Closed | TcpState::Reset => current,
    }
}
```

### Step 4 · Construct In-Memory Flow Table Engine
Create `src/flow/table.rs` storing active flows with thread-safe aggregation:

```rust
use std::collections::HashMap;
use std::net::IpAddr;
use std::time::{Duration, Instant};
use crate::flow::key::FlowKey;
use crate::flow::state::update_tcp_state;
use crate::flow::types::{FlowRecord, TcpState};
use crate::protocol::TcpFlags;

pub struct FlowTable {
    flows: HashMap<FlowKey, FlowRecord>,
    ttl: Duration,
}

impl FlowTable {
    pub fn new(ttl: Duration) -> Self {
        Self {
            flows: HashMap::new(),
            ttl,
        }
    }

    /// Ingests a transport packet into the flow table, creating or updating its record.
    pub fn ingest_packet(
        &mut self,
        src_ip: IpAddr,
        src_port: u16,
        dst_ip: IpAddr,
        dst_port: u16,
        protocol: u8,
        bytes: u64,
        tcp_flags: Option<TcpFlags>,
        now: Instant,
    ) {
        let (key, is_forward) = FlowKey::from_packet(src_ip, src_port, dst_ip, dst_port, protocol);

        if let Some(record) = self.flows.get_mut(&key) {
            record.last_seen = now;
            if is_forward {
                record.forward_metrics.packets += 1;
                record.forward_metrics.bytes += bytes;
            } else {
                record.reverse_metrics.packets += 1;
                record.reverse_metrics.bytes += bytes;
            }
            if let Some(flags) = tcp_flags {
                record.tcp_state = update_tcp_state(record.tcp_state, flags, is_forward);
            }
        } else {
            let initial_state = if let Some(flags) = tcp_flags {
                update_tcp_state(TcpState::Unknown, flags, is_forward)
            } else {
                TcpState::Unknown
            };
            let record = FlowRecord::new(now, bytes, is_forward, initial_state);
            self.flows.insert(key, record);
        }
    }

    /// Evicts idle flows that have not seen traffic for longer than the TTL.
    pub fn evict_expired(&mut self, now: Instant) -> usize {
        let ttl = self.ttl;
        let initial_count = self.flows.len();
        self.flows.retain(|_, record| now.duration_since(record.last_seen) < ttl);
        initial_count - self.flows.len()
    }

    pub fn active_flow_count(&self) -> usize {
        self.flows.len()
    }

    pub fn iter_flows(&self) -> impl Iterator<Item = (&FlowKey, &FlowRecord)> {
        self.flows.iter()
    }
}
```

