use pcap::{Active, Capture, Device};
use crate::error::SnifferError;

const DEFAULT_SNAPLEN: i32 = 65535;
const DEFAULT_TIMEOUT_MS: i32 = 100;
const BUFFER_SIZE_BYTES: i32 = 4 * 1024 * 1024;

pub struct CaptureConfig {
    pub device_name: String,
    pub promiscuous: bool,
    pub snaplen: i32,
    pub timeout_ms: i32,
    pub buffer_size: i32,
    pub bpf_filter: Option<String>,
}

impl Default for CaptureConfig {
    fn default() -> Self {
        Self {
            device_name: String::new(),
            promiscuous: true,
            snaplen: DEFAULT_SNAPLEN,
            timeout_ms: DEFAULT_TIMEOUT_MS,
            buffer_size: BUFFER_SIZE_BYTES,
            bpf_filter: None,
        }
    }
}

/// Opens a live capture session and applies in-kernel BPF filters if specified.
pub fn open_capture(device: Device, config: &CaptureConfig) -> Result<Capture<Active>, SnifferError> {
    let mut cap = Capture::from_device(device)?
        .promisc(config.promiscuous)
        .snaplen(config.snaplen)
        .timeout(config.timeout_ms)
        .buffer_size(config.buffer_size)
        .open()?;

    // Compile and attach BPF filter in kernel space
    if let Some(ref filter_expr) = config.bpf_filter {
        cap.filter(filter_expr, true)?;
    }

    Ok(cap)
}
