use std::net::IpAddr;
use std::time::{Duration, Instant};
use sniff::flow::{FlowKey, FlowTable, TcpState};
use sniff::protocol::TcpFlags;

#[test]
fn test_bidirectional_traffic_aggregates_into_single_flow() {
    let mut table = FlowTable::new(Duration::from_secs(60));
    let now = Instant::now();

    let client_ip: IpAddr = "192.168.1.50".parse().unwrap();
    let server_ip: IpAddr = "142.250.190.46".parse().unwrap();

    // 1. Client -> Server SYN (forward packet)
    table.ingest_packet(client_ip, 54321, server_ip, 443, 6, 64, Some(TcpFlags::SYN), now);
    assert_eq!(table.active_flow_count(), 1);

    // 2. Server -> Client SYN-ACK (reverse reply packet)
    table.ingest_packet(server_ip, 443, client_ip, 54321, 6, 64, Some(TcpFlags::SYN | TcpFlags::ACK), now);
    // Must STILL be 1 flow record!
    assert_eq!(table.active_flow_count(), 1);

    // 3. Client -> Server ACK (forward packet)
    table.ingest_packet(client_ip, 54321, server_ip, 443, 6, 52, Some(TcpFlags::ACK), now);
    assert_eq!(table.active_flow_count(), 1);

    // Verify metrics
    let (key, _) = FlowKey::from_packet(client_ip, 54321, server_ip, 443, 6);
    let record = table.iter_flows().find(|(k, _)| **k == key).unwrap().1;

    assert_eq!(record.forward_metrics.packets, 2);
    assert_eq!(record.forward_metrics.bytes, 116);
    assert_eq!(record.reverse_metrics.packets, 1);
    assert_eq!(record.reverse_metrics.bytes, 64);
    assert_eq!(record.total_packets(), 3);
    assert_eq!(record.total_bytes(), 180);
    assert_eq!(record.tcp_state, TcpState::Established);
}

#[test]
fn test_idle_flow_eviction() {
    let mut table = FlowTable::new(Duration::from_millis(50));
    let t0 = Instant::now();

    let ip_a: IpAddr = "10.0.0.1".parse().unwrap();
    let ip_b: IpAddr = "10.0.0.2".parse().unwrap();

    table.ingest_packet(ip_a, 1000, ip_b, 2000, 17, 100, None, t0);
    assert_eq!(table.active_flow_count(), 1);

    // Advance time beyond TTL (100ms later)
    let t1 = t0 + Duration::from_millis(100);
    let evicted = table.evict_expired(t1);
    assert_eq!(evicted, 1);
    assert_eq!(table.active_flow_count(), 0);
}
