### Step 3 · Implement Capture Worker Producer Thread
Create `src/ui/worker.rs` extracting summaries and sending them non-blockingly:

```rust
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::SyncSender;
use std::sync::Arc;
use std::time::Instant;
use pcap::{Active, Capture};
use crate::protocol::{decode_full_packet, TransportPacket};
use crate::ui::events::PacketSummary;

/// Runs the packet capture worker, decoding packets and sending summaries across the channel.
pub fn start_capture_worker(
    mut cap: Capture<Active>,
    tx: SyncSender<PacketSummary>,
    running: Arc<AtomicBool>,
) -> std::thread::JoinHandle<u64> {
    std::thread::spawn(move || {
        let mut total_packets = 0u64;

        while running.load(Ordering::Relaxed) {
            match cap.next_packet() {
                Ok(packet) => {
                    total_packets += 1;
                    if let Some((_, Some(ip), Some(transport))) = decode_full_packet(packet.data) {
                        let (src_port, dst_port, tcp_flags) = match transport {
                            TransportPacket::Tcp(t) => (t.source_port(), t.destination_port(), Some(t.flags())),
                            TransportPacket::Udp(u) => (u.source_port(), u.destination_port(), None),
                            _ => (0, 0, None),
                        };

                        let summary = PacketSummary {
                            timestamp: Instant::now(),
                            src_ip: std::net::IpAddr::V4(ip.source()),
                            src_port,
                            dst_ip: std::net::IpAddr::V4(ip.destination()),
                            dst_port,
                            protocol: ip.protocol(),
                            wire_bytes: packet.header.len as u64,
                            tcp_flags,
                        };

                        // Non-blocking try_send: drops sample if UI lags, never blocks capture!
                        let _ = tx.try_send(summary);
                    }
                }
                Err(pcap::Error::TimeoutExpired) => continue,
                Err(_) => break,
            }
        }

        total_packets
    })
}
```

### Step 4 · Implement Top-Talkers Sorting and Formatting Helper
Create `src/ui/table_view.rs` formatting flow rows for Ratatui display:

```rust
use crate::flow::{FlowKey, FlowRecord, FlowTable};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortOrder {
    ByBytes,
    ByPackets,
    ByDuration,
}

/// Formats byte quantities into human-readable strings (KB, MB, GB).
pub fn format_bytes(bytes: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = 1024 * KB;
    const GB: u64 = 1024 * MB;

    if bytes >= GB {
        format!("{:.2} GB", bytes as f64 / GB as f64)
    } else if bytes >= MB {
        format!("{:.2} MB", bytes as f64 / MB as f64)
    } else if bytes >= KB {
        format!("{:.1} KB", bytes as f64 / KB as f64)
    } else {
        format!("{} B", bytes)
    }
}

/// Extracts sorted top talkers from the flow table.
pub fn get_top_flows<'a>(
    table: &'a FlowTable,
    limit: usize,
    sort_order: SortOrder,
) -> Vec<(&'a FlowKey, &'a FlowRecord)> {
    let mut list: Vec<(&'a FlowKey, &'a FlowRecord)> = table.iter_flows().collect();

    match sort_order {
        SortOrder::ByBytes => list.sort_by(|a, b| b.1.total_bytes().cmp(&a.1.total_bytes())),
        SortOrder::ByPackets => list.sort_by(|a, b| b.1.total_packets().cmp(&a.1.total_packets())),
        SortOrder::ByDuration => list.sort_by(|a, b| b.1.duration_secs().partial_cmp(&a.1.duration_secs()).unwrap()),
    }

    list.truncate(limit);
    list
}
```

