### Step 6 · Implement Terminal Setup, Teardown & Panic Hook Guard
Create `src/ui/terminal.rs` ensuring terminal attributes are always restored:

```rust
use std::io::{self, stdout};
use crossterm::execute;
use crossterm::terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;

pub struct TerminalGuard;

impl TerminalGuard {
    pub fn init() -> io::Result<Terminal<CrosstermBackend<io::Stdout>>> {
        enable_raw_mode()?;
        let mut out = stdout();
        execute!(out, EnterAlternateScreen)?;

        // Install panic hook to restore terminal if application crashes
        let original_hook = std::panic::take_hook();
        std::panic::set_hook(Box::new(move |info| {
            let _ = disable_raw_mode();
            let _ = execute!(stdout(), LeaveAlternateScreen);
            original_hook(info);
        }));

        let backend = CrosstermBackend::new(out);
        Terminal::new(backend)
    }
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        let _ = disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen);
    }
}
```

### Step 7 · Build Interactive UI Event Loop
Create `src/ui/app.rs` coordinating channels, keypresses, and dashboard rendering:

```rust
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::Receiver;
use std::sync::Arc;
use std::time::{Duration, Instant};
use crossterm::event::{self, Event, KeyCode};
use crate::flow::FlowTable;
use crate::ui::dashboard::{render_dashboard, DashboardState};
use crate::ui::events::PacketSummary;
use crate::ui::table_view::SortOrder;
use crate::ui::terminal::TerminalGuard;

pub fn run_ui_loop(
    interface_name: &str,
    bpf_filter: Option<&str>,
    rx: Receiver<PacketSummary>,
    running: Arc<AtomicBool>,
) -> anyhow::Result<()> {
    let _guard = TerminalGuard;
    let mut terminal = TerminalGuard::init()?;

    let mut flow_table = FlowTable::new(Duration::from_secs(60));
    let mut total_packets = 0u64;
    let mut total_bytes = 0u64;
    let mut sort_order = SortOrder::ByBytes;
    let mut last_eviction = Instant::now();

    while running.load(Ordering::Relaxed) {
        // 1. Drain up to 256 pending packet summaries from channel per frame
        for _ in 0..256 {
            match rx.try_recv() {
                Ok(pkt) => {
                    total_packets += 1;
                    total_bytes += pkt.wire_bytes;
                    flow_table.ingest_packet(
                        pkt.src_ip,
                        pkt.src_port,
                        pkt.dst_ip,
                        pkt.dst_port,
                        pkt.protocol,
                        pkt.wire_bytes,
                        pkt.tcp_flags,
                        pkt.timestamp,
                    );
                }
                Err(_) => break,
            }
        }

        // 2. Periodic flow table TTL eviction every 5 seconds
        let now = Instant::now();
        if now.duration_since(last_eviction) >= Duration::from_secs(5) {
            flow_table.evict_expired(now);
            last_eviction = now;
        }

        // 3. Render Dashboard
        let state = DashboardState {
            interface: interface_name,
            filter: bpf_filter,
            total_packets,
            total_bytes,
            sort_order,
        };

        terminal.draw(|f| render_dashboard(f, &flow_table, &state))?;

        // 4. Poll keyboard inputs with 100ms timeout (10 FPS)
        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => {
                        running.store(false, Ordering::SeqCst);
                        break;
                    }
                    KeyCode::Char('b') => sort_order = SortOrder::ByBytes,
                    KeyCode::Char('p') => sort_order = SortOrder::ByPackets,
                    KeyCode::Char('d') => sort_order = SortOrder::ByDuration,
                    KeyCode::Char('c') => {
                        flow_table = FlowTable::new(Duration::from_secs(60));
                    }
                    _ => {}
                }
            }
        }
    }

    Ok(())
}
```

