## 🛠 Step-by-Step Implementation

### Step 1 · Implement Savefile Writer for Live PCAP Export
Create `src/capture/writer.rs` managing file dumps:

```rust
use std::path::Path;
use pcap::{Active, Capture, Savefile};
use crate::error::SnifferError;

pub struct PcapWriter {
    savefile: Savefile,
}

impl PcapWriter {
    /// Creates a new PCAP savefile matching the parameters of the active capture session.
    pub fn new<P: AsRef<Path>>(cap: &Capture<Active>, path: P) -> Result<Self, SnifferError> {
        let savefile = cap.savefile(path)?;
        Ok(Self { savefile })
    }

    /// Writes a captured packet to the PCAP file on disk.
    pub fn write_packet(&mut self, packet: &pcap::Packet) {
        self.savefile.write(packet);
    }

    /// Flushes buffered packet writes to disk.
    pub fn flush(&mut self) -> Result<(), SnifferError> {
        self.savefile.flush()?;
        Ok(())
    }
