/// Writes a valid 24-byte PCAP Global Header (Ethernet, Snaplen=65535)
pub fn create_test_pcap_file<P: AsRef<Path>>(path: P, packets: &[&[u8]]) -> std::io::Result<()> {
    let mut file = File::create(path)?;

    // 24-byte Global Header
    let global_header: [u8; 24] = [
        0xd4, 0xc3, 0xb2, 0xa1, // Magic: Little-endian 0xa1b2c3d4
        0x02, 0x00,             // Major: 2
        0x04, 0x00,             // Minor: 4
        0x00, 0x00, 0x00, 0x00, // ThisZone: 0
        0x00, 0x00, 0x00, 0x00, // SigFigs: 0
        0xff, 0xff, 0x00, 0x00, // SnapLen: 65535
        0x01, 0x00, 0x00, 0x00, // Network: 1 (DLT_EN10MB Ethernet)
    ];
    file.write_all(&global_header)?;

    for (i, &pkt_data) in packets.iter().enumerate() {
        let len = pkt_data.len() as u32;
        let mut pkt_header = [0u8; 16];
        // ts_sec
        pkt_header[0..4].copy_from_slice(&(1700000000u32 + i as u32).to_le_bytes());
        // ts_usec
        pkt_header[4..8].copy_from_slice(&0u32.to_le_bytes());
        // caplen
        pkt_header[8..12].copy_from_slice(&len.to_le_bytes());
        // orig_len
        pkt_header[12..16].copy_from_slice(&len.to_le_bytes());

        file.write_all(&pkt_header)?;
        file.write_all(pkt_data)?;
    }

    file.flush()
}
