### Step 4 · Implement Binary Record Encoder with CRC32 Checksums
Create `src/wal/encoder.rs` encoding binary records into byte vectors:

```rust
use byteorder::{LittleEndian, WriteBytesExt};
use crate::wal::record::{WalEntry, WalOpType};

/// Encodes a WalEntry into binary framed bytes [Len: 4B][CRC32: 4B][Payload...].
pub fn encode_record(entry: &WalEntry) -> Vec<u8> {
    let val_bytes = entry.value.as_deref().unwrap_or(&[]);
    let payload_len = 1 + 4 + 4 + entry.key.len() + val_bytes.len();

    let mut payload = Vec::with_capacity(payload_len);
    payload.push(entry.op as u8);
    payload.write_u32::<LittleEndian>(entry.key.len() as u32).unwrap();
    payload.write_u32::<LittleEndian>(val_bytes.len() as u32).unwrap();
    payload.extend_from_slice(&entry.key);
    payload.extend_from_slice(val_bytes);

    let crc = crc32fast::hash(&payload);

    let mut record = Vec::with_capacity(8 + payload_len);
    record.write_u32::<LittleEndian>(payload_len as u32).unwrap();
    record.write_u32::<LittleEndian>(crc).unwrap();
    record.extend_from_slice(&payload);

    record
}
```

### Step 5 · Implement Append-Only WAL Writer
