```rust
use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};
use crate::error::LsmError;
use crate::wal::encoder::encode_record;
use crate::wal::record::{WalEntry, WalOpType};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SyncPolicy {
    /// Call sync_data (fdatasync) after every single write (maximum durability, RPO=0)
    Immediate,
    /// Rely on BufWriter and OS flush (maximum throughput)
    Buffered,
}

pub struct WalWriter {
    path: PathBuf,
    writer: BufWriter<File>,
    policy: SyncPolicy,
    bytes_written: u64,
}

impl WalWriter {
    /// Opens or creates a WAL file at the given path in append mode.
    pub fn open<P: AsRef<Path>>(path: P, policy: SyncPolicy) -> Result<Self, LsmError> {
        let path_buf = path.as_ref().to_path_buf();
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&path_buf)?;

        let bytes_written = file.metadata()?.len();
        let writer = BufWriter::with_capacity(64 * 1024, file);

        Ok(Self {
            path: path_buf,
            writer,
            policy,
            bytes_written,
        })
    }

    /// Appends a PUT operation to the WAL.
    pub fn append_put(&mut self, key: &[u8], value: &[u8]) -> Result<(), LsmError> {
        let entry = WalEntry {
            op: WalOpType::Put,
            key: key.to_vec(),
            value: Some(value.to_vec()),
        };
        self.append_entry(&entry)
    }

    /// Appends a DELETE tombstone operation to the WAL.
    pub fn append_delete(&mut self, key: &[u8]) -> Result<(), LsmError> {
        let entry = WalEntry {
            op: WalOpType::Delete,
            key: key.to_vec(),
            value: None,
        };
        self.append_entry(&entry)
    }

    fn append_entry(&mut self, entry: &WalEntry) -> Result<(), LsmError> {
        let bytes = encode_record(entry);
        self.writer.write_all(&bytes)?;
        self.bytes_written += bytes.len() as u64;

        if self.policy == SyncPolicy::Immediate {
            self.writer.flush()?;
            self.writer.get_ref().sync_data()?;
        }

        Ok(())
    }

    /// Flushes the in-memory buffer and synchronizes all data to disk.
    pub fn sync(&mut self) -> Result<(), LsmError> {
        self.writer.flush()?;
        self.writer.get_ref().sync_data()?;
        Ok(())
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn size(&self) -> u64 {
        self.bytes_written
    }
}
```

### Step 6 · Implement WAL Recovery Reader with Torn-Write Detection
Create `src/wal/reader.rs` iterating over records and validating CRC32:

```rust
use std::fs::File;
use std::io::{BufReader, Read, Seek, SeekFrom};
use std::path::Path;
use byteorder::{LittleEndian, ReadBytesExt};
use crate::error::LsmError;
use crate::wal::record::{WalEntry, WalOpType};

pub struct WalReader {
    reader: BufReader<File>,
    current_offset: u64,
}

impl WalReader {
    pub fn open<P: AsRef<Path>>(path: P) -> Result<Self, LsmError> {
        let file = File::open(path)?;
        Ok(Self {
            reader: BufReader::new(file),
            current_offset: 0,
        })
    }

    /// Reads the next valid WAL entry. Returns Ok(None) upon clean EOF.
    /// If a torn write occurs at EOF, halts gracefully and reports the corruption.
    pub fn next_entry(&mut self) -> Result<Option<WalEntry>, LsmError> {
        let mut header_buf = [0u8; 8];
        match self.reader.read_exact(&mut header_buf) {
            Ok(()) => {}
            Err(ref e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
                // Clean EOF: no bytes left to read
                return Ok(None);
            }
            Err(e) => return Err(LsmError::Io(e)),
        }

        let mut header_cursor = &header_buf[..];
        let payload_len = header_cursor.read_u32::<LittleEndian>().unwrap() as usize;
        let stored_crc = header_cursor.read_u32::<LittleEndian>().unwrap();

        let mut payload = vec![0u8; payload_len];
        if let Err(e) = self.reader.read_exact(&mut payload) {
            if e.kind() == std::io::ErrorKind::UnexpectedEof {
                // Torn write detected: record was cut off before completing
                return Err(LsmError::WalTruncated { offset: self.current_offset });
            }
            return Err(LsmError::Io(e));
        }

        // Validate CRC32
        let computed_crc = crc32fast::hash(&payload);
        if computed_crc != stored_crc {
            return Err(LsmError::WalCrcMismatch {
                expected: stored_crc,
                computed: computed_crc,
                offset: self.current_offset,
            });
        }

        self.current_offset += 8 + payload_len as u64;

        // Decode payload
        let mut cur = &payload[..];
        let op_byte = cur.read_u8()?;
        let op = WalOpType::try_from(op_byte).map_err(LsmError::InvalidOpType)?;
        let key_len = cur.read_u32::<LittleEndian>()? as usize;
        let val_len = cur.read_u32::<LittleEndian>()? as usize;

        let key = cur[..key_len].to_vec();
        let val_slice = &cur[key_len..key_len + val_len];
        let value = match op {
            WalOpType::Put => Some(val_slice.to_vec()),
            WalOpType::Delete => None,
        };

        Ok(Some(WalEntry { op, key, value }))
    }

    /// Recovers all valid entries until clean EOF, stopping safely at the first torn record.
pub fn recover_all(&mut self) -> (Vec<WalEntry>, Option<LsmError>) {
        let mut entries = Vec::new();
        loop {
            match self.next_entry() {
                Ok(Some(entry)) => entries.push(entry),
                Ok(None) => return (entries, None), // Clean EOF
                Err(err) => return (entries, Some(err)), // Torn write or corruption
            }
        }
    }
}
```

