/// Represents the state of a key in the MemTable: either a live value or a deletion tombstone.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ValueState {
    Value(Vec<u8>),
    Tombstone,
}

impl ValueState {
    pub fn is_tombstone(&self) -> bool {
        matches!(self, ValueState::Tombstone)
    }

    pub fn as_bytes(&self) -> Option<&[u8]> {
        match self {
            ValueState::Value(v) => Some(v.as_slice()),
            ValueState::Tombstone => None,
        }
    }

    pub fn len(&self) -> usize {
        match self {
            ValueState::Value(v) => v.len(),
            ValueState::Tombstone => 0,
        }
    }
}
