### Step 3 · Implement In-Memory MemTable with Precise Memory Accounting
Create `src/memtable/table.rs` managing the ordered `BTreeMap` and size tracking:

```rust
use std::collections::BTreeMap;
use crate::memtable::entry::ValueState;

const NODE_OVERHEAD_BYTES: usize = 32;

pub struct MemTable {
    map: BTreeMap<Vec<u8>, ValueState>,
    size_bytes: usize,
    capacity_bytes: usize,
}

impl MemTable {
    pub fn new(capacity_bytes: usize) -> Self {
        Self {
            map: BTreeMap::new(),
            size_bytes: 0,
            capacity_bytes,
        }
    }

    /// Inserts or updates a key with a live value.
pub fn put(&mut self, key: Vec<u8>, value: Vec<u8>) {
        let entry_size = key.len() + value.len() + NODE_OVERHEAD_BYTES;
        let new_state = ValueState::Value(value);

        if let Some(old_state) = self.map.insert(key, new_state) {
            self.size_bytes += entry_size;
            self.size_bytes = self.size_bytes.saturating_sub(old_state.len() + NODE_OVERHEAD_BYTES);
        } else {
            self.size_bytes += entry_size;
        }
    }

    /// Inserts a deletion tombstone for a key.
pub fn delete(&mut self, key: Vec<u8>) {
        let entry_size = key.len() + NODE_OVERHEAD_BYTES;
        let new_state = ValueState::Tombstone;

        if let Some(old_state) = self.map.insert(key, new_state) {
            self.size_bytes += entry_size;
            self.size_bytes = self.size_bytes.saturating_sub(old_state.len() + NODE_OVERHEAD_BYTES);
        } else {
            self.size_bytes += entry_size;
        }
    }

    /// Retrieves the current value state for a key (returns None if key is absent from this MemTable).
pub fn get(&self, key: &[u8]) -> Option<&ValueState> {
        self.map.get(key)
    }

    /// Returns true if the MemTable memory footprint has reached or exceeded capacity.
pub fn should_flush(&self) -> bool {
        self.size_bytes >= self.capacity_bytes
    }

    pub fn size_bytes(&self) -> usize {
        self.size_bytes
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }

    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }

    /// Returns an ordered iterator over all entries in the MemTable.
pub fn iter(&self) -> impl Iterator<Item = (&Vec<u8>, &ValueState)> {
        self.map.iter()
    }
}
```

