### Step 5 · Implement Concurrent MemTable Manager with Active/Frozen Slots
Create `src/memtable/manager.rs` managing active vs immutable tables:

```rust
use std::sync::Arc;
use parking_lot::RwLock;
use crate::memtable::entry::ValueState;
use crate::memtable::table::MemTable;

pub struct MemTableManager {
    active: RwLock<MemTable>,
    frozen: RwLock<Option<Arc<MemTable>>>,
    capacity_bytes: usize,
}

impl MemTableManager {
    pub fn new(capacity_bytes: usize) -> Self {
        Self {
            active: RwLock::new(MemTable::new(capacity_bytes)),
            frozen: RwLock::new(None),
            capacity_bytes,
        }
    }

    /// Inserts a key-value pair into the active MemTable.
    /// Returns true if the active table reached flush threshold and should be frozen.
pub fn put(&self, key: Vec<u8>, value: Vec<u8>) -> bool {
        let mut active = self.active.write();
        active.put(key, value);
        active.should_flush()
    }

    /// Inserts a deletion tombstone into the active MemTable.
pub fn delete(&self, key: Vec<u8>) -> bool {
        let mut active = self.active.write();
        active.delete(key);
        active.should_flush()
    }

    /// Searches for a key, inspecting Active MemTable first, then Frozen MemTable.
pub fn get(&self, key: &[u8]) -> Option<ValueState> {
        // 1. Check active table
        if let Some(state) = self.active.read().get(key) {
            return Some(state.clone());
        }

        // 2. Check frozen table
        if let Some(ref frozen) = *self.frozen.read() {
            if let Some(state) = frozen.get(key) {
                return Some(state.clone());
            }
        }

        None
    }

    /// Freezes the current active MemTable if no frozen table is currently pending flush.
    /// Returns the Arc<MemTable> ready for background disk flushing.
pub fn freeze_active(&self) -> Option<Arc<MemTable>> {
        let mut frozen_guard = self.frozen.write();
        if frozen_guard.is_some() {
            // Background flush has not finished dumping prior frozen table yet!
            return None;
        }

        let mut active_guard = self.active.write();
        let old_active = std::mem::replace(&mut *active_guard, MemTable::new(self.capacity_bytes));
        let frozen_arc = Arc::new(old_active);
        *frozen_guard = Some(frozen_arc.clone());
        Some(frozen_arc)
    }

    /// Clears the frozen MemTable slot after SSTable flush completes successfully.
pub fn clear_frozen(&self) {
        let mut frozen_guard = self.frozen.write();
        *frozen_guard = None;
    }

    pub fn has_frozen(&self) -> bool {
        self.frozen.read().is_some()
    }
}
```

