```rust
use crate::error::LsmError;
use crate::memtable::manager::MemTableManager;
use crate::wal::WalWriter;

/// Coordinates a durable write: WAL append followed by in-memory MemTable insertion.
pub fn durable_put(
    wal: &mut WalWriter,
    mem: &MemTableManager,
    key: &[u8],
    value: &[u8],
) -> Result<bool, LsmError> {
    // 1. Write to WAL first (crash safety)
    wal.append_put(key, value)?;

    // 2. Update MemTable
    let should_flush = mem.put(key.to_vec(), value.to_vec());
    Ok(should_flush)
}

/// Coordinates a durable delete: WAL append followed by tombstone insertion.
pub fn durable_delete(
    wal: &mut WalWriter,
    mem: &MemTableManager,
    key: &[u8],
) -> Result<bool, LsmError> {
    wal.append_delete(key)?;
    let should_flush = mem.delete(key.to_vec());
    Ok(should_flush)
}
```

