### Step 2 · Implement Data Block Binary Serialization
Create `src/sstable/block.rs` packing key-value pairs into 4KB chunks:

```rust
use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use std::io::{self, Cursor};
use crate::memtable::ValueState;

/// An in-memory data block consisting of packed key-value pairs.
#[derive(Debug, Clone, Default)]
pub struct DataBlock {
    data: Vec<u8>,
    num_entries: usize,
}

impl DataBlock {
    pub fn new() -> Self {
        Self { data: Vec::new(), num_entries: 0 }
    }

    /// Appends a key-value record to the data block.
    /// Format per entry: [KeyLen: 2B][ValLen: 4B (0 if tombstone)][IsTombstone: 1B][Key][Val]
pub fn add_entry(&mut self, key: &[u8], value: &ValueState) {
        let val_bytes = value.as_bytes().unwrap_or(&[]);
        let is_tombstone = if value.is_tombstone() { 1u8 } else { 0u8 };

        self.data.write_u16::<LittleEndian>(key.len() as u16).unwrap();
        self.data.write_u32::<LittleEndian>(val_bytes.len() as u32).unwrap();
        self.data.push(is_tombstone);
        self.data.extend_from_slice(key);
        self.data.extend_from_slice(val_bytes);
        self.num_entries += 1;
    }

    pub fn estimated_size(&self) -> usize {
        self.data.len()
    }

    pub fn as_bytes(&self) -> &[u8] {
        &self.data
    }

    /// Decodes and searches for a specific key within this block's raw bytes.
pub fn find_key(block_bytes: &[u8], target_key: &[u8]) -> io::Result<Option<ValueState>> {
        let mut cursor = Cursor::new(block_bytes);
        while (cursor.position() as usize) < block_bytes.len() {
            let key_len = cursor.read_u16::<LittleEndian>()? as usize;
            let val_len = cursor.read_u32::<LittleEndian>()? as usize;
            let is_tombstone = cursor.read_u8()? == 1;

            let pos = cursor.position() as usize;
            let key_slice = &block_bytes[pos..pos + key_len];
            cursor.set_position((pos + key_len) as u64);

            let val_pos = cursor.position() as usize;
            let val_slice = &block_bytes[val_pos..val_pos + val_len];
            cursor.set_position((val_pos + val_len) as u64);

            if key_slice == target_key {
                if is_tombstone {
                    return Ok(Some(ValueState::Tombstone));
                } else {
                    return Ok(Some(ValueState::Value(val_slice.to_vec())));
                }
            }
        }
        Ok(None)
    }
}
```

### Step 3 · Implement Sparse Block Index Serialization & Binary Search
Create `src/sstable/index.rs` implementing block anchor indexing:

```rust
use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use std::io::{self, Cursor};

/// A single index entry pointing to the start of a 4KB data block.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BlockIndexEntry {
    pub first_key: Vec<u8>,
    pub block_offset: u64,
    pub block_len: u64,
}

/// Sparse index containing first keys and offsets for all blocks in an SSTable.
#[derive(Debug, Clone, Default)]
pub struct SparseIndex {
    pub entries: Vec<BlockIndexEntry>,
}

impl SparseIndex {
    pub fn new() -> Self {
        Self { entries: Vec::new() }
    }

    pub fn add(&mut self, first_key: Vec<u8>, block_offset: u64, block_len: u64) {
        self.entries.push(BlockIndexEntry { first_key, block_offset, block_len });
    }

    /// Encodes the sparse index into binary bytes.
pub fn encode(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        buf.write_u32::<LittleEndian>(self.entries.len() as u32).unwrap();
        for e in &self.entries {
            buf.write_u16::<LittleEndian>(e.first_key.len() as u16).unwrap();
            buf.extend_from_slice(&e.first_key);
            buf.write_u64::<LittleEndian>(e.block_offset).unwrap();
            buf.write_u64::<LittleEndian>(e.block_len).unwrap();
        }
        buf
    }

    /// Decodes the sparse index from binary bytes.
pub fn decode(bytes: &[u8]) -> io::Result<Self> {
        let mut cursor = Cursor::new(bytes);
        let count = cursor.read_u32::<LittleEndian>()? as usize;
        let mut entries = Vec::with_capacity(count);

        for _ in 0..count {
            let k_len = cursor.read_u16::<LittleEndian>()? as usize;
            let mut key = vec![0u8; k_len];
            std::io::Read::read_exact(&mut cursor, &mut key)?;
            let block_offset = cursor.read_u64::<LittleEndian>()?;
            let block_len = cursor.read_u64::<LittleEndian>()?;
            entries.push(BlockIndexEntry { first_key: key, block_offset, block_len });
        }

        Ok(Self { entries })
    }

    /// Binary searches the sparse index to locate the candidate data block for a key.
pub fn search_candidate_block(&self, key: &[u8]) -> Option<&BlockIndexEntry> {
        if self.entries.is_empty() {
            return None;
        }
        // Binary search for the largest first_key <= target key
        match self.entries.binary_search_by(|entry| entry.first_key.as_slice().cmp(key)) {
            Ok(exact) => Some(&self.entries[exact]),
            Err(idx) => {
                if idx == 0 {
                    // Key is smaller than the first block's first key; could be in block 0
                    Some(&self.entries[0])
                } else {
                    Some(&self.entries[idx - 1])
                }
            }
        }
    }
}
```

### Step 4 · Implement Fixed 48-Byte Footer Encoding & Decoding
Create `src/sstable/footer.rs` encoding/decoding trailers:

```rust
use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use std::io::{self, Cursor};
use crate::sstable::format::{SstableFooter, FOOTER_SIZE_BYTES, SSTABLE_MAGIC};

impl SstableFooter {
    pub fn encode(&self) -> [u8; FOOTER_SIZE_BYTES] {
        let mut buf = [0u8; FOOTER_SIZE_BYTES];
        let mut cur = &mut buf[..];
        cur.write_u64::<LittleEndian>(self.index_offset).unwrap();
        cur.write_u64::<LittleEndian>(self.index_len).unwrap();
        cur.write_u64::<LittleEndian>(self.bloom_offset).unwrap();
        cur.write_u64::<LittleEndian>(self.bloom_len).unwrap();
        cur.write_u64::<LittleEndian>(self.magic).unwrap();
        cur.write_u64::<LittleEndian>(0).unwrap(); // Reserved padding
        buf
    }

    pub fn decode(bytes: &[u8]) -> io::Result<Self> {
        if bytes.len() != FOOTER_SIZE_BYTES {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "invalid footer length"));
        }
        let mut cur = Cursor::new(bytes);
        let index_offset = cur.read_u64::<LittleEndian>()?;
        let index_len = cur.read_u64::<LittleEndian>()?;
        let bloom_offset = cur.read_u64::<LittleEndian>()?;
        let bloom_len = cur.read_u64::<LittleEndian>()?;
        let magic = cur.read_u64::<LittleEndian>()?;

        if magic != SSTABLE_MAGIC {
            return Err(io::Error::new(io::ErrorKind::InvalidData, format!("SSTable magic mismatch: 0x{:016x}", magic)));
        }

        Ok(Self { index_offset, index_len, bloom_offset, bloom_len, magic })
    }
}
```

### Step 5 · Implement Streaming SSTableBuilder
Create `src/sstable/builder.rs` writing sorted MemTables to SSTables:

```rust
use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};
use crate::error::LsmError;
use crate::memtable::ValueState;
use crate::sstable::block::DataBlock;
use crate::sstable::format::{SstableFooter, DEFAULT_BLOCK_SIZE_BYTES};
use crate::sstable::index::SparseIndex;

pub struct SstableBuilder {
    path: PathBuf,
    writer: BufWriter<File>,
    index: SparseIndex,
    current_block: DataBlock,
    current_block_first_key: Option<Vec<u8>>,
    current_offset: u64,
    block_size_bytes: usize,
}

impl SstableBuilder {
    pub fn create<P: AsRef<Path>>(path: P) -> Result<Self, LsmError> {
        let path_buf = path.as_ref().to_path_buf();
        let file = OpenOptions::new().create(true).write(true).truncate(true).open(&path_buf)?;
        Ok(Self {
            path: path_buf,
            writer: BufWriter::with_capacity(64 * 1024, file),
            index: SparseIndex::new(),
            current_block: DataBlock::new(),
            current_block_first_key: None,
            current_offset: 0,
            block_size_bytes: DEFAULT_BLOCK_SIZE_BYTES,
        })
    }

    /// Appends a sorted key-value pair to the SSTable.
pub fn add(&mut self, key: &[u8], value: &ValueState) -> Result<(), LsmError> {
        if self.current_block_first_key.is_none() {
            self.current_block_first_key = Some(key.to_vec());
        }

        self.current_block.add_entry(key, value);

        if self.current_block.estimated_size() >= self.block_size_bytes {
            self.flush_current_block()?;
        }
        Ok(())
    }

    fn flush_current_block(&mut self) -> Result<(), LsmError> {
        if self.current_block.estimated_size() == 0 {
            return Ok(());
        }

        let block_bytes = self.current_block.as_bytes();
        let block_len = block_bytes.len() as u64;
        let first_key = self.current_block_first_key.take().unwrap();

        self.writer.write_all(block_bytes)?;
        self.index.add(first_key, self.current_offset, block_len);

        self.current_offset += block_len;
        self.current_block = DataBlock::new();
        Ok(())
    }

    /// Flushes final blocks, index, bloom dummy offset, footer, and fsyncs to disk.
pub fn finish(mut self) -> Result<PathBuf, LsmError> {
        self.flush_current_block()?;

        // Write Sparse Index
        let index_bytes = self.index.encode();
        let index_offset = self.current_offset;
        let index_len = index_bytes.len() as u64;
        self.writer.write_all(&index_bytes)?;
        self.current_offset += index_len;

        // Reserved Bloom Filter placeholder (to be wired in Phase 4)
        let bloom_offset = self.current_offset;
        let bloom_len = 0u64;

        // Write Footer (48 bytes)
        let footer = SstableFooter::new(index_offset, index_len, bloom_offset, bloom_len);
        self.writer.write_all(&footer.encode())?;

        self.writer.flush()?;
        self.writer.get_ref().sync_all()?;

        Ok(self.path)
    }
}
```

### Step 6 · Implement SSTableReader with Fast Sparse Lookups
Create `src/sstable/reader.rs` querying keys from disk via sparse index:

```rust
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::{Path, PathBuf};
use crate::error::LsmError;
use crate::memtable::ValueState;
use crate::sstable::block::DataBlock;
use crate::sstable::footer::SstableFooter;
use crate::sstable::format::FOOTER_SIZE_BYTES;
use crate::sstable::index::SparseIndex;

pub struct SstableReader {
    path: PathBuf,
    file: File,
    index: SparseIndex,
    footer: SstableFooter,
}

impl SstableReader {
    /// Opens an existing SSTable file, reads footer, and loads sparse index into RAM.
pub fn open<P: AsRef<Path>>(path: P) -> Result<Self, LsmError> {
        let path_buf = path.as_ref().to_path_buf();
        let mut file = File::open(&path_buf)?;
        let file_len = file.metadata()?.len();

        if file_len < FOOTER_SIZE_BYTES as u64 {
            return Err(LsmError::Io(std::io::Error::new(
                std::io::ErrorKind::UnexpectedEof,
                "file smaller than SSTable footer",
            )));
        }

        // 1. Read 48-byte Footer from tail
        file.seek(SeekFrom::Start(file_len - FOOTER_SIZE_BYTES as u64))?;
        let mut footer_buf = [0u8; FOOTER_SIZE_BYTES];
        file.read_exact(&mut footer_buf)?;
        let footer = SstableFooter::decode(&footer_buf)?;

        // 2. Read Sparse Index into memory
        file.seek(SeekFrom::Start(footer.index_offset))?;
        let mut index_buf = vec![0u8; footer.index_len as usize];
        file.read_exact(&mut index_buf)?;
        let index = SparseIndex::decode(&index_buf)?;

        Ok(Self { path: path_buf, file, index, footer })
    }

    /// Queries a key by binary searching the sparse index and reading exactly one 4KB data block.
pub fn get(&mut self, key: &[u8]) -> Result<Option<ValueState>, LsmError> {
        let entry = match self.index.search_candidate_block(key) {
            Some(e) => e.clone(),
            None => return Ok(None),
        };

        // Read candidate 4KB block from disk
        self.file.seek(SeekFrom::Start(entry.block_offset))?;
        let mut block_buf = vec![0u8; entry.block_len as usize];
        self.file.read_exact(&mut block_buf)?;

        let result = DataBlock::find_key(&block_buf, key)?;
        Ok(result)
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}
```

