## 🛠 Step-by-Step Implementation

### Step 1 · Implement 64-Bit Hash Utility
Create `src/bloom/hash.rs` providing fast 64-bit hashing using Fowler-Noll-Vo (FNV-1a) and CRC32:

```rust
/// Computes two independent 64-bit hashes for Kirsch-Mitzenmacher double-hashing.
pub fn hash_pair(data: &[u8]) -> (u64, u64) {
    // Hash 1: FNV-1a 64-bit
    let mut h1: u64 = 0xcbf29ce484222325;
    for &b in data {
        h1 ^= b as u64;
        h1 = h1.wrapping_mul(0x100000001b3);
    }

    // Hash 2: CRC32 with bit mixing
    let crc = crc32fast::hash(data) as u64;
    let h2 = (crc << 32) | (crc ^ h1);

    (h1, if h2 == 0 { 1 } else { h2 })
}
```

### Step 2 · Implement Bloom Filter with Mathematical Sizing
Create `src/bloom/filter.rs` implementing the bit array and probe generation:

```rust
use crate::bloom::hash::hash_pair;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BloomFilter {
    bits: Vec<u8>,
    num_bits: usize,
    num_probes: usize, // k
}

impl BloomFilter {
    /// Creates a Bloom filter sized for `num_keys` with the target `false_positive_rate`.
pub fn new(num_keys: usize, false_positive_rate: f64) -> Self {
        let n = num_keys.max(1) as f64;
        let p = false_positive_rate.clamp(0.0001, 0.5);

        // m = -n * ln(p) / (ln(2)^2)
        let ln2 = std::f64::consts::LN_2;
        let m = ((-n * p.ln()) / (ln2 * ln2)).ceil() as usize;
        let num_bits = m.max(64);

        // k = (m / n) * ln(2)
        let k = ((num_bits as f64 / n) * ln2).round() as usize;
        let num_probes = k.clamp(1, 30);

        let num_bytes = (num_bits + 7) / 8;
        Self {
            bits: vec![0u8; num_bytes],
            num_bits,
            num_probes,
        }
    }

    /// Inserts a key into the Bloom filter.
pub fn insert(&mut self, key: &[u8]) {
        let (h1, h2) = hash_pair(key);
        for i in 0..self.num_probes {
            let bit_idx = (h1.wrapping_add((i as u64).wrapping_mul(h2)) % (self.num_bits as u64)) as usize;
            self.bits[bit_idx / 8] |= 1 << (bit_idx % 8);
        }
    }

    /// Tests if a key might be in the set (guarantees zero false negatives).
pub fn contains(&self, key: &[u8]) -> bool {
        if self.bits.is_empty() || self.num_bits == 0 {
            return false;
        }
        let (h1, h2) = hash_pair(key);
        for i in 0..self.num_probes {
            let bit_idx = (h1.wrapping_add((i as u64).wrapping_mul(h2)) % (self.num_bits as u64)) as usize;
            if (self.bits[bit_idx / 8] & (1 << (bit_idx % 8))) == 0 {
                return false; // Definitely absent! (Zero false negatives)
            }
        }
        true // Probably present
    }

    pub fn as_bytes(&self) -> &[u8] {
        &self.bits
    }

    pub fn num_bits(&self) -> usize {
        self.num_bits
    }

    pub fn num_probes(&self) -> usize {
        self.num_probes
    }
}
```

