```rust
use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use std::io::{self, Cursor};
use crate::bloom::filter::BloomFilter;

impl BloomFilter {
    pub fn encode(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(8 + 4 + self.bits.len());
        buf.write_u64::<LittleEndian>(self.num_bits as u64).unwrap();
        buf.write_u32::<LittleEndian>(self.num_probes as u32).unwrap();
        buf.extend_from_slice(&self.bits);
        buf
    }

    pub fn decode(bytes: &[u8]) -> io::Result<Self> {
        if bytes.len() < 12 {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "bloom filter buffer too short"));
        }
        let mut cur = Cursor::new(bytes);
        let num_bits = cur.read_u64::<LittleEndian>()? as usize;
        let num_probes = cur.read_u32::<LittleEndian>()? as usize;
        let bits = bytes[12..].to_vec();

        Ok(Self {
            bits,
            num_bits,
            num_probes,
        })
    }
}
```

