### Step 7 · Implement Unified Layered Read Path Engine
Create `src/sstable/layered_read.rs` coordinating MemTables and SSTables:

```rust
use crate::error::LsmError;
use crate::memtable::manager::MemTableManager;
use crate::sstable::reader::SstableReader;

/// Coordinates the multi-layered read path from newest to oldest storage.
pub fn layered_get(
    mem: &MemTableManager,
    tables: &mut [SstableReader], // Sorted newest first!
    key: &[u8],
) -> Result<Option<Vec<u8>>, LsmError> {
    // 1. Check Active & Frozen MemTable (RAM)
    if let Some(state) = mem.get(key) {
        return Ok(state.as_bytes().map(|b| b.to_vec()));
    }

    // 2. Check SSTables (Newest to Oldest)
    for table in tables.iter_mut() {
        if let Some(state) = table.get(key)? {
            // Hit encountered! Either live value or tombstone
            return Ok(state.as_bytes().map(|b| b.to_vec()));
        }
    }

    // Not found anywhere
    Ok(None)
}
```

