    let mut false_positives = 0;
    for i in 10_000..20_000 {
        let k = format!("other_{:06}", i).into_bytes();
        if filter.contains(&k) {
            false_positives += 1;
        }
    }

    let rate = false_positives as f64 / 10_000.0;
    assert!(rate <= 0.02, "observed false positive rate {:.4} exceeded tolerance!", rate);
