fn test_layered_read_path_shadows_and_tombstones() {
    let dir = tempdir().unwrap();
    let sst_path = dir.path().join("older.sst");

    // 1. Create on-disk SSTable with an old version of 'key_x' and 'key_y'
    let mut builder = SstableBuilder::create_with_bloom(&sst_path, 10).unwrap();
    builder.add(b"key_x", &ValueState::Value(b"old_val_x".to_vec())).unwrap();
    builder.add(b"key_y", &ValueState::Value(b"val_y".to_vec())).unwrap();
    builder.finish().unwrap();

    let mut reader = SstableReader::open(&sst_path).unwrap();
    let mut tables = vec![reader];

    let mem = MemTableManager::new(1024 * 1024);
    // 2. Update 'key_x' in MemTable with new value
    mem.put(b"key_x".to_vec(), b"new_val_x".to_vec());

    // Read 'key_x' -> must return new value from MemTable!
    let val_x = layered_get(&mem, &mut tables, b"key_x").unwrap();
    assert_eq!(val_x, Some(b"new_val_x".to_vec()));

    // Read 'key_y' -> absent from MemTable, must be read from SSTable
    let val_y = layered_get(&mem, &mut tables, b"key_y").unwrap();
    assert_eq!(val_y, Some(b"val_y".to_vec()));

