    mem.delete(b"key_y".to_vec());

    // Read 'key_y' -> must return None (tombstone shadows older disk SSTable!)
    let val_y_del = layered_get(&mem, &mut tables, b"key_y").unwrap();
    assert_eq!(val_y_del, None);
