### Step 1 · Implement Sequential SSTable Stream Iterator
Create `src/sstable/stream.rs` streaming sorted entries from an SSTable on disk:

```rust
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::Path;
use byteorder::{LittleEndian, ReadBytesExt};
use crate::error::LsmError;
use crate::memtable::ValueState;
use crate::sstable::footer::SstableFooter;
use crate::sstable::format::FOOTER_SIZE_BYTES;

/// A streaming sequential iterator over all key-value entries in an SSTable.
pub struct SstableStreamIterator {
    file: File,
    data_end_offset: u64,
    current_offset: u64,
}

impl SstableStreamIterator {
    pub fn open<P: AsRef<Path>>(path: P) -> Result<Self, LsmError> {
        let mut file = File::open(path)?;
        let file_len = file.metadata()?.len();
        if file_len < FOOTER_SIZE_BYTES as u64 {
            return Err(LsmError::WalTruncated { offset: 0 });
        }

        // Read footer to find where data blocks end (index_offset)
        file.seek(SeekFrom::Start(file_len - FOOTER_SIZE_BYTES as u64))?;
        let mut footer_buf = [0u8; FOOTER_SIZE_BYTES];
        file.read_exact(&mut footer_buf)?;
        let footer = SstableFooter::decode(&footer_buf)?;

        // Rewind to beginning of data blocks
        file.seek(SeekFrom::Start(0))?;

        Ok(Self {
            file,
            data_end_offset: footer.index_offset,
            current_offset: 0,
        })
    }

    /// Reads the next entry. Returns Ok(None) when data block boundary is reached.
pub fn next_entry(&mut self) -> Result<Option<(Vec<u8>, ValueState)>, LsmError> {
        if self.current_offset >= self.data_end_offset {
            return Ok(None);
        }

        let key_len = match self.file.read_u16::<LittleEndian>() {
            Ok(len) => len as usize,
            Err(ref e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Ok(None),
            Err(e) => return Err(LsmError::Io(e)),
        };
        let val_len = self.file.read_u32::<LittleEndian>()? as usize;
        let is_tombstone = self.file.read_u8()? == 1;

        let mut key = vec![0u8; key_len];
        self.file.read_exact(&mut key)?;

        let mut val = vec![0u8; val_len];
        self.file.read_exact(&mut val)?;

        self.current_offset += 2 + 4 + 1 + key_len as u64 + val_len as u64;

        let state = if is_tombstone {
            ValueState::Tombstone
        } else {
            ValueState::Value(val)
        };

        Ok(Some((key, state)))
    }
}
```

### Step 2 · Implement Min-Heap Comparator with Chronological Age Priority
Create `src/compaction/heap_item.rs` ordering heap candidates:

```rust
use std::cmp::Ordering;
use crate::memtable::ValueState;

/// Wrapper for heap items ordered primarily by key (ascending), then file age (ascending).
#[derive(Debug, Eq, PartialEq)]
pub struct HeapItem {
    pub key: Vec<u8>,
    pub value: ValueState,
    pub file_age: usize, // 0 = newest file, higher numbers = older files
    pub source_idx: usize,
}

impl Ord for HeapItem {
    fn cmp(&self, other: &Self) -> Ordering {
        // Invert ordering because Rust BinaryHeap is a MAX-HEAP by default.
        // We want the SMALLEST key to pop first (Min-Heap behavior).
        match other.key.cmp(&self.key) {
            Ordering::Equal => other.file_age.cmp(&self.file_age),
            ord => ord,
        }
    }
}

impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
```

### Step 3 · Implement Streaming K-Way Merge Iterator
Create `src/compaction/kway_merge.rs` merging multiple iterators:

```rust
use std::collections::BinaryHeap;
use crate::compaction::heap_item::HeapItem;
use crate::error::LsmError;
use crate::memtable::ValueState;
use crate::sstable::stream::SstableStreamIterator;

pub struct KWayMergeIterator {
    sources: Vec<SstableStreamIterator>,
    heap: BinaryHeap<HeapItem>,
    is_bottom_level: bool,
}

impl KWayMergeIterator {
    pub fn new(mut sources: Vec<SstableStreamIterator>, is_bottom_level: bool) -> Result<Self, LsmError> {
        let mut heap = BinaryHeap::with_capacity(sources.len());

        // Seed heap with first entry from each source (source 0 is newest)
        for (idx, src) in sources.iter_mut().enumerate() {
            if let Some((k, v)) = src.next_entry()? {
                heap.push(HeapItem {
                    key: k,
                    value: v,
                    file_age: idx,
                    source_idx: idx,
                });
            }
        }

        Ok(Self { sources, heap, is_bottom_level })
    }

    /// Returns the next deduplicated, globally smallest key-value pair.
pub fn next_merged(&mut self) -> Result<Option<(Vec<u8>, ValueState)>, LsmError> {
        while let Some(top) = self.heap.pop() {
            let target_key = top.key;
            let winning_val = top.value;

            // Refill the iterator that produced `top`
            if let Some((k, v)) = self.sources[top.source_idx].next_entry()? {
                self.heap.push(HeapItem {
                    key: k,
                    value: v,
                    file_age: top.source_idx,
                    source_idx: top.source_idx,
                });
            }

            // Drain all superseded duplicates of `target_key` from older files
            while let Some(peek_item) = self.heap.peek() {
                if peek_item.key == target_key {
                    let dup = self.heap.pop().unwrap();
                    // Refill source
                    if let Some((k, v)) = self.sources[dup.source_idx].next_entry()? {
                        self.heap.push(HeapItem {
                            key: k,
                            value: v,
                            file_age: dup.source_idx,
                            source_idx: dup.source_idx,
                        });
                    }
                } else {
                    break;
                }
            }

            // Bottom-level tombstone purging check
            if winning_val.is_tombstone() && self.is_bottom_level {
                // Purge tombstone! Do not output to compacted file
                continue;
            }

            return Ok(Some((target_key, winning_val)));
        }

        Ok(None)
    }
}
