### Step 4 · Implement SSTable Compactor Execution Pipeline
Create `src/compaction/compactor.rs` orchestrating merge and file emission:

```rust
use std::fs;
use std::path::{Path, PathBuf};
use crate::compaction::kway_merge::KWayMergeIterator;
use crate::error::LsmError;
use crate::sstable::builder::SstableBuilder;
use crate::sstable::stream::SstableStreamIterator;

pub struct Compactor;

impl Compactor {
    /// Compacts a list of SSTables (ordered newest first) into a single new SSTable.
pub fn compact_files<P: AsRef<Path>>(
        input_paths: &[P],
        output_path: P,
        is_bottom_level: bool,
    ) -> Result<PathBuf, LsmError> {
        let mut streams = Vec::with_capacity(input_paths.len());
        for p in input_paths {
            streams.push(SstableStreamIterator::open(p)?);
        }

        let mut merge_iter = KWayMergeIterator::new(streams, is_bottom_level)?;
        let mut builder = SstableBuilder::create_with_bloom(output_path.as_ref(), 100_000)?;

        let mut entry_count = 0;
        while let Some((key, val)) = merge_iter.next_merged()? {
            builder.add(&key, &val)?;
            entry_count += 1;
        }

        let finished_path = builder.finish()?;

        // Atomically delete old input SSTables
        for p in input_paths {
            let _ = fs::remove_file(p);
        }

        Ok(finished_path)
    }
}
```

