    let sst1_path = dir.path().join("table_newest.sst");
    let sst2_path = dir.path().join("table_older.sst");
    let compacted_path = dir.path().join("table_compacted.sst");

    // 1. Table 2 (Older): key1=v1_old, key2=v2, key3=v3_old
    let mut b2 = SstableBuilder::create_with_bloom(&sst2_path, 10).unwrap();
    b2.add(b"key1", &ValueState::Value(b"v1_old".to_vec())).unwrap();
    b2.add(b"key2", &ValueState::Value(b"v2".to_vec())).unwrap();
    b2.add(b"key3", &ValueState::Value(b"v3_old".to_vec())).unwrap();
    b2.finish().unwrap();

    // 2. Table 1 (Newer): key1=v1_new, key3=TOMBSTONE
    let mut b1 = SstableBuilder::create_with_bloom(&sst1_path, 10).unwrap();
    b1.add(b"key1", &ValueState::Value(b"v1_new".to_vec())).unwrap();
    b1.add(b"key3", &ValueState::Tombstone).unwrap();
    b1.finish().unwrap();

    // 3. Compact with is_bottom_level = false (keep tombstones)
    Compactor::compact_files(&[&sst1_path, &sst2_path], &compacted_path, false).unwrap();

    let mut reader = SstableReader::open(&compacted_path).unwrap();

    // key1 must have newest value
    let k1 = reader.get(b"key1").unwrap().unwrap();
    assert_eq!(k1.as_bytes(), Some(&b"v1_new"[..]));

    // key2 must be preserved
    let k2 = reader.get(b"key2").unwrap().unwrap();
    assert_eq!(k2.as_bytes(), Some(&b"v2"[..]));

    // key3 must be a tombstone
    let k3 = reader.get(b"key3").unwrap().unwrap();
    assert!(k3.is_tombstone());
}

