### Step 2 · Implement Monotonic File Sequence Registry
Create `src/manifest.rs` tracking SSTable and WAL sequence IDs:

```rust
use std::fs;
use std::path::Path;
use crate::error::LsmError;

pub struct FileRegistry {
    next_seq: u64,
}

impl FileRegistry {
    /// Scans a directory to discover the highest existing sequence number.
pub fn scan<P: AsRef<Path>>(dir: P) -> Result<Self, LsmError> {
        let mut max_seq = 0u64;
        if dir.as_ref().exists() {
            for entry in fs::read_dir(dir)? {
                let entry = entry?;
                let fname = entry.file_name();
                let name = fname.to_string_lossy();
                if let Some(stem) = name.strip_suffix(".sst").or_else(|| name.strip_suffix(".wal")) {
                    if let Ok(num) = stem.parse::<u64>() {
                        if num > max_seq {
                            max_seq = num;
                        }
                    }
                }
            }
        }
        Ok(Self { next_seq: max_seq + 1 })
    }

    pub fn next_sstable_name<P: AsRef<Path>>(&mut self, dir: P) -> std::path::PathBuf {
        let fname = format!("{:06}.sst", self.next_seq);
        self.next_seq += 1;
        dir.as_ref().join(fname)
    }

    pub fn next_wal_name<P: AsRef<Path>>(&mut self, dir: P) -> std::path::PathBuf {
        let fname = format!("{:06}.wal", self.next_seq);
        self.next_seq += 1;
        dir.as_ref().join(fname)
    }
}
```

### Step 3 · Implement Database Engine Core
Create `src/db/inner.rs` orchestrating WAL, MemTable, and SSTables:

```rust
use std::fs;
use std::path::PathBuf;
use std::sync::Arc;
use parking_lot::{Mutex, RwLock};
use crate::config::DbOptions;
use crate::error::LsmError;
use crate::memtable::{MemTableManager, ValueState};
use crate::sstable::builder::SstableBuilder;
use crate::sstable::layered_read::layered_get;
use crate::sstable::reader::SstableReader;
use crate::wal::{WalOpType, WalReader, WalWriter};
use crate::manifest::FileRegistry;

pub struct EngineInner {
    options: DbOptions,
    mem: MemTableManager,
    wal: Mutex<WalWriter>,
    sstables: RwLock<Vec<SstableReader>>,
    registry: Mutex<FileRegistry>,
}

impl EngineInner {
    pub fn open(options: DbOptions) -> Result<Arc<Self>, LsmError> {
        fs::create_dir_all(&options.dir)?;

        let mut registry = FileRegistry::scan(&options.dir)?;

        // 1. Discover and load existing SSTables (sorted newest first)
        let mut sst_paths = Vec::new();
        for entry in fs::read_dir(&options.dir)? {
            let entry = entry?;
            let p = entry.path();
            if p.extension().map_or(false, |ext| ext == "sst") {
                sst_paths.push(p);
            }
        }
        sst_paths.sort_by(|a, b| b.cmp(a)); // Descending order (newest first)

        let mut sstables = Vec::with_capacity(sst_paths.len());
        for path in sst_paths {
            sstables.push(SstableReader::open(path)?);
        }

        // 2. Discover and replay latest WAL if present
        let mem = MemTableManager::new(options.memtable_capacity_bytes);
        let mut wal_paths = Vec::new();
        for entry in fs::read_dir(&options.dir)? {
            let entry = entry?;
            let p = entry.path();
            if p.extension().map_or(false, |ext| ext == "wal") {
                wal_paths.push(p);
            }
        }
        wal_paths.sort();

        if let Some(latest_wal) = wal_paths.last() {
            let mut reader = WalReader::open(latest_wal)?;
            let (entries, _err) = reader.recover_all();
            for entry in entries {
                match entry.op {
                    WalOpType::Put => {
                        if let Some(v) = entry.value {
                            mem.put(entry.key, v);
                        }
                    }
                    WalOpType::Delete => {
                        mem.delete(entry.key);
                    }
                }
            }
        }

        // 3. Allocate fresh WAL for upcoming writes
        let new_wal_path = registry.next_wal_name(&options.dir);
        let wal = WalWriter::open(new_wal_path, options.sync_policy)?;

        Ok(Arc::new(Self {
            options,
            mem,
            wal: Mutex::new(wal),
            sstables: RwLock::new(sstables),
            registry: Mutex::new(registry),
        }))
    }

    pub fn put(&self, key: &[u8], value: &[u8]) -> Result<(), LsmError> {
        let mut wal = self.wal.lock();
        wal.append_put(key, value)?;
        drop(wal);

        if self.mem.put(key.to_vec(), value.to_vec()) {
            self.flush_memtable()?;
        }
        Ok(())
    }

    pub fn delete(&self, key: &[u8]) -> Result<(), LsmError> {
        let mut wal = self.wal.lock();
        wal.append_delete(key)?;
        drop(wal);

        if self.mem.delete(key.to_vec()) {
            self.flush_memtable()?;
        }
        Ok(())
    }

    pub fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>, LsmError> {
        let mut sstables = self.sstables.write();
        layered_get(&self.mem, &mut sstables, key)
    }

    pub fn flush_memtable(&self) -> Result<(), LsmError> {
        if let Some(frozen) = self.mem.freeze_active() {
            let mut reg = self.registry.lock();
            let sst_path = reg.next_sstable_name(&self.options.dir);
            drop(reg);

            let mut builder = SstableBuilder::create_with_bloom(&sst_path, frozen.len())?;
            for (k, v) in frozen.iter() {
                builder.add(k, v)?;
            }
            builder.finish()?;

            let new_reader = SstableReader::open(&sst_path)?;
            let mut sst_guard = self.sstables.write();
            sst_guard.insert(0, new_reader); // Insert at index 0 (newest)

            self.mem.clear_frozen();
        }
        Ok(())
    }
}
```

