pub mod inner;

use std::path::Path;
use std::sync::Arc;
use crate::config::DbOptions;
use crate::error::LsmError;
use inner::EngineInner;

/// Primary thread-safe database handle for the LSM-Tree storage engine.
#[derive(Clone)]
pub struct LsmDb {
    inner: Arc<EngineInner>,
}

impl LsmDb {
    /// Opens or creates an LSM database inside the specified directory.
pub fn open<P: AsRef<Path>>(dir: P) -> Result<Self, LsmError> {
        let options = DbOptions::new(dir);
        let inner = EngineInner::open(options)?;
        Ok(Self { inner })
    }

    /// Opens the database with customized options.
pub fn open_with_options(options: DbOptions) -> Result<Self, LsmError> {
        let inner = EngineInner::open(options)?;
        Ok(Self { inner })
    }

    /// Stores a key-value pair durably.
pub fn put(&self, key: &[u8], value: &[u8]) -> Result<(), LsmError> {
        self.inner.put(key, value)
    }

    /// Retrieves the value associated with a key.
pub fn get(&self, key: &[u8]) -> Result<Option<Vec<u8>>, LsmError> {
        self.inner.get(key)
    }

    /// Deletes a key by appending a tombstone.
pub fn delete(&self, key: &[u8]) -> Result<(), LsmError> {
        self.inner.delete(key)
    }

    /// Explicitly flushes the in-memory MemTable to an on-disk SSTable.
pub fn flush(&self) -> Result<(), LsmError> {
        self.inner.flush_memtable()
    }
}
