    let ack_file = PathBuf::from(args.get(2).expect("missing ack file"));

    let db = LsmDb::open(&db_dir)?;
    let file = File::open(&ack_file)?;
    let reader = BufReader::new(file);

    let mut verified = 0u64;
    for line in reader.lines() {
        let line = line?;
        let id: u64 = line.trim().parse()?;
        let key = format!("user:{:08}", id);
        let expected_val = format!("payload_{:08}", id);

        match db.get(key.as_bytes())? {
            Some(val) => {
                assert_eq!(val, expected_val.as_bytes(), "corrupted value for key {}", key);
                verified += 1;
            }
            None => {
                panic!("FATAL: Acknowledged key {} was LOST after crash!", key);
            }
        }
    }

    println!("✅ Verification successful! All {} acknowledged writes intact.", verified);
    Ok(())
}
