```sql
-- Create state machine enum type
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'job_state') THEN
        CREATE TYPE job_state AS ENUM ('queued', 'running', 'done', 'failed', 'cancelled');
    END IF;
END $$;

-- Create durable jobs queue table
CREATE TABLE IF NOT EXISTS job (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    queue TEXT NOT NULL DEFAULT 'default',
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    state job_state NOT NULL DEFAULT 'queued',
    attempts INT NOT NULL DEFAULT 0,
    max_attempts INT NOT NULL DEFAULT 5,
    run_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    locked_until TIMESTAMPTZ,
    locked_by TEXT,
    last_error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

-- Partial B-Tree Index: indexes ONLY runnable queued tasks!
CREATE INDEX IF NOT EXISTS idx_job_runnable 
ON job (queue, run_at, id) 
WHERE state = 'queued';

-- Secondary index for monitoring dead-letter failed jobs
CREATE INDEX IF NOT EXISTS idx_job_failed 
ON job (queue, created_at) 
WHERE state = 'failed';
