### Step 2 · Implement Core Single Enqueue Function (`src/producer/enqueue.ts`)
Create `src/producer/enqueue.ts` handling both pool and transactional client instances:

```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';
import type { EnqueueOptions, Job } from '../types/job.js';

export type Queryable = pg.Pool | pg.PoolClient;

export async function enqueueJob<T = Record<string, unknown>>(
  client: Queryable = pool,
  queueName: string,
  payload: T,
  options: EnqueueOptions = {}
): Promise<Job<T>> {
  const delaySeconds = options.delaySeconds ?? 0;
  const maxAttempts = options.maxAttempts ?? 5;
  const runAt = options.runAt;

  let queryText: string;
  let queryParams: any[];

  if (runAt) {
    queryText = `
      INSERT INTO job (queue, payload, run_at, max_attempts, state)
      VALUES ($1, $2, $3, $4, 'queued')
      RETURNING *;
    `;
    queryParams = [queueName, JSON.stringify(payload), runAt, maxAttempts];
  } else {
    queryText = `
      INSERT INTO job (queue, payload, run_at, max_attempts, state)
      VALUES ($1, $2, clock_timestamp() + make_interval(secs => $3), $4, 'queued')
      RETURNING *;
    `;
    queryParams = [queueName, JSON.stringify(payload), delaySeconds, maxAttempts];
  }

  const res = await client.query(queryText, queryParams);
  const row = res.rows[0];
  return {
    ...row,
    id: row.id.toString(),
  };
}
```

### Step 3 · Implement Deduplicated Idempotent Enqueueing (`src/producer/dedup.ts`)
Create `src/producer/dedup.ts` supporting unique job tokens:

```typescript
import type { Queryable } from './enqueue.js';
import { pool } from '../db/pool.js';
import type { EnqueueOptions, Job } from '../types/job.js';

export async function enqueueIdempotent<T = Record<string, unknown>>(
  client: Queryable = pool,
  queueName: string,
  payload: T,
  dedupKey: string,
  options: EnqueueOptions = {}
): Promise<Job<T> | null> {
  const delaySeconds = options.delaySeconds ?? 0;
  const maxAttempts = options.maxAttempts ?? 5;

  const queryText = `
    INSERT INTO job (queue, payload, run_at, max_attempts, dedup_key, state)
    VALUES ($1, $2, clock_timestamp() + make_interval(secs => $3), $4, $5, 'queued')
    ON CONFLICT (queue, dedup_key) WHERE state IN ('queued', 'running')
    DO NOTHING
    RETURNING *;
  `;
  const queryParams = [queueName, JSON.stringify(payload), delaySeconds, maxAttempts, dedupKey];

  const res = await client.query(queryText, queryParams);
  if (res.rowCount === 0) {
    return null; // Duplicate active job already exists!
  }

  const row = res.rows[0];
  return {
    ...row,
    id: row.id.toString(),
  };
}
```

### Step 4 · Implement High-Speed Batch Enqueue with `UNNEST` (`src/producer/batch.ts`)
Create `src/producer/batch.ts` inserting thousands of tasks in a single query:

```typescript
import type { Queryable } from './enqueue.js';
import { pool } from '../db/pool.js';
import type { Job } from '../types/job.js';

export interface BatchJobItem<T = Record<string, unknown>> {
  payload: T;
  delaySeconds?: number;
  maxAttempts?: number;
}

export async function enqueueBatch<T = Record<string, unknown>>(
  client: Queryable = pool,
  queueName: string,
  items: BatchJobItem<T>[]
): Promise<Job<T>[]> {
  if (items.length === 0) return [];

  const payloads = items.map((i) => JSON.stringify(i.payload));
  const delays = items.map((i) => i.delaySeconds ?? 0);
  const maxAttemptsList = items.map((i) => i.maxAttempts ?? 5);

  const queryText = `
    INSERT INTO job (queue, payload, run_at, max_attempts, state)
    SELECT 
      $1,
      p,
      clock_timestamp() + make_interval(secs => d),
      m,
      'queued'
    FROM UNNEST(
      $2::jsonb[],
      $3::int[],
      $4::int[]
    ) AS t(p, d, m)
    RETURNING *;
  `;

  const res = await client.query(queryText, [queueName, payloads, delays, maxAttemptsList]);
  return res.rows.map((row) => ({
    ...row,
    id: row.id.toString(),
  }));
}
```

### Step 5 · Implement Transaction Helper Engine (`src/db/transaction.ts`)
Create `src/db/transaction.ts` providing managed transaction scoping:

```typescript
import type pg from 'pg';
import { pool } from './pool.js';

export async function withTransaction<T>(
  callback: (client: pg.PoolClient) => Promise<T>
): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
```

### Step 6 · Create Unified `QueueProducer` Interface (`src/producer/index.ts`)
Create `src/producer/index.ts` packaging all producer methods:

```typescript
import type { Queryable } from './enqueue.js';
import { enqueueJob } from './enqueue.js';
import { enqueueIdempotent } from './dedup.js';
import { enqueueBatch, BatchJobItem } from './batch.js';
import type { EnqueueOptions, Job } from '../types/job.js';

export class QueueProducer {
  constructor(private client?: Queryable) {}

  async enqueue<T = Record<string, unknown>>(
    queue: string,
    payload: T,
    options?: EnqueueOptions
  ): Promise<Job<T>> {
    return enqueueJob(this.client, queue, payload, options);
  }

  async enqueueIdempotent<T = Record<string, unknown>>(
    queue: string,
    payload: T,
    dedupKey: string,
    options?: EnqueueOptions
  ): Promise<Job<T> | null> {
    return enqueueIdempotent(this.client, queue, payload, dedupKey, options);
  }

  async enqueueBatch<T = Record<string, unknown>>(
    queue: string,
    items: BatchJobItem<T>[]
  ): Promise<Job<T>[]> {
    return enqueueBatch(this.client, queue, items);
  }
}
