## 🛠 Step-by-Step Implementation

### Step 1 · Implement Atomic Claim Query Function (`src/consumer/claim.ts`)
Create `src/consumer/claim.ts` claiming jobs atomically using `FOR UPDATE SKIP LOCKED`:

```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';
import type { Job } from '../types/job.js';

export interface ClaimOptions {
  batchSize?: number;
  leaseSeconds?: number;
  workerId?: string;
}

export async function claimJobs<T = Record<string, unknown>>(
  client: pg.Pool | pg.PoolClient = pool,
  queueName: string,
  options: ClaimOptions = {}
): Promise<Job<T>[]> {
  const batchSize = options.batchSize ?? 1;
  const leaseSeconds = options.leaseSeconds ?? 60;
  const workerId = options.workerId ?? `worker-${process.pid}-${Math.random().toString(36).slice(2, 7)}`;

  const queryText = `
    WITH claimable AS (
      SELECT id
      FROM job
      WHERE queue = $1 AND state = 'queued' AND run_at <= clock_timestamp()
      ORDER BY run_at ASC, id ASC
      FOR UPDATE SKIP LOCKED
      LIMIT $2
    )
    UPDATE job j
    SET 
      state = 'running',
      attempts = j.attempts + 1,
      locked_until = clock_timestamp() + make_interval(secs => $3),
      locked_by = $4,
      updated_at = clock_timestamp()
    FROM claimable
    WHERE j.id = claimable.id
    RETURNING j.*;
  `;

  const res = await client.query(queryText, [queueName, batchSize, leaseSeconds, workerId]);
  return res.rows.map((row) => ({
    ...row,
    id: row.id.toString(),
  }));
}
```

