### Step 4 · Implement Graceful Shutdown Coordinator (`src/consumer/shutdown.ts`)
Create `src/consumer/shutdown.ts` managing OS process signals (`SIGINT`, `SIGTERM`):

```typescript
export class ShutdownCoordinator {
  private isShuttingDown = false;
  private activeJobsCount = 0;
  private drainResolvers: (() => void)[] = [];

  constructor() {
    const onSignal = () => {
      console.log('\nReceived shutdown signal. Draining active workers...');
      this.initiateShutdown();
    };
    process.on('SIGINT', onSignal);
    process.on('SIGTERM', onSignal);
  }

  public initiateShutdown() {
    this.isShuttingDown = true;
    this.checkDrain();
  }

  public get shuttingDown(): boolean {
    return this.isShuttingDown;
  }

  public trackJobStart() {
    this.activeJobsCount += 1;
  }

  public trackJobEnd() {
    this.activeJobsCount -= 1;
    this.checkDrain();
  }

  public waitForDrain(): Promise<void> {
    if (this.activeJobsCount === 0) {
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      this.drainResolvers.push(resolve);
    });
  }

  private checkDrain() {
    if (this.isShuttingDown && this.activeJobsCount === 0) {
      for (const resolve of this.drainResolvers) {
        resolve();
      }
      this.drainResolvers = [];
    }
  }
}
```

### Step 5 · Implement Worker Execution Loop with Semaphore (`src/consumer/worker.ts`)
Create `src/consumer/worker.ts` executing concurrent worker loops:

```typescript
import { pool } from '../db/pool.js';
import { claimJobs } from './claim.js';
import { markJobDone } from './complete.js';
import type { JobHandler, WorkerConfig } from './handler.js';
import { ShutdownCoordinator } from './shutdown.js';

export class WorkerRunner<T = any> {
  private shutdown = new ShutdownCoordinator();
  private running = false;
  private activeExecutions = 0;

  constructor(
    private config: WorkerConfig,
    private handler: JobHandler<T>
  ) {}

  public async start(): Promise<void> {
    this.running = true;
    const concurrency = this.config.concurrency ?? 5;
    const pollIntervalMs = this.config.pollIntervalMs ?? 500;

    console.log(`Starting worker [${this.config.queue}] with concurrency = ${concurrency}`);

    while (this.running && !this.shutdown.shuttingDown) {
      const availableSlots = concurrency - this.activeExecutions;
      if (availableSlots <= 0) {
        await new Promise((res) => setTimeout(res, 50));
        continue;
      }

      try {
        const jobs = await claimJobs<T>(pool, this.config.queue, {
          batchSize: availableSlots,
          leaseSeconds: this.config.leaseSeconds ?? 60,
          workerId: this.config.workerId,
        });

        if (jobs.length === 0) {
          // No runnable jobs currently available; back off poll interval
          await new Promise((res) => setTimeout(res, pollIntervalMs));
          continue;
        }

        for (const job of jobs) {
          this.activeExecutions += 1;
          this.shutdown.trackJobStart();

          this.executeJob(job).finally(() => {
            this.activeExecutions -= 1;
            this.shutdown.trackJobEnd();
          });
        }
      } catch (err) {
        console.error('Error claiming jobs from queue:', err);
        await new Promise((res) => setTimeout(res, 1000));
      }
    }

    await this.shutdown.waitForDrain();
    console.log(`Worker [${this.config.queue}] stopped cleanly.`);
  }

  private async executeJob(job: any): Promise<void> {
    try {
      await this.handler(job);
      await markJobDone(pool, job.id);
    } catch (err: any) {
      console.error(`Job [${job.id}] failed during execution:`, err?.message || err);
      // Retries and failure policies handled in Phase 4
    }
  }

  public async stop(): Promise<void> {
    this.running = false;
    this.shutdown.initiateShutdown();
    await this.shutdown.waitForDrain();
  }
}
```

