### Step 1 · Implement Exponential Backoff with Jitter Calculator (`src/consumer/backoff.ts`)
Create `src/consumer/backoff.ts` calculating retry delays:

```typescript
export interface BackoffOptions {
  baseSeconds?: number;
  maxSeconds?: number;
  jitterFactor?: number;
}

export function calculateBackoffSeconds(
  attemptNumber: number,
  options: BackoffOptions = {}
): number {
  const base = options.baseSeconds ?? 2;
  const max = options.maxSeconds ?? 300; // 5 minutes max
  const jitterFactor = options.jitterFactor ?? 0.25;

  // attemptNumber is 1-indexed (1, 2, 3...)
  const exp = Math.max(0, attemptNumber - 1);
  const exponential = base * Math.pow(2, exp);
  const capped = Math.min(max, exponential);

  // Add randomized jitter
  const jitter = Math.random() * (capped * jitterFactor);
  const finalDelay = Math.min(max, capped + jitter);

  return Math.round(finalDelay * 100) / 100;
}
```

### Step 2 · Implement Failure & Dead-Letter Transition Logic (`src/consumer/failure.ts`)
Create `src/consumer/failure.ts` updating failed jobs with backoff or marking them dead-lettered:

```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';
import { calculateBackoffSeconds } from './backoff.js';
import type { Job } from '../types/job.js';

export async function handleJobFailure(
  client: pg.Pool | pg.PoolClient = pool,
  job: Job,
  error: Error | any
): Promise<{ state: 'queued' | 'failed'; nextRunAt: Date | null }> {
  const errorMessage = error instanceof Error 
    ? `${error.name}: ${error.message}\n${error.stack ?? ''}` 
    : String(error);

  const isDeadLetter = job.attempts >= job.max_attempts;

  if (isDeadLetter) {
    // Transition permanently to Dead-Letter state ('failed')
    await client.query(`
      UPDATE job
      SET 
        state = 'failed',
        locked_until = NULL,
        locked_by = NULL,
        last_error = $2,
        updated_at = clock_timestamp()
      WHERE id = $1;
    `, [job.id, errorMessage]);

    return { state: 'failed', nextRunAt: null };
  } else {
    // Reschedule with exponential backoff
    const delaySec = calculateBackoffSeconds(job.attempts);
    const res = await client.query(`
      UPDATE job
      SET 
        state = 'queued',
        run_at = clock_timestamp() + make_interval(secs => $2),
        locked_until = NULL,
        locked_by = NULL,
        last_error = $3,
        updated_at = clock_timestamp()
      WHERE id = $1
      RETURNING run_at;
    `, [job.id, delaySec, errorMessage]);

    const nextRunAt = res.rows[0].run_at;
    return { state: 'queued', nextRunAt };
  }
}
```

