```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';

export interface ReapResult {
  reapedCount: number;
  reapedJobIds: string[];
}

export async function reapOrphanedJobs(
  client: pg.Pool | pg.PoolClient = pool,
  queueName?: string
): Promise<ReapResult> {
  let queryText: string;
  let queryParams: any[];

  if (queueName) {
    queryText = `
      UPDATE job
      SET 
        state = 'queued',
        locked_until = NULL,
        locked_by = NULL,
        updated_at = clock_timestamp(),
        last_error = COALESCE(last_error || E'\n', '') || '[REAPER] Worker lease expired; recovered to queue.'
      WHERE 
        queue = $1 
        AND state = 'running' 
        AND locked_until < clock_timestamp()
      RETURNING id;
    `;
    queryParams = [queueName];
  } else {
    queryText = `
      UPDATE job
      SET 
        state = 'queued',
        locked_until = NULL,
        locked_by = NULL,
        updated_at = clock_timestamp(),
        last_error = COALESCE(last_error || E'\n', '') || '[REAPER] Worker lease expired; recovered to queue.'
      WHERE 
        state = 'running' 
        AND locked_until < clock_timestamp()
      RETURNING id;
    `;
    queryParams = [];
  }

  const res = await client.query(queryText, queryParams);
  const reapedJobIds = res.rows.map((r) => r.id.toString());

  return {
    reapedCount: res.rowCount ?? 0,
    reapedJobIds,
  };
}
