import { reapOrphanedJobs } from './reaper.js';

export class ReaperService {
  private timer: NodeJS.Timeout | null = null;
  private running = false;

  constructor(private intervalMs = 15000) {}

  public start() {
    if (this.running) return;
    this.running = true;
    console.log(`Starting Reaper daemon (sweep every ${this.intervalMs}ms)...`);

    const sweep = async () => {
      try {
        const result = await reapOrphanedJobs();
        if (result.reapedCount > 0) {
          console.log(`[REAPER] Revived ${result.reapedCount} expired jobs: [${result.reapedJobIds.join(', ')}]`);
        }
      } catch (err) {
        console.error('[REAPER] Error during lease sweep:', err);
      } finally {
        if (this.running) {
          this.timer = setTimeout(sweep, this.intervalMs);
        }
      }
    };

    sweep();
  }

  public stop() {
    this.running = false;
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
    console.log('Reaper daemon stopped.');
  }
}
