import type pg from 'pg';
import { pool } from '../db/pool.js';
import type { Job } from '../types/job.js';

export async function listFailedJobs<T = any>(
  client: pg.Pool | pg.PoolClient = pool,
  queueName: string,
  limit = 50
): Promise<Job<T>[]> {
  const res = await client.query(`
    SELECT * FROM job
    WHERE queue = $1 AND state = 'failed'
    ORDER BY updated_at DESC
    LIMIT $2;
  `, [queueName, limit]);

  return res.rows.map((row) => ({
    ...row,
    id: row.id.toString(),
  }));
}

export async function retryFailedJob(
  client: pg.Pool | pg.PoolClient = pool,
  jobId: string,
  resetAttempts = false
): Promise<boolean> {
  const queryText = resetAttempts
    ? `
      UPDATE job
      SET state = 'queued', attempts = 0, run_at = clock_timestamp(), last_error = NULL, updated_at = clock_timestamp()
      WHERE id = $1 AND state = 'failed'
      RETURNING id;
    `
    : `
      UPDATE job
      SET state = 'queued', run_at = clock_timestamp(), updated_at = clock_timestamp()
      WHERE id = $1 AND state = 'failed'
      RETURNING id;
    `;

  const res = await client.query(queryText, [jobId]);
  return res.rowCount !== null && res.rowCount > 0;
}
