-- Create trigger function that publishes to dynamic queue channels
CREATE OR REPLACE FUNCTION notify_job_inserted()
RETURNS TRIGGER AS $$
BEGIN
    -- Only notify if the newly inserted job is immediately runnable
    IF NEW.state = 'queued' AND NEW.run_at <= clock_timestamp() THEN
        PERFORM pg_notify('job_' || NEW.queue, NEW.id::text);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Attach trigger to job table
DROP TRIGGER IF EXISTS trg_job_notify_insert ON job;
CREATE TRIGGER trg_job_notify_insert
AFTER INSERT ON job
FOR EACH ROW
EXECUTE FUNCTION notify_job_inserted();
