### Step 2 · Implement Dedicated Persistent Listener Client (`src/consumer/listener.ts`)
Create `src/consumer/listener.ts` maintaining an independent TCP connection for `LISTEN`:

```typescript
import pg from 'pg';
import dotenv from 'dotenv';

dotenv.config();

const { Client } = pg;

export class QueueListener {
  private client: pg.Client | null = null;
  private connected = false;
  private reconnectTimer: NodeJS.Timeout | null = null;

  constructor(
    private connectionString: string = process.env.DATABASE_URL || 'postgresql://postgres:postgres@localhost:5432/job_queue_db',
    private channel: string = 'job_default'
  ) {}

  public async connect(onNotification: (payload: string) => void): Promise<void> {
    this.client = new Client({ connectionString: this.connectionString });

    this.client.on('notification', (msg) => {
      if (msg.channel === this.channel) {
        onNotification(msg.payload || '');
      }
    });

    this.client.on('error', (err) => {
      console.error(`[LISTENER] Socket error on channel ${this.channel}:`, err.message);
      this.reconnect(onNotification);
    });

    this.client.on('end', () => {
      console.warn(`[LISTENER] Connection ended on channel ${this.channel}.`);
      this.reconnect(onNotification);
    });

    try {
      await this.client.connect();
      await this.client.query(`LISTEN ${this.channel}`);
      this.connected = true;
      console.log(`[LISTENER] Successfully listening on PostgreSQL channel: ${this.channel}`);
    } catch (err: any) {
      console.error(`[LISTENER] Initial connection failed:`, err.message);
      this.reconnect(onNotification);
    }
  }

  private reconnect(onNotification: (payload: string) => void) {
    if (this.reconnectTimer) return;
    this.connected = false;
    this.reconnectTimer = setTimeout(async () => {
      this.reconnectTimer = null;
      console.log(`[LISTENER] Attempting reconnection to channel: ${this.channel}...`);
      await this.connect(onNotification);
    }, 2000);
  }

  public async close(): Promise<void> {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.client) {
      try {
        await this.client.query(`UNLISTEN ${this.channel}`);
        await this.client.end();
      } catch (err) {
        // Ignore error on teardown
      }
      this.client = null;
    }
  }
}
```

