/// Debounces rapid successive notifications into a single execution tick.
export class NotificationDebouncer {
  private timeout: NodeJS.Timeout | null = null;

  constructor(private delayMs: number = 20) {}

  public trigger(callback: () => void) {
    if (this.timeout) return; // Debounce window already pending

    this.timeout = setTimeout(() => {
      this.timeout = null;
      callback();
    }, this.delayMs);
  }

  public cancel() {
    if (this.timeout) {
      clearTimeout(this.timeout);
      this.timeout = null;
    }
  }
}
```

### Step 4 · Implement Dynamic Heartbeat Lease Extension Routine (`src/consumer/heartbeat.ts`)
