```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';

export class JobHeartbeat {
  private timer: NodeJS.Timeout | null = null;
  private active = false;

  constructor(
    private jobId: string,
    private extensionSeconds: number = 30,
    private intervalMs: number = 10000,
    private client: pg.Pool | pg.PoolClient = pool
  ) {}

  public start() {
    this.active = true;
    this.scheduleNext();
  }

  private scheduleNext() {
    if (!this.active) return;

    this.timer = setTimeout(async () => {
      if (!this.active) return;
      try {
        await this.extend();
      } catch (err: any) {
        console.error(`[HEARTBEAT] Failed to extend lease for job ${this.jobId}:`, err.message);
      } finally {
        this.scheduleNext();
      }
    }, this.intervalMs);
  }

  public async extend(): Promise<boolean> {
    const res = await this.client.query(`
      UPDATE job
      SET locked_until = clock_timestamp() + make_interval(secs => $2), updated_at = clock_timestamp()
      WHERE id = $1 AND state = 'running'
      RETURNING locked_until;
    `, [this.jobId, this.extensionSeconds]);

    return res.rowCount !== null && res.rowCount > 0;
  }

  public stop() {
    this.active = false;
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
  }
}
```

