import type { JobHandler, WorkerConfig } from './handler.js';

export class EventDrivenWorker<T = any> {
  private shutdown = new ShutdownCoordinator();
  private listener: QueueListener;
  private debouncer = new NotificationDebouncer(10);
  private running = false;
  private activeSlots = 0;
