  public async start(): Promise<void> {
    this.running = true;
    const concurrency = this.config.concurrency ?? 5;
    const fallbackIntervalMs = this.config.pollIntervalMs ?? 10000; // 10s safety fallback poll

    console.log(`Starting EventDrivenWorker [${this.config.queue}] with instant LISTEN/NOTIFY...`);

    // 1. Connect LISTEN client to channel
    await this.listener.connect(() => {
      // Instant wake-up upon receipt of PostgreSQL NOTIFY event!
      this.debouncer.trigger(() => this.drainQueue());
    });

    // 2. Setup low-frequency safety fallback timer (for missed notifications / reconnects)
    const scheduleFallback = () => {
      if (!this.running) return;
      this.fallbackTimer = setTimeout(async () => {
        if (!this.running) return;
        await this.drainQueue();
        scheduleFallback();
      }, fallbackIntervalMs);
    };
    scheduleFallback();

    // 3. Initial drain of any existing backlog
    await this.drainQueue();
  }

  private async drainQueue(): Promise<void> {
    if (!this.running || this.shutdown.shuttingDown) return;

    const concurrency = this.config.concurrency ?? 5;
    while (this.running && !this.shutdown.shuttingDown) {
      const available = concurrency - this.activeSlots;
      if (available <= 0) break;

      const jobs = await claimJobs<T>(pool, this.config.queue, {
        batchSize: available,
        leaseSeconds: this.config.leaseSeconds ?? 30,
        workerId: this.config.workerId,
      });

      if (jobs.length === 0) {
        break; // Queue drained; return to waiting on socket
      }

      for (const job of jobs) {
        this.activeSlots += 1;
        this.shutdown.trackJobStart();

        this.processJobWithHeartbeat(job).finally(() => {
          this.activeSlots -= 1;
          this.shutdown.trackJobEnd();
          // Trigger subsequent drain if additional capacity opened
          this.debouncer.trigger(() => this.drainQueue());
        });
      }
    }
  }

  private async processJobWithHeartbeat(job: any): Promise<void> {
    // Launch heartbeat extension every 10s (lease 30s)
    const heartbeat = new JobHeartbeat(job.id, 30, 10000, pool);
    heartbeat.start();

    try {
      await this.handler(job);
      await markJobDone(pool, job.id);
    } catch (err: any) {
      await handleJobFailure(pool, job, err);
    } finally {
      heartbeat.stop();
    }
  }

  public async stop(): Promise<void> {
    this.running = false;
    if (this.fallbackTimer) clearTimeout(this.fallbackTimer);
    this.debouncer.cancel();
    await this.listener.close();
    this.shutdown.initiateShutdown();
    await this.shutdown.waitForDrain();
    console.log(`EventDrivenWorker [${this.config.queue}] stopped cleanly.`);
  }
}
