### Step 2 · Implement Table Bloat & Dead Tuple Monitoring Query (`src/admin/stats.ts`)
Create `src/admin/stats.ts` inspecting PostgreSQL system statistics:

```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';

export interface QueueTableStats {
  tableName: string;
  liveTuples: number;
  deadTuples: number;
  deadRatioPercent: number;
  lastVacuum: Date | null;
  lastAutovacuum: Date | null;
  tableSizePretty: string;
  indexSizePretty: string;
}

export async function getQueueTableStats(
  client: pg.Pool | pg.PoolClient = pool
): Promise<QueueTableStats> {
  const res = await client.query(`
    SELECT 
      relname AS table_name,
      n_live_tup AS live_tuples,
      n_dead_tup AS dead_tuples,
      ROUND((n_dead_tup::numeric / GREATEST(n_live_tup + n_dead_tup, 1)::numeric) * 100, 2) AS dead_ratio_percent,
      last_vacuum,
      last_autovacuum,
      pg_size_pretty(pg_relation_size(relid)) AS table_size,
      pg_size_pretty(pg_indexes_size(relid)) AS index_size
    FROM pg_stat_user_tables
    WHERE relname = 'job';
  `);

  const row = res.rows[0];
  if (!row) {
    throw new Error('Table job not found in pg_stat_user_tables');
  }

  return {
    tableName: row.table_name,
    liveTuples: Number(row.live_tuples),
    deadTuples: Number(row.dead_tuples),
    deadRatioPercent: Number(row.dead_ratio_percent),
    lastVacuum: row.last_vacuum ? new Date(row.last_vacuum) : null,
    lastAutovacuum: row.last_autovacuum ? new Date(row.last_autovacuum) : null,
    tableSizePretty: row.table_size,
    indexSizePretty: row.index_size,
  };
}
