### Step 3 · Implement Automated Retention Pruner Routine (`src/admin/prune.ts`)
Create `src/admin/prune.ts` purging completed jobs older than a threshold:

```typescript
import type pg from 'pg';
import { pool } from '../db/pool.js';

export interface PruneOptions {
  retentionDays?: number;
  batchLimit?: number;
}

export async function pruneCompletedJobs(
  client: pg.Pool | pg.PoolClient = pool,
  options: PruneOptions = {}
): Promise<number> {
  const days = options.retentionDays ?? 7;
  const batchLimit = options.batchLimit ?? 5000;

  // Purge in bounded batches to prevent long lock times and excessive WAL spikes
  const res = await client.query(`
    WITH to_delete AS (
      SELECT id FROM job
      WHERE 
        state IN ('done', 'cancelled') 
        AND updated_at < clock_timestamp() - make_interval(days => $1)
      LIMIT $2
    )
    DELETE FROM job
    WHERE id IN (SELECT id FROM to_delete)
    RETURNING id;
  `, [days, batchLimit]);

  return res.rowCount ?? 0;
}
```

