```typescript
import { pool } from '../db/pool.js';
import { enqueueBatch } from '../producer/batch.js';

export async function produceBenchmarkBatch(
  queue: string,
  totalCount: number,
  batchSize: number = 500
): Promise<number> {
  const batches = Math.ceil(totalCount / batchSize);
  let enqueued = 0;

  for (let b = 0; b < batches; b++) {
    const currentBatchSize = Math.min(batchSize, totalCount - enqueued);
    const items = Array.from({ length: currentBatchSize }, (_, i) => ({
      payload: { index: enqueued + i, timestamp: Date.now() },
    }));

    await enqueueBatch(pool, queue, items);
    enqueued += currentBatchSize;
  }

  return enqueued;
}
```

