```typescript
import { pool } from '../db/pool.js';
import { claimJobs } from '../consumer/claim.js';
import { markJobDone } from '../consumer/complete.js';

export async function consumeBenchmarkJobs(
  queue: string,
  workerCount: number,
  batchSize: number
): Promise<number> {
  let processed = 0;
  let active = true;

  const worker = async (id: number) => {
    while (active) {
      const jobs = await claimJobs(pool, queue, {
        batchSize,
        leaseSeconds: 30,
        workerId: `bench_w_${id}`,
      });

      if (jobs.length === 0) {
        break; // Queue drained
      }

      // Complete jobs concurrently
      await Promise.all(jobs.map((j) => markJobDone(pool, j.id)));
      processed += jobs.length;
    }
  };

  await Promise.all(Array.from({ length: workerCount }, (_, i) => worker(i)));
  return processed;
}
```

