### Step 1 · Implement Hash Function Provider (`internal/ring/hash.go`)
Create `internal/ring/hash.go` providing fast, uniform 32-bit hashing:

```go
package ring

import (
	"hash/crc32"
)

// HashFunc converts a string key into a 32-bit unsigned integer along the ring [0, 2^32-1].
type HashFunc func(key string) uint32

// DefaultHash uses IEEE CRC32 for high throughput and uniform distribution.
func DefaultHash(key string) uint32 {
	return crc32.ChecksumIEEE([]byte(key))
}
```

### Step 2 · Implement Core Ring Data Structures (`internal/ring/ring.go`)
Create `internal/ring/ring.go` defining the thread-safe ring and node mappings:

```go
package ring

import (
	"fmt"
	"sync"
)

type Ring struct {
	mu       sync.RWMutex
	hashFunc HashFunc
	vnodes   int
	tokens   []uint32          // Sorted list of token hashes on the ring
	owners   map[uint32]string // Maps each token hash to physical shard ID
	shards   map[string]bool   // Set of active physical shard IDs
}

func NewRing(vnodes int, hashFunc HashFunc) *Ring {
	if vnodes <= 0 {
		vnodes = 128
	}
	if hashFunc == nil {
		hashFunc = DefaultHash
	}

	return &Ring{
		hashFunc: hashFunc,
		vnodes:   vnodes,
		tokens:   make([]uint32, 0),
		owners:   make(map[uint32]string),
		shards:   make(map[string]bool),
	}
}

func (r *Ring) VNodes() int {
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.vnodes
}

func (r *Ring) ShardList() []string {
	r.mu.RLock()
	defer r.mu.RUnlock()
	list := make([]string, 0, len(r.shards))
	for s := range r.shards {
		list = append(list, s)
	}
	return list
}
```

### Step 3 · Implement Virtual Node Token Generation and Ring Sorting (`internal/ring/vnode.go`)
Create `internal/ring/vnode.go` handling token generation and binary sorting:

```go
package ring

import (
	"fmt"
	"sort"
)

func (r *Ring) generateTokens(shardID string) []uint32 {
	toks := make([]uint32, r.vnodes)
	for i := 0; i < r.vnodes; i++ {
		tokenKey := fmt.Sprintf("%s#vnode%d", shardID, i)
		toks[i] = r.hashFunc(tokenKey)
	}
	return toks
}

func (r *Ring) rebuildTokensLocked() {
	toks := make([]uint32, 0, len(r.owners))
	for t := range r.owners {
		toks = append(toks, t)
	}
	sort.Slice(toks, func(i, j int) bool {
		return toks[i] < toks[j]
	})
	r.tokens = toks
}
```

### Step 4 · Implement High-Performance Binary Search Lookup (`internal/ring/lookup.go`)
Create `internal/ring/lookup.go` locating the owning shard in $\mathcal{O}(\log(V \cdot N))$ time:

```go
package ring

import (
	"errors"
	"sort"
)

var ErrEmptyRing = errors.New("cannot route key: hash ring contains no shards")

// GetShard maps a shard key (e.g. tenant_id) to the owning physical shard ID.
func (r *Ring) GetShard(key string) (string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	if len(r.tokens) == 0 {
		return "", ErrEmptyRing
	}

	h := r.hashFunc(key)

	// Binary search for the first token >= h
	idx := sort.Search(len(r.tokens), func(i int) bool {
		return r.tokens[i] >= h
	})

	// If h is greater than all tokens on the ring, wrap around clockwise to 0
	if idx == len(r.tokens) {
		idx = 0
	}

	token := r.tokens[idx]
	return r.owners[token], nil
}
```

### Step 5 · Implement Dynamic Add & Remove Shard Mutations (`internal/ring/mutate.go`)
Create `internal/ring/mutate.go` supporting live topology reconfigurations:

```go
package ring

import (
	"fmt"
)

func (r *Ring) AddShard(shardID string) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	if r.shards[shardID] {
		return fmt.Errorf("shard %s already exists in ring", shardID)
	}

	r.shards[shardID] = true
	toks := r.generateTokens(shardID)
	for _, t := range toks {
		r.owners[t] = shardID
	}

	r.rebuildTokensLocked()
	return nil
}

func (r *Ring) RemoveShard(shardID string) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	if !r.shards[shardID] {
		return fmt.Errorf("shard %s not found in ring", shardID)
	}

	delete(r.shards, shardID)
	for t, owner := range r.owners {
		if owner == shardID {
			delete(r.owners, t)
		}
	}

	r.rebuildTokensLocked()
	return nil
}
```

### Step 6 · Implement Migration Set Calculation Engine (`internal/ring/migration_plan.go`)
Create `internal/ring/migration_plan.go` calculating key displacement during topology changes:

```go
package ring

type MigrationPlan struct {
	TotalKeysTested int
	MovedKeysCount  int
	MovedPercentage float64
	Routes          map[string]map[string]int // fromShard -> toShard -> count
}

// CalculateMigration determines how keys will shift between oldRing and newRing.
func CalculateMigration(oldRing, newRing *Ring, sampleKeys []string) (*MigrationPlan, error) {
	plan := &MigrationPlan{
		TotalKeysTested: len(sampleKeys),
		Routes:          make(map[string]map[string]int),
	}

	moved := 0
	for _, k := range sampleKeys {
		oldShard, err1 := oldRing.GetShard(k)
		newShard, err2 := newRing.GetShard(k)
		if err1 != nil || err2 != nil {
			continue
		}

		if oldShard != newShard {
			moved++
			if plan.Routes[oldShard] == nil {
				plan.Routes[oldShard] = make(map[string]int)
			}
			plan.Routes[oldShard][newShard]++
		}
	}

	plan.MovedKeysCount = moved
	if len(sampleKeys) > 0 {
		plan.MovedPercentage = (float64(moved) / float64(len(sampleKeys))) * 100.0
	}
	return plan, nil
}
```

