		key := strconv.Itoa(i + 1000)
		sampleKeys[i] = key
		shard, _ := r.GetShard(key)
		counts[shard]++
	}

	fmt.Printf("Total Keys: %d | Shards: 3 | VNodes per Shard: 128\n\n", totalKeys)
