```go
package router

import (
	"fmt"
	"strconv"

	"github.com/jackc/pgx/v5/pgxpool"
)

func (r *Router) resolveShard(tenantID int64) (string, *pgxpool.Pool, error) {
	if tenantID <= 0 {
		return "", nil, ErrMissingShardKey
	}

	key := strconv.FormatInt(tenantID, 10)
	shardID, err := r.ring.GetShard(key)
	if err != nil {
		return "", nil, fmt.Errorf("failed to locate shard for tenant %d: %w", tenantID, err)
	}

	pool, err := r.pm.GetPool(shardID)
	if err != nil {
		return "", nil, fmt.Errorf("failed to get connection pool for shard %s: %w", shardID, err)
	}

	return shardID, pool, nil
}
```

