		ON CONFLICT (id) DO UPDATE SET
			name = EXCLUDED.name,
			tier = EXCLUDED.tier;
	`
	_, err = pool.Exec(ctx, query, tenant.ID, tenant.Name, tenant.Tier)
	if err != nil {
		return "", fmt.Errorf("failed to insert tenant on shard %s: %w", shardID, err)
	}

	return shardID, nil
}

func (r *Router) InsertEvent(ctx context.Context, event Event) (string, string, error) {
	shardID, pool, err := r.resolveShard(event.TenantID)
	if err != nil {
		return "", "", err
	}

	var eventID string
	query := `
		INSERT INTO events (tenant_id, kind, payload)
		VALUES ($1, $2, $3)
		RETURNING id::text;
	`
	err = pool.QueryRow(ctx, query, event.TenantID, event.Kind, event.Payload).Scan(&eventID)
	if err != nil {
		return "", "", fmt.Errorf("failed to insert event on shard %s: %w", shardID, err)
	}

	return shardID, eventID, nil
}
