func (r *Router) GetTenant(ctx context.Context, tenantID int64) (*Tenant, string, error) {
	shardID, pool, err := r.resolveShard(tenantID)
	if err != nil {
		return nil, "", err
	}

	query := `SELECT id, name, tier, created_at FROM tenants WHERE id = $1;`
	var t Tenant
	err = pool.QueryRow(ctx, query, tenantID).Scan(&t.ID, &t.Name, &t.Tier, &t.CreatedAt)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, shardID, ErrTenantNotFound
		}
		return nil, shardID, fmt.Errorf("failed to query tenant on shard %s: %w", shardID, err)
	}

	return &t, shardID, nil
}

func (r *Router) ListEventsByTenant(ctx context.Context, tenantID int64, limit int) ([]Event, string, error) {
	shardID, pool, err := r.resolveShard(tenantID)
	if err != nil {
		return nil, "", err
	}
	if limit <= 0 {
		limit = 50
	}

	query := `
		SELECT tenant_id, id::text, kind, payload, created_at
		FROM events
		WHERE tenant_id = $1
		ORDER BY created_at DESC
		LIMIT $2;
	`
	rows, err := pool.Query(ctx, query, tenantID, limit)
	if err != nil {
		return nil, shardID, fmt.Errorf("failed to query events on shard %s: %w", shardID, err)
	}
	defer rows.Close()

	events, err := pgx.CollectRows(rows, pgx.RowToStructByName[Event])
	if err != nil {
		return nil, shardID, fmt.Errorf("failed to deserialize events on shard %s: %w", shardID, err)
	}

	return events, shardID, nil
}
