### Step 6 · Implement Context-Aware Transactional Helper `WithTenantTx` (`internal/router/transaction.go`)
Create `internal/router/transaction.go` enabling atomic multi-statement operations on a single shard:

```go
package router

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5"
)

// WithTenantTx executes a closure inside a local ACID transaction on the owning shard.
func (r *Router) WithTenantTx(ctx context.Context, tenantID int64, fn func(tx pgx.Tx) error) error {
	shardID, pool, err := r.resolveShard(tenantID)
	if err != nil {
		return err
	}

	tx, err := pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.ReadCommitted})
	if err != nil {
		return fmt.Errorf("failed to begin transaction on shard %s: %w", shardID, err)
	}
	defer tx.Rollback(ctx) // Safe to call if tx already committed

	if err := fn(tx); err != nil {
		return err
	}

	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("failed to commit transaction on shard %s: %w", shardID, err)
	}

	return nil
}
```

