### Step 2 · Implement Parallel Aggregation Fan-Out (`internal/router/scatter_count.go`)
Create `internal/router/scatter_count.go` fanning out group-by aggregations using `errgroup`:

```go
package router

import (
	"context"
	"fmt"
	"sync"
	"time"

	"golang.org/x/sync/errgroup"
)

func (r *Router) CountEventsByKind(ctx context.Context, timeout time.Duration) (map[string]int64, error) {
	if timeout <= 0 {
		timeout = 3 * time.Second
	}
	sctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	g, gctx := errgroup.WithContext(sctx)
	var mu sync.Mutex
	totals := make(map[string]int64)

	pools := r.pm.AllPools()
	for shardID, pool := range pools {
		shardID, pool := shardID, pool
		g.Go(func() error {
			query := `SELECT kind, count(*) FROM events GROUP BY kind;`
			rows, err := pool.Query(gctx, query)
			if err != nil {
				return fmt.Errorf("shard %s failed: %w", shardID, err)
			}
			defer rows.Close()

			localCounts := make(map[string]int64)
			for rows.Next() {
				var kind string
				var count int64
				if err := rows.Scan(&kind, &count); err != nil {
					return err
				}
				localCounts[kind] = count
			}
			if err := rows.Err(); err != nil {
				return err
			}

			mu.Lock()
			for k, v := range localCounts {
				totals[k] += v
			}
			mu.Unlock()
			return nil
		})
	}

	if err := g.Wait(); err != nil {
		return nil, err
	}
	return totals, nil
}
```

### Step 3 · Implement Algebraic Multi-Shard Average Calculation (`internal/router/scatter_avg.go`)
Create `internal/router/scatter_avg.go` using algebraic pairs for mathematically sound averaging:

```go
package router

import (
	"context"
	"fmt"
	"sync"
	"time"

	"golang.org/x/sync/errgroup"
)

func (r *Router) SummarizeEventPayloadAmounts(ctx context.Context) (*NumericMetricSummary, error) {
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	g, gctx := errgroup.WithContext(ctx)
	var mu sync.Mutex
	var totalCount int64
	var totalSum float64

	for shardID, pool := range r.pm.AllPools() {
		shardID, pool := shardID, pool
		g.Go(func() error {
			// Pushdown query extracting numeric amounts from jsonb
			query := `
				SELECT 
					count(*), 
					COALESCE(sum((payload->>'amount')::numeric), 0)
				FROM events 
				WHERE payload ? 'amount';
			`
			var count int64
			var sum float64
			err := pool.QueryRow(gctx, query).Scan(&count, &sum)
			if err != nil {
				return fmt.Errorf("shard %s calculation failed: %w", shardID, err)
			}

			mu.Lock()
			totalCount += count
			totalSum += sum
			mu.Unlock()
			return nil
		})
	}

	if err := g.Wait(); err != nil {
		return nil, err
	}

	avg := 0.0
	if totalCount > 0 {
		avg = totalSum / float64(totalCount)
	}

	return &NumericMetricSummary{
		Count:   totalCount,
		Sum:     totalSum,
		Average: avg,
	}, nil
}
