### Step 4 · Implement Min-Heap for $K$-Way Stream Merging (`internal/router/heap_merger.go`)
Create `internal/router/heap_merger.go` for cross-shard ordered pagination:

```go
package router

import (
	"container/heap"
)

type shardStreamElement struct {
	event   Event
	shardID string
	index   int // Current index in that shard's slice
}

type eventMinHeap []shardStreamElement

func (h eventMinHeap) Len() int           { return len(h) }
// We want latest events first (Descending by CreatedAt)
func (h eventMinHeap) Less(i, j int) bool { return h[i].event.CreatedAt.After(h[j].event.CreatedAt) }
func (h eventMinHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *eventMinHeap) Push(x any) {
	*h = append(*h, x.(shardStreamElement))
}

func (h *eventMinHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// MergeSortedShardEvents merges N slices pre-sorted descending into a single top-K slice
func MergeSortedShardEvents(shardEvents map[string][]Event, limit int) []Event {
	h := &eventMinHeap{}
	heap.Init(h)

	// Seed heap with first element from each non-empty shard slice
	for shardID, events := range shardEvents {
		if len(events) > 0 {
			heap.Push(h, shardStreamElement{
				event:   events[0],
				shardID: shardID,
				index:   0,
			})
		}
	}

	result := make([]Event, 0, limit)
	for h.Len() > 0 && len(result) < limit {
		top := heap.Pop(h).(shardStreamElement)
		result = append(result, top.event)

		// Push next item from the shard that produced the popped element
		nextIdx := top.index + 1
		slice := shardEvents[top.shardID]
		if nextIdx < len(slice) {
			heap.Push(h, shardStreamElement{
				event:   slice[nextIdx],
				shardID: top.shardID,
				index:   nextIdx,
			})
		}
	}

	return result
}
```

### Step 5 · Implement Cross-Shard Global Ordered Pagination (`internal/router/scatter_list.go`)
