```go
package router

import (
	"context"
	"fmt"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"golang.org/x/sync/errgroup"
)

func (r *Router) ListLatestEventsGlobal(ctx context.Context, limit int) ([]Event, error) {
	if limit <= 0 {
		limit = 20
	}

	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	g, gctx := errgroup.WithContext(ctx)
	var mu sync.Mutex
	shardResults := make(map[string][]Event)

	for shardID, pool := range r.pm.AllPools() {
		shardID, pool := shardID, pool
		g.Go(func() error {
			// Push down ORDER BY and LIMIT to each shard
			query := `
				SELECT tenant_id, id::text, kind, payload, created_at
				FROM events
				ORDER BY created_at DESC
				LIMIT $1;
			`
			rows, err := pool.Query(gctx, query, limit)
			if err != nil {
				return fmt.Errorf("shard %s query failed: %w", shardID, err)
			}
			defer rows.Close()

			events, err := pgx.CollectRows(rows, pgx.RowToStructByName[Event])
			if err != nil {
				return err
			}

			mu.Lock()
			shardResults[shardID] = events
			mu.Unlock()
			return nil
		})
	}

	if err := g.Wait(); err != nil {
		return nil, err
	}

	// Perform K-Way merge in Go router memory in O(K log N)
	return MergeSortedShardEvents(shardResults, limit), nil
}
