```go
package router

import (
	"context"
	"sync"
	"time"
)

func (r *Router) CountEventsByKindResilient(ctx context.Context, timeout time.Duration) *ScatterResult[map[string]int64] {
	sctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	pools := r.pm.AllPools()
	totalShards := len(pools)

	var wg sync.WaitGroup
	var mu sync.Mutex
	totals := make(map[string]int64)
	var failedShards []string

	for shardID, pool := range pools {
		wg.Add(1)
		go func(sID string, p *pgxpool.Pool) {
			defer wg.Done()
			query := `SELECT kind, count(*) FROM events GROUP BY kind;`
			rows, err := p.Query(sctx, query)
			if err != nil {
				mu.Lock()
				failedShards = append(failedShards, sID)
				mu.Unlock()
				return
			}
			defer rows.Close()

			localCounts := make(map[string]int64)
			for rows.Next() {
				var kind string
				var count int64
				if err := rows.Scan(&kind, &count); err == nil {
					localCounts[kind] = count
				}
			}

			mu.Lock()
			for k, v := range localCounts {
				totals[k] += v
			}
			mu.Unlock()
		}(shardID, pool)
	}

	wg.Wait()

	return &ScatterResult[map[string]int64]{
		Data:               totals,
		Degraded:           len(failedShards) > 0,
		FailedShards:       failedShards,
		TotalShardsQueried: totalShards,
	}
}
