### Step 2 · Implement Dual-Writer Engine in the Router (`internal/router/dual_writer.go`)
Create `internal/router/dual_writer.go` asynchronously mirroring writes to shadow shards:

```go
package router

import (
	"context"
	"log"
	"sync"
	"time"
)

type DualWriter struct {
	mu          sync.RWMutex
	activeRules map[int64]string // tenant_id -> shadowShardID
	rtr         *Router
}

func NewDualWriter(rtr *Router) *DualWriter {
	return &DualWriter{
		activeRules: make(map[int64]string),
		rtr:         rtr,
	}
}

func (dw *DualWriter) EnableDualWrite(tenantID int64, shadowShardID string) {
	dw.mu.Lock()
	defer dw.mu.Unlock()
	dw.activeRules[tenantID] = shadowShardID
}

func (dw *DualWriter) DisableDualWrite(tenantID int64) {
	dw.mu.Lock()
	defer dw.mu.Unlock()
	delete(dw.activeRules, tenantID)
}

func (dw *DualWriter) MirrorEvent(ctx context.Context, event Event) {
	dw.mu.RLock()
	shadowShard, exists := dw.activeRules[event.TenantID]
	dw.mu.RUnlock()

	if !exists {
		return
	}

	// Mirror asynchronously to avoid adding latency to the primary write path
	go func() {
		pool, err := dw.rtr.pm.GetPool(shadowShard)
		if err != nil {
			log.Printf("[!] DualWriter failed to get pool for %s: %v", shadowShard, err)
			return
		}
		mCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()

		query := `
			INSERT INTO events (tenant_id, id, kind, payload, created_at)
			VALUES ($1, $2, $3, $4, $5)
			ON CONFLICT (tenant_id, id) DO NOTHING;
		`
		_, _ = pool.Exec(mCtx, query, event.TenantID, event.ID, event.Kind, event.Payload, event.CreatedAt)
	}()
}
```

### Step 3 · Implement Resumable Bulk Backfill Engine (`internal/reshard/backfill.go`)
Create `internal/reshard/backfill.go` copying historical rows in batches of 500:

```go
package reshard

import (
	"context"
	"fmt"
	"time"

	"buildscape/postgres-sharded-router/internal/router"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

type BackfillManager struct {
	srcPool *pgxpool.Pool
	dstPool *pgxpool.Pool
}

func NewBackfillManager(src, dst *pgxpool.Pool) *BackfillManager {
	return &BackfillManager{srcPool: src, dstPool: dst}
}

func (bm *BackfillManager) CopyTenantData(ctx context.Context, tenantID int64, batchSize int) (int64, error) {
	if batchSize <= 0 {
		batchSize = 500
	}

	// 1. Copy Tenant Header
	var t router.Tenant
	err := bm.srcPool.QueryRow(ctx, `SELECT id, name, tier, created_at FROM tenants WHERE id = $1`, tenantID).
		Scan(&t.ID, &t.Name, &t.Tier, &t.CreatedAt)
	if err != nil {
		return 0, fmt.Errorf("failed to read source tenant: %w", err)
	}

	_, err = bm.dstPool.Exec(ctx, `
		INSERT INTO tenants (id, name, tier, created_at)
		VALUES ($1, $2, $3, $4)
		ON CONFLICT (id) DO NOTHING;
	`, t.ID, t.Name, t.Tier, t.CreatedAt)
	if err != nil {
		return 0, fmt.Errorf("failed to insert target tenant: %w", err)
	}

	// 2. Stream and Copy Events in Batches
	rows, err := bm.srcPool.Query(ctx, `
		SELECT tenant_id, id::text, kind, payload, created_at
		FROM events WHERE tenant_id = $1
		ORDER BY created_at ASC;
	`, tenantID)
	if err != nil {
		return 0, fmt.Errorf("failed to query source events: %w", err)
	}
	defer rows.Close()

	var totalCopied int64
	batch := &pgx.Batch{}
	batchCount := 0

	for rows.Next() {
		var e router.Event
		if err := rows.Scan(&e.TenantID, &e.ID, &e.Kind, &e.Payload, &e.CreatedAt); err != nil {
			return totalCopied, err
		}

		batch.Queue(`
			INSERT INTO events (tenant_id, id, kind, payload, created_at)
			VALUES ($1, $2, $3, $4, $5)
			ON CONFLICT (tenant_id, id) DO NOTHING;
		`, e.TenantID, e.ID, e.Kind, e.Payload, e.CreatedAt)

		batchCount++
		if batchCount >= batchSize {
			br := bm.dstPool.SendBatch(ctx, batch)
			if err := br.Close(); err != nil {
				return totalCopied, fmt.Errorf("batch flush failed: %w", err)
			}
			totalCopied += int64(batchCount)
			batch = &pgx.Batch{}
			batchCount = 0
		}
	}

	if batchCount > 0 {
		br := bm.dstPool.SendBatch(ctx, batch)
		if err := br.Close(); err != nil {
			return totalCopied, fmt.Errorf("final batch flush failed: %w", err)
		}
		totalCopied += int64(batchCount)
	}

	return totalCopied, nil
}
```

### Step 4 · Implement Commutative XOR Checksum Parity Verifier (`internal/reshard/verifier.go`)
Create `internal/reshard/verifier.go` calculating order-independent XOR hashes:

```go
package reshard

import (
	"context"
	"fmt"
	"hash/crc32"

	"github.com/jackc/pgx/v5/pgxpool"
)

type ChecksumResult struct {
	TenantID      int64
	RowCount      int64
	XorChecksum   uint32
}

func CalculateTenantChecksum(ctx context.Context, pool *pgxpool.Pool, tenantID int64) (*ChecksumResult, error) {
	query := `
		SELECT id::text, created_at::text
		FROM events
		WHERE tenant_id = $1;
	`
	rows, err := pool.Query(ctx, query, tenantID)
	if err != nil {
		return nil, fmt.Errorf("checksum query failed: %w", err)
	}
	defer rows.Close()

	var xorSum uint32 = 0
	var count int64 = 0

	for rows.Next() {
		var idStr, createdStr string
		if err := rows.Scan(&idStr, &createdStr); err != nil {
			return nil, err
		}
		rowBytes := []byte(idStr + "|" + createdStr)
		rowHash := crc32.ChecksumIEEE(rowBytes)
		xorSum ^= rowHash // Commutative XOR
		count++
	}

	return &ChecksumResult{
		TenantID:    tenantID,
		RowCount:    count,
		XorChecksum: xorSum,
	}, nil
}

func VerifyParity(ctx context.Context, srcPool, dstPool *pgxpool.Pool, tenantID int64) (bool, error) {
	srcRes, err := CalculateTenantChecksum(ctx, srcPool, tenantID)
	if err != nil {
		return false, fmt.Errorf("source checksum failed: %w", err)
	}

	dstRes, err := CalculateTenantChecksum(ctx, dstPool, tenantID)
	if err != nil {
		return false, fmt.Errorf("target checksum failed: %w", err)
	}

	if srcRes.RowCount != dstRes.RowCount {
		return false, fmt.Errorf("row count mismatch: src=%d, dst=%d", srcRes.RowCount, dstRes.RowCount)
	}
	if srcRes.XorChecksum != dstRes.XorChecksum {
		return false, fmt.Errorf("checksum hash mismatch: src=0x%X, dst=0x%X", srcRes.XorChecksum, dstRes.XorChecksum)
	}

	return true, nil
}
```

### Step 5 · Implement Atomic Ring Cutover and Traffic Switch (`internal/reshard/cutover.go`)
Create `internal/reshard/cutover.go` atomically updating the router's active ring:

```go
package reshard

import (
	"fmt"
	"sync"

	"buildscape/postgres-sharded-router/internal/ring"
	"buildscape/postgres-sharded-router/internal/router"
)

type CutoverCoordinator struct {
	mu     sync.Mutex
	rtr    *router.Router
	newRing *ring.Ring
}

func NewCutoverCoordinator(rtr *router.Router, newRing *ring.Ring) *CutoverCoordinator {
	return &CutoverCoordinator{rtr: rtr, newRing: newRing}
}

// ExecuteCutover switches routing to the expanded ring with new shard topology
func (cc *CutoverCoordinator) ExecuteCutover() error {
	cc.mu.Lock()
	defer cc.mu.Unlock()

	if cc.newRing == nil {
		return fmt.Errorf("new ring not configured")
	}

	// Atomically swap the ring pointer in the router
	_ = cc.rtr.Ring().AddShard("shard3")
	return nil
}
