```go
package reshard

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
)

func PruneMigratedTenant(ctx context.Context, srcPool *pgxpool.Pool, tenantID int64) (int64, error) {
	// Clean events first due to foreign key
	ct, err := srcPool.Exec(ctx, `DELETE FROM events WHERE tenant_id = $1`, tenantID)
	if err != nil {
		return 0, fmt.Errorf("failed to delete migrated events from source: %w", err)
	}

	_, err = srcPool.Exec(ctx, `DELETE FROM tenants WHERE id = $1`, tenantID)
	if err != nil {
		return ct.RowsAffected(), fmt.Errorf("failed to delete migrated tenant header: %w", err)
	}

	return ct.RowsAffected(), nil
}
