## 🛠 Step-by-Step Implementation

### Step 1 · Implement Per-Shard Three-State Circuit Breaker (`internal/circuit/breaker.go`)
Create `internal/circuit/breaker.go` managing failure thresholds and cooldown timers:

```go
package circuit

import (
	"errors"
	"sync"
	"time"
)

var ErrCircuitOpen = errors.New("circuit breaker: shard is offline, fast-failing query")

type State int

const (
	StateClosed State = iota
	StateHalfOpen
	StateOpen
)

type Breaker struct {
	mu              sync.Mutex
	state           State
	failureCount    int
	consecutiveMax  int
	cooldownTimeout time.Duration
	lastStateChange time.Time
}

func NewBreaker(consecutiveMax int, cooldown time.Duration) *Breaker {
	if consecutiveMax <= 0 {
		consecutiveMax = 5
	}
	if cooldown <= 0 {
		cooldown = 5 * time.Second
	}
	return &Breaker{
		state:           StateClosed,
		consecutiveMax:  consecutiveMax,
		cooldownTimeout: cooldown,
		lastStateChange: time.Now(),
	}
}

func (b *Breaker) Allow() error {
	b.mu.Lock()
	defer b.mu.Unlock()

	if b.state == StateClosed {
		return nil
	}

	if b.state == StateOpen {
		if time.Since(b.lastStateChange) >= b.cooldownTimeout {
			b.state = StateHalfOpen
			b.lastStateChange = time.Now()
			return nil // Allow single canary probe
		}
		return ErrCircuitOpen
	}

	// In HalfOpen, only allow canary; subsequent concurrent calls rejected
	return ErrCircuitOpen
}

func (b *Breaker) ReportSuccess() {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.failureCount = 0
	b.state = StateClosed
	b.lastStateChange = time.Now()
}

func (b *Breaker) ReportFailure() {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.failureCount++
	if b.failureCount >= b.consecutiveMax || b.state == StateHalfOpen {
		b.state = StateOpen
		b.lastStateChange = time.Now()
	}
}

func (b *Breaker) State() State {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.state
}
```

