### Step 3 · Integrate Circuit Breakers into Resilient Pool Dispatcher (`internal/router/resilient_dispatch.go`)
Create `internal/router/resilient_dispatch.go` combining pool execution with circuit guards:

```go
package router

import (
	"context"
	"errors"
	"fmt"
	"time"

	"buildscape/postgres-sharded-router/internal/circuit"
	"buildscape/postgres-sharded-router/internal/metrics"
	"github.com/jackc/pgx/v5/pgxpool"
)

type ResilientDispatcher struct {
	rtr      *Router
	breakers map[string]*circuit.Breaker
}

func NewResilientDispatcher(rtr *Router) *ResilientDispatcher {
	rd := &ResilientDispatcher{
		rtr:      rtr,
		breakers: make(map[string]*circuit.Breaker),
	}
	for _, s := range rtr.Ring().ShardList() {
		rd.breakers[s] = circuit.NewBreaker(5, 5*time.Second)
		metrics.CircuitStateGauge.WithLabelValues(s).Set(0)
	}
	return rd
}

func (rd *ResilientDispatcher) ExecuteOnShard(ctx context.Context, shardID string, op string, fn func(pool *pgxpool.Pool) error) error {
	cb, ok := rd.breakers[shardID]
	if !ok {
		return fmt.Errorf("unknown shard ID: %s", shardID)
	}

	if err := cb.Allow(); err != nil {
		metrics.TotalQueries.WithLabelValues(shardID, op, "circuit_rejected").Inc()
		return err
	}

	pool, err := rd.rtr.pm.GetPool(shardID)
	if err != nil {
		cb.ReportFailure()
		return err
	}

	start := time.Now()
	execErr := fn(pool)
	duration := time.Since(start).Seconds()

	if execErr != nil {
		cb.ReportFailure()
		metrics.CircuitStateGauge.WithLabelValues(shardID).Set(float64(cb.State()))
		metrics.QueryDuration.WithLabelValues(shardID, op, "error").Observe(duration)
		metrics.TotalQueries.WithLabelValues(shardID, op, "error").Inc()
		return execErr
	}

	cb.ReportSuccess()
	metrics.CircuitStateGauge.WithLabelValues(shardID).Set(0)
	metrics.QueryDuration.WithLabelValues(shardID, op, "success").Observe(duration)
	metrics.TotalQueries.WithLabelValues(shardID, op, "success").Inc()
	return nil
}
```

