```go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"buildscape/postgres-sharded-router/internal/circuit"
	"buildscape/postgres-sharded-router/internal/cluster"
	"buildscape/postgres-sharded-router/internal/config"
	"buildscape/postgres-sharded-router/internal/ring"
	"buildscape/postgres-sharded-router/internal/router"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

func main() {
	cfg := config.LoadClusterConfig()
	pm, err := cluster.NewPoolManager(cfg)
	if err != nil {
		log.Fatalf("Failed to connect to cluster: %v", err)
	}
	defer pm.Close()

	r := ring.NewRing(128, ring.DefaultHash)
	_ = r.AddShard("shard0")
	_ = r.AddShard("shard1")
	_ = r.AddShard("shard2")

	rtr := router.NewRouter(r, pm)
	disp := router.NewResilientDispatcher(rtr)

	mux := http.NewServeMux()
	mux.Handle("/metrics", promhttp.Handler())

	mux.HandleFunc("/health", func(w http.ResponseWriter, req *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"UP"}`))
	})

	// Single-tenant query endpoint: GET /tenants/{id}/events
	mux.HandleFunc("/tenants/", func(w http.ResponseWriter, req *http.Request) {
		tIDStr := req.URL.Path[len("/tenants/"):]
		if idx := len(tIDStr) - len("/events"); idx > 0 && tIDStr[idx:] == "/events" {
			tIDStr = tIDStr[:idx]
		}
		tID, err := strconv.ParseInt(tIDStr, 10, 64)
		if err != nil || tID <= 0 {
			http.Error(w, "Invalid tenant ID", http.StatusBadRequest)
			return
		}

		shardID, _ := r.GetShard(strconv.FormatInt(tID, 10))
		var events []router.Event

		dispErr := disp.ExecuteOnShard(req.Context(), shardID, "list_events", func(pool *pgxpool.Pool) error {
			ev, _, qErr := rtr.ListEventsByTenant(req.Context(), tID, 50)
			events = ev
			return qErr
		})

		if dispErr != nil {
			if errors.Is(dispErr, circuit.ErrCircuitOpen) {
				http.Error(w, fmt.Sprintf("Shard %s offline (Circuit Open)", shardID), http.StatusServiceUnavailable)
				return
			}
			http.Error(w, dispErr.Error(), http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("X-Routed-Shard", shardID)
		_ = json.NewEncoder(w).Encode(events)
	})

	// Scatter-gather metrics endpoint: GET /stats/by-kind
	mux.HandleFunc("/stats/by-kind", func(w http.ResponseWriter, req *http.Request) {
		res := rtr.CountEventsByKindResilient(req.Context(), 2*time.Second)
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(res)
	})

	srv := &http.Server{Addr: ":8080", Handler: mux}

	go func() {
		log.Println("[*] Sharded Router HTTP Proxy listening on http://localhost:8080")
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("Server error: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
	<-stop
	log.Println("[*] Shutting down router proxy gracefully...")
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = srv.Shutdown(ctx)
}
