### Step 5 · Implement Live Cluster Health Probing Utility (`internal/router/health.go`)
Create `internal/router/health.go` reporting active status across all shards:

```go
package router

import (
	"context"
	"time"
)

type ShardHealthStatus struct {
	ShardID string `json:"shard_id"`
	Healthy bool   `json:"healthy"`
	Latency string `json:"latency"`
	Error   string `json:"error,omitempty"`
}

func (r *Router) CheckClusterHealth(ctx context.Context) []ShardHealthStatus {
	pools := r.pm.AllPools()
	statuses := make([]ShardHealthStatus, 0, len(pools))

	for shardID, pool := range pools {
		start := time.Now()
		pCtx, cancel := context.WithTimeout(ctx, 1*time.Second)
		err := pool.Ping(pCtx)
		cancel()

		status := ShardHealthStatus{
			ShardID: shardID,
			Healthy: err == nil,
			Latency: time.Since(start).String(),
		}
		if err != nil {
			status.Error = err.Error()
		}
		statuses = append(statuses, status)
	}
	return statuses
}
